// ---- src/210-rename-and-line-context.js ----
class RenameCurrentFileModal extends Modal {
  constructor(app, plugin, file) {
    super(app);
    this.plugin = plugin;
    this.file = file;
    this.parts = getFileRenameParts(file && file.path);
    this.submitting = false;
  }

  onOpen() {
    const { contentEl } = this;
    contentEl.empty();
    this.modalEl.addClass("bob-rename-file-modal");
    contentEl.addClass("bob-rename-file");

    const header = contentEl.createDiv({ cls: "bob-rename-file-header" });
    const icon = header.createDiv({ cls: "bob-rename-file-header-icon" });
    applyIcon(icon, "file-pen-line");

    const headerText = header.createDiv({ cls: "bob-rename-file-header-text" });
    headerText.createDiv({
      cls: "bob-rename-file-title",
      text: "Rename current file",
    });
    headerText.createDiv({
      cls: "bob-rename-file-subtitle",
      text: this.parts.currentPath,
    });

    const field = contentEl.createDiv({ cls: "bob-rename-file-field" });
    field.createEl("label", {
      cls: "bob-rename-file-label",
      text: "File name",
    });
    this.inputEl = field.createEl("input", {
      cls: "bob-rename-file-input",
      attr: {
        "aria-label": "File name",
        type: "text",
      },
    });
    this.inputEl.value = this.parts.basename;
    this.inputEl.addEventListener("keydown", (event) => {
      if (event.key !== "Enter") {
        return;
      }

      event.preventDefault();
      event.stopPropagation();
      this.submit();
    });

    const actions = contentEl.createDiv({ cls: "bob-rename-file-actions" });
    const cancelButton = actions.createEl("button", { text: "Cancel" });
    cancelButton.addEventListener("click", () => this.close());
    this.renameButtonEl = actions.createEl("button", {
      cls: "mod-cta",
      text: "Rename",
    });
    this.renameButtonEl.addEventListener("click", () => this.submit());

    window.setTimeout(() => {
      this.inputEl.focus();
      this.inputEl.select();
    }, 0);
  }

  onClose() {
    this.modalEl.removeClass("bob-rename-file-modal");
    this.contentEl.empty();
  }

  setSubmitting(submitting) {
    this.submitting = submitting;
    if (this.renameButtonEl) {
      this.renameButtonEl.disabled = submitting;
    }
    if (this.inputEl) {
      this.inputEl.disabled = submitting;
    }
  }

  async submit() {
    if (this.submitting) {
      return;
    }

    this.setSubmitting(true);
    try {
      const renamed = await this.plugin.renameCurrentFileToName(
        this.inputEl ? this.inputEl.value : "",
      );
      if (renamed) {
        this.close();
      }
    } finally {
      this.setSubmitting(false);
    }
  }
}

function addElementClasses(el, ...classes) {
  if (!el || !el.classList) {
    return;
  }

  classes.filter(Boolean).forEach((className) => el.classList.add(className));
}

function fuzzyMatchesText(source, query) {
  const haystack = String(source || "").toLowerCase();
  const needle = String(query || "").toLowerCase();
  if (!needle) {
    return true;
  }

  let haystackIndex = 0;
  for (let needleIndex = 0; needleIndex < needle.length; needleIndex += 1) {
    haystackIndex = haystack.indexOf(needle[needleIndex], haystackIndex);
    if (haystackIndex === -1) {
      return false;
    }
    haystackIndex += 1;
  }

  return true;
}

function truncateBulletPropertySubtitle(line) {
  const text = String(line || "").trim();
  if (text.length <= 140) {
    return text;
  }

  return `${text.slice(0, 137)}...`;
}

function getBulletPropertyFieldMap(line) {
  const fields = new Map();
  parseBulletPropertyFields(line).forEach((field) => {
    if (!fields.has(field.key)) {
      fields.set(field.key, field);
    }
  });
  return fields;
}

function splitMarkdownContent(content) {
  const text = String(content || "");
  const lineEnding = text.includes("\r\n") ? "\r\n" : "\n";
  return {
    lines: text.split(/\r?\n/),
    lineEnding,
  };
}

function isProjectLifecycleTaskLine(lineText) {
  const text = String(lineText || "");
  const match = OBSIDIAN_TASK_LINE_RE.exec(text);
  if (!match || getTrailingBlockId(text) !== "prj") {
    return false;
  }

  return PROJECT_TASK_TAG_RE.test(match[2] || "");
}

function getMarkdownLineContext(content, targetLine) {
  const { lines } = splitMarkdownContent(content);
  if (
    !Number.isInteger(targetLine) ||
    targetLine < 0 ||
    targetLine >= lines.length
  ) {
    return Object.freeze({ valid: false, inFrontmatter: false, inFence: false });
  }

  let inFrontmatter = startsWithFrontmatter(lines);
  let inFence = null;
  for (let lineIndex = 0; lineIndex <= targetLine; lineIndex += 1) {
    const line = String(lines[lineIndex] || "");
    if (inFrontmatter) {
      if (lineIndex > 0 && FRONTMATTER_DELIMITER_RE.test(line)) {
        inFrontmatter = false;
      }
      if (lineIndex === targetLine) {
        return Object.freeze({
          valid: true,
          inFrontmatter: true,
          inFence: false,
        });
      }
      continue;
    }

    if (inFence) {
      const targetIsInFence = lineIndex === targetLine;
      if (isClosingFence(line, inFence)) {
        inFence = null;
      }
      if (targetIsInFence) {
        return Object.freeze({
          valid: true,
          inFrontmatter: false,
          inFence: true,
        });
      }
      continue;
    }

    const openingFence = getFenceOpening(line);
    if (openingFence) {
      inFence = openingFence;
      if (lineIndex === targetLine) {
        return Object.freeze({
          valid: true,
          inFrontmatter: false,
          inFence: true,
        });
      }
      continue;
    }

    if (lineIndex === targetLine) {
      return Object.freeze({
        valid: true,
        inFrontmatter: false,
        inFence: false,
      });
    }
  }

  return Object.freeze({ valid: false, inFrontmatter: false, inFence: false });
}

function getMarkdownLineContextsForLines(lines) {
  const sourceLines = Array.isArray(lines) ? lines : [];
  const contexts = [];
  let inFrontmatter = startsWithFrontmatter(sourceLines);
  let inFence = null;
  for (let lineIndex = 0; lineIndex < sourceLines.length; lineIndex += 1) {
    const line = String(sourceLines[lineIndex] || "");
    if (inFrontmatter) {
      contexts.push(
        Object.freeze({ valid: true, inFrontmatter: true, inFence: false }),
      );
      if (lineIndex > 0 && FRONTMATTER_DELIMITER_RE.test(line)) {
        inFrontmatter = false;
      }
      continue;
    }
    if (inFence) {
      contexts.push(
        Object.freeze({ valid: true, inFrontmatter: false, inFence: true }),
      );
      if (isClosingFence(line, inFence)) {
        inFence = null;
      }
      continue;
    }
    const openingFence = getFenceOpening(line);
    if (openingFence) {
      inFence = openingFence;
      contexts.push(
        Object.freeze({ valid: true, inFrontmatter: false, inFence: true }),
      );
      continue;
    }
    contexts.push(
      Object.freeze({ valid: true, inFrontmatter: false, inFence: false }),
    );
  }
  return Object.freeze(contexts);
}

function getMarkdownLineContexts(content) {
  return getMarkdownLineContextsForLines(splitMarkdownContent(content).lines);
}

// Short-lived per-note parse snapshot shared by one dependency stage build.
// Tied to exact note content: lines, Markdown contexts, scanned task entries
// (with forward-carried sections), lazily built block-id identities, and a
// per-parent dependency-collection cache. Never reuse across changed editor
// content, write-planner intermediate content, or reopened stages.
function createDependencyNoteSnapshot(content) {
  const text = String(content || "");
  const { lines, lineEnding } = splitMarkdownContent(text);
  const contexts = getMarkdownLineContextsForLines(lines);
  let currentSection = null;
  const entries = [];
  for (let line = 0; line < lines.length; line += 1) {
    const rawLine = String(lines[line] || "");
    const sectionMatch = DEPENDENCY_STAGE_SECTION_RE.exec(rawLine);
    if (sectionMatch) {
      const heading = (sectionMatch[1] || "").trim() || null;
      currentSection = heading;
    }
    const context = contexts[line] || {};
    if (!context.valid || context.inFrontmatter || context.inFence) {
      continue;
    }
    if (isObsidianTaskLine(rawLine)) {
      const match = OBSIDIAN_TASK_LINE_RE.exec(rawLine);
      const status = match ? match[1] : " ";
      const idField = findBulletPropertyField(rawLine, "id");
      entries.push(
        Object.freeze({
          line,
          rawLine,
          isTask: true,
          status,
          open: OPEN_OBSIDIAN_TASK_STATUSES.has(status),
          blocked: status === "?",
          text: cleanTaskDisplayText(rawLine),
          blockId: getTrailingBlockId(rawLine),
          idField: idField
            ? normalizeBulletPropertyValue(idField.value)
            : null,
          hidden: hasWholeTaskTag(rawLine, PROJECT_HIDE_TAG),
          section: currentSection,
        }),
      );
      continue;
    }
    const blockId = getTrailingBlockId(rawLine);
    if (blockId) {
      entries.push(
        Object.freeze({
          line,
          rawLine,
          isTask: false,
          status: null,
          open: false,
          blocked: false,
          text: rawLine.trim(),
          blockId,
          idField: null,
          hidden: false,
          section: currentSection,
        }),
      );
    }
  }
  return {
    text,
    lines,
    lineEnding,
    contexts,
    entries: Object.freeze(entries),
    identities: null,
    collections: new Map(),
  };
}

function getDependencySnapshotIdentities(snapshot) {
  if (!snapshot) {
    return new Map();
  }
  if (snapshot.identities) {
    return snapshot.identities;
  }
  const identities = new Map();
  for (const entry of snapshot.entries) {
    if (!entry.isTask || !entry.blockId) {
      continue;
    }
    identities.set(
      entry.blockId,
      entry.idField || entry.blockId,
    );
  }
  snapshot.identities = identities;
  return identities;
}

function dependencySnapshotKey(additionalManagedIds) {
  if (!additionalManagedIds || additionalManagedIds.length === 0) {
    return "";
  }
  try {
    return JSON.stringify(
      normalizeDependencyNavigationTargets(additionalManagedIds).map(
        dependencyNavigationTargetKey,
      ),
    );
  } catch (_error) {
    return `count:${additionalManagedIds.length}`;
  }
}

function vaultStageYield() {
  return new Promise((resolve) => setTimeout(resolve, 0));
}

// Whole-note dependency operations must reject task-shaped examples in YAML
// frontmatter and fenced code, even when the individual line looks valid.
function isObsidianTaskAtLine(
  content,
  lineIndex,
  lineContexts = null,
  sourceLines = null,
) {
  const lines = sourceLines || splitMarkdownContent(content).lines;
  const context = lineContexts
    ? lineContexts[lineIndex] || {
        valid: false,
        inFrontmatter: false,
        inFence: false,
      }
    : getMarkdownLineContext(content, lineIndex);
  return (
    context.valid &&
    !context.inFrontmatter &&
    !context.inFence &&
    isObsidianTaskLine(lines[lineIndex])
  );
}

function isProjectLifecycleTaskAtLine(content, lineIndex) {
  const { lines } = splitMarkdownContent(content);
  const context = getMarkdownLineContext(content, lineIndex);
  return (
    context.valid &&
    !context.inFrontmatter &&
    !context.inFence &&
    isProjectLifecycleTaskLine(lines[lineIndex])
  );
}

function getYamlScalarText(rawValue) {
  const text = String(rawValue || "").trim();
  const quoted = /^(["'])(.*)\1(?:[ \t]+#.*)?$/.exec(text);
  if (quoted) {
    return quoted[2].trim();
  }

  return text.replace(/[ \t]+#.*$/, "").trim();
}

function parseProjectNoteFrontmatter(content, options = {}) {
  const { lines, lineEnding } = splitMarkdownContent(content);
  if (!startsWithFrontmatter(lines)) {
    return Object.freeze({
      valid: false,
      error: "Project note has no YAML frontmatter",
    });
  }

  let closingLine = -1;
  for (let lineIndex = 1; lineIndex < lines.length; lineIndex += 1) {
    if (FRONTMATTER_DELIMITER_RE.test(lines[lineIndex])) {
      closingLine = lineIndex;
      break;
    }
  }
  if (closingLine === -1) {
    return Object.freeze({
      valid: false,
      error: "Project note frontmatter is not closed",
    });
  }

  const yamlText = lines.slice(1, closingLine).join("\n");
  let data;
  try {
    const yamlParser = options.parseYaml || parseYaml;
    data = yamlParser(yamlText);
  } catch (error) {
    return Object.freeze({
      valid: false,
      error: "Project note frontmatter is malformed",
    });
  }

  if (!data || typeof data !== "object" || Array.isArray(data)) {
    return Object.freeze({
      valid: false,
      error: "Project note frontmatter must be a YAML mapping",
    });
  }
  const typeLine = lines
    .slice(1, closingLine)
    .map((line, index) => ({
      line: index + 1,
      match: /^type[ \t]*:(.*)$/.exec(line),
    }))
    .find((entry) => entry.match);
  const rawType = typeLine ? getYamlScalarText(typeLine.match[1]) : "";
  if (!isProjectType(data.type) && rawType !== PROJECT_TYPE_WIKILINK) {
    return Object.freeze({
      valid: false,
      error: "The ^prj task is not in a project note",
    });
  }

  const scheduledLines = [];
  for (let lineIndex = 1; lineIndex < closingLine; lineIndex += 1) {
    const match = /^scheduled[ \t]*:(.*)$/.exec(lines[lineIndex]);
    if (match) {
      scheduledLines.push({ line: lineIndex, rawValue: match[1] });
    }
  }
  if (scheduledLines.length > 1) {
    return Object.freeze({
      valid: false,
      error: "Project note has multiple scheduled properties",
    });
  }

  const scheduledDefined = Object.prototype.hasOwnProperty.call(
    data,
    "scheduled",
  );
  if (scheduledDefined !== (scheduledLines.length === 1)) {
    return Object.freeze({
      valid: false,
      error: "Project scheduled must be a top-level YAML property",
    });
  }

  let scheduledValue = "";
  if (scheduledDefined) {
    const parsedValue = data.scheduled;
    if (
      parsedValue !== null &&
      parsedValue !== undefined &&
      typeof parsedValue !== "string" &&
      !(parsedValue instanceof Date)
    ) {
      return Object.freeze({
        valid: false,
        error: "Project scheduled must be a YYYY-MM-DD date",
      });
    }
    scheduledValue = getYamlScalarText(scheduledLines[0].rawValue);
    const validation = validateProjectScheduledDate(scheduledValue);
    if (!validation.valid) {
      return Object.freeze({ valid: false, error: validation.message });
    }
    scheduledValue = validation.value;
  }

  return Object.freeze({
    valid: true,
    error: null,
    data,
    lines,
    lineEnding,
    closingLine,
    scheduledDefined,
    scheduledValue,
    scheduledLine: scheduledDefined ? scheduledLines[0].line : null,
  });
}

function emptyProjectNoteReversalSplit(error, extra = {}) {
  return Object.freeze({
    valid: false,
    error,
    status: extra.status === undefined ? null : extra.status,
    description:
      extra.description === undefined ? null : extra.description,
    lifecycleChildLines: Object.freeze(
      Array.isArray(extra.lifecycleChildLines)
        ? extra.lifecycleChildLines.slice()
        : [],
    ),
    taskLines: Object.freeze([]),
    sections: Object.freeze([]),
  });
}

function getProjectReversalChildLines(lines, startIndex) {
  const sourceLines = Array.isArray(lines) ? lines : [];
  const parentLine = String(sourceLines[startIndex] || "");
  const parentMatch = PROJECT_LIST_ITEM_RE.exec(parentLine);
  if (!parentMatch) {
    return [];
  }

  const parentIndentLength = parentMatch[1].length;
  const collected = [];
  let lastContentOffset = -1;
  for (let index = startIndex + 1; index < sourceLines.length; index += 1) {
    const lineText = String(sourceLines[index] || "");
    if (lineText.trim() === "") {
      collected.push(lineText);
      continue;
    }

    const indentMatch = /^(\s*)/.exec(lineText);
    const indentLength = indentMatch ? indentMatch[1].length : 0;
    if (indentLength > parentIndentLength) {
      collected.push(lineText);
      lastContentOffset = collected.length - 1;
      continue;
    }

    break;
  }

  return lastContentOffset === -1
    ? []
    : collected.slice(0, lastContentOffset + 1);
}

function formatProjectReversalSnippet(lineText) {
  return truncateProjectTaskDescription(String(lineText || "").trim());
}

function formatProjectReversalSectionLabel(headerText) {
  return String(headerText || "")
    .trim()
    .replace(/\s+/g, " ");
}

function splitProjectNoteForReversal(content) {
  const { lines } = splitMarkdownContent(content);
  const contexts = getMarkdownLineContexts(content);
  const prjIndexes = [];
  for (let index = 0; index < lines.length; index += 1) {
    const context = contexts[index];
    if (!context || context.inFrontmatter || context.inFence) {
      continue;
    }
    if (isProjectLifecycleTaskLine(lines[index])) {
      prjIndexes.push(index);
    }
  }

  if (prjIndexes.length === 0) {
    return emptyProjectNoteReversalSplit("Project note has no ^prj task");
  }
  if (prjIndexes.length > 1) {
    return emptyProjectNoteReversalSplit(
      "Project note has multiple ^prj tasks",
    );
  }

  const prjIndex = prjIndexes[0];
  const parsed = parseProjectLifecycleTaskBody(lines[prjIndex]);
  const status = parsed ? parsed.status : null;
  const description = parsed ? parsed.description : "";
  const lifecycleChildLines = getProjectReversalChildLines(lines, prjIndex);
  const prjBlockEnd = prjIndex + lifecycleChildLines.length;
  const splitExtra = { status, description, lifecycleChildLines };

  const taskLines = [];
  const sections = [];
  let index = 0;
  while (index < lines.length) {
    const context = contexts[index];
    if (!context || context.inFrontmatter) {
      index += 1;
      continue;
    }

    if (index === prjIndex) {
      index = prjBlockEnd + 1;
      continue;
    }

    const line = String(lines[index] || "");
    if (
      context.valid &&
      !context.inFence &&
      PROJECT_SECTION_HEADER_RE.test(line)
    ) {
      const headerMatch = PROJECT_SECTION_HEADER_RE.exec(line);
      const headerText = headerMatch && headerMatch[1] ? headerMatch[1] : "";
      const sectionLabel = formatProjectReversalSectionLabel(headerText);
      const bodyLines = [];
      let bodyIndex = index + 1;
      for (; bodyIndex < lines.length; bodyIndex += 1) {
        const bodyContext = contexts[bodyIndex];
        const bodyLine = String(lines[bodyIndex] || "");
        if (
          bodyContext &&
          bodyContext.valid &&
          !bodyContext.inFrontmatter &&
          !bodyContext.inFence &&
          PROJECT_SECTION_BOUNDARY_HEADER_RE.test(bodyLine)
        ) {
          break;
        }
        if (bodyLine.trim() === "") {
          continue;
        }
        if (
          bodyContext &&
          bodyContext.valid &&
          !bodyContext.inFence &&
          PROJECT_LIST_ITEM_RE.test(bodyLine)
        ) {
          bodyLines.push(bodyLine);
          continue;
        }

        return emptyProjectNoteReversalSplit(
          `Section "${sectionLabel}" has content that is not a list item: "${formatProjectReversalSnippet(bodyLine)}"`,
          splitExtra,
        );
      }

      if (normalizeProjectSectionTitle(headerText) === "tasks") {
        for (const item of bodyLines) {
          if (!item.includes(PROJECT_TASKS_PLACEHOLDER)) {
            taskLines.push(item);
          }
        }
      } else if (bodyLines.length > 0) {
        const title = formatProjectReversalSectionTitle(headerText);
        if (!title) {
          return emptyProjectNoteReversalSplit(
            `Section "${sectionLabel}" cannot be converted into a task bullet`,
            splitExtra,
          );
        }
        sections.push(
          Object.freeze({
            title,
            noteLines: Object.freeze(bodyLines.slice()),
          }),
        );
      }

      index = bodyIndex;
      continue;
    }

    if (line.trim() === "") {
      index += 1;
      continue;
    }

    return emptyProjectNoteReversalSplit(
      `Project note has content outside the ^prj task and its sections: "${formatProjectReversalSnippet(line)}"`,
      splitExtra,
    );
  }

  return Object.freeze({
    valid: true,
    error: null,
    status,
    description,
    lifecycleChildLines: Object.freeze(lifecycleChildLines.slice()),
    taskLines: Object.freeze(taskLines),
    sections: Object.freeze(sections),
  });
}

function emptyProjectNoteReversalBlock(error, extra = {}) {
  return Object.freeze({
    valid: false,
    error,
    lines: Object.freeze([]),
    taskCount: 0,
    sectionCount: 0,
    blockId: extra.blockId === undefined ? null : extra.blockId,
    scheduled: extra.scheduled || "",
    created: extra.created || "",
    parentLink: extra.parentLink === undefined ? null : extra.parentLink,
  });
}

function buildTaskBlockFromProjectNote(content, options = {}) {
  const frontmatter = parseProjectNoteFrontmatter(content, options);
  if (!frontmatter.valid) {
    return emptyProjectNoteReversalBlock(frontmatter.error);
  }

  const split = splitProjectNoteForReversal(content);
  if (
    split.error === "Project note has multiple ^prj tasks" ||
    split.error === "Project note has no ^prj task"
  ) {
    return emptyProjectNoteReversalBlock(split.error, {
      parentLink: frontmatter.data && frontmatter.data.parent,
    });
  }

  if (split.status === null || split.status === undefined) {
    return emptyProjectNoteReversalBlock(
      split.error || "Project note has no ^prj task",
      { parentLink: frontmatter.data && frontmatter.data.parent },
    );
  }

  if (!PROJECT_OPEN_TASK_STATUSES.has(split.status)) {
    return emptyProjectNoteReversalBlock(
      "Only open projects can be converted back to a task",
      { parentLink: frontmatter.data && frontmatter.data.parent },
    );
  }
  if (
    String(split.description || "").includes(PROJECT_COMPLETION_PLACEHOLDER)
  ) {
    return emptyProjectNoteReversalBlock(
      "Project completion criteria is still the template placeholder",
      { parentLink: frontmatter.data && frontmatter.data.parent },
    );
  }
  if (!split.description) {
    return emptyProjectNoteReversalBlock(
      "Project completion criteria is empty",
      { parentLink: frontmatter.data && frontmatter.data.parent },
    );
  }
  if (!split.valid) {
    return emptyProjectNoteReversalBlock(split.error, {
      parentLink: frontmatter.data && frontmatter.data.parent,
    });
  }

  const noteBasename = String(options.noteBasename || "").trim();
  const parentBasename =
    options.parentBasename === undefined
      ? getProjectParentBasenameFromLink(
          frontmatter.data && frontmatter.data.parent,
        )
      : String(options.parentBasename || "").trim();
  const blockId = getProjectReversalBlockId(noteBasename, parentBasename);
  const scheduled = frontmatter.scheduledValue || "";
  const createdRaw = getProjectFrontmatterCreatedDate(
    frontmatter.lines,
    frontmatter.closingLine,
  );
  const now = options.now instanceof Date ? options.now : new Date();
  const created = createdRaw || formatProjectTaskCreatedDate(now);
  const taskLine = buildTaskLineFromProjectNote({
    status: split.status,
    description: split.description,
    scheduled,
    created,
    blockId,
  });

  const indentedTasks = indentProjectReversalLines(split.taskLines, 1);
  const lines = [taskLine, ...indentedTasks];
  let sectionCount = 0;
  for (const section of split.sections) {
    lines.push(`\t- ${section.title}`);
    lines.push(...indentProjectReversalLines(section.noteLines, 2));
    sectionCount += 1;
  }
  lines.push(...indentProjectReversalLines(split.lifecycleChildLines, 1));

  let taskCount = 0;
  for (const line of indentedTasks) {
    const parsedChild = parseProjectChildListItem(line, 0);
    if (parsedChild && parsedChild.indent === "\t") {
      taskCount += 1;
    }
  }

  return Object.freeze({
    valid: true,
    error: null,
    lines: Object.freeze(lines),
    taskCount,
    sectionCount,
    blockId,
    scheduled,
    created,
    parentLink: frontmatter.data && frontmatter.data.parent,
  });
}

function getProjectNotePropertyContext(content, lineIndex, options = {}) {
  if (!isProjectLifecycleTaskAtLine(content, lineIndex)) {
    return Object.freeze({
      valid: true,
      isProjectTask: false,
      frontmatter: null,
    });
  }

  const frontmatter = parseProjectNoteFrontmatter(content, options);
  if (!frontmatter.valid) {
    return Object.freeze({
      valid: false,
      isProjectTask: true,
      error: frontmatter.error,
      frontmatter,
    });
  }

  return Object.freeze({
    valid: true,
    isProjectTask: true,
    error: null,
    frontmatter,
  });
}

// ---- src/220-property-targets.js ----
function resolveBulletPropertyTarget(name, context = {}) {
  const descriptor = Object.prototype.hasOwnProperty.call(
    PROJECT_NOTE_PROPERTY_TARGETS,
    name,
  )
    ? PROJECT_NOTE_PROPERTY_TARGETS[name]
    : null;
  if (descriptor && context.isProjectTask && context.valid) {
    return descriptor;
  }

  return Object.freeze({ kind: "inline", fieldName: name });
}

function getBulletPropertyCurrentLabel(property, value) {
  const currentValue = normalizeBulletPropertyValue(value);
  if (
    property &&
    property.values === "priority" &&
    property.levelsByValue instanceof Map
  ) {
    const level = property.levelsByValue.get(currentValue);
    if (level) {
      return level.label;
    }
  }

  return currentValue;
}

function createBulletPropertyItems(config, line, context = {}) {
  const fields = getBulletPropertyFieldMap(line);
  const dependencyEligible =
    context.isObsidianTask === undefined
      ? isObsidianTaskLine(line)
      : Boolean(context.isObsidianTask);
  return config.properties
    .map((property, order) => {
      const target = resolveBulletPropertyTarget(property.name, context);
      const field =
        target.kind === "inline" ? fields.get(property.name) || null : null;
      const frontmatterDefined =
        target.kind === "project-frontmatter" &&
        context.frontmatter &&
        context.frontmatter.scheduledDefined;
      const currentValue = frontmatterDefined
        ? context.frontmatter.scheduledValue
        : field
          ? field.value
          : "";
      return {
        kind: "property",
        property,
        target,
        order,
        defined: frontmatterDefined || !!field,
        currentValue,
        currentLabel: getBulletPropertyCurrentLabel(property, currentValue),
        dependencyEligible,
      };
    })
    .filter(
      (item) =>
        item.property.values !== "local_task_id" ||
        item.dependencyEligible ||
        item.defined,
    )
    .sort((first, second) => {
      if (first.defined !== second.defined) {
        return first.defined ? -1 : 1;
      }

      return first.order - second.order;
    });
}

// An explicit Vim count for the property picker means "additional tasks": a
// repeat of 2 snapshots the current real task plus the next two real tasks in
// document order. Physical line distance is deliberately irrelevant.
function discoverCountedObsidianTaskTargets(
  content,
  startLine,
  additionalTaskCount,
) {
  const text = String(content || "");
  const source = splitMarkdownContent(text);
  const line = Math.floor(numericOrDefault(startLine, Number.NaN));
  const additional = Math.max(
    0,
    Math.floor(numericOrDefault(additionalTaskCount, 0)),
  );
  const requestedCount = additional + 1;
  const contexts = getMarkdownLineContexts(text);

  if (
    !Number.isFinite(line) ||
    !isObsidianTaskAtLine(text, line, contexts, source.lines)
  ) {
    return Object.freeze({
      valid: false,
      error: "Counted property editing must start on a #task checkbox",
      explicit: true,
      startLine: Number.isFinite(line) ? line : null,
      requestedAdditionalCount: additional,
      requestedCount,
      actualCount: 0,
      clamped: false,
      targets: Object.freeze([]),
    });
  }

  const targets = [];
  for (
    let lineIndex = line;
    lineIndex < source.lines.length && targets.length < requestedCount;
    lineIndex += 1
  ) {
    if (
      isObsidianTaskAtLine(text, lineIndex, contexts, source.lines)
    ) {
      targets.push(
        Object.freeze({
          line: lineIndex,
          rawLine: String(source.lines[lineIndex] || ""),
        }),
      );
    }
  }

  return Object.freeze({
    valid: true,
    error: null,
    explicit: true,
    startLine: line,
    requestedAdditionalCount: additional,
    requestedCount,
    actualCount: targets.length,
    clamped: targets.length < requestedCount,
    targets: Object.freeze(targets),
  });
}

function validateCountedTaskSession(content, session) {
  const text = String(content || "");
  const source = splitMarkdownContent(text);
  const contexts = getMarkdownLineContexts(text);
  const targets = session && Array.isArray(session.targets)
    ? session.targets
    : [];
  if (!session || session.valid === false || targets.length === 0) {
    return Object.freeze({
      valid: false,
      error: "Counted task session is unavailable",
      staleTarget: null,
    });
  }

  for (const target of targets) {
    const liveLine = Number.isInteger(target.line)
      ? source.lines[target.line]
      : undefined;
    if (
      liveLine !== target.rawLine ||
      !isObsidianTaskAtLine(text, target.line, contexts, source.lines)
    ) {
      return Object.freeze({
        valid: false,
        error: "A counted task changed while the picker was open",
        staleTarget: target,
      });
    }
  }

  return Object.freeze({ valid: true, error: null, staleTarget: null });
}

// ---------------------------------------------------------------------------
// link-picker: Ctrl+Shift+P edits the task behind a Task Link bullet.
//
// A dedicated Task Link bullet is a bullet whose body, after an optional
// checkbox, optional 🍅 markers, an optional wrapping ~~…~~, and an optional
// trailing `#` move-only marker, is exactly one block link `[[T#^id]]` or
// `![[T#^id]]` with an optional alias. This mirrors block-id-prompt's
// dedicated-link grammar so both plugins agree on what a Task Link bullet is,
// but stays self-contained because plugins deploy separately.
// ---------------------------------------------------------------------------
const LINK_PICKER_DEDICATED_BODY_RE =
  /^(?:\[[^\]\n]\][ \t]+)?(?:🍅[ \t]+)*(~~)?(!)?\[\[([^\]\n]*?)#\^([A-Za-z0-9-]+)(?:\|[^\]\n]*)?\]\](~~)?(?:[ \t]*#)?[ \t]*$/u;

// Parse a dedicated Task Link bullet line into its link parts, or null when
// the line is not one. The body must hold exactly one block link; a
// strikethrough marker must wrap both sides or neither.
function parseLinkPickerTaskLink(lineText) {
  const line = String(lineText || "");
  const bounds = pomodoroBulletBodyBounds(line);
  if (!bounds) {
    return null;
  }
  const body = line.slice(bounds.start, bounds.end);
  const match = LINK_PICKER_DEDICATED_BODY_RE.exec(body);
  if (!match) {
    return null;
  }
  const strikeOpen = match[1] || null;
  const strikeClose = match[5] || null;
  if (Boolean(strikeOpen) !== Boolean(strikeClose)) {
    return null;
  }
  return Object.freeze({
    target: String(match[3] || "").trim(),
    blockId: match[4],
    embedded: Boolean(match[2]),
    struck: Boolean(strikeOpen),
  });
}

// Discover the Task Links a counted Ctrl+Shift+P covers: the dedicated link
// under the cursor plus the next N dedicated Task Link siblings — same indent
// depth, same parent block (for ledger links, the same Pomodoro entry), in
// document order, skipping non-link siblings. The scan stops when the parent
// block ends and clamps there. On a #task line the existing task behavior is
// unchanged, so a non-link line reports `notLink` instead of an error and the
// caller falls through to the regular picker path.
function discoverLinkPickerTargets(content, startLine, additionalTaskCount) {
  const text = String(content || "");
  const source = splitMarkdownContent(text);
  const line = Math.floor(numericOrDefault(startLine, Number.NaN));
  const additional = Math.max(
    0,
    Math.floor(numericOrDefault(additionalTaskCount, 0)),
  );
  const requestedCount = additional + 1;
  const contexts = getMarkdownLineContexts(text);
  const invalid = (error, notLink = false) =>
    Object.freeze({
      valid: false,
      error,
      notLink,
      explicit: additional > 0,
      kind: "task-link",
      startLine: Number.isFinite(line) ? line : null,
      requestedAdditionalCount: additional,
      requestedCount,
      actualCount: 0,
      clamped: false,
      targets: Object.freeze([]),
    });
  if (
    !Number.isFinite(line) ||
    line < 0 ||
    line >= source.lines.length ||
    (contexts[line] && contexts[line].inFence)
  ) {
    return invalid("Cursor is not on a Task Link", true);
  }
  if (isObsidianTaskAtLine(text, line, contexts, source.lines)) {
    return invalid("Cursor is not on a Task Link", true);
  }
  const firstLink = parseLinkPickerTaskLink(source.lines[line]);
  if (!firstLink) {
    return invalid("Cursor is not on a Task Link", true);
  }

  const cursorIndent = getBulletIndentWidth(String(source.lines[line] || ""));
  const targets = [
    Object.freeze({
      line,
      rawLine: String(source.lines[line] || ""),
      link: firstLink,
    }),
  ];
  let clamped = false;
  for (
    let lineIndex = line + 1;
    lineIndex < source.lines.length && targets.length < requestedCount;
    lineIndex += 1
  ) {
    const lineText = String(source.lines[lineIndex] || "");
    if (lineText.trim() === "") {
      continue;
    }
    if (contexts[lineIndex] && contexts[lineIndex].inFence) {
      continue;
    }
    const indent = getBulletIndentWidth(lineText);
    if (indent < cursorIndent) {
      clamped = targets.length < requestedCount;
      break;
    }
    if (
      cursorIndent === 0 &&
      !PROJECT_LIST_ITEM_RE.test(lineText)
    ) {
      clamped = targets.length < requestedCount;
      break;
    }
    if (indent !== cursorIndent) {
      continue;
    }
    const link = parseLinkPickerTaskLink(lineText);
    if (!link) {
      continue;
    }
    targets.push(
      Object.freeze({ line: lineIndex, rawLine: lineText, link }),
    );
  }
  if (targets.length < requestedCount) {
    clamped = true;
  }

  return Object.freeze({
    valid: true,
    error: null,
    notLink: false,
    explicit: additional > 0,
    kind: "task-link",
    startLine: line,
    requestedAdditionalCount: additional,
    requestedCount,
    actualCount: targets.length,
    clamped,
    targets: Object.freeze(targets),
  });
}

// Resolve a block ID to its task line inside one note's content. The ID must
// be unique and must sit on an open #task line; anything else reports an
// error the caller surfaces as a Notice without changing anything.
function findUniqueLinkPickerTargetLine(noteContent, blockId) {
  const id = normalizeBulletPropertyValue(blockId);
  const text = String(noteContent || "");
  if (!id) {
    return Object.freeze({ valid: false, error: "missing", line: null });
  }
  const source = splitMarkdownContent(text);
  const contexts = getMarkdownLineContexts(text);
  const matches = [];
  for (let index = 0; index < source.lines.length; index += 1) {
    if (
      getTrailingBlockId(String(source.lines[index] || "")) === id
    ) {
      matches.push(index);
    }
  }
  if (matches.length === 0) {
    return Object.freeze({ valid: false, error: "missing", line: null });
  }
  if (matches.length !== 1) {
    return Object.freeze({ valid: false, error: "duplicated", line: null });
  }
  const line = matches[0];
  const rawLine = String(source.lines[line] || "");
  if (!isObsidianTaskAtLine(text, line, contexts, source.lines)) {
    return Object.freeze({ valid: false, error: "not-task", line: null });
  }
  if (!isOpenObsidianTaskLine(rawLine)) {
    return Object.freeze({ valid: false, error: "closed", line: null });
  }
  return Object.freeze({ valid: true, error: null, line, rawLine });
}

// Aggregate one property row across link-picker targets that live in different
// notes. Mirrors createCountedBulletPropertyItems (common only when every
// target defines the same value, otherwise mixed) but reads each target from
// its own note content. The Depends on row edits the linked task in its own
// note, for single links and batches alike (`docs/task-dependencies.md` §6.1).
function createLinkPickerPropertyItems(config, resolvedTargets, options = {}) {
  const targets = Array.isArray(resolvedTargets) ? resolvedTargets : [];
  if (targets.length === 0) {
    return Object.freeze({ valid: false, error: "No linked tasks", items: [] });
  }
  const singleLinkTarget =
    targets.length === 1 ? targets[0] : null;
  const properties = (config && Array.isArray(config.properties)
    ? config.properties
    : []
  ).filter((property) => {
    const name = normalizeBulletPropertyName(property && property.name);
    if (property && property.values === "local_task_id") {
      return name === "dependsOn";
    }
    return name !== "dependsOn";
  });
  const items = [];
  for (let order = 0; order < properties.length; order += 1) {
    const property = properties[order];
    const states = [];
    for (const target of targets) {
      const state = getCountedPropertyTargetState(
        target.content,
        { line: target.line, rawLine: target.rawLine },
        property,
        options,
      );
      if (!state.valid) {
        return Object.freeze({ valid: false, error: state.error, items: [] });
      }
      states.push(state);
    }

    const definedStates = states.filter((state) => state.defined);
    const values = Array.from(
      new Set(definedStates.map((state) => state.value)),
    );
    const allDefined = definedStates.length === states.length;
    const valueState =
      definedStates.length === 0
        ? "absent"
        : allDefined && values.length === 1
          ? "common"
          : "mixed";
    const currentLabels = Object.freeze(
      values.map((value) => getBulletPropertyCurrentLabel(property, value)),
    );
    const isLinkDependencyRow =
      property &&
      property.values === "local_task_id" &&
      normalizeBulletPropertyName(property.name) === "dependsOn";
    items.push({
      kind: "property",
      property,
      target: Object.freeze({ kind: "link-picker-batch" }),
      order,
      defined: definedStates.length > 0,
      definedCount: definedStates.length,
      targetCount: states.length,
      currentValue: valueState === "common" ? values[0] : "",
      currentLabel: valueState === "common" ? currentLabels[0] : "",
      currentValues: Object.freeze(values),
      currentLabels,
      valueState,
      mixed: valueState === "mixed",
      dependencyEligible: false,
      sourceStates: Object.freeze(states),
      linkDependency: isLinkDependencyRow,
      detailText: isLinkDependencyRow
        ? singleLinkTarget
          ? `↗ ${dependencyStageBasenameOf(singleLinkTarget.path)} · ${singleLinkTarget.displayText}`
          : `↗ ${targets.length} linked tasks · opens each in its own note`
        : null,
    });
  }

  items.sort((first, second) => {
    if (first.defined !== second.defined) {
      return first.defined ? -1 : 1;
    }
    return first.order - second.order;
  });
  return Object.freeze({
    valid: true,
    error: null,
    items: Object.freeze(items),
  });
}

// Group resolved link-picker targets by note so each note is planned with the
// pure counted-batch planner and written with one guarded transaction.
function groupLinkPickerTargetsByNote(resolvedTargets) {
  const groups = new Map();
  for (const target of Array.isArray(resolvedTargets)
    ? resolvedTargets
    : []) {
    if (!target || !target.path) {
      continue;
    }
    if (!groups.has(target.path)) {
      groups.set(
        target.path,
        Object.freeze({
          path: target.path,
          file: target.file || null,
          content: target.content,
          targets: [],
        }),
      );
    }
    groups.get(target.path).targets.push(
      Object.freeze({ line: target.line, rawLine: target.rawLine }),
    );
  }
  return Array.from(groups.values()).map((group) =>
    Object.freeze({
      path: group.path,
      file: group.file,
      content: group.content,
      session: Object.freeze({
        valid: true,
        error: null,
        explicit: true,
        kind: "task-link",
        startLine: group.targets[0] ? group.targets[0].line : null,
        requestedAdditionalCount: group.targets.length - 1,
        requestedCount: group.targets.length,
        actualCount: group.targets.length,
        clamped: false,
        targets: Object.freeze(group.targets),
      }),
    }),
  );
}

// Picker subtitle for a link session: `↗ <note> · <task text>` for one link,
// a link count for a batch, and the clamp notice at the parent's end.
function getLinkPickerSessionSubtitle(session) {
  if (!session || !Array.isArray(session.targets)) {
    return "";
  }
  if (session.actualCount <= 1) {
    const first =
      session.resolved && session.resolved.length > 0
        ? session.resolved[0]
        : null;
    if (!first) {
      return "Task Link";
    }
    const note = getVaultPathBasenameWithoutExtension(first.path || "");
    const task = truncateBulletPropertySubtitle(
      cleanTaskDisplayText(first.rawLine || ""),
    );
    const single = `↗ ${note} · ${task}`;
    if (session.clamped) {
      return `${single} · ${formatCountLabel(session.actualCount, "link")} of ${session.requestedCount} requested · end of Pomodoro`;
    }
    return single;
  }
  if (session.clamped) {
    return `${formatCountLabel(session.actualCount, "link")} of ${
      session.requestedCount
    } requested · end of Pomodoro`;
  }
  return formatCountLabel(session.actualCount, "link");
}

// ---------------------------------------------------------------------------
// task-lane: Commit Ready to Next, or release Next/In Progress to Ready.
//
// - Commit: if any target is Ready (` `), every Ready target becomes Next
//   (`*`). Other targets are untouched and no link is written.
// - Release: otherwise, every Next (`*`) and In Progress (`/`) target
//   becomes Ready (` `), and each released task's live links under today's
//   open Pomodoros are removed by the caller. Blocked (`?`) targets are
//   skipped and counted in the Notice ("Blocked is derived").
// - Done, cancelled and non-task targets keep the existing session refusals.
// - `summary` (optional) is prepended to each released In Progress task's
//   Work Log; a blank summary writes nothing. `dateText` is `YYYY-MM-DD`.
//   Work Log planning mirrors block-id-prompt's pure `planWorkLogInsertion`
//   (see `plugins/block-id-prompt/main.js`): prepend under the existing
//   marker when one is a direct child, else append a new marker plus entry
//   at the end of the task's child block. Copied as an independent
//   implementation since plugins deploy separately and never import each
//   other's `main.js`.
function normalizeLaneWorkSummary(value) {
  return String(value === null || value === undefined ? "" : value)
    .trim()
    .replace(/\s+/g, " ");
}

function formatLaneWorkLogEntry(summary, dateText) {
  const normalized = normalizeLaneWorkSummary(summary);
  if (!normalized) {
    return "";
  }
  return `*${String(dateText || "")}* — ${normalized}`;
}

function findLaneWorkLogParent(lines, taskLine) {
  const sourceLines = Array.isArray(lines) ? lines : [];
  const taskIndex = Math.floor(numericOrDefault(taskLine, Number.NaN));
  if (!Number.isFinite(taskIndex) || taskIndex < 0 || taskIndex >= sourceLines.length) {
    return null;
  }
  const block = findCurrentBulletChildBlock(sourceLines, taskIndex);
  for (let index = block.startLine; index < block.endLineExclusive; index += 1) {
    const lineText = String(sourceLines[index] || "");
    if (!lineText.trim()) {
      continue;
    }
    if (!WORK_LOG_PARENT_RE.exec(lineText)) {
      continue;
    }
    if (findNearestParentListItem(sourceLines, index) === taskIndex) {
      const indentMatch = /^([ \t]*)/.exec(lineText);
      const markerMatch = /^[ \t]*(?:>\s*)*([-*+]|\d+[.)])/.exec(lineText);
      return {
        line: index,
        indent: indentMatch ? indentMatch[1] : "",
        marker: markerMatch ? markerMatch[1] : "-",
      };
    }
  }
  return null;
}

function getLaneTaskChildIndent(lines, taskLine) {
  const sourceLines = Array.isArray(lines) ? lines : [];
  const taskIndex = Math.floor(numericOrDefault(taskLine, Number.NaN));
  const parentIndent = Number.isFinite(taskIndex)
    ? getBulletIndent(String(sourceLines[taskIndex] || ""))
    : "";
  const block = findCurrentBulletChildBlock(sourceLines, taskIndex);
  for (let index = block.startLine; index < block.endLineExclusive; index += 1) {
    const lineText = String(sourceLines[index] || "");
    if (!lineText.trim()) {
      continue;
    }
    if (
      BULLET_PROPERTY_LIST_ITEM_RE.test(lineText) &&
      findNearestParentListItem(sourceLines, index) === taskIndex
    ) {
      return getBulletIndent(lineText);
    }
  }
  const unit = parentIndent && !parentIndent.includes("\t") ? parentIndent : "\t";
  return `${parentIndent}${unit}`;
}

// Insert one Work Log entry into `workingLines` (mutated in place) for the
// task at `taskLine`. Returns true when an entry was added.
function insertLaneWorkLogEntry(workingLines, taskLine, summary, dateText) {
  const normalized = normalizeLaneWorkSummary(summary);
  if (!normalized) {
    return false;
  }
  const entryText = formatLaneWorkLogEntry(normalized, dateText);
  if (!entryText) {
    return false;
  }
  const marker = findLaneWorkLogParent(workingLines, taskLine);
  if (marker) {
    const markerBlock = findCurrentBulletChildBlock(workingLines, marker.line);
    let entryIndent = `${marker.indent}\t`;
    let entryMarker = "-";
    for (let index = marker.line + 1; index < markerBlock.endLineExclusive; index += 1) {
      const lineText = String(workingLines[index] || "");
      if (!lineText.trim()) {
        continue;
      }
      if (
        BULLET_PROPERTY_LIST_ITEM_RE.test(lineText) &&
        findNearestParentListItem(workingLines, index) === marker.line
      ) {
        entryIndent = getBulletIndent(lineText);
        const markerMatch = /^[ \t]*(?:>\s*)*([-*+]|\d+[.)])/.exec(lineText);
        entryMarker = markerMatch ? markerMatch[1] : "-";
        break;
      }
    }
    workingLines.splice(marker.line + 1, 0, `${entryIndent}${entryMarker} ${entryText}`);
    return true;
  }
  const childIndent = getLaneTaskChildIndent(workingLines, taskLine);
  const taskIndent = getBulletIndent(String(workingLines[taskLine] || ""));
  const taskMarkerMatch = /^[ \t]*(?:>\s*)*([-*+]|\d+[.)])/.exec(
    String(workingLines[taskLine] || ""),
  );
  const taskMarker = taskMarkerMatch ? taskMarkerMatch[1] : "-";
  void taskMarker;
  const block = findCurrentBulletChildBlock(workingLines, taskLine);
  const markerLine = `${childIndent}- ${WORK_LOG_EMOJI} **${WORK_LOG_LABEL}**`;
  const entryLine = `${childIndent}\t- ${entryText}`;
  void taskIndent;
  workingLines.splice(block.endLineExclusive, 0, markerLine, entryLine);
  return true;
}

// Scheduling Work Log eligibility: the explicit target's validated line must be
// a real open `#task` in Pending (`/`) or Next (`*`) before any schedule
// propagation, checkbox recovery/blocking, freshness stamp, or cancellation.
// Determined from the original status, never from links or the postimage
// (which may already be `[?]` after a future-date prune).
function isSchedulingWorkLogStatus(status) {
  return status === "/" || status === "*";
}

function isSchedulingWorkLogRawLine(rawLine) {
  const status = getObsidianTaskCheckboxStatus(String(rawLine || ""));
  if (!isSchedulingWorkLogStatus(status)) {
    return false;
  }
  return isObsidianTaskLine(String(rawLine || ""));
}

function isPendingWorkLogTargetRawLine(rawLine) {
  const line = String(rawLine || "");
  return (
    getObsidianTaskCheckboxStatus(line) === "/" &&
    isObsidianTaskLine(line)
  );
}

function normalizeSchedulingWorkSummary(value) {
  return normalizeLaneWorkSummary(value);
}

function hasSchedulingWorkLogInput(workLog) {
  if (!workLog || typeof workLog !== "object") {
    return false;
  }
  return Boolean(normalizeSchedulingWorkSummary(workLog.summary));
}

function resolveSchedulingWorkLogDateText(workLog, fallbackDate) {
  if (workLog && typeof workLog.dateText === "string" && workLog.dateText) {
    return String(workLog.dateText);
  }
  if (typeof fallbackDate === "string" && fallbackDate) {
    return String(fallbackDate);
  }
  return formatBulletPropertyDate(getLocalDateStart(new Date()));
}

// Note-plus-identity key for a scheduling target. Linked notes can share a
// line number, so eligibility and review counts never use line alone.
function schedulingWorkLogTargetIdentity(target) {
  if (!target || typeof target !== "object") {
    return "";
  }
  const path = typeof target.path === "string" ? target.path : "";
  const blockId =
    normalizeBulletPropertyValue(target.blockId) ||
    getTrailingBlockId(String(target.rawLine || "")) ||
    "";
  if (blockId) {
    return `${path}#^${blockId}`;
  }
  if (Number.isInteger(target.line)) {
    return `${path}::${target.line}`;
  }
  return "";
}

function freezeSchedulingWorkLogTargets(targets) {
  return Object.freeze(
    (Array.isArray(targets) ? targets : [])
      .filter((target) => target && Number.isInteger(target.line))
      .map((target) =>
        Object.freeze({
          path: typeof target.path === "string" ? target.path : "",
          line: target.line,
          rawLine: String(target.rawLine || ""),
          blockId:
            normalizeBulletPropertyValue(target.blockId) ||
            getTrailingBlockId(String(target.rawLine || "")) ||
            "",
        }),
      ),
  );
}

function collectSchedulingWorkLogTargetIdentities(targets) {
  const identities = new Set();
  for (const target of Array.isArray(targets) ? targets : []) {
    const identity = schedulingWorkLogTargetIdentity(target);
    if (identity) {
      identities.add(identity);
    }
  }
  return identities;
}

function collectSchedulingWorkLogEligibleIdentities(targets) {
  const eligible = new Set();
  for (const target of Array.isArray(targets) ? targets : []) {
    if (!isSchedulingWorkLogRawLine(target && target.rawLine)) {
      continue;
    }
    const identity = schedulingWorkLogTargetIdentity(target);
    if (identity) {
      eligible.add(identity);
    }
  }
  return eligible;
}

function schedulingWorkLogSnapshotChanged(frozen, currentTargets) {
  const current = freezeSchedulingWorkLogTargets(currentTargets);
  const previous = freezeSchedulingWorkLogTargets(frozen);
  if (previous.length !== current.length) {
    return true;
  }
  for (let index = 0; index < previous.length; index += 1) {
    const left = previous[index];
    const right = current[index];
    if (
      !left ||
      !right ||
      left.path !== right.path ||
      left.line !== right.line ||
      left.rawLine !== right.rawLine ||
      left.blockId !== right.blockId
    ) {
      return true;
    }
  }
  return false;
}

function getScheduleReviewHints(options = {}) {
  const hints = [
    {
      keys: ["↵"],
      label: options.empty ? "Skip optional logs" : "Apply schedule",
    },
  ];
  if (options.hasWorkLog) {
    hints.push({ keys: ["tab"], label: "Next field" });
  }
  hints.push({ keys: ["esc"], label: "Cancel" });
  return hints;
}

// Pure planner for the combined Task Card schedule review. A review is needed
// when the reason is still unknown or any explicit Next/Pending target
// qualifies for a Work Log. Inline/skip reasons with no Work target dispatch
// immediately.
// ---- src/230-schedule-review.js ----
function planScheduleReview(options = {}) {
  const dateItem = options.dateItem || null;
  const from = normalizeBulletPropertyValue(options.from);
  const to = normalizeBulletPropertyValue(
    options.to || (dateItem && dateItem.value) || "",
  );
  const reasonText = normalizeScheduleReasonText(options.reason);
  const reasonSupplied = options.reasonSupplied === true;
  const targets = freezeSchedulingWorkLogTargets(options.targets);
  const totalIdentities = collectSchedulingWorkLogTargetIdentities(targets);
  const eligibleIdentities = collectSchedulingWorkLogEligibleIdentities(targets);
  const totalCount = totalIdentities.size || targets.length;
  const eligibleCount = eligibleIdentities.size;
  const needsWorkLog = eligibleCount > 0;
  const needsReason = !reasonSupplied;
  const needsReview = needsReason || needsWorkLog;
  const isProject = options.isProject === true;
  const isBatch = totalCount > 1;
  const baseDate =
    options.baseDate instanceof Date
      ? getLocalDateStart(options.baseDate)
      : getLocalDateStart(new Date());
  const validation = validateProjectScheduledDate(to);
  const scheduledDate = validation.valid
    ? projectScheduleLocalDate(validation)
    : null;
  const offset =
    scheduledDate instanceof Date
      ? getLocalDayOffset(baseDate, scheduledDate)
      : null;
  const future = Number.isInteger(offset) && offset > 0;
  const effects = [];
  if (from && to && from !== to) {
    effects.push(`${from}${SCHEDULE_LOG_TRANSITION}${to}`);
  } else if (to) {
    effects.push(`scheduled → ${to}`);
  }
  if (scheduledDate instanceof Date) {
    effects.push(getBulletPropertyDateWeekday(scheduledDate));
    if (Number.isInteger(offset)) {
      effects.push(formatRelativeDayOffset(offset));
    }
  }
  if (isProject) {
    effects.push("propagates to project tasks");
  }
  if (future) {
    effects.push("future date marks Blocked");
  }
  if (needsWorkLog) {
    const taskWord = eligibleCount === 1 ? "task" : "tasks";
    effects.push(
      isBatch
        ? `${eligibleCount} of ${totalCount} ${taskWord} qualify for Work Log`
        : eligibleCount === 1
          ? "1 task qualifies for Work Log"
          : `${eligibleCount} tasks qualify for Work Log`,
    );
  }
  effects.push("nothing written yet");
  return Object.freeze({
    dateItem,
    from,
    to,
    reason: reasonText.reason,
    reasonEmpty: reasonText.empty,
    reasonHasInlineField: reasonText.hasInlineField,
    reasonSupplied,
    needsReason,
    needsWorkLog,
    needsReview,
    targets,
    totalCount,
    eligibleCount,
    isBatch,
    isProject,
    future,
    title: isBatch ? `Schedule ${totalCount} tasks` : "Schedule task",
    focusField: needsReason ? "reason" : needsWorkLog ? "summary" : "reason",
    effects: Object.freeze(effects),
    scheduleSummary: effects.filter((part) => part !== "nothing written yet").join(" · "),
  });
}

// Original lines (pre-batch `target.line` values) whose validated `rawLine`
// qualifies for a scheduling Work Log. Propagation-only tasks are never in
// `targets`, so they are excluded by construction. Prompt counting uses
// identity keys; writers still map these original lines.
function collectSchedulingWorkLogEligibleOriginalLines(targets) {
  const eligible = new Set();
  for (const target of Array.isArray(targets) ? targets : []) {
    if (
      target &&
      Number.isInteger(target.line) &&
      isSchedulingWorkLogRawLine(target.rawLine)
    ) {
      eligible.add(target.line);
    }
  }
  return eligible;
}

// Insert one Work Log entry per eligible target into `workingLines` (mutated
// in place). `mappedLinesByOriginal` maps original `target.line` to the
// current line in `workingLines` after task edits, frontmatter shifts, Cancel
// Log insertion, and Schedule Log insertion. Applies bottom-up so an earlier
// insert never invalidates a later target's mapped line. Returns the number
// of entries written. Blank summaries write nothing and never create a
// marker (insertLaneWorkLogEntry already enforces this).
function applySchedulingWorkLogsToLines(
  workingLines,
  mappedLinesByOriginal,
  eligibleOriginalLines,
  summary,
  dateText,
) {
  const normalized = normalizeSchedulingWorkSummary(summary);
  if (!normalized || !Array.isArray(workingLines)) {
    return 0;
  }
  const eligible =
    eligibleOriginalLines instanceof Set
      ? eligibleOriginalLines
      : new Set();
  const entries = [];
  if (mappedLinesByOriginal instanceof Map) {
    for (const [originalLine, currentLine] of mappedLinesByOriginal) {
      if (!eligible.has(originalLine)) {
        continue;
      }
      if (!Number.isInteger(currentLine)) {
        continue;
      }
      entries.push({ originalLine, currentLine });
    }
  }
  entries.sort((a, b) => b.currentLine - a.currentLine);
  let written = 0;
  for (const entry of entries) {
    if (
      insertLaneWorkLogEntry(
        workingLines,
        entry.currentLine,
        normalized,
        dateText,
      )
    ) {
      written += 1;
    }
  }
  return written;
}

// Plan a lane commit/release across the task lines of one note's content.
// Commit wins when any target is Ready; otherwise release. Pass `summary`
// plus `dateText` to log an optional Work Log entry on each released In
// Progress task (blank writes nothing). Stale preimages (a line changed or
// stopped being a task) refuse the whole batch.
function planTaskLaneBatch(content, session, options = {}) {
  const text = String(content || "");
  const source = splitMarkdownContent(text);
  const contexts = getMarkdownLineContexts(text);
  const targets =
    session && Array.isArray(session.targets) ? session.targets : [];
  const invalid = (error, stale = false) =>
    Object.freeze({
      valid: false,
      error,
      stale,
      mode: null,
      changedTaskCount: 0,
      blockedSkipped: 0,
      skippedClosedCount: 0,
      workLogWrittenCount: 0,
      released: Object.freeze([]),
      content: text,
    });
  if (targets.length === 0) {
    return invalid("No tasks to update");
  }
  for (const target of targets) {
    const live =
      Number.isInteger(target.line) &&
      target.line >= 0 &&
      target.line < source.lines.length
        ? source.lines[target.line]
        : undefined;
    if (
      live !== target.rawLine ||
      !isObsidianTaskAtLine(text, target.line, contexts, source.lines)
    ) {
      return invalid("A task changed while the picker was open", true);
    }
  }
  const statuses = targets.map((target) =>
    getObsidianTaskCheckboxStatus(target.rawLine || ""),
  );
  const hasReady = statuses.some((status) => status === " ");
  const mode = hasReady ? "commit" : "release";
  const summary = normalizeLaneWorkSummary(options.summary);
  const dateText = String(options.dateText || "");
  // Freshness is the last transformation of the task line (nav-stamps). The
  // stamper itself refuses closed and recurring lines, so those never stamp.
  // Pure planners take the stamper as an injected option (identity by default).
  const laneStamper = resolveFreshStamper(options);
  const laneFreshDateText = resolveFreshDateText(options);
  const workingLines = source.lines.slice();
  let changedTaskCount = 0;
  let blockedSkipped = 0;
  let skippedClosedCount = 0;
  let workLogWrittenCount = 0;
  const released = [];
  // Work Log insertions shift later lines, so apply bottom-up.
  const ordered = targets
    .map((target, index) => ({ target, status: statuses[index] }))
    .sort((a, b) => b.target.line - a.target.line);
  for (const { target, status } of ordered) {
    const oldLine = String(workingLines[target.line] || "");
    if (mode === "commit") {
      if (status === " ") {
        let nextLine = replaceObsidianTaskCheckboxStatus(oldLine, "*");
        if (laneStamper) {
          nextLine = applyFreshStampLine(nextLine, laneStamper, laneFreshDateText);
        }
        if (nextLine !== oldLine) {
          changedTaskCount += 1;
        }
        workingLines[target.line] = nextLine;
      } else if (status === "?") {
        blockedSkipped += 1;
      } else if (status === "x" || status === "X" || status === "-") {
        skippedClosedCount += 1;
      }
      continue;
    }
    if (status === "*" || status === "/") {
      let nextLine = replaceObsidianTaskCheckboxStatus(oldLine, " ");
      if (laneStamper) {
        nextLine = applyFreshStampLine(nextLine, laneStamper, laneFreshDateText);
      }
      if (nextLine !== oldLine) {
        changedTaskCount += 1;
      }
      workingLines[target.line] = nextLine;
      const blockId = getTrailingBlockId(nextLine);
      released.push(
        Object.freeze({
          line: target.line,
          blockId: blockId || null,
          fromStatus: status,
        }),
      );
      if (status === "/" && summary) {
        if (insertLaneWorkLogEntry(workingLines, target.line, summary, dateText)) {
          workLogWrittenCount += 1;
        }
      }
    } else if (status === "?") {
      blockedSkipped += 1;
    } else if (status === "x" || status === "X" || status === "-") {
      skippedClosedCount += 1;
    }
  }
  if (changedTaskCount === 0) {
    if (blockedSkipped > 0 && skippedClosedCount === 0) {
      return invalid("Blocked is derived; no tasks were updated");
    }
    return invalid("No tasks to update");
  }
  released.sort((a, b) => a.line - b.line);
  return Object.freeze({
    valid: true,
    error: null,
    stale: false,
    mode,
    changedTaskCount,
    blockedSkipped,
    skippedClosedCount,
    workLogWrittenCount,
    released: Object.freeze(released),
    content: workingLines.join(source.lineEnding),
  });
}

// Build the lane Notice. Budget suffixes come from the ledger-tools api v2
// read before the write, adjusted by the number of tasks that changed,
// because the Tasks cache lags behind the write. They are omitted when the
// api is unavailable. Over-cap counts gain a red dot plus the weekly-review
// hint.
function buildLaneToggleNotice(details = {}) {
  const mode = details.mode === "release" ? "release" : "commit";
  const changed = Math.max(
    0,
    Math.floor(numericOrDefault(details.changedTaskCount, 0)),
  );
  const arrow = "→";
  const dest = mode === "release" ? "Ready" : "Next";
  let text = `${arrow} ${dest} · ${formatCountLabel(changed, "task")}`;
  const unlinked = Math.max(
    0,
    Math.floor(numericOrDefault(details.unlinkedFromToday, 0)),
  );
  if (mode === "release" && unlinked > 0) {
    text += ` · unlinked ${unlinked} from today`;
  }
  const blocked = Math.max(
    0,
    Math.floor(numericOrDefault(details.blockedSkipped, 0)),
  );
  if (blocked > 0) {
    text += ` · ${blocked} Blocked skipped — Blocked is derived`;
  }
  const budgets = details.laneBudgets || null;
  const parts = [];
  if (
    budgets &&
    budgets.next &&
    Number.isFinite(Math.floor(Number(budgets.next.count))) &&
    Number.isFinite(Math.floor(Number(budgets.next.cap)))
  ) {
    const delta =
      mode === "release"
        ? -Math.max(
            0,
            Math.floor(numericOrDefault(details.releasedNextCount, changed)),
          )
        : changed;
    void delta;
    const nextAfter = Math.max(
      0,
      Math.floor(Number(budgets.next.count)) +
        (mode === "release"
          ? -Math.floor(numericOrDefault(details.releasedNextCount, 0))
          : changed),
    );
    const nextCap = Math.floor(Number(budgets.next.cap));
    parts.push(`NEXT ${nextAfter}/${nextCap}`);
    if (nextAfter > nextCap) {
      parts.push("🔴 · prune at the weekly review");
    }
  }
  if (
    budgets &&
    budgets.pending &&
    Number.isFinite(Math.floor(Number(budgets.pending.count))) &&
    Number.isFinite(Math.floor(Number(budgets.pending.cap)))
  ) {
    const pendingAfter = Math.max(
      0,
      Math.floor(Number(budgets.pending.count)) +
        (mode === "release"
          ? -Math.floor(numericOrDefault(details.releasedPendingCount, 0))
          : 0),
    );
    const pendingCap = Math.floor(Number(budgets.pending.cap));
    parts.push(`PENDING ${pendingAfter}/${pendingCap}`);
    if (pendingAfter > pendingCap) {
      parts.push("🔴 · prune at the weekly review");
    }
  }
  // Deduplicate the prune hint when both lanes are over.
  const deduped = [];
  let hintSeen = false;
  for (const part of parts) {
    if (part.includes("prune at the weekly review")) {
      if (hintSeen) {
        continue;
      }
      hintSeen = true;
    }
    deduped.push(part);
  }
  if (deduped.length > 0) {
    text += ` · ${deduped.join(" · ")}`;
  }
  return text;
}

// Read the ledger-tools lane budgets for the Notice, or null when the api
// is missing, older than v2, or unusable. Never throws and never awaits:
// callers read synchronously before the write.
function readLaneBudgets(app) {
  try {
    const plugins = app && app.plugins && app.plugins.plugins;
    const holder = plugins && plugins["bob-ledger-tools"];
    const api = holder && holder.api;
    if (!api || Number(api.version) < 2) {
      return null;
    }
    if (
      typeof api.nextBudget !== "function" ||
      typeof api.pendingBudget !== "function"
    ) {
      return null;
    }
    const next = api.nextBudget();
    const pending = api.pendingBudget();
    if (next && typeof next.then === "function") {
      return null;
    }
    if (pending && typeof pending.then === "function") {
      return null;
    }
    const clean = (value) => {
      if (
        !value ||
        !Number.isFinite(Math.floor(Number(value.count))) ||
        !Number.isFinite(Math.floor(Number(value.cap)))
      ) {
        return null;
      }
      return Object.freeze({
        count: Math.floor(Number(value.count)),
        cap: Math.floor(Number(value.cap)),
        over: Boolean(value.over),
      });
    };
    const cleanNext = clean(next);
    const cleanPending = clean(pending);
    if (!cleanNext && !cleanPending) {
      return null;
    }
    return Object.freeze({ next: cleanNext, pending: cleanPending });
  } catch (error) {
    return null;
  }
}

// Describe the pinned lane picker row: null when no committable or
// releasable target exists, otherwise whether choosing the row would commit
// or release, how many tasks it covers, and whether a Work Log reason stage
// applies (release with an In Progress target).
function describeLaneRow(content, options = {}) {
  const text = String(content || "");
  const cursorLine = Math.floor(numericOrDefault(options.cursorLine, NaN));
  const taskSession = options.taskSession || null;
  const linkResolved = Array.isArray(options.linkResolved)
    ? options.linkResolved
    : null;
  const statusOf = (lineText) => getObsidianTaskCheckboxStatus(lineText);
  const summarize = (statuses) => {
    const hasReady = statuses.some((status) => status === " ");
    if (hasReady) {
      return Object.freeze({
        mode: "commit",
        detail: "lane · commit to Next",
        needsReason: false,
      });
    }
    const releasable = statuses.filter(
      (status) => status === "*" || status === "/",
    );
    if (releasable.length > 0) {
      return Object.freeze({
        mode: "release",
        detail: "lane · release to Ready",
        needsReason: releasable.some((status) => status === "/"),
      });
    }
    return null;
  };
  if (linkResolved) {
    if (linkResolved.length === 0) {
      return null;
    }
    const resolved = summarize(
      linkResolved.map((target) => statusOf(target.rawLine || "")),
    );
    if (!resolved) {
      return null;
    }
    return Object.freeze({
      kind: "link",
      count: linkResolved.length,
      mode: resolved.mode,
      detail: resolved.detail,
      needsReason: resolved.needsReason,
    });
  }
  if (
    taskSession &&
    taskSession.explicit &&
    Array.isArray(taskSession.targets) &&
    taskSession.targets.length > 0
  ) {
    const resolved = summarize(
      taskSession.targets.map((target) => statusOf(target.rawLine || "")),
    );
    if (!resolved) {
      return null;
    }
    return Object.freeze({
      kind: "task",
      count: taskSession.targets.length,
      mode: resolved.mode,
      detail: resolved.detail,
      needsReason: resolved.needsReason,
    });
  }
  if (
    Number.isFinite(cursorLine) &&
    isObsidianTaskLine(String(text.split(/\r?\n/)[cursorLine] || ""))
  ) {
    const line = String(text.split(/\r?\n/)[cursorLine] || "");
    const status = statusOf(line);
    if (status === " ") {
      return Object.freeze({
        kind: "task",
        count: 1,
        mode: "commit",
        detail: "lane · commit to Next",
        needsReason: false,
      });
    }
    if (status === "*" || status === "/") {
      return Object.freeze({
        kind: "task",
        count: 1,
        mode: "release",
        detail: "lane · release to Ready",
        needsReason: status === "/",
      });
    }
  }
  return null;
}

// True when a task line is recurring: it carries a Tasks `repeat` field in
// either the bracket `[repeat:: …]` or parenthetical `(repeat:: …)` shape, or
// the 🔁 emoji. Such tasks are refused by the cancel planner so Obsidian
// Tasks can create the next occurrence.
function isRecurringTaskLine(lineText) {
  const text = String(lineText || "");
  return (
    /\[repeat\s*::/i.test(text) ||
    /\(repeat\s*::/i.test(text) ||
    text.includes("🔁")
  );
}

// Status name for the cancel row detail: Ready (` `), Next (`*`),
// In Progress (`/`) or Blocked (`?`). Null for any other symbol.
function getTaskCancelStatusLabel(symbol) {
  switch (String(symbol ?? "")) {
    case " ":
      return "Ready";
    case "*":
      return "Next";
    case "/":
      return "In Progress";
    case "?":
      return "Blocked";
    default:
      return null;
  }
}

// Describe the pinned Cancel picker row: null when no open `#task` target
// exists (closed tasks, plain bullets, or no task under the cursor), otherwise
// the counts, recurring flag, and detail line the picker renders. `^prj`
// lifecycle tasks are allowed. In counted and link sessions a single recurring
// open target refuses the whole batch, so the detail reports the recurring
// refusal.
function describeCancelTaskRow(content, options = {}) {
  const text = String(content || "");
  const cursorLine = Math.floor(numericOrDefault(options.cursorLine, NaN));
  const taskSession = options.taskSession || null;
  const linkResolved = Array.isArray(options.linkResolved)
    ? options.linkResolved
    : null;

  const statusOf = (lineText) => getObsidianTaskCheckboxStatus(lineText);
  const isOpenStatus = (status) =>
    status !== null && OPEN_OBSIDIAN_TASK_STATUSES.has(status);

  if (linkResolved) {
    if (linkResolved.length === 0) {
      return null;
    }
    let openCount = 0;
    let closedCount = 0;
    let recurring = false;
    for (const target of linkResolved) {
      const rawLine = String((target && target.rawLine) || "");
      const status = statusOf(rawLine);
      if (isObsidianTaskLine(rawLine) && isOpenStatus(status)) {
        openCount += 1;
        if (isRecurringTaskLine(rawLine)) {
          recurring = true;
        }
      } else {
        closedCount += 1;
      }
    }
    if (openCount === 0) {
      return null;
    }
    if (recurring) {
      return Object.freeze({
        kind: "link",
        count: linkResolved.length,
        openCount,
        closedCount,
        recurring: true,
        fromStatus: null,
        detail: "recurring · use Obsidian Tasks",
      });
    }
    const sessionLike = {
      targets: linkResolved,
      resolved: linkResolved,
      actualCount: linkResolved.length,
      requestedCount: linkResolved.length,
      clamped: false,
    };
    const subtitle = getLinkPickerSessionSubtitle(sessionLike);
    const detail =
      closedCount > 0
        ? `${subtitle} → Cancelled · ${closedCount} already closed`
        : `${subtitle} → Cancelled`;
    return Object.freeze({
      kind: "link",
      count: linkResolved.length,
      openCount,
      closedCount,
      recurring: false,
      fromStatus: null,
      detail,
    });
  }

  if (
    taskSession &&
    Array.isArray(taskSession.targets) &&
    taskSession.targets.length > 0
  ) {
    let openCount = 0;
    let closedCount = 0;
    let recurring = false;
    for (const target of taskSession.targets) {
      const rawLine = String((target && target.rawLine) || "");
      const status = statusOf(rawLine);
      if (isObsidianTaskLine(rawLine) && isOpenStatus(status)) {
        openCount += 1;
        if (isRecurringTaskLine(rawLine)) {
          recurring = true;
        }
      } else {
        closedCount += 1;
      }
    }
    if (openCount === 0) {
      return null;
    }
    if (recurring) {
      return Object.freeze({
        kind: "task",
        count: taskSession.targets.length,
        openCount,
        closedCount,
        recurring: true,
        fromStatus: null,
        detail: "recurring · use Obsidian Tasks",
      });
    }
    const taskWord = openCount === 1 ? "task" : "tasks";
    const detail =
      closedCount > 0
        ? `${openCount} ${taskWord} → Cancelled · ${closedCount} already closed`
        : `${openCount} ${taskWord} → Cancelled · asks why`;
    return Object.freeze({
      kind: "task",
      count: taskSession.targets.length,
      openCount,
      closedCount,
      recurring: false,
      fromStatus: null,
      detail,
    });
  }

  if (Number.isFinite(cursorLine)) {
    const lines = text.split(/\r?\n/);
    const line = String(lines[cursorLine] || "");
    if (!isObsidianTaskLine(line)) {
      return null;
    }
    const status = statusOf(line);
    if (!isOpenStatus(status)) {
      return null;
    }
    const fromStatus = getTaskCancelStatusLabel(status);
    if (isRecurringTaskLine(line)) {
      return Object.freeze({
        kind: "task",
        count: 1,
        openCount: 1,
        closedCount: 0,
        recurring: true,
        fromStatus,
        detail: "recurring · use Obsidian Tasks",
      });
    }
    return Object.freeze({
      kind: "task",
      count: 1,
      openCount: 1,
      closedCount: 0,
      recurring: false,
      fromStatus,
      detail: `${fromStatus} → Cancelled · asks why`,
    });
  }

  return null;
}

// Plan a pure batch cancel across one note's content: set `[-]`, upsert
// `[cancelled:: date]`, and write the Cancel Log first-child/prepend/fallback
// entry for every open target. Closed targets are skipped. A single recurring
// open target refuses the whole batch. `details.reasonByLine` (a Map from
// original line to reason) overrides `details.reason` per target; callers that
// omit it get byte-identical output. Targets are processed bottom-up so
// insertions never shift pending lines. Pure and CRLF-preserving.
// ---- src/240-cancel-and-lanes.js ----
function planTaskCancelBatch(content, session, details = {}) {
  const text = String(content || "");
  const source = splitMarkdownContent(text);
  const contexts = getMarkdownLineContexts(text);
  const targets =
    session && Array.isArray(session.targets) ? session.targets : [];

  const invalid = (error, extra = {}) =>
    Object.freeze({
      valid: false,
      error,
      recurring: Boolean(extra.recurring),
      stale: Boolean(extra.stale),
      content: text,
      cancelledCount: 0,
      skippedClosedCount: 0,
      loggedCount: 0,
      createdLogCount: 0,
      fallbackLoggedCount: 0,
      cancelled: Object.freeze([]),
      cursorLineShift: (line) => line,
    });

  if (!session || session.valid === false || targets.length === 0) {
    return invalid("Counted task session is unavailable");
  }

  for (const target of targets) {
    const liveLine =
      Number.isInteger(target.line) &&
      target.line >= 0 &&
      target.line < source.lines.length
        ? source.lines[target.line]
        : undefined;
    if (
      liveLine !== target.rawLine ||
      !isObsidianTaskAtLine(text, target.line, contexts, source.lines)
    ) {
      return invalid("A counted task changed while the picker was open", {
        stale: true,
      });
    }
  }

  const dateText = normalizeBulletPropertyValue(details.date);
  if (!dateText) {
    return invalid("Cancel date is required");
  }
  const reasonInput = String(details.reason ?? "");
  const fallbackInput = String(details.fallbackReason ?? "");
  const reasonByLine =
    details.reasonByLine instanceof Map ? details.reasonByLine : null;

  let skippedClosedCount = 0;
  const openTargets = [];
  for (const target of targets) {
    const status = getObsidianTaskCheckboxStatus(target.rawLine || "");
    if (
      !isObsidianTaskLine(target.rawLine || "") ||
      !OPEN_OBSIDIAN_TASK_STATUSES.has(status)
    ) {
      skippedClosedCount += 1;
      continue;
    }
    openTargets.push(target);
  }

  if (openTargets.length === 0) {
    const finalOriginsEmpty = source.lines.map((_, index) => index);
    return Object.freeze({
      valid: true,
      error: null,
      recurring: false,
      stale: false,
      content: text,
      cancelledCount: 0,
      skippedClosedCount,
      loggedCount: 0,
      createdLogCount: 0,
      fallbackLoggedCount: 0,
      cancelled: Object.freeze([]),
      cursorLineShift: (line) => {
        const numeric = Math.floor(numericOrDefault(line, NaN));
        if (!Number.isFinite(numeric)) {
          return line;
        }
        const found = finalOriginsEmpty.indexOf(numeric);
        return found === -1 ? line : found;
      },
    });
  }

  for (const target of openTargets) {
    if (isRecurringTaskLine(target.rawLine || "")) {
      return invalid(
        "Recurring tasks are cancelled with Obsidian Tasks so the next occurrence is handled; no tasks were updated",
        { recurring: true },
      );
    }
  }

  const workingLines = source.lines.slice();
  const lineOrigins = source.lines.map((_, index) => index);
  let loggedCount = 0;
  let createdLogCount = 0;
  let fallbackLoggedCount = 0;
  const cancelled = [];

  const ordered = openTargets.slice().sort((a, b) => b.line - a.line);
  for (const target of ordered) {
    const oldLine = String(workingLines[target.line] || "");
    const status = getObsidianTaskCheckboxStatus(oldLine);
    const fromStatus = getTaskCancelStatusLabel(status);
    const blockId = getTrailingBlockId(oldLine);
    const idField = findBulletPropertyField(oldLine, "id");
    const normalizedId = idField
      ? normalizeBulletPropertyValue(idField.value)
      : "";
    const taskId = normalizedId || blockId || null;

    const replaced = replaceObsidianTaskCheckboxStatus(oldLine, "-");
    const upserted = upsertBulletProperty(replaced, "cancelled", dateText);
    const nextTaskLine = upserted.line;
    workingLines[target.line] = nextTaskLine;

    const targetReason =
      reasonByLine && reasonByLine.has(target.line)
        ? String(reasonByLine.get(target.line) ?? "")
        : reasonInput;
    const plan = planCancelLogEntry(
      workingLines.join(source.lineEnding),
      target.line,
      { date: dateText, reason: targetReason, fallbackReason: fallbackInput },
    );
    let logApplied = false;
    if (plan.valid && plan.changed) {
      const insertAt = Math.floor(numericOrDefault(plan.insertLine, NaN));
      if (Number.isFinite(insertAt) && insertAt >= 0) {
        const insertTexts = Array.isArray(plan.lineTexts)
          ? plan.lineTexts.slice()
          : [];
        workingLines.splice(insertAt, 0, ...insertTexts);
        lineOrigins.splice(
          insertAt,
          0,
          ...insertTexts.map(() => null),
        );
        logApplied = true;
        loggedCount += 1;
        if (plan.createdParent) {
          createdLogCount += 1;
        }
        if (plan.usedFallback) {
          fallbackLoggedCount += 1;
        }
      }
    } else if (
      !plan.valid &&
      plan.reason !== "empty-reason" &&
      plan.reason !== "no-cancel-log"
    ) {
      // Any other guard (out-of-range, non-bullet) cannot happen after the
      // staleness check above; treat it as a batch failure rather than a
      // silent skip so callers never report success on a half-written task.
      return invalid(plan.reason || "Cancel log could not be planned");
    }

    cancelled.push(
      Object.freeze({
        originalLine: target.line,
        blockId,
        taskId,
        fromStatus,
        logged: logApplied,
      }),
    );
  }

  cancelled.sort((a, b) => a.originalLine - b.originalLine);
  const finalOrigins = lineOrigins.slice();
  const cursorLineShift = (line) => {
    const numeric = Math.floor(numericOrDefault(line, NaN));
    if (!Number.isFinite(numeric)) {
      return line;
    }
    const found = finalOrigins.indexOf(numeric);
    return found === -1 ? line : found;
  };

  return Object.freeze({
    valid: true,
    error: null,
    recurring: false,
    stale: false,
    content: workingLines.join(source.lineEnding),
    cancelledCount: openTargets.length,
    skippedClosedCount,
    loggedCount,
    createdLogCount,
    fallbackLoggedCount,
    cancelled: Object.freeze(cancelled),
    cursorLineShift,
  });
}

// A task move uses the same count convention as counted property editing, but
// project lifecycle tasks are structural controls and therefore never become
// move targets. The first line must itself be movable; later ^prj tasks are
// skipped without consuming the requested count.
function discoverMovableObsidianTaskTargets(
  content,
  startLine,
  additionalTaskCount,
) {
  const text = String(content || "");
  const source = splitMarkdownContent(text);
  const line = Math.floor(numericOrDefault(startLine, Number.NaN));
  const additional = Math.max(
    0,
    Math.floor(numericOrDefault(additionalTaskCount, 0)),
  );
  const requestedCount = additional + 1;
  const contexts = getMarkdownLineContexts(text);
  const invalid = (error) =>
    Object.freeze({
      valid: false,
      error,
      explicit: additional > 0,
      startLine: Number.isFinite(line) ? line : null,
      requestedAdditionalCount: additional,
      requestedCount,
      actualCount: 0,
      clamped: false,
      targets: Object.freeze([]),
    });

  if (
    !Number.isFinite(line) ||
    !isObsidianTaskAtLine(text, line, contexts, source.lines)
  ) {
    return invalid("Move tasks must start on a real #task checkbox");
  }
  if (isProjectLifecycleTaskLine(source.lines[line])) {
    return invalid("Project lifecycle tasks cannot be moved");
  }

  const targets = [];
  for (
    let lineIndex = line;
    lineIndex < source.lines.length && targets.length < requestedCount;
    lineIndex += 1
  ) {
    if (
      isObsidianTaskAtLine(text, lineIndex, contexts, source.lines) &&
      !isProjectLifecycleTaskLine(source.lines[lineIndex])
    ) {
      targets.push(
        Object.freeze({
          line: lineIndex,
          rawLine: String(source.lines[lineIndex] || ""),
        }),
      );
    }
  }

  return Object.freeze({
    valid: true,
    error: null,
    explicit: additional > 0,
    startLine: line,
    requestedAdditionalCount: additional,
    requestedCount,
    actualCount: targets.length,
    clamped: targets.length < requestedCount,
    targets: Object.freeze(targets),
  });
}

function getTaskMoveColumn(text) {
  let column = 0;
  for (const character of String(text || "")) {
    column += character === "\t" ? 4 : 1;
  }
  return column;
}

// Return the Markdown container prefix before a line's content. The prefix may
// contain indentation and one or more blockquote markers. Keeping both its raw
// text and display column lets subtree detection handle nested/quoted tasks
// while still rebasing the captured block losslessly in the common case.
function parseTaskMoveContainerPrefix(lineText) {
  const text = String(lineText || "");
  let index = 0;
  let quoteDepth = 0;
  let initialIndentEnd = 0;
  let sawQuote = false;

  while (index < text.length) {
    const whitespaceStart = index;
    while (index < text.length && (text[index] === " " || text[index] === "\t")) {
      index += 1;
    }
    if (!sawQuote) {
      initialIndentEnd = index;
    }
    if (text[index] !== ">") {
      break;
    }
    sawQuote = true;
    quoteDepth += 1;
    index += 1;
    if (text[index] === " " || text[index] === "\t") {
      index += 1;
    }
    if (index === whitespaceStart) {
      break;
    }
  }

  const prefix = text.slice(0, index);
  const initialIndent = text.slice(0, initialIndentEnd);
  return Object.freeze({
    prefix,
    length: prefix.length,
    column: getTaskMoveColumn(prefix),
    quoteDepth,
    initialIndentColumn: getTaskMoveColumn(initialIndent),
  });
}

function parseTaskMoveListItem(lineText) {
  const text = String(lineText || "");
  const container = parseTaskMoveContainerPrefix(text);
  const remainder = text.slice(container.length);
  const markerMatch = /^(?:[-+*]|\d+[.)])[ \t]+/.exec(remainder);
  if (!markerMatch) {
    return null;
  }
  return Object.freeze({
    ...container,
    markerIndex: container.length,
    markerText: markerMatch[0],
    contentColumn: container.column + getTaskMoveColumn(markerMatch[0]),
  });
}

function isTaskMoveBlankLine(lineText) {
  return /^[\s>]*$/.test(String(lineText || ""));
}

function taskMoveLineIsDescendant(root, lineText) {
  const text = String(lineText || "");
  if (!root || isTaskMoveBlankLine(text)) {
    return false;
  }
  const candidate = parseTaskMoveContainerPrefix(text);
  if (candidate.quoteDepth < root.quoteDepth) {
    return false;
  }
  // A top-level blockquote immediately following an unquoted task is a sibling
  // block, not task content. An indented blockquote can still be a child.
  if (
    root.quoteDepth === 0 &&
    candidate.quoteDepth > 0 &&
    candidate.initialIndentColumn <= root.initialIndentColumn
  ) {
    return false;
  }
  return candidate.column >= root.contentColumn;
}

function captureTaskMoveSubtree(content, target) {
  const text = String(content || "");
  const source = splitMarkdownContent(text);
  const line = target && Number.isInteger(target.line) ? target.line : -1;
  const contexts = getMarkdownLineContexts(text);
  if (
    line < 0 ||
    line >= source.lines.length ||
    source.lines[line] !== target.rawLine ||
    !isObsidianTaskAtLine(text, line, contexts, source.lines) ||
    isProjectLifecycleTaskLine(source.lines[line])
  ) {
    return Object.freeze({
      valid: false,
      error: "A selected task changed before it could be moved",
    });
  }

  const root = parseTaskMoveListItem(source.lines[line]);
  if (!root) {
    return Object.freeze({ valid: false, error: "Selected task is not a list item" });
  }

  let endLineExclusive = line + 1;
  let pendingBlankEnd = endLineExclusive;
  for (let index = line + 1; index < source.lines.length; index += 1) {
    const candidate = String(source.lines[index] || "");
    if (isTaskMoveBlankLine(candidate)) {
      pendingBlankEnd = index + 1;
      continue;
    }
    if (!taskMoveLineIsDescendant(root, candidate)) {
      break;
    }
    endLineExclusive = index + 1;
    pendingBlankEnd = endLineExclusive;
  }

  // Blank lines are retained only when followed by deeper content. Trailing
  // separators stay with the source/destination section rather than the task.
  const blockLines = source.lines.slice(line, endLineExclusive);
  return Object.freeze({
    valid: true,
    error: null,
    startLine: line,
    endLineExclusive,
    lines: Object.freeze(blockLines),
    root,
    pendingBlankEnd,
    selectedTargetLines: Object.freeze([line]),
  });
}

function buildTaskMoveRanges(content, targets) {
  const captured = [];
  for (const target of Array.isArray(targets) ? targets : []) {
    const block = captureTaskMoveSubtree(content, target);
    if (!block.valid) {
      return Object.freeze({ valid: false, error: block.error, ranges: [] });
    }
    captured.push(block);
  }
  captured.sort((left, right) => left.startLine - right.startLine);

  const ranges = [];
  for (const block of captured) {
    const previous = ranges[ranges.length - 1];
    if (previous && block.startLine < previous.endLineExclusive) {
      previous.selectedTargetLines.push(block.startLine);
      continue;
    }
    ranges.push({
      startLine: block.startLine,
      endLineExclusive: block.endLineExclusive,
      lines: [...block.lines],
      root: block.root,
      selectedTargetLines: [...block.selectedTargetLines],
    });
  }

  return Object.freeze({
    valid: ranges.length > 0,
    error: ranges.length > 0 ? null : "No movable tasks were selected",
    ranges: Object.freeze(
      ranges.map((range) =>
        Object.freeze({
          ...range,
          lines: Object.freeze(range.lines),
          selectedTargetLines: Object.freeze(range.selectedTargetLines),
        }),
      ),
    ),
  });
}

function removeTaskMoveRanges(content, ranges) {
  const text = String(content || "");
  const source = splitMarkdownContent(text);
  const nextLines = source.lines.slice();
  const ordered = (Array.isArray(ranges) ? ranges : [])
    .slice()
    .sort((left, right) => right.startLine - left.startLine);
  if (ordered.length === 0) {
    return Object.freeze({
      valid: false,
      error: "No task ranges are available",
      content: text,
      nextLine: 0,
    });
  }

  for (const range of ordered) {
    const expected = Array.isArray(range.lines) ? range.lines : [];
    const live = nextLines.slice(range.startLine, range.endLineExclusive);
    if (
      live.length !== expected.length ||
      live.some((line, index) => line !== expected[index])
    ) {
      return Object.freeze({
        valid: false,
        error: "A selected task subtree changed before it could be moved",
        content: text,
        nextLine: range.startLine,
      });
    }

    let deleteCount = range.endLineExclusive - range.startLine;
    const before = nextLines[range.startLine - 1];
    const after = nextLines[range.endLineExclusive];
    if (
      before !== undefined &&
      after !== undefined &&
      String(before).trim() === "" &&
      String(after).trim() === ""
    ) {
      // Avoid leaving a doubled seam while preserving one existing separator.
      deleteCount += 1;
    }
    nextLines.splice(range.startLine, deleteCount);
  }

  const firstStart = Math.min(...ordered.map((range) => range.startLine));
  return Object.freeze({
    valid: true,
    error: null,
    content: nextLines.join(source.lineEnding),
    nextLine: Math.min(firstStart, Math.max(nextLines.length - 1, 0)),
  });
}

function rebaseTaskMoveBlock(range) {
  const lines = range && Array.isArray(range.lines) ? range.lines : [];
  const root = range && range.root;
  if (!root || lines.length === 0) {
    return Object.freeze([]);
  }
  return Object.freeze(
    lines.map((line, index) => {
      const text = String(line || "");
      if (isTaskMoveBlankLine(text)) {
        return "";
      }
      if (index === 0) {
        return text.slice(root.markerIndex);
      }
      if (root.prefix && text.startsWith(root.prefix)) {
        return text.slice(root.prefix.length);
      }
      // Mixed tabs/spaces or quote spacing can make the raw prefix differ.
      // Remove no more than the root's structural display width.
      let column = 0;
      let offset = 0;
      while (offset < text.length && column < root.column) {
        column += text[offset] === "\t" ? 4 : 1;
        offset += 1;
      }
      return text.slice(offset);
    }),
  );
}

function flattenTaskMoveBlocks(blocks) {
  const lines = [];
  for (const block of Array.isArray(blocks) ? blocks : []) {
    const blockLines = Array.isArray(block) ? block.map(String) : [];
    if (blockLines.length === 0) {
      continue;
    }
    lines.push(...blockLines);
  }
  return lines;
}

function parseTaskMoveDestinationFrontmatter(content, options = {}) {
  const text = String(content || "");
  const source = splitMarkdownContent(text);
  if (!startsWithFrontmatter(source.lines)) {
    return Object.freeze({ valid: false, error: "Destination has no YAML frontmatter" });
  }
  let closingLine = -1;
  for (let index = 1; index < source.lines.length; index += 1) {
    if (FRONTMATTER_DELIMITER_RE.test(source.lines[index])) {
      closingLine = index;
      break;
    }
  }
  if (closingLine === -1) {
    return Object.freeze({ valid: false, error: "Destination frontmatter is not closed" });
  }

  let data;
  try {
    const yamlParser = options.parseYaml || parseYaml;
    data = yamlParser(source.lines.slice(1, closingLine).join("\n"));
  } catch (error) {
    return Object.freeze({ valid: false, error: "Destination frontmatter is malformed" });
  }
  if (!data || typeof data !== "object" || Array.isArray(data)) {
    return Object.freeze({ valid: false, error: "Destination frontmatter must be a mapping" });
  }

  const noteInfo = getChildNoteInfo(data, options.now || new Date());
  if (noteInfo.kind === "area") {
    return Object.freeze({
      valid: true,
      error: null,
      kind: "area",
      statusKey: "",
      data,
      noteInfo,
    });
  }
  if (
    noteInfo.kind === "project" &&
    TASK_MOVE_OPEN_PROJECT_STATUSES.has(noteInfo.statusKey)
  ) {
    return Object.freeze({
      valid: true,
      error: null,
      kind: "project",
      statusKey: noteInfo.statusKey,
      data,
      noteInfo,
    });
  }

  const error =
    noteInfo.kind === "project"
      ? "Destination project is no longer open"
      : "Destination is no longer an area or open project";
  return Object.freeze({ valid: false, error, kind: noteInfo.kind, data, noteInfo });
}

function collectTaskMoveDestinations(files, sourcePath, getNoteInfo) {
  const source = normalizeVaultRelativePath(sourcePath);
  const infoFor =
    typeof getNoteInfo === "function"
      ? getNoteInfo
      : () => getChildNoteInfo(null);
  return (Array.isArray(files) ? files : [])
    .filter((file) => {
      const path = normalizeVaultRelativePath(file && file.path);
      return (
        path &&
        MARKDOWN_EXTENSION_RE.test(path) &&
        path !== source &&
        !TASK_MOVE_TEMPLATE_PATHS.has(path)
      );
    })
    .map((file) => ({ file, noteInfo: infoFor(file) }))
    .filter(
      ({ noteInfo }) =>
        noteInfo &&
        (noteInfo.kind === "area" ||
          (noteInfo.kind === "project" &&
            TASK_MOVE_OPEN_PROJECT_STATUSES.has(noteInfo.statusKey))),
    )
    .sort((left, right) => {
      const leftPath = String(left.file.path || "");
      const rightPath = String(right.file.path || "");
      return leftPath < rightPath ? -1 : leftPath > rightPath ? 1 : 0;
    })
    .map((entry) => Object.freeze(entry));
}

function getTaskMoveSectionEnd(lines, headerIndex) {
  let inFence = null;
  for (let index = headerIndex + 1; index < lines.length; index += 1) {
    const line = String(lines[index] || "");
    if (inFence) {
      if (isClosingFence(line, inFence)) {
        inFence = null;
      }
      continue;
    }
    const openingFence = getFenceOpening(line);
    if (openingFence) {
      inFence = openingFence;
      continue;
    }
    if (SECTION_HEADER_RE.test(line)) {
      return index;
    }
  }
  return lines.length;
}

function insertTaskMoveBlocks(content, blocks, destinationKind) {
  const text = String(content || "");
  const source = splitMarkdownContent(text);
  const movedLines = flattenTaskMoveBlocks(blocks);
  if (movedLines.length === 0) {
    return Object.freeze({ valid: false, error: "No task content is available", content: text });
  }

  let headerIndex = findProjectTasksHeaderIndex(source.lines);
  if (headerIndex === -1) {
    if (destinationKind !== "area") {
      return Object.freeze({
        valid: false,
        error: "Open project destination has no valid ## Tasks section",
        content: text,
      });
    }
    const hadTerminalNewline = /\r?\n$/.test(text);
    let next = text;
    if (next && !next.endsWith(source.lineEnding)) {
      next += source.lineEnding;
    }
    if (next && !next.endsWith(source.lineEnding + source.lineEnding)) {
      next += source.lineEnding;
    }
    next += `${PROJECT_TASKS_HEADER}${source.lineEnding}${source.lineEnding}`;
    const insertedLine = next.split(source.lineEnding).length - 1;
    next += movedLines.join(source.lineEnding);
    if (hadTerminalNewline) {
      next += source.lineEnding;
    }
    return Object.freeze({ valid: true, error: null, content: next, createdSection: true, insertedLine });
  }

  const sectionEnd = getTaskMoveSectionEnd(source.lines, headerIndex);
  const nonblankBody = [];
  for (let index = headerIndex + 1; index < sectionEnd; index += 1) {
    if (String(source.lines[index] || "").trim() !== "") {
      nonblankBody.push(index);
    }
  }
  const placeholderIndex =
    nonblankBody.length === 1 &&
    PROJECT_SOURCE_TASK_LINE_RE.test(source.lines[nonblankBody[0]]) &&
    source.lines[nonblankBody[0]].includes(PROJECT_TASKS_PLACEHOLDER)
      ? nonblankBody[0]
      : -1;

  let nextLines;
  let insertedLine;
  if (placeholderIndex !== -1) {
    nextLines = source.lines
      .slice(0, placeholderIndex)
      .concat(movedLines, source.lines.slice(placeholderIndex + 1));
    insertedLine = placeholderIndex;
  } else {
    let insertAt = sectionEnd;
    while (
      insertAt > headerIndex + 1 &&
      String(source.lines[insertAt - 1] || "").trim() === ""
    ) {
      insertAt -= 1;
    }
    const insertion = [];
    if (insertAt === headerIndex + 1) {
      insertion.push("");
    }
    insertion.push(...movedLines);
    nextLines = source.lines
      .slice(0, insertAt)
      .concat(insertion, source.lines.slice(insertAt));
    insertedLine = insertAt + (insertion.length - movedLines.length);
  }

  return Object.freeze({
    valid: true,
    error: null,
    content: nextLines.join(source.lineEnding),
    createdSection: false,
    insertedLine,
  });
}

function collectTaskMoveBlockIds(content) {
  const text = String(content || "");
  const source = splitMarkdownContent(text);
  const contexts = getMarkdownLineContexts(text);
  const ids = new Set();
  for (let index = 0; index < source.lines.length; index += 1) {
    const context = contexts[index];
    if (!context || context.inFrontmatter || context.inFence) {
      continue;
    }
    const id = getTrailingBlockId(source.lines[index]);
    if (id) {
      ids.add(id);
    }
  }
  return ids;
}

function prepareTaskMoveBlockIdentities(blocks, sourcePath, destinationPath) {
  const nextBlocks = (Array.isArray(blocks) ? blocks : []).map((block) =>
    Array.isArray(block) ? block.map(String) : [],
  );
  const movedBlockIds = new Set();
  const idReplacements = new Map();

  for (const block of nextBlocks) {
    for (let index = 0; index < block.length; index += 1) {
      const line = block[index];
      const blockId = getTrailingBlockId(line);
      if (!blockId) {
        continue;
      }
      if (movedBlockIds.has(blockId)) {
        return Object.freeze({ valid: false, error: `Moved task block ID is duplicated: ${blockId}` });
      }
      movedBlockIds.add(blockId);

      if (!isObsidianTaskLine(line)) {
        continue;
      }
      const oldCanonicalId = tryDependencyId(sourcePath, blockId);
      const newCanonicalId = tryDependencyId(destinationPath, blockId);
      if (!oldCanonicalId || !newCanonicalId) {
        return Object.freeze({
          valid: false,
          error: `Task block ID cannot be encoded for the move: ${blockId}`,
        });
      }
      const idFields = parseBulletPropertyFields(line).filter(
        (field) => field.key === "id",
      );
      if (idFields.length > 1) {
        return Object.freeze({
          valid: false,
          error: `Task has multiple [id::] fields: ${blockId}`,
        });
      }
      if (idFields.length === 1) {
        const existingId = normalizeBulletPropertyValue(idFields[0].value);
        if (existingId !== oldCanonicalId && existingId !== blockId) {
          return Object.freeze({
            valid: false,
            error: `Task has an ambiguous [id::] value: ${blockId}`,
          });
        }
        if (existingId) {
          idReplacements.set(existingId, newCanonicalId);
        }
      }
      idReplacements.set(oldCanonicalId, newCanonicalId);
      block[index] = upsertBulletProperty(line, "id", newCanonicalId).line;
    }
  }

  return Object.freeze({
    valid: true,
    error: null,
    blocks: Object.freeze(nextBlocks.map((block) => Object.freeze(block))),
    movedBlockIds,
    idReplacements,
  });
}

function taskMoveLinkNoteMatchesPath(note, filePath) {
  const target = normalizeVaultRelativePath(note).replace(MARKDOWN_EXTENSION_RE, "");
  const path = normalizeVaultRelativePath(filePath).replace(MARKDOWN_EXTENSION_RE, "");
  if (!target || !path) {
    return false;
  }
  const basename = path.slice(path.lastIndexOf("/") + 1);
  return target === path || target === basename;
}

// ---- src/250-task-move.js ----
function rewriteTaskMoveBlockLinks(content, options = {}) {
  const text = String(content || "");
  const sourcePath = normalizeVaultRelativePath(options.sourcePath);
  const destinationPath = normalizeVaultRelativePath(options.destinationPath);
  const currentPath = normalizeVaultRelativePath(options.currentPath);
  const role = String(options.role || "external");
  const movedBlockIds =
    options.movedBlockIds instanceof Set
      ? options.movedBlockIds
      : new Set(options.movedBlockIds || []);
  const sourceBlockIds =
    options.sourceBlockIds instanceof Set
      ? options.sourceBlockIds
      : new Set(options.sourceBlockIds || []);
  const sourceNote = sourcePath.replace(MARKDOWN_EXTENSION_RE, "");
  const destinationNote = destinationPath.replace(MARKDOWN_EXTENSION_RE, "");

  const nextNote = (note, blockId, markdown) => {
    const pathless = !String(note || "").trim();
    if (role === "moved" && pathless) {
      if (movedBlockIds.has(blockId)) {
        return note;
      }
      if (sourceBlockIds.has(blockId)) {
        return markdown ? sourcePath : sourceNote;
      }
      return note;
    }

    const targetsSource = pathless
      ? currentPath === sourcePath
      : taskMoveLinkNoteMatchesPath(note, sourcePath);
    if (targetsSource && movedBlockIds.has(blockId)) {
      return markdown ? destinationPath : destinationNote;
    }
    return note;
  };

  const rewriteLine = (line) => {
    let nextLine = String(line || "").replace(
      /(!?)\[\[([^\]\n|#]*?)#\^([A-Za-z0-9-]+)(\|[^\]\n]*)?\]\]/g,
      (match, embed, note, blockId, alias = "") => {
        const replacementNote = nextNote(note, blockId, false);
        return replacementNote === note
          ? match
          : `${embed}[[${replacementNote}#^${blockId}${alias || ""}]]`;
      },
    );
    nextLine = nextLine.replace(
      /(!?\[[^\]\n]*(?:\\.[^\]\n]*)*\]\()([^\s)#]*?)#\^([A-Za-z0-9-]+)([^)]*)\)/g,
      (match, prefix, note, blockId, suffix = "") => {
        const replacementNote = nextNote(note, blockId, true);
        return replacementNote === note
          ? match
          : `${prefix}${replacementNote}#^${blockId}${suffix || ""})`;
      },
    );
    return nextLine;
  };
  const source = splitMarkdownContent(text);
  const contexts = getMarkdownLineContexts(text);
  const next = source.lines
    .map((line, index) =>
      contexts[index] && contexts[index].inFence ? line : rewriteLine(line),
    )
    .join(source.lineEnding);
  return Object.freeze({ content: next, changed: next !== text });
}

function rewriteTaskMoveReferences(content, options = {}) {
  const text = String(content || "");
  const dependencyRewrite = rewriteDependsOnIdsInContent(
    text,
    options.idReplacements || new Map(),
  );
  return rewriteTaskMoveBlockLinks(dependencyRewrite.content, options);
}

function planTaskMoveAcrossFiles(options = {}) {
  const sourcePath = normalizeVaultRelativePath(options.sourcePath);
  const destinationPath = normalizeVaultRelativePath(options.destinationPath);
  const sourceContent = String(options.sourceContent || "");
  const destinationContent = String(options.destinationContent || "");
  if (!sourcePath || !destinationPath || sourcePath === destinationPath) {
    return Object.freeze({ valid: false, error: "Task move source and destination are invalid" });
  }

  const destination = parseTaskMoveDestinationFrontmatter(
    destinationContent,
    options,
  );
  if (!destination.valid) {
    return Object.freeze({ valid: false, error: destination.error });
  }
  const rangeResult = buildTaskMoveRanges(sourceContent, options.targets);
  if (!rangeResult.valid) {
    return Object.freeze({ valid: false, error: rangeResult.error });
  }
  const removal = removeTaskMoveRanges(sourceContent, rangeResult.ranges);
  if (!removal.valid) {
    return Object.freeze({ valid: false, error: removal.error });
  }

  const rebasedBlocks = rangeResult.ranges.map(rebaseTaskMoveBlock);
  const identities = prepareTaskMoveBlockIdentities(
    rebasedBlocks,
    sourcePath,
    destinationPath,
  );
  if (!identities.valid) {
    return Object.freeze({ valid: false, error: identities.error });
  }
  const destinationBlockIds = collectTaskMoveBlockIds(destinationContent);
  for (const blockId of identities.movedBlockIds) {
    if (destinationBlockIds.has(blockId)) {
      return Object.freeze({
        valid: false,
        error: `Destination already contains block ID: ${blockId}`,
      });
    }
  }

  const sourceBlockIds = collectTaskMoveBlockIds(sourceContent);
  const referenceOptions = {
    sourcePath,
    destinationPath,
    movedBlockIds: identities.movedBlockIds,
    sourceBlockIds,
    idReplacements: identities.idReplacements,
  };
  // Freshness is the last transformation of each moved open task line
  // (nav-stamps), applied at the destination. The stamper itself refuses
  // closed and recurring lines.
  const moveStamper = resolveFreshStamper(options);
  const moveFreshDateText = resolveFreshDateText(options);
  const movedBlocks = identities.blocks.map((block) => {
    const rewritten = rewriteTaskMoveReferences(block.join("\n"), {
      ...referenceOptions,
      currentPath: sourcePath,
      role: "moved",
    });
    let lines = rewritten.content.split("\n");
    if (moveStamper) {
      lines = lines.map((line) => applyFreshStampLine(line, moveStamper, moveFreshDateText));
    }
    return Object.freeze(lines);
  });
  const rewrittenSource = rewriteTaskMoveReferences(removal.content, {
    ...referenceOptions,
    currentPath: sourcePath,
    role: "source",
  }).content;
  const rewrittenDestination = rewriteTaskMoveReferences(destinationContent, {
    ...referenceOptions,
    currentPath: destinationPath,
    role: "destination",
  }).content;
  const insertion = insertTaskMoveBlocks(
    rewrittenDestination,
    movedBlocks,
    destination.kind,
  );
  if (!insertion.valid) {
    return Object.freeze({ valid: false, error: insertion.error });
  }

  const changes = new Map([
    [sourcePath, Object.freeze({ before: sourceContent, after: rewrittenSource })],
    [
      destinationPath,
      Object.freeze({ before: destinationContent, after: insertion.content }),
    ],
  ]);
  const otherContents =
    options.otherContents instanceof Map
      ? options.otherContents
      : new Map(Object.entries(options.otherContents || {}));
  for (const [path, content] of otherContents.entries()) {
    const normalizedPath = normalizeVaultRelativePath(path);
    if (!normalizedPath || normalizedPath === sourcePath || normalizedPath === destinationPath) {
      continue;
    }
    const before = String(content || "");
    const after = rewriteTaskMoveReferences(before, {
      ...referenceOptions,
      currentPath: normalizedPath,
      role: "external",
    }).content;
    if (after !== before) {
      changes.set(normalizedPath, Object.freeze({ before, after }));
    }
  }

  return Object.freeze({
    valid: true,
    error: null,
    changes,
    ranges: rangeResult.ranges,
    movedBlocks: Object.freeze(movedBlocks),
    movedBlockIds: identities.movedBlockIds,
    idReplacements: identities.idReplacements,
    nextSourceLine: removal.nextLine,
    destinationKind: destination.kind,
    destinationLine: insertion.insertedLine,
    destinationAnchorText: movedBlocks[0][0],
    destinationBlockId: getTrailingBlockId(movedBlocks[0][0]) || null,
  });
}

function resolveTaskMoveDestinationLine(content, anchor) {
  const text = String(content || "");
  const { lines } = splitMarkdownContent(text);
  const anchorInfo = anchor && typeof anchor === "object" ? anchor : {};
  const anchorLine = anchorInfo.line;
  const anchorText = anchorInfo.text;
  const anchorBlockId = anchorInfo.blockId;

  if (
    Number.isInteger(anchorLine) &&
    anchorLine >= 0 &&
    anchorLine < lines.length &&
    lines[anchorLine] === anchorText
  ) {
    return Object.freeze({ line: anchorLine, source: "planned" });
  }

  if (anchorBlockId) {
    const blockIdLine = findTaskLineByBlockId(lines, anchorBlockId);
    if (blockIdLine !== null) {
      return Object.freeze({ line: blockIdLine, source: "block-id" });
    }
  }

  if (anchorText) {
    const contexts = getMarkdownLineContexts(text);
    for (let index = 0; index < lines.length; index += 1) {
      const context = contexts[index];
      if (context && (context.inFrontmatter || context.inFence)) {
        continue;
      }
      if (lines[index] === anchorText) {
        return Object.freeze({ line: index, source: "text" });
      }
    }
  }

  if (lines.length === 0) {
    return Object.freeze({ line: 0, source: "clamped" });
  }
  const clampedLine = Math.min(
    Math.max(numericOrDefault(anchorLine, 0), 0),
    lines.length - 1,
  );
  return Object.freeze({ line: clampedLine, source: "clamped" });
}

function getCountedPropertyTargetState(
  content,
  target,
  property,
  options = {},
) {
  const context = getProjectNotePropertyContext(
    content,
    target.line,
    options,
  );
  if (!context.valid) {
    return Object.freeze({ valid: false, error: context.error });
  }

  const descriptor = resolveBulletPropertyTarget(property.name, context);
  if (descriptor.kind === "project-frontmatter") {
    const defined = Boolean(
      context.frontmatter && context.frontmatter.scheduledDefined,
    );
    return Object.freeze({
      valid: true,
      error: null,
      target: descriptor,
      context,
      defined,
      value: defined ? context.frontmatter.scheduledValue : "",
    });
  }

  const field = findBulletPropertyField(target.rawLine, property.name);
  return Object.freeze({
    valid: true,
    error: null,
    target: descriptor,
    context,
    defined: Boolean(field),
    value: field ? field.value : "",
  });
}

// Aggregate a property row across counted source tasks. A value is "common"
// only when every source defines the same value; partial presence is mixed.
function createCountedBulletPropertyItems(
  config,
  content,
  session,
  options = {},
) {
  const validation = validateCountedTaskSession(content, session);
  if (!validation.valid) {
    return Object.freeze({ valid: false, error: validation.error, items: [] });
  }

  const items = [];
  for (let order = 0; order < config.properties.length; order += 1) {
    const property = config.properties[order];
    const states = [];
    for (const target of session.targets) {
      const state = getCountedPropertyTargetState(
        content,
        target,
        property,
        options,
      );
      if (!state.valid) {
        return Object.freeze({ valid: false, error: state.error, items: [] });
      }
      states.push(state);
    }

    const definedStates = states.filter((state) => state.defined);
    const values = Array.from(
      new Set(definedStates.map((state) => state.value)),
    );
    const allDefined = definedStates.length === states.length;
    const valueState =
      definedStates.length === 0
        ? "absent"
        : allDefined && values.length === 1
          ? "common"
          : "mixed";
    const currentLabels = Object.freeze(
      values.map((value) => getBulletPropertyCurrentLabel(property, value)),
    );
    items.push({
      kind: "property",
      property,
      target: Object.freeze({ kind: "counted-task-batch" }),
      order,
      defined: definedStates.length > 0,
      definedCount: definedStates.length,
      targetCount: states.length,
      currentValue: valueState === "common" ? values[0] : "",
      currentLabel: valueState === "common" ? currentLabels[0] : "",
      currentValues: Object.freeze(values),
      currentLabels,
      valueState,
      mixed: valueState === "mixed",
      dependencyEligible: true,
      sourceStates: Object.freeze(states),
    });
  }

  items.sort((first, second) => {
    if (first.defined !== second.defined) {
      return first.defined ? -1 : 1;
    }
    return first.order - second.order;
  });
  return Object.freeze({
    valid: true,
    error: null,
    items: Object.freeze(items),
  });
}

function validateDependencyParentForEditor(editor, cursor, expectedLine = null) {
  if (!editor || typeof editor.getValue !== "function" || !cursor) {
    return Object.freeze({
      valid: false,
      line: null,
      message: "No active markdown editor",
    });
  }
  const line = getEditorLine(editor, cursor.line);
  if (line === null) {
    return Object.freeze({
      valid: false,
      line: null,
      message: "No active markdown editor",
    });
  }
  const content = String(editor.getValue() || "");
  if (!isObsidianTaskAtLine(content, cursor.line)) {
    return Object.freeze({
      valid: false,
      line,
      message: "Dependencies can only be set on #task checkboxes.",
    });
  }
  if (isBlockquotedMarkdownLine(line)) {
    return Object.freeze({
      valid: false,
      line,
      message: "⛓ Dependencies can't be edited inside a blockquote",
    });
  }
  if (expectedLine !== null && line !== expectedLine) {
    return Object.freeze({
      valid: false,
      line,
      message: "Current task changed; dependencies not updated",
    });
  }
  return Object.freeze({ valid: true, line, message: null });
}

function isTaskTagLeftBoundary(character) {
  return (
    character === undefined || /\s/.test(character) || "([{".includes(character)
  );
}

function isTaskTagRightBoundary(character) {
  return (
    character === undefined ||
    /\s/.test(character) ||
    "])}:.,;!?".includes(character)
  );
}

function getWholeTaskTagSpans(text, tag) {
  const source = String(text || "");
  const spans = [];
  let offset = 0;
  while (offset < source.length) {
    const relativeIndex = source.indexOf(tag, offset);
    if (relativeIndex === -1) {
      break;
    }
    const end = relativeIndex + tag.length;
    if (
      isTaskTagLeftBoundary(source[relativeIndex - 1]) &&
      isTaskTagRightBoundary(source[end])
    ) {
      spans.push(Object.freeze({ start: relativeIndex, end }));
      offset = end;
    } else {
      offset = relativeIndex + 1;
    }
  }
  return spans;
}

function hasWholeTaskTag(text, tag) {
  return getWholeTaskTagSpans(text, tag).length > 0;
}

function removeTextSpans(line, spans) {
  return (Array.isArray(spans) ? spans : [])
    .slice()
    .sort((left, right) => right.start - left.start)
    .reduce(
      (text, span) => removeBulletPropertyFieldSpan(text, span),
      String(line || ""),
    );
}

function normalizeProjectLifecycleHideTag(lineText, hide, includeProjectTask) {
  const text = String(lineText || "");
  if (!includeProjectTask) {
    return text;
  }
  const spans = getWholeTaskTagSpans(text, PROJECT_HIDE_TAG);
  if (!hide) {
    return removeTextSpans(text, spans);
  }
  if (spans.length > 0) {
    return removeTextSpans(text, spans.slice(1));
  }

  const trailingBlockId = getTrailingBlockIdSpan(text);
  const insertionIndex = trailingBlockId
    ? trailingBlockId.start
    : text.trimEnd().length;
  const before = text.slice(0, insertionIndex).replace(/[ \t]+$/, "");
  const after = text.slice(insertionIndex);
  return `${before} ${PROJECT_HIDE_TAG}${after}`;
}

function parseProjectTaskScheduledFields(lineText) {
  const text = String(lineText || "");
  const fields = [];
  const pattern =
    /(?:\[([^\[\]\n]+?)::([^\]\n]*)\]|\(([^()\n]+?)::([^)\n]*)\))/g;
  let match = pattern.exec(text);
  while (match) {
    const key = String(match[1] ?? match[3] ?? "").trim();
    if (key === "scheduled") {
      fields.push(
        Object.freeze({
          key,
          value: String(match[2] ?? match[4] ?? "").trim(),
          raw: match[0],
          span: Object.freeze({
            start: match.index,
            end: match.index + match[0].length,
          }),
        }),
      );
    }
    match = pattern.exec(text);
  }
  return fields;
}

function upsertProjectTaskScheduledField(lineText, scheduled) {
  const text = String(lineText || "");
  const fields = parseProjectTaskScheduledFields(text);
  if (fields.length > 1) {
    return Object.freeze({ line: text, changed: false, ambiguous: true });
  }
  if (fields.length === 1) {
    const validation = validateProjectScheduledDate(fields[0].value);
    if (validation.valid && validation.value >= scheduled) {
      return Object.freeze({
        line: text,
        changed: false,
        ambiguous: false,
      });
    }
    const nextLine =
      text.slice(0, fields[0].span.start) +
      formatBulletPropertyField("scheduled", scheduled) +
      text.slice(fields[0].span.end);
    return Object.freeze({
      line: nextLine,
      changed: nextLine !== text,
      ambiguous: false,
    });
  }
  const inserted = upsertBulletProperty(text, "scheduled", scheduled);
  return Object.freeze({
    line: inserted.line,
    changed: inserted.changed,
    ambiguous: false,
  });
}

function removeProjectTaskScheduledFields(lineText, predicate = () => true) {
  const text = String(lineText || "");
  const spans = parseProjectTaskScheduledFields(text)
    .filter((field) => predicate(field))
    .map((field) => field.span);
  return Object.freeze({
    line: removeTextSpans(text, spans),
    removedCount: spans.length,
  });
}

function getRealMarkdownTaskLines(content) {
  const { lines } = splitMarkdownContent(content);
  const tasks = [];
  let inFrontmatter = startsWithFrontmatter(lines);
  let inFence = null;

  for (let lineIndex = 0; lineIndex < lines.length; lineIndex += 1) {
    const line = String(lines[lineIndex] || "");
    if (inFrontmatter) {
      if (lineIndex > 0 && FRONTMATTER_DELIMITER_RE.test(line)) {
        inFrontmatter = false;
      }
      continue;
    }
    if (inFence) {
      if (isClosingFence(line, inFence)) {
        inFence = null;
      }
      continue;
    }
    const openingFence = getFenceOpening(line);
    if (openingFence) {
      inFence = openingFence;
      continue;
    }
    if (!OBSIDIAN_TASK_LINE_RE.test(line)) {
      continue;
    }

    tasks.push(
      Object.freeze({
        line: lineIndex,
        text: line,
        isProjectTask: isProjectLifecycleTaskLine(line),
      }),
    );
  }

  return tasks;
}

function getProjectScheduleRecoveryTargetLines(content) {
  return getRealMarkdownTaskLines(content)
    .filter((task) => {
      if (task.isProjectTask) {
        return false;
      }
      const match = OBSIDIAN_TASK_LINE_RE.exec(task.text);
      return Boolean(match && OPEN_OBSIDIAN_TASK_STATUSES.has(match[1]));
    })
    .map((task) => task.line);
}

function planProjectTaskSchedules(
  content,
  scheduled,
  today = new Date(),
  options = {},
) {
  const validation = validateProjectScheduledDate(scheduled);
  if (!validation.valid) {
    return Object.freeze({
      valid: false,
      error: validation.message,
      content: String(content || ""),
      changed: false,
      changedTaskCount: 0,
      scheduledTaskCount: 0,
      removedHideTaskCount: 0,
      blockedTaskCount: 0,
      recoveredReadyTaskCount: 0,
      recoveredNextTaskCount: 0,
      recoveredInProgressTaskCount: 0,
      stillBlockedTaskCount: 0,
      deferredRecoveryTaskCount: 0,
      ambiguousTaskLines: Object.freeze([]),
      taskCount: 0,
      futureScheduledTaskLines: Object.freeze([]),
    });
  }

  const scheduledDate = new Date(
    validation.year,
    validation.month - 1,
    validation.day,
  );
  const localToday = getLocalDateStart(today);
  const future = compareLocalDates(scheduledDate, localToday) > 0;
  const source = splitMarkdownContent(content);
  const tasks = getRealMarkdownTaskLines(content);
  let changedTaskCount = 0;
  let scheduledTaskCount = 0;
  let removedHideTaskCount = 0;
  let blockedTaskCount = 0;
  let projectHideChanged = false;
  const ambiguousTaskLines = [];
  const futureScheduledTaskLines = [];
  const recoveryCounts = emptyScheduledRecoveryCounts();
  tasks.forEach((task) => {
    if (task.isProjectTask) {
      let nextLine = normalizeProjectLifecycleHideTag(
        task.text,
        future,
        future || tasks.length === 1,
      );
      nextLine = removeProjectTaskScheduledFields(nextLine).line;
      if (nextLine !== task.text) {
        source.lines[task.line] = nextLine;
        changedTaskCount += 1;
        projectHideChanged =
          getWholeTaskTagSpans(nextLine, PROJECT_HIDE_TAG).length !==
          getWholeTaskTagSpans(task.text, PROJECT_HIDE_TAG).length;
      }
      // `^prj` never receives an inline `scheduled` field — its schedule lives
      // in frontmatter only — so it is never blocked by the branch below. It
      // still needs pruning from today's open Pomodoros when the project
      // itself moves to a future date.
      if (future) {
        futureScheduledTaskLines.push(task.line);
      }
      return;
    }

    const scheduledFields = parseProjectTaskScheduledFields(task.text);
    if (scheduledFields.length > 1) {
      ambiguousTaskLines.push(task.line);
      return;
    }

    let nextLine = removeTextSpans(
      task.text,
      getWholeTaskTagSpans(task.text, PROJECT_HIDE_TAG),
    );
    if (nextLine !== task.text) {
      removedHideTaskCount += 1;
    }
    const match = OBSIDIAN_TASK_LINE_RE.exec(nextLine);
    const status = match ? match[1] : null;
    if (OPEN_OBSIDIAN_TASK_STATUSES.has(status)) {
      const scheduleResult = upsertProjectTaskScheduledField(
        nextLine,
        validation.value,
      );
      nextLine = scheduleResult.line;
      if (scheduleResult.changed) {
        scheduledTaskCount += 1;
      }

      const finalFields = parseProjectTaskScheduledFields(nextLine);
      const futureTaskSchedule =
        finalFields.length === 1 &&
        isFutureInlineScheduledValue(finalFields[0].value, today);
      if (futureTaskSchedule) {
        futureScheduledTaskLines.push(task.line);
        const blockedLine = blockObsidianTaskCheckboxStatus(nextLine);
        if (blockedLine !== nextLine) {
          nextLine = blockedLine;
          blockedTaskCount += 1;
        }
      } else if (finalFields.length === 1) {
        const recovery = reconcileBlockedScheduledTaskLine(
          nextLine,
          getTargetScheduledRecovery(options, task.line),
        );
        nextLine = recovery.line;
        recordScheduledRecoveryOutcome(recoveryCounts, recovery.outcome);
      }
    }
    if (nextLine !== task.text) {
      source.lines[task.line] = nextLine;
      changedTaskCount += 1;
    }
  });

  const nextContent = source.lines.join(source.lineEnding);
  return Object.freeze({
    valid: true,
    error: null,
    content: nextContent,
    changed: nextContent !== String(content || ""),
    changedTaskCount,
    scheduledTaskCount,
    removedHideTaskCount,
    blockedTaskCount,
    recoveredReadyTaskCount: recoveryCounts.ready,
    recoveredNextTaskCount: recoveryCounts.next,
    recoveredInProgressTaskCount: recoveryCounts.inProgress,
    stillBlockedTaskCount: recoveryCounts.stillBlocked,
    deferredRecoveryTaskCount: recoveryCounts.deferred,
    ambiguousTaskLines: Object.freeze(ambiguousTaskLines),
    taskCount: tasks.length,
    future,
    projectHideChanged,
    futureScheduledTaskLines: Object.freeze(futureScheduledTaskLines),
  });
}

function removeAllBulletProperties(line, name) {
  let text = String(line || "");
  let field = findBulletPropertyField(text, name);
  while (field) {
    text = removeBulletPropertyFieldSpan(text, field.span);
    field = findBulletPropertyField(text, name);
  }
  return text;
}

function replaceMarkdownLine(content, lineIndex, nextLine) {
  const source = splitMarkdownContent(content);
  if (lineIndex < 0 || lineIndex >= source.lines.length) {
    return String(content || "");
  }
  source.lines[lineIndex] = nextLine;
  return source.lines.join(source.lineEnding);
}

function updateProjectScheduledFrontmatter(content, frontmatter, value) {
  const source = splitMarkdownContent(content);
  let cursorLineDelta = 0;
  if (value === null) {
    if (frontmatter.scheduledDefined) {
      source.lines.splice(frontmatter.scheduledLine, 1);
      cursorLineDelta = -1;
    }
  } else if (frontmatter.scheduledDefined) {
    source.lines[frontmatter.scheduledLine] = `scheduled: ${value}`;
  } else {
    source.lines.splice(frontmatter.closingLine, 0, `scheduled: ${value}`);
    cursorLineDelta = 1;
  }

  return Object.freeze({
    content: source.lines.join(source.lineEnding),
    cursorLineDelta,
  });
}

function planProjectScheduledUpdate(
  content,
  cursorLine,
  scheduled,
  today = new Date(),
  options = {},
) {
  const validation = validateProjectScheduledDate(scheduled);
  if (!validation.valid) {
    return Object.freeze({ valid: false, error: validation.message });
  }
  const context = getProjectNotePropertyContext(content, cursorLine, options);
  if (!context.valid || !context.isProjectTask) {
    return Object.freeze({
      valid: false,
      error: context.error || "Cursor is not on a valid ^prj task",
    });
  }

  const propagation = planProjectTaskSchedules(
    content,
    validation.value,
    today,
    options,
  );
  if (!propagation.valid) {
    return Object.freeze({ valid: false, error: propagation.error });
  }
  const frontmatterUpdate = updateProjectScheduledFrontmatter(
    propagation.content,
    context.frontmatter,
    validation.value,
  );

  return Object.freeze({
    valid: true,
    error: null,
    content: frontmatterUpdate.content,
    changed: frontmatterUpdate.content !== String(content || ""),
    cursorLine: cursorLine + frontmatterUpdate.cursorLineDelta,
    scheduled: validation.value,
    future: propagation.future,
    changedTaskCount: propagation.changedTaskCount,
    scheduledTaskCount: propagation.scheduledTaskCount,
    removedHideTaskCount: propagation.removedHideTaskCount,
    futureScheduledTaskLines: propagation.futureScheduledTaskLines,
    blockedTaskCount: propagation.blockedTaskCount,
    recoveredReadyTaskCount: propagation.recoveredReadyTaskCount,
    recoveredNextTaskCount: propagation.recoveredNextTaskCount,
    recoveredInProgressTaskCount:
      propagation.recoveredInProgressTaskCount,
    stillBlockedTaskCount: propagation.stillBlockedTaskCount,
    deferredRecoveryTaskCount: propagation.deferredRecoveryTaskCount,
    ambiguousTaskLines: propagation.ambiguousTaskLines,
  });
}

// ---- src/260-project-schedules.js ----
function planProjectScheduledDelete(content, cursorLine, options = {}) {
  const context = getProjectNotePropertyContext(content, cursorLine, options);
  if (!context.valid || !context.isProjectTask) {
    return Object.freeze({
      valid: false,
      error: context.error || "Cursor is not on a valid ^prj task",
    });
  }
  if (!context.frontmatter.scheduledDefined) {
    return Object.freeze({
      valid: false,
      error: "scheduled is not set on this project",
    });
  }

  const scheduled = context.frontmatter.scheduledValue;
  const source = splitMarkdownContent(content);
  const tasks = getRealMarkdownTaskLines(content);
  let changedTaskCount = 0;
  let removedScheduledTaskCount = 0;
  const recoveryCounts = emptyScheduledRecoveryCounts();
  tasks.forEach((task) => {
    let nextLine = task.text;
    if (task.isProjectTask) {
      nextLine = removeProjectTaskScheduledFields(nextLine).line;
    } else {
      const match = OBSIDIAN_TASK_LINE_RE.exec(nextLine);
      const status = match ? match[1] : null;
      if (!OPEN_OBSIDIAN_TASK_STATUSES.has(status)) {
        return;
      }
      const removed = removeProjectTaskScheduledFields(
        nextLine,
        (field) => field.value === scheduled,
      );
      nextLine = removed.line;
      if (removed.removedCount > 0) {
        removedScheduledTaskCount += 1;
      }
      const remaining = parseProjectTaskScheduledFields(nextLine);
      if (
        remaining.length === 1 &&
        isFutureInlineScheduledValue(remaining[0].value, options.today || new Date())
      ) {
        nextLine = blockObsidianTaskCheckboxStatus(nextLine);
      } else if (remaining.length < 2) {
        const recovery = reconcileBlockedScheduledTaskLine(
          nextLine,
          getTargetScheduledRecovery(options, task.line),
        );
        nextLine = recovery.line;
        recordScheduledRecoveryOutcome(recoveryCounts, recovery.outcome);
      }
    }
    if (nextLine !== task.text) {
      source.lines[task.line] = nextLine;
      changedTaskCount += 1;
    }
  });
  const cleanedContent = source.lines.join(source.lineEnding);
  const frontmatterUpdate = updateProjectScheduledFrontmatter(
    cleanedContent,
    context.frontmatter,
    null,
  );
  return Object.freeze({
    valid: true,
    error: null,
    content: frontmatterUpdate.content,
    changed: frontmatterUpdate.content !== String(content || ""),
    cursorLine: cursorLine + frontmatterUpdate.cursorLineDelta,
    scheduled,
    changedTaskCount,
    removedScheduledTaskCount,
    recoveredReadyTaskCount: recoveryCounts.ready,
    recoveredNextTaskCount: recoveryCounts.next,
    recoveredInProgressTaskCount: recoveryCounts.inProgress,
    stillBlockedTaskCount: recoveryCounts.stillBlocked,
    deferredRecoveryTaskCount: recoveryCounts.deferred,
  });
}

function isDueInlineScheduledValue(value, today = new Date()) {
  const validation = validateProjectScheduledDate(value);
  return (
    validation.valid &&
    !isFutureInlineScheduledValue(validation.value, today)
  );
}

function getTargetScheduledRecovery(options, line) {
  const recoveryByLine = options && options.recoveryByLine;
  if (recoveryByLine instanceof Map) {
    return recoveryByLine.get(line) || null;
  }
  if (recoveryByLine && typeof recoveryByLine === "object") {
    return recoveryByLine[line] || null;
  }
  return null;
}

function reconcileBlockedScheduledTaskLine(lineText, recovery) {
  const line = String(lineText || "");
  const taskMatch = OBSIDIAN_TASK_LINE_RE.exec(line);
  if (!taskMatch || taskMatch[1] !== "?") {
    return Object.freeze({
      line,
      changed: false,
      outcome: null,
    });
  }
  const decision =
    recovery || deferredScheduledRecovery("recovery snapshot is unavailable");
  if (
    !["ready", "next", "in-progress"].includes(decision.state) ||
    ![" ", "*", "/"].includes(decision.rank)
  ) {
    return Object.freeze({
      line,
      changed: false,
      outcome:
        decision.state === "blocked" ? "still-blocked" : "deferred",
    });
  }
  const checkboxOffset = taskMatch[0].indexOf("[?]") + 1;
  const nextLine =
    line.slice(0, checkboxOffset) +
    decision.rank +
    line.slice(checkboxOffset + 1);
  return Object.freeze({
    line: nextLine,
    changed: nextLine !== line,
    outcome: decision.state,
  });
}

function emptyScheduledRecoveryCounts() {
  return {
    ready: 0,
    next: 0,
    inProgress: 0,
    stillBlocked: 0,
    deferred: 0,
  };
}

function recordScheduledRecoveryOutcome(counts, outcome) {
  if (outcome === "ready") counts.ready += 1;
  if (outcome === "next") counts.next += 1;
  if (outcome === "in-progress") counts.inProgress += 1;
  if (outcome === "still-blocked") counts.stillBlocked += 1;
  if (outcome === "deferred") counts.deferred += 1;
}

function scheduledRecoveryNoticeParts(counts = {}) {
  const parts = [];
  if (counts.ready > 0) {
    parts.push(`recovered ${formatCountLabel(counts.ready, "task")} Ready`);
  }
  if (counts.next > 0) {
    parts.push(`recovered ${formatCountLabel(counts.next, "task")} Next`);
  }
  if (counts.inProgress > 0) {
    parts.push(
      `recovered ${formatCountLabel(counts.inProgress, "task")} In Progress`,
    );
  }
  if (counts.stillBlocked > 0) {
    parts.push(
      `${formatCountLabel(counts.stillBlocked, "task")} still Blocked`,
    );
  }
  if (counts.deferred > 0) {
    parts.push(
      `${formatCountLabel(
        counts.deferred,
        "task",
      )} deferred to bob task reconcile`,
    );
  }
  return Object.freeze(parts);
}

function scheduledRecoveryNoticeSuffix(counts = {}) {
  const parts = scheduledRecoveryNoticeParts(counts);
  return parts.length > 0 ? `; ${parts.join("; ")}` : "";
}

function getCountedTaskNoticeParts(session, unchangedTaskCount = 0) {
  const parts = [];
  if (unchangedTaskCount > 0) {
    parts.push(`${formatCountLabel(unchangedTaskCount, "task")} unchanged`);
  }
  if (session && session.clamped) {
    parts.push(
      `requested ${session.requestedCount}, found ${session.actualCount} at end of note`,
    );
  }
  return Object.freeze(parts);
}

function getCountedTaskNoticeSuffix(session, unchangedTaskCount = 0) {
  const parts = getCountedTaskNoticeParts(session, unchangedTaskCount);
  return parts.length > 0 ? `; ${parts.join("; ")}` : "";
}

// Plan one counted set/delete without mutating the editor. Scheduled values on
// ^prj sources are composed through project frontmatter and task schedules first;
// every other source remains an inline Dataview edit. `options.priorityValueByLine`
// (a Map from original line to priority value) overrides the shared
// `options.priorityValue` per target for `set-priority`; callers that omit it get
// byte-identical output. The caller can therefore commit the complete result as
// one guarded transaction.
function planCountedBulletPropertyBatch(
  content,
  session,
  name,
  value,
  options = {},
) {
  const text = String(content || "");
  const propertyName = normalizeBulletPropertyName(name);
  const operation =
    options.operation === "delete"
      ? "delete"
      : options.operation === "set-priority"
        ? "set-priority"
        : "set";
  const isPriorityOperation = operation === "set-priority";
  const normalizedValue = normalizeBulletPropertyValue(
    isPriorityOperation ? options.priorityValue : value,
  );
  const scheduledPropertyName = isPriorityOperation
    ? normalizeBulletPropertyName(options.scheduledPropertyName)
    : "";
  const scheduledValueByLine =
    isPriorityOperation && options.scheduledValueByLine instanceof Map
      ? options.scheduledValueByLine
      : null;
  const priorityValueByLine =
    isPriorityOperation && options.priorityValueByLine instanceof Map
      ? options.priorityValueByLine
      : null;
  const getCountedPriorityValueForLine = (targetLine) => {
    if (priorityValueByLine && priorityValueByLine.has(targetLine)) {
      return normalizeBulletPropertyValue(
        priorityValueByLine.get(targetLine),
      );
    }
    return normalizedValue;
  };
  const shouldBlockInlineTasks =
    operation === "set" &&
    propertyName === "scheduled" &&
    isFutureInlineScheduledValue(
      normalizedValue,
      options.today || new Date(),
    );
  const shouldRecoverInlineTasks =
    propertyName === "scheduled" &&
    (operation === "delete" ||
      (operation === "set" &&
        isDueInlineScheduledValue(
          normalizedValue,
          options.today || new Date(),
        )));
  const sessionValidation = validateCountedTaskSession(text, session);
  if (!sessionValidation.valid) {
    return Object.freeze({
      valid: false,
      stale: true,
      error: sessionValidation.error,
      content: text,
      changed: false,
    });
  }
  if (!propertyName) {
    return Object.freeze({
      valid: false,
      stale: false,
      error: "Bullet property name is empty",
      content: text,
      changed: false,
    });
  }
  if (
    isPriorityOperation &&
    ((!normalizedValue && !priorityValueByLine) ||
      !scheduledPropertyName ||
      !scheduledValueByLine)
  ) {
    return Object.freeze({
      valid: false,
      stale: false,
      error: "Counted priority update is missing configured values",
      content: text,
      changed: false,
    });
  }

  const targetStates = [];
  const property = { name: propertyName };
  const scheduledProperty = { name: scheduledPropertyName };
  for (const target of session.targets) {
    const state = getCountedPropertyTargetState(
      text,
      target,
      property,
      options,
    );
    if (!state.valid) {
      return Object.freeze({
        valid: false,
        stale: false,
        error: state.error,
        content: text,
        changed: false,
      });
    }
    let scheduledState = null;
    if (isPriorityOperation) {
      const scheduledValue = normalizeBulletPropertyValue(
        scheduledValueByLine.get(target.line),
      );
      if (
        !scheduledValue ||
        !validateProjectScheduledDate(scheduledValue).valid
      ) {
        return Object.freeze({
          valid: false,
          stale: false,
          error: `Counted priority update has no valid scheduled date for line ${
            target.line + 1
          }`,
          content: text,
          changed: false,
        });
      }
      scheduledState = getCountedPropertyTargetState(
        text,
        target,
        scheduledProperty,
        options,
      );
      if (!scheduledState.valid) {
        return Object.freeze({
          valid: false,
          stale: false,
          error: scheduledState.error,
          content: text,
          changed: false,
        });
      }
    }
    targetStates.push({ target, state, scheduledState });
  }

  const projectTargets =
    propertyName === "scheduled" || isPriorityOperation
      ? targetStates.filter(
          (entry) =>
            (isPriorityOperation ? entry.scheduledState : entry.state).target
              .kind === "project-frontmatter",
        )
      : [];
  let nextContent = text;
  let taskLineDelta = 0;
  let propagatedScheduleTaskCount = 0;
  let removedProjectScheduleTaskCount = 0;
  let removedHideTaskCount = 0;
  let blockedTaskCount = 0;
  let ambiguousProjectTaskCount = 0;
  const recoveryCounts = emptyScheduledRecoveryCounts();
  let projectPropertyChanged = false;
  let projectScheduledValue = "";
  // Original (pre-batch) line numbers, matching the convention `target.line`
  // and `recoveryByLine` already use throughout this function.
  const futureScheduledTaskLines = [];

  if (projectTargets.length > 0) {
    const firstProject = projectTargets[0];
    const projectState = isPriorityOperation
      ? firstProject.scheduledState
      : firstProject.state;
    const frontmatter = projectState.context.frontmatter;
    projectScheduledValue = isPriorityOperation
      ? normalizeBulletPropertyValue(
          scheduledValueByLine.get(firstProject.target.line),
        )
      : normalizedValue;
    if (operation === "set" || isPriorityOperation) {
      const projectPlan = planProjectScheduledUpdate(
        text,
        firstProject.target.line,
        projectScheduledValue,
        options.today || new Date(),
        options,
      );
      if (!projectPlan.valid) {
        return Object.freeze({
          valid: false,
          stale: false,
          error: projectPlan.error,
          content: text,
          changed: false,
        });
      }
      nextContent = projectPlan.content;
      taskLineDelta = projectPlan.cursorLine - firstProject.target.line;
      propagatedScheduleTaskCount = projectPlan.scheduledTaskCount;
      removedHideTaskCount = projectPlan.removedHideTaskCount;
      blockedTaskCount = projectPlan.blockedTaskCount;
      ambiguousProjectTaskCount = projectPlan.ambiguousTaskLines.length;
      recoveryCounts.ready += projectPlan.recoveredReadyTaskCount;
      recoveryCounts.next += projectPlan.recoveredNextTaskCount;
      recoveryCounts.inProgress +=
        projectPlan.recoveredInProgressTaskCount;
      recoveryCounts.stillBlocked += projectPlan.stillBlockedTaskCount;
      recoveryCounts.deferred += projectPlan.deferredRecoveryTaskCount;
      projectPropertyChanged =
        !frontmatter.scheduledDefined ||
        frontmatter.scheduledValue !== projectScheduledValue;
      futureScheduledTaskLines.push(...projectPlan.futureScheduledTaskLines);
    } else if (frontmatter.scheduledDefined) {
      const projectPlan = planProjectScheduledDelete(
        text,
        firstProject.target.line,
        options,
      );
      if (!projectPlan.valid) {
        return Object.freeze({
          valid: false,
          stale: false,
          error: projectPlan.error,
          content: text,
          changed: false,
        });
      }
      nextContent = projectPlan.content;
      taskLineDelta = projectPlan.cursorLine - firstProject.target.line;
      removedProjectScheduleTaskCount =
        projectPlan.removedScheduledTaskCount;
      recoveryCounts.ready += projectPlan.recoveredReadyTaskCount;
      recoveryCounts.next += projectPlan.recoveredNextTaskCount;
      recoveryCounts.inProgress +=
        projectPlan.recoveredInProgressTaskCount;
      recoveryCounts.stillBlocked += projectPlan.stillBlockedTaskCount;
      recoveryCounts.deferred += projectPlan.deferredRecoveryTaskCount;
      projectPropertyChanged = true;
    }
  }

  // Freshness is the last transformation of the task line (nav-stamps).
  // Project-frontmatter edits never stamp; the stamper itself refuses closed
  // and recurring lines.
  const countedStamper = resolveFreshStamper(options);
  const countedFreshDateText = resolveFreshDateText(options);
  const source = splitMarkdownContent(nextContent);
  const changedTargets = [];
  const unchangedTargets = [];
  for (const { target, state, scheduledState } of targetStates) {
    const mappedLine = target.line + taskLineDelta;
    const liveLine = String(source.lines[mappedLine] || "");
    let nextLine = liveLine;
    let targetChanged = false;

    if (isPriorityOperation) {
      const targetPriorityValue = getCountedPriorityValueForLine(target.line);
      if (!targetPriorityValue) {
        return Object.freeze({
          valid: false,
          stale: false,
          error: `Counted priority update has no valid priority value for line ${
            target.line + 1
          }`,
          content: text,
          changed: false,
        });
      }
      const priorityBaseLine = removeAllBulletProperties(
        liveLine,
        scheduledPropertyName,
      );
      const priorityResult = upsertBulletProperty(
        priorityBaseLine,
        propertyName,
        targetPriorityValue,
      );
      nextLine = priorityResult.line;
      targetChanged =
        priorityBaseLine !== liveLine || priorityResult.changed;
      const scheduledValue = normalizeBulletPropertyValue(
        scheduledValueByLine.get(target.line),
      );
      if (scheduledState.target.kind === "project-frontmatter") {
        nextLine = removeAllBulletProperties(
          nextLine,
          scheduledPropertyName,
        );
        targetChanged ||=
          projectPropertyChanged ||
          Boolean(
            findBulletPropertyField(target.rawLine, scheduledPropertyName),
          ) ||
          nextLine !== priorityResult.line;
      } else {
        const scheduledResult = upsertBulletProperty(
          nextLine,
          scheduledPropertyName,
          scheduledValue,
        );
        nextLine = scheduledResult.line;
        targetChanged ||= scheduledResult.changed;
        if (
          isFutureInlineScheduledValue(
            scheduledValue,
            options.today || new Date(),
          )
        ) {
          futureScheduledTaskLines.push(target.line);
          const blockedLine = blockObsidianTaskCheckboxStatus(nextLine);
          if (blockedLine !== nextLine) {
            nextLine = blockedLine;
            targetChanged = true;
            blockedTaskCount += 1;
          }
        } else if (
          isDueInlineScheduledValue(
            scheduledValue,
            options.today || new Date(),
          )
        ) {
          const recovery = reconcileBlockedScheduledTaskLine(
            nextLine,
            getTargetScheduledRecovery(options, target.line),
          );
          nextLine = recovery.line;
          targetChanged ||= recovery.changed;
          recordScheduledRecoveryOutcome(recoveryCounts, recovery.outcome);
        }
      }
    } else if (
      propertyName === "scheduled" &&
      state.target.kind === "project-frontmatter"
    ) {
      // Keep the existing ^prj rule strict even if several lifecycle task
      // sources were counted: scheduled is represented only in frontmatter.
      if (operation === "set" || state.defined) {
        nextLine = removeAllBulletProperties(liveLine, propertyName);
      }
      targetChanged =
        projectPropertyChanged ||
        Boolean(findBulletPropertyField(target.rawLine, propertyName)) ||
        nextLine !== liveLine;
    } else {
      const result =
        operation === "set" &&
        propertyName === "scheduled" &&
        projectTargets.length > 0
          ? upsertProjectTaskScheduledField(liveLine, normalizedValue)
          : operation === "delete"
            ? deleteBulletProperty(liveLine, propertyName)
            : upsertBulletProperty(liveLine, propertyName, normalizedValue);
      nextLine = result.line;
      targetChanged = result.changed;
      if (shouldBlockInlineTasks) {
        futureScheduledTaskLines.push(target.line);
        const blockedLine = blockObsidianTaskCheckboxStatus(nextLine);
        if (blockedLine !== nextLine) {
          nextLine = blockedLine;
          targetChanged = true;
          blockedTaskCount += 1;
        }
      } else if (shouldRecoverInlineTasks) {
        const recovery = reconcileBlockedScheduledTaskLine(
          nextLine,
          getTargetScheduledRecovery(options, target.line),
        );
        nextLine = recovery.line;
        targetChanged ||= recovery.changed;
        recordScheduledRecoveryOutcome(
          recoveryCounts,
          recovery.outcome,
        );
      }
    }

    if (countedStamper && targetChanged) {
      const isFrontmatterTarget =
        !isPriorityOperation && state && state.target && state.target.kind === "project-frontmatter";
      if (!isFrontmatterTarget) {
        const stamped = applyFreshStampLine(nextLine, countedStamper, countedFreshDateText);
        if (stamped !== nextLine) {
          nextLine = stamped;
          targetChanged = true;
        }
      }
    }

    source.lines[mappedLine] = nextLine;
    const detail = Object.freeze({
      line: mappedLine,
      originalLine: target.line,
      rawLine: target.rawLine,
      lineText: nextLine,
    });
    (targetChanged ? changedTargets : unchangedTargets).push(detail);
  }

  // One entry per changed target, using that target's own previous value
  // (captured above via getCountedPropertyTargetState) and its own rolled date.
  // A priority batch supplies reasonByLine because each task may have had a
  // different previous level; a scheduled batch supplies one shared reason.
  // Insertions apply in descending insertLine order so an earlier (smaller-index)
  // insert position is never invalidated by a later one.
  let scheduleLoggedTaskCount = 0;
  let scheduleLogCreatedParentCount = 0;
  let scheduleLogFallbackTaskCount = 0;
  const appliedScheduleInserts = [];
  const scheduleLogOptions =
    options.scheduleLog && (isPriorityOperation || (operation === "set" && propertyName === "scheduled"))
      ? options.scheduleLog
      : null;
  if (scheduleLogOptions) {
    const entryByOriginalLine = new Map(targetStates.map((entry) => [entry.target.line, entry]));
    const scheduleLogPlans = changedTargets
      .map((detail) => {
        const entry = entryByOriginalLine.get(detail.originalLine);
        const scheduledState = isPriorityOperation ? entry && entry.scheduledState : entry && entry.state;
        // Only the first ^prj target's roll reaches frontmatter, so every
        // project-frontmatter target logs the value that was actually written.
        const to = !isPriorityOperation
          ? normalizedValue
          : scheduledState && scheduledState.target.kind === "project-frontmatter"
            ? projectScheduledValue
            : normalizeBulletPropertyValue(scheduledValueByLine.get(detail.originalLine));
        const from = scheduledState ? scheduledState.value : "";
        const rawReason =
          scheduleLogOptions.reasonByLine instanceof Map && scheduleLogOptions.reasonByLine.has(detail.originalLine)
            ? scheduleLogOptions.reasonByLine.get(detail.originalLine)
            : scheduleLogOptions.reason;
        const normalizedReason = normalizeScheduleReasonText(rawReason);
        // planScheduleLogEntry decides per target whether an empty reason falls
        // back, since only it knows whether that task already keeps a log.
        if (normalizedReason.empty && normalizeScheduleReasonText(scheduleLogOptions.fallbackReason).empty) {
          return null;
        }
        if (scheduleLogOptions.automatic && !shouldWriteAutomaticScheduleLog(from, to)) {
          return null;
        }
        return planScheduleLogEntry(source.lines.join(source.lineEnding), detail.line, {
          from,
          to,
          reason: normalizedReason.reason,
          fallbackReason: scheduleLogOptions.fallbackReason,
        });
      })
      .filter((scheduleLogPlan) => scheduleLogPlan && scheduleLogPlan.valid)
      .sort((first, second) => second.insertLine - first.insertLine);
    for (const scheduleLogPlan of scheduleLogPlans) {
      const applied = applyScheduleLogEntryToLines(source.lines, scheduleLogPlan);
      if (applied > 0) {
        scheduleLoggedTaskCount += 1;
        appliedScheduleInserts.push({
          insertLine: scheduleLogPlan.insertLine,
          count: applied,
        });
        if (scheduleLogPlan.createdParent) {
          scheduleLogCreatedParentCount += 1;
        }
        if (scheduleLogPlan.usedFallback) {
          scheduleLogFallbackTaskCount += 1;
        }
      }
    }
  }

  const isSchedulingWorkLogOperation =
    isPriorityOperation || (operation === "set" && propertyName === "scheduled");
  const schedulingWorkLogInput =
    options.schedulingWorkLog && typeof options.schedulingWorkLog === "object"
      ? options.schedulingWorkLog
      : options.workLog && typeof options.workLog === "object"
        ? options.workLog
        : null;
  let schedulingWorkLogWrittenCount = 0;
  let schedulingWorkLogEligibleCount = 0;
  if (isSchedulingWorkLogOperation && hasSchedulingWorkLogInput(schedulingWorkLogInput)) {
    const eligibleOriginalLines =
      collectSchedulingWorkLogEligibleOriginalLines(session.targets);
    schedulingWorkLogEligibleCount = eligibleOriginalLines.size;
    if (eligibleOriginalLines.size > 0) {
      const mappedByOriginal = new Map();
      for (const detail of changedTargets) {
        mappedByOriginal.set(detail.originalLine, detail.line);
      }
      for (const detail of unchangedTargets) {
        if (!mappedByOriginal.has(detail.originalLine)) {
          mappedByOriginal.set(detail.originalLine, detail.line);
        }
      }
      // Schedule inserts land strictly after their own task line, so shift
      // every mapped task line at or after each applied insert.
      for (const insert of appliedScheduleInserts) {
        const at = Math.floor(numericOrDefault(insert.insertLine, NaN));
        const count = Math.floor(numericOrDefault(insert.count, 0));
        if (!Number.isFinite(at) || count <= 0) {
          continue;
        }
        for (const [originalLine, currentLine] of Array.from(mappedByOriginal)) {
          if (currentLine >= at) {
            mappedByOriginal.set(originalLine, currentLine + count);
          }
        }
      }
      const workLogDateText = resolveSchedulingWorkLogDateText(
        schedulingWorkLogInput,
        undefined,
      );
      schedulingWorkLogWrittenCount = applySchedulingWorkLogsToLines(
        source.lines,
        mappedByOriginal,
        eligibleOriginalLines,
        schedulingWorkLogInput.summary,
        workLogDateText,
      );
    }
  }

  nextContent = source.lines.join(source.lineEnding);
  const cursorLine = session.targets[0].line + taskLineDelta;
  return Object.freeze({
    valid: true,
    stale: false,
    error: null,
    operation,
    propertyName,
    value: normalizedValue,
    scheduledPropertyName,
    content: nextContent,
    changed: nextContent !== text,
    changedTaskCount: changedTargets.length,
    unchangedTaskCount: unchangedTargets.length,
    targetCount: session.targets.length,
    changedTargets: Object.freeze(changedTargets),
    unchangedTargets: Object.freeze(unchangedTargets),
    cursorLine,
    cursorLineDelta: taskLineDelta,
    propagatedScheduleTaskCount,
    removedProjectScheduleTaskCount,
    removedHideTaskCount,
    ambiguousProjectTaskCount,
    blockedTaskCount,
    scheduleLoggedTaskCount,
    scheduleLogCreatedParentCount,
    scheduleLogFallbackTaskCount,
    schedulingWorkLogWrittenCount,
    schedulingWorkLogEligibleCount,
    recoveredReadyTaskCount: recoveryCounts.ready,
    recoveredNextTaskCount: recoveryCounts.next,
    recoveredInProgressTaskCount: recoveryCounts.inProgress,
    stillBlockedTaskCount: recoveryCounts.stillBlocked,
    deferredRecoveryTaskCount: recoveryCounts.deferred,
    futureScheduledTaskLines: Object.freeze(futureScheduledTaskLines),
  });
}

// Converge one selected dependency across every counted source task. All
// source fields, target identity normalization, and per-parent navigation
// bullets are built in memory so the runtime path can apply exactly one write.
// ---- src/270-counted-batches.js ----
function planCountedLocalTaskDependency(
  content,
  session,
  dependencyTask,
  filePath,
  options = {},
) {
  const text = String(content || "");
  const sessionValidation = validateCountedTaskSession(text, session);
  if (!sessionValidation.valid) {
    return Object.freeze({
      valid: false,
      stale: true,
      error: sessionValidation.error,
      content: text,
      changed: false,
    });
  }
  const countedLines = String(content || "").split(/\r?\n/);
  for (const target of session.targets || []) {
    if (
      Number.isInteger(target.line) &&
      isBlockquotedMarkdownLine(countedLines[target.line])
    ) {
      return Object.freeze({
        valid: false,
        stale: true,
        error: "⛓ Dependencies can't be edited inside a blockquote",
        content: text,
        changed: false,
      });
    }
  }

  const dependencyLine = dependencyTask && dependencyTask.line;
  const sourceLines = new Set(session.targets.map((target) => target.line));
  const currentDependencyLine = Number.isInteger(dependencyLine)
    ? splitMarkdownContent(text).lines[dependencyLine]
    : undefined;
  if (
    !dependencyTask ||
    sourceLines.has(dependencyLine) ||
    currentDependencyLine !== dependencyTask.rawLine ||
    !isObsidianTaskAtLine(text, dependencyLine)
  ) {
    return Object.freeze({
      valid: false,
      stale: true,
      error: "The selected dependency changed while the picker was open",
      content: text,
      changed: false,
    });
  }

  const confirmedBlockId = normalizeBulletPropertyValue(
    options.confirmedBlockId,
  );
  let dependencyLineText = currentDependencyLine;
  let resolved = resolveTargetTaskIdentity(dependencyLineText, {
    promptWhenBlockIdMissing: true,
    filePath,
  });
  if (resolved.needsBlockIdPrompt) {
    if (!confirmedBlockId) {
      return Object.freeze({
        valid: false,
        stale: false,
        needsBlockIdPrompt: true,
        error: "The selected dependency needs a block ID",
        content: text,
        changed: false,
      });
    }
    const blockIdValidation = validateBlockIdCandidate(
      confirmedBlockId,
      text,
    );
    if (!blockIdValidation.valid) {
      return Object.freeze({
        valid: false,
        stale: false,
        error: blockIdValidation.message,
        content: text,
        changed: false,
      });
    }
    // An existing valid `[id::]` is never rewritten (§3): only the missing
    // `^id` is appended, and the kept id resolves the field.
    dependencyLineText = applyPromptedBlockIdPreservingLegacyId(
      dependencyLineText,
      confirmedBlockId,
      filePath,
    );
    if (dependencyLineText === null) {
      return Object.freeze({
        valid: false,
        stale: false,
        error: "This note path cannot be encoded as a dependency ID",
        content: text,
        changed: false,
      });
    }
    resolved = Object.freeze({
      value: dependencyTargetId(
        dependencyLineText,
        filePath,
        confirmedBlockId,
      ),
      linkBlockId: confirmedBlockId,
      legacyValue:
        normalizeBulletPropertyValue(dependencyTask.existingIdField) || null,
      needsBlockIdPrompt: false,
      targetEdits: Object.freeze([]),
    });
  } else if (resolved.targetEdits.length > 0) {
    // An existing valid `[id::]` is never rewritten (§3): only apply the
    // add-missing-id edit and resolve the kept id for the field.
    const missingIdEdits = resolved.targetEdits.filter(
      (edit) => edit.kind === "add-id-field",
    );
    if (missingIdEdits.length > 0) {
      dependencyLineText =
        missingIdEdits[missingIdEdits.length - 1].line;
    }
    const keptValue = dependencyTargetId(
      dependencyLineText,
      filePath,
      resolved.linkBlockId,
    );
    resolved = Object.freeze({
      value: keptValue,
      linkBlockId: resolved.linkBlockId,
      legacyValue: resolved.legacyValue,
      needsBlockIdPrompt: false,
      targetEdits: Object.freeze([]),
    });
  }

  if (!resolved.value || !resolved.linkBlockId) {
    return Object.freeze({
      valid: false,
      stale: false,
      error: "Could not identify the selected dependency",
      content: text,
      changed: false,
    });
  }

  const dependencyAliases = new Set(
    [
      resolved.value,
      resolved.legacyValue,
      dependencyTask.existingIdField,
      dependencyTask.existingBlockId,
    ]
      .map(normalizeBulletPropertyValue)
      .filter(Boolean),
  );
  const linkedBefore = session.targets.map((target) => {
    const field = findBulletPropertyField(target.rawLine, "dependsOn");
    const values = new Set(
      field ? parseLocalTaskIdList(field.value) : [],
    );
    return Array.from(dependencyAliases).some((alias) => values.has(alias));
  });
  const remove = linkedBefore.every(Boolean);

  // An existing valid `[id::]` is never rewritten (§3): the kept id
  // resolves every source field through the planner below.
  const nextSource = splitMarkdownContent(text);
  nextSource.lines[dependencyLine] = dependencyLineText;
  let nextContent = nextSource.lines.join(nextSource.lineEnding);

  // Freshness is the last transformation of each parent task line
  // (nav-stamps). Process parents bottom-to-top through the pure planner so
  // every source keeps the line, the field, status effects, and legacy
  // folding; edits only shift lines below the current parent, so every
  // still-pending source retains its snapshot index.
  const countedDepStamper = resolveFreshStamper(options);
  const countedDepFreshDateText = resolveFreshDateText(options);
  const countedTargetRef = Object.freeze({
    path: normalizeVaultRelativePath(filePath),
    blockId: resolved.linkBlockId,
  });
  let navigationChangedCount = 0;
  const sourceResults = [];
  const orderedTargets = session.targets
    .slice()
    .sort((first, second) => second.line - first.line);
  for (const target of orderedTargets) {
    const parentPlan = planDependencyEdit({
      content: nextContent,
      parentLine: target.line,
      parentPath: filePath,
      add: remove ? [] : [countedTargetRef],
      remove: remove ? [countedTargetRef] : [],
      files: { [normalizeVaultRelativePath(filePath)]: nextContent },
      vaultFiles: options.vaultFiles,
      resolveLinkpath: options.resolveLinkpath,
      recovery: options.recovery,
    });
    if (!parentPlan.ok) {
      return Object.freeze({
        valid: false,
        stale: false,
        error: "Could not plan dependency navigation for every source task",
        content: text,
        changed: false,
      });
    }
    const beforeLines = nextContent.split(/\r?\n/);
    const currentLine = String(beforeLines[target.line] || "");
    let parentChanged =
      parentPlan.changed || currentLine !== target.rawLine;
    nextContent = parentPlan.nextContent;
    if (countedDepStamper && parentChanged) {
      const afterLines = nextContent.split(/\r?\n/);
      const stamped = applyFreshStampLine(
        afterLines[target.line],
        countedDepStamper,
        countedDepFreshDateText,
      );
      if (stamped !== afterLines[target.line]) {
        afterLines[target.line] = stamped;
        const ending = nextContent.includes("\r\n") ? "\r\n" : "\n";
        nextContent = afterLines.join(ending);
        parentChanged = true;
      }
    }
    if (
      parentPlan.structural.replaceLine !== null ||
      parentPlan.structural.insertAt !== null ||
      parentPlan.structural.deleteLines.length > 0
    ) {
      navigationChangedCount += 1;
    }
    sourceResults.push({
      target,
      dependencyChanged: parentChanged,
      navigationChanged: parentPlan.changed,
    });
  }

  const changedTaskCount = sourceResults.filter(
    (entry) => entry.dependencyChanged || entry.navigationChanged,
  ).length;
  return Object.freeze({
    valid: true,
    stale: false,
    needsBlockIdPrompt: false,
    error: null,
    content: nextContent,
    changed: nextContent !== text,
    operation: remove ? "remove" : "add",
    dependencyValue: resolved.value,
    linkBlockId: resolved.linkBlockId,
    targetIdentityChanged: dependencyLineText !== currentDependencyLine,
    changedTaskCount,
    unchangedTaskCount: session.targets.length - changedTaskCount,
    targetCount: session.targets.length,
    navigationChangedCount,
    cursorLine: session.targets[0].line,
  });
}

function getLocalDateStart(date) {
  return new Date(date.getFullYear(), date.getMonth(), date.getDate());
}

function compareLocalDates(firstDate, secondDate) {
  const firstTime = getLocalDateStart(firstDate).getTime();
  const secondTime = getLocalDateStart(secondDate).getTime();
  if (firstTime === secondTime) {
    return 0;
  }

  return firstTime < secondTime ? -1 : 1;
}

function addLocalDateDays(date, days) {
  return new Date(date.getFullYear(), date.getMonth(), date.getDate() + days);
}

function getLocalDayOffset(baseDate, targetDate) {
  const baseTime = getLocalDateStart(baseDate).getTime();
  const targetTime = getLocalDateStart(targetDate).getTime();
  return Math.round((targetTime - baseTime) / 86_400_000);
}

function formatRelativeDayOffset(offset) {
  const days = Number(offset);
  if (!Number.isFinite(days)) {
    return "";
  }
  if (days === 0) {
    return "today";
  }
  if (days === 1) {
    return "tomorrow";
  }
  if (days === -1) {
    return "yesterday";
  }
  if (days > 1) {
    return `in ${days} days`;
  }
  return `${Math.abs(days)} days ago`;
}

function formatRelativeDayRange(minOffset, maxOffset) {
  const min = Number(minOffset);
  const max = Number(maxOffset);
  if (!Number.isFinite(min) || !Number.isFinite(max)) {
    return "";
  }
  if (min === max) {
    return formatRelativeDayOffset(min);
  }
  if (min >= 1) {
    return `in ${min}–${max} days`;
  }
  return `${formatRelativeDayOffset(min)} to ${formatRelativeDayOffset(max)}`;
}

function rollPriorityScheduledDateWithOffset(
  level,
  baseDate,
  random = Math.random,
) {
  const span = level.maxDays - level.minDays + 1;
  const rolledOffset = Math.floor(random() * span);
  const offset =
    level.minDays + clampNumber(rolledOffset, 0, Math.max(0, span - 1));
  return Object.freeze({
    date: addLocalDateDays(getLocalDateStart(baseDate), offset),
    offset,
  });
}

function rollPriorityScheduledDate(level, baseDate, random = Math.random) {
  return rollPriorityScheduledDateWithOffset(level, baseDate, random).date;
}

// Roll a recommendation date that never lands on the task's current `scheduled`
// date when the window has room. Draws uniformly from the window minus the
// current date's offset, and only when that offset is inside the window and the
// window spans more than one day; otherwise behaves exactly like
// rollPriorityScheduledDateWithOffset. A skipped automatic entry (unchanged
// date) would otherwise silently lose a streak step.
function rollPriorityRecommendationDate(
  level,
  baseDate,
  random = Math.random,
  avoidValue = "",
) {
  const bounds = getPriorityRollBounds(level);
  const start = getLocalDateStart(baseDate);
  if (!bounds) {
    return rollPriorityScheduledDateWithOffset(level, baseDate, random);
  }
  const span = bounds.maxDays - bounds.minDays + 1;
  if (!(span > 1)) {
    return rollPriorityScheduledDateWithOffset(level, baseDate, random);
  }
  const avoidText = normalizeBulletPropertyValue(avoidValue);
  const avoidMatch = /^(\d{4})-(\d{2})-(\d{2})/.exec(avoidText);
  if (!avoidMatch) {
    return rollPriorityScheduledDateWithOffset(level, baseDate, random);
  }
  const avoidDate = new Date(
    Number(avoidMatch[1]),
    Number(avoidMatch[2]) - 1,
    Number(avoidMatch[3]),
  );
  if (!Number.isFinite(avoidDate.getTime())) {
    return rollPriorityScheduledDateWithOffset(level, baseDate, random);
  }
  const avoidOffset = getLocalDayOffset(start, avoidDate);
  if (avoidOffset < bounds.minDays || avoidOffset > bounds.maxDays) {
    return rollPriorityScheduledDateWithOffset(level, baseDate, random);
  }
  const rolled = Math.floor(random() * (span - 1));
  const clamped = clampNumber(rolled, 0, Math.max(0, span - 2));
  let offset = bounds.minDays + clamped;
  if (offset >= avoidOffset) {
    offset += 1;
  }
  return Object.freeze({
    date: addLocalDateDays(start, offset),
    offset,
  });
}

function addLocalDateMonths(date, months) {
  const targetMonthIndex = date.getMonth() + months;
  const targetYear = date.getFullYear() + Math.floor(targetMonthIndex / 12);
  const normalizedMonthIndex = ((targetMonthIndex % 12) + 12) % 12;
  const targetMonth = normalizedMonthIndex + 1;
  const targetDay = Math.min(
    date.getDate(),
    getDaysInMonth(targetYear, targetMonth),
  );

  return new Date(targetYear, normalizedMonthIndex, targetDay);
}

function getDaysUntilWeekday(date, weekday, allowToday) {
  const delta = (weekday - date.getDay() + 7) % 7;
  return delta === 0 && !allowToday ? 7 : delta;
}

function formatBulletPropertyDate(date) {
  const year = date.getFullYear();
  const month = String(date.getMonth() + 1).padStart(2, "0");
  const day = String(date.getDate()).padStart(2, "0");
  return `${year}-${month}-${day}`;
}

function getBulletPropertyDateWeekday(date) {
  return BULLET_PROPERTY_WEEKDAY_NAMES[date.getDay()] || "";
}

function createBulletPropertyDateValueItem(
  label,
  date,
  currentValue,
  options = {},
) {
  const value = formatBulletPropertyDate(date);
  const weekday = getBulletPropertyDateWeekday(date);
  return {
    kind: "value",
    value,
    label,
    detail: `${value} · ${weekday}`,
    current: value === currentValue,
    dynamic: !!options.dynamic,
    searchText: `${label} ${value} ${weekday}`,
  };
}

function createBulletPropertyDateItems(baseDate, currentValue) {
  const today = getLocalDateStart(baseDate);
  const saturday = addLocalDateDays(
    today,
    getDaysUntilWeekday(today, 6, true),
  );
  const sunday = addLocalDateDays(today, getDaysUntilWeekday(today, 0, true));
  const nextMonday = addLocalDateDays(
    today,
    getDaysUntilWeekday(today, 1, false),
  );

  return [
    ["Today", today],
    ["Tomorrow", addLocalDateDays(today, 1)],
    ["In 2 days", addLocalDateDays(today, 2)],
    ["In 3 days", addLocalDateDays(today, 3)],
    ["This Saturday", saturday],
    ["This Sunday", sunday],
    ["Next Monday", nextMonday],
    ["In 1 week", addLocalDateDays(today, 7)],
    ["In 2 weeks", addLocalDateDays(today, 14)],
    ["In 1 month", addLocalDateMonths(today, 1)],
  ].map(([label, date]) =>
    createBulletPropertyDateValueItem(label, date, currentValue),
  );
}

function createPriorityRollDateItem(
  level,
  baseDate,
  currentValue,
  random = Math.random,
) {
  const roll = rollPriorityScheduledDateWithOffset(level, baseDate, random);
  const date = roll.date;
  const value = formatBulletPropertyDate(date);
  const weekday = getBulletPropertyDateWeekday(date);
  return {
    kind: "value",
    value,
    label: `${level.label} roll`,
    detail: `${value} · ${weekday} · ${formatPriorityRollWindowText(level)}`,
    current: value === currentValue,
    dynamic: false,
    priorityRoll: true,
    level,
    rolledDays: roll.offset,
    searchText: `${level.label} roll ${value} ${weekday} random priority`,
  };
}

function getPriorityLevelIconName(levelIndex) {
  if (levelIndex === 0) {
    return "signal-high";
  }
  if (levelIndex === 1) {
    return "signal-medium";
  }
  if (levelIndex === 2) {
    return "signal-low";
  }
  return "signal-zero";
}

function normalizePriorityLevelIndex(property, level, levelIndex) {
  if (Number.isInteger(levelIndex) && levelIndex >= 0) {
    return levelIndex;
  }
  const levels = property && Array.isArray(property.levels)
    ? property.levels
    : [];
  const directIndex = levels.indexOf(level);
  if (directIndex >= 0) {
    return directIndex;
  }
  const levelLabel = level && normalizeBulletPropertyValue(level.label);
  const levelValue = level && normalizeBulletPropertyValue(level.value);
  const matchingIndex = levels.findIndex(
    (candidate) =>
      normalizeBulletPropertyValue(candidate && candidate.label) === levelLabel &&
      normalizeBulletPropertyValue(candidate && candidate.value) === levelValue,
  );
  return matchingIndex >= 0 ? matchingIndex : 0;
}

function parsePriorityNoticeScheduledValue(value) {
  const text = normalizeBulletPropertyValue(value);
  const validation = validateProjectScheduledDate(text);
  if (!validation.valid) {
    return Object.freeze({
      text: text || validation.value,
      valid: false,
      date: null,
      time: null,
      weekday: "",
    });
  }
  const date = projectScheduleLocalDate(validation);
  return Object.freeze({
    text: validation.value,
    valid: true,
    date,
    time: getLocalDateStart(date).getTime(),
    weekday: getBulletPropertyDateWeekday(date),
  });
}

function getPriorityNoticeScheduleSummary(values, baseDate) {
  const entries = (Array.isArray(values) ? values : [values])
    .map(parsePriorityNoticeScheduledValue)
    .filter((entry) => entry.text);
  if (entries.length === 0) {
    return Object.freeze({
      exactDateText: "",
      dateStartText: "",
      dateEndText: "",
      weekdayText: "",
      relativeText: "",
      textDateText: "",
      dateText: "",
    });
  }
  const validEntries = entries.filter((entry) => entry.valid);
  if (validEntries.length !== entries.length) {
    if (entries.length === 1) {
      return Object.freeze({
        exactDateText: entries[0].text,
        dateStartText: entries[0].text,
        dateEndText: "",
        weekdayText: "",
        relativeText: "",
        textDateText: entries[0].text,
        dateText: entries[0].text,
      });
    }
    const firstText = entries[0].text;
    const lastText = entries[entries.length - 1].text;
    const textDateText = `${firstText} to ${lastText}`;
    return Object.freeze({
      exactDateText: `${firstText} → ${lastText}`,
      dateStartText: firstText,
      dateEndText: lastText,
      weekdayText: "",
      relativeText: "",
      textDateText,
      dateText: textDateText,
    });
  }

  const sortedEntries = validEntries
    .slice()
    .sort((first, second) => first.time - second.time);
  const first = sortedEntries[0];
  const last = sortedEntries[sortedEntries.length - 1];
  if (first.time === last.time) {
    const textDateText = `${first.text} · ${first.weekday}`;
    return Object.freeze({
      exactDateText: first.text,
      dateStartText: first.text,
      dateEndText: "",
      weekdayText: first.weekday,
      relativeText: formatRelativeDayOffset(
        getLocalDayOffset(baseDate, first.date),
      ),
      textDateText,
      dateText: textDateText,
    });
  }

  const minOffset = getLocalDayOffset(baseDate, first.date);
  const maxOffset = getLocalDayOffset(baseDate, last.date);
  const textDateText = `${first.text} to ${last.text}`;
  return Object.freeze({
    exactDateText: `${first.text} → ${last.text}`,
    dateStartText: first.text,
    dateEndText: last.text,
    weekdayText: "",
    relativeText: formatRelativeDayRange(minOffset, maxOffset),
    textDateText,
    dateText: textDateText,
  });
}

function normalizePriorityNoticeCount(value) {
  return Math.max(0, Math.floor(numericOrDefault(value, 0)));
}

function getPriorityNoticeRecoveryCounts(outcome = {}) {
  const recoveryCounts = outcome.recoveryCounts || {};
  return Object.freeze({
    ready: normalizePriorityNoticeCount(
      recoveryCounts.ready ?? outcome.recoveredReadyTaskCount,
    ),
    next: normalizePriorityNoticeCount(
      recoveryCounts.next ?? outcome.recoveredNextTaskCount,
    ),
    inProgress: normalizePriorityNoticeCount(
      recoveryCounts.inProgress ?? outcome.recoveredInProgressTaskCount,
    ),
    stillBlocked: normalizePriorityNoticeCount(
      recoveryCounts.stillBlocked ?? outcome.stillBlockedTaskCount,
    ),
    deferred: normalizePriorityNoticeCount(
      recoveryCounts.deferred ?? outcome.deferredRecoveryTaskCount,
    ),
  });
}

function getPriorityNoticeBlockedText(count, scope) {
  if (count <= 0) {
    return "";
  }
  if (scope === "task") {
    return "marked task Blocked";
  }
  return `marked ${formatCountLabel(count, "task")} Blocked`;
}

function getPriorityNoticeOutcomeParts(outcome = {}, scope = "task") {
  const parts = [];
  if (scope === "counted") {
    parts.push(
      ...getCountedTaskNoticeParts(
        outcome.session,
        normalizePriorityNoticeCount(outcome.unchangedTaskCount),
      ),
    );
  }
  const propagatedScheduleTaskCount = normalizePriorityNoticeCount(
    outcome.propagatedScheduleTaskCount ?? outcome.scheduledTaskCount,
  );
  if (propagatedScheduleTaskCount > 0) {
    parts.push(
      `scheduled ${formatCountLabel(propagatedScheduleTaskCount, "task")}`,
    );
  }
  const removedHideTaskCount = normalizePriorityNoticeCount(
    outcome.removedHideTaskCount,
  );
  if (removedHideTaskCount > 0) {
    parts.push(
      `removed #hide from ${formatCountLabel(removedHideTaskCount, "task")}`,
    );
  }
  const scheduleLoggedTaskCount = normalizePriorityNoticeCount(outcome.scheduleLoggedTaskCount);
  if (scheduleLoggedTaskCount > 0) {
    parts.push(
      scope === "counted" ? `logged reason on ${formatCountLabel(scheduleLoggedTaskCount, "task")}` : "logged reason",
    );
  }
  const schedulingWorkLogWrittenCount = normalizePriorityNoticeCount(
    outcome.schedulingWorkLogWrittenCount,
  );
  if (schedulingWorkLogWrittenCount > 0) {
    parts.push(
      scope === "counted"
        ? `${formatCountLabel(schedulingWorkLogWrittenCount, "Work Log")}`
        : "1 Work Log",
    );
  }
  const blockedText = getPriorityNoticeBlockedText(
    normalizePriorityNoticeCount(outcome.blockedTaskCount),
    scope,
  );
  if (blockedText) {
    parts.push(blockedText);
  }
  const ambiguousTaskCount = normalizePriorityNoticeCount(
    outcome.ambiguousTaskCount ?? outcome.ambiguousProjectTaskCount,
  );
  if (ambiguousTaskCount > 0) {
    parts.push(
      `${formatCountLabel(ambiguousTaskCount, "task")} with multiple scheduled fields unchanged`,
    );
  }
  parts.push(...scheduledRecoveryNoticeParts(getPriorityNoticeRecoveryCounts(outcome)));
  const removedPomodoroLinkCount = normalizePriorityNoticeCount(
    outcome.removedPomodoroLinkCount,
  );
  if (removedPomodoroLinkCount > 0) {
    parts.push(
      `removed ${formatCountLabel(removedPomodoroLinkCount, "Pomodoro link")}`,
    );
  } else if (outcome.pomodoroPruneFailed) {
    parts.push("Pomodoro links not removed");
  }
  return Object.freeze(parts);
}

function getPriorityNoticeChipTone(text) {
  if (/^recovered /.test(text)) {
    return "ok";
  }
  if (/Blocked$/.test(text)) {
    return "warn";
  }
  if (text === "Pomodoro links not removed") {
    return "warn";
  }
  if (/^(scheduled|removed #hide|removed \d+ Pomodoro links?)/.test(text)) {
    return "info";
  }
  if (/^logged reason/.test(text)) {
    return "info";
  }
  if (/Work Log$/.test(text)) {
    return "info";
  }
  return "muted";
}

function getPriorityNoticeChipText(text) {
  const markedMatch = /^marked (?:(\d+) tasks?|task) Blocked$/.exec(text);
  if (markedMatch) {
    return markedMatch[1] ? `${markedMatch[1]} Blocked` : "Blocked";
  }
  const loggedMatch = /^logged reason(?: on (\d+) tasks?)?$/.exec(text);
  if (loggedMatch) {
    return loggedMatch[1] ? `${loggedMatch[1]} logged` : "logged";
  }
  const workLogMatch = /^(\d+) Work Logs?$/.exec(text);
  if (workLogMatch) {
    return workLogMatch[1] === "1" ? "1 Work Log" : `${workLogMatch[1]} Work Log`;
  }
  if (text === "1 Work Log") {
    return "1 Work Log";
  }
  const pomodoroRemovedMatch = /^removed (\d+) Pomodoro links?$/.exec(text);
  if (pomodoroRemovedMatch) {
    return `${pomodoroRemovedMatch[1]} removed`;
  }
  if (text === "Pomodoro links not removed") {
    return "not removed";
  }
  return text;
}

function formatPriorityNoticeText(model) {
  const parts = [];
  if (model.textHeader) {
    parts.push(model.textHeader);
  }
  if (Array.isArray(model.leadingTextParts)) {
    parts.push(...model.leadingTextParts);
  }
  const dateText = model.textDateText || model.dateText || model.exactDateText;
  if (dateText) {
    const dateLabel = model.textDateLabel || model.dateLabel || "scheduled";
    const relativeText = model.relativeText ? ` · ${model.relativeText}` : "";
    parts.push(`${dateLabel} → ${dateText}${relativeText}`);
  }
  if (Array.isArray(model.outcomeTextParts)) {
    parts.push(...model.outcomeTextParts);
  }
  return parts.join("; ");
}

// ---- src/280-notices-and-dates.js ----
function buildPriorityNoticeModel(options = {}) {
  const property = options.property || {};
  const level = options.level || {};
  const scope = ["task", "counted", "project"].includes(options.scope)
    ? options.scope
    : "task";
  const propertyName = normalizeBulletPropertyName(property.name) || "priority";
  const scheduledName =
    normalizeBulletPropertyName(property.schedules) || "scheduled";
  const levelIndex = normalizePriorityLevelIndex(
    property,
    level,
    options.levelIndex,
  );
  const roll =
    options.roll && typeof options.roll === "object" ? options.roll : null;
  const rollKind =
    roll && typeof roll.kind === "string" ? roll.kind : "";
  const rollFromLevel = normalizeBulletPropertyValue(roll && roll.fromLevel);
  const pill =
    rollKind === "roll" && normalizeBulletPropertyValue(level.label)
      ? `${normalizeBulletPropertyValue(level.label)} roll`
      : rollKind === "decay" && rollFromLevel && normalizeBulletPropertyValue(level.label)
        ? `${rollFromLevel} → ${normalizeBulletPropertyValue(level.label)}`
        : normalizeBulletPropertyValue(level.label);
  const levelValue = normalizeBulletPropertyValue(level.value);
  const taskCount = Math.max(
    1,
    normalizePriorityNoticeCount(options.taskCount || 1),
  );
  const scheduleSummary = getPriorityNoticeScheduleSummary(
    options.scheduledValues || [],
    options.baseDate instanceof Date
      ? getLocalDateStart(options.baseDate)
      : getLocalDateStart(new Date()),
  );
  const outcomeTextParts = getPriorityNoticeOutcomeParts(
    options.outcome || {},
    scope,
  );
  const textHeader =
    rollKind === "roll"
      ? `${scheduledName} → ${pill}`
      : rollKind === "decay"
        ? `${propertyName} → ${normalizeBulletPropertyValue(level.label)} (${levelValue}) · decayed from ${rollFromLevel}`
        : scope === "counted"
          ? `${propertyName} → ${pill} (${levelValue}) on ${formatCountLabel(
              taskCount,
              "task",
            )}`
          : `${propertyName} → ${pill} (${levelValue})`;
  // Leading roll chips, before the existing outcome chips. With decay
  // disabled (no step/limit) there are no roll or next chips.
  const leadingChips = [];
  if (rollKind === "roll" && Number.isFinite(Number(roll.step)) && roll.limit !== null && roll.limit !== undefined) {
    leadingChips.push(
      Object.freeze({ text: `roll ${roll.step}/${roll.limit}`, tone: "info" }),
    );
  } else if (rollKind === "decay" && rollFromLevel) {
    leadingChips.push(
      Object.freeze({ text: `decayed from ${rollFromLevel}`, tone: "warn" }),
    );
  }
  if (
    (rollKind === "roll" || rollKind === "decay") &&
    roll &&
    typeof roll.next === "string"
  ) {
    if (roll.next === "decay" && normalizeBulletPropertyValue(roll.nextLabel)) {
      leadingChips.push(
        Object.freeze({
          text: `next ^↵ → ${normalizeBulletPropertyValue(roll.nextLabel)}`,
          tone: "warn",
        }),
      );
    } else if (roll.next === "cancel") {
      leadingChips.push(
        Object.freeze({ text: "next ^↵ cancels", tone: "warn" }),
      );
    }
  }
  const leadingTextParts = leadingChips.map((chip) => chip.text);
  const model = {
    iconName: getPriorityLevelIconName(levelIndex),
    levelIndex,
    pill,
    countPill: scope === "counted" ? formatCountLabel(taskCount, "task") : "",
    receipt: `[${propertyName}:: ${levelValue}]`,
    dateLabel: scope === "project" ? `${scheduledName} (project)` : scheduledName,
    textDateLabel: scheduledName,
    exactDateText: scheduleSummary.exactDateText,
    dateStartText: scheduleSummary.dateStartText,
    dateEndText: scheduleSummary.dateEndText,
    weekdayText: scheduleSummary.weekdayText,
    textDateText: scheduleSummary.textDateText,
    dateText: scheduleSummary.dateText,
    relativeText: scheduleSummary.relativeText,
    chips: Object.freeze([
      ...leadingChips,
      ...outcomeTextParts.map((part) =>
        Object.freeze({
          text: getPriorityNoticeChipText(part),
          tone: getPriorityNoticeChipTone(part),
        }),
      ),
    ]),
    outcomeTextParts,
    leadingTextParts: Object.freeze(leadingTextParts),
    textHeader,
  };
  model.text = formatPriorityNoticeText(model);
  return Object.freeze(model);
}

// One priority-style card for a counted recommended-roll batch: header icon
// `dices`, pill `Rolled N tasks`, leading `N rolled` / `N decayed` /
// `N cancelled` chips, the rolled date span, then the existing outcome chips
// (Blocked, removed Pomodoro links, skipped, prune-failed). Pure.
function buildBatchPriorityRollNoticeModel(batch, options = {}) {
  const counts = (batch && batch.counts) || {};
  const rolled = Math.max(0, Math.floor(numericOrDefault(counts.roll, 0)));
  const decayed = Math.max(0, Math.floor(numericOrDefault(counts.decay, 0)));
  const cancelled = Math.max(0, Math.floor(numericOrDefault(counts.cancel, 0)));
  const actionable = Math.max(
    0,
    Math.floor(
      numericOrDefault(
        batch && batch.actionableCount,
        rolled + decayed + cancelled,
      ),
    ),
  );
  const baseDate =
    options.baseDate instanceof Date
      ? getLocalDateStart(options.baseDate)
      : getLocalDateStart(new Date());
  const scheduledValues = Array.isArray(options.scheduledValues)
    ? options.scheduledValues
    : [];
  const scheduleSummary = getPriorityNoticeScheduleSummary(
    scheduledValues,
    baseDate,
  );
  const outcome = options.outcome || {};
  const outcomeTextParts = getPriorityNoticeOutcomeParts(outcome, "counted");
  const leadingChips = [];
  if (rolled > 0) {
    leadingChips.push(
      Object.freeze({
        text: `${rolled} rolled`,
        tone: "info",
      }),
    );
  }
  if (decayed > 0) {
    leadingChips.push(
      Object.freeze({ text: `${decayed} decayed`, tone: "warn" }),
    );
  }
  if (cancelled > 0) {
    leadingChips.push(
      Object.freeze({ text: `${cancelled} cancelled`, tone: "warn" }),
    );
  }
  const leadingTextParts = leadingChips.map((chip) => chip.text);
  const skipped = Math.max(
    0,
    Math.floor(
      numericOrDefault(
        outcome.skippedCount ?? (batch && batch.skippedCount),
        0,
      ),
    ),
  );
  const fullOutcomeParts = skipped > 0
    ? Object.freeze([
        ...outcomeTextParts,
        `${formatCountLabel(skipped, "task")} skipped`,
      ])
    : outcomeTextParts;
  const pill = `Rolled ${formatCountLabel(actionable, "task")}`;
  const model = {
    iconName: "dices",
    levelIndex: null,
    pill,
    countPill: "",
    receipt: "[priority]",
    dateLabel: "scheduled",
    textDateLabel: "scheduled",
    exactDateText: scheduleSummary.exactDateText,
    dateStartText: scheduleSummary.dateStartText,
    dateEndText: scheduleSummary.dateEndText,
    weekdayText: scheduleSummary.weekdayText,
    textDateText: scheduleSummary.textDateText,
    dateText: scheduleSummary.dateText,
    relativeText: scheduleSummary.relativeText,
    chips: Object.freeze([
      ...leadingChips,
      ...fullOutcomeParts.map((part) =>
        Object.freeze({
          text: getPriorityNoticeChipText(part),
          tone: getPriorityNoticeChipTone(part),
        }),
      ),
    ]),
    outcomeTextParts: fullOutcomeParts,
    leadingTextParts: Object.freeze(leadingTextParts),
    textHeader: pill,
  };
  model.text = formatPriorityNoticeText(model);
  return Object.freeze(model);
}

function renderPriorityNoticeFragment(model, root) {
  const levelClass =
    Number.isInteger(model.levelIndex) &&
    model.levelIndex >= 0 &&
    model.levelIndex <= 3
      ? ` is-level-${model.levelIndex}`
      : "";
  const card = root.createDiv({
    cls: `bob-nh-notice${levelClass}`,
    attr: { "aria-label": model.text },
  });
  const headerEl = card.createDiv({ cls: "bob-nh-notice-header" });
  const iconEl = headerEl.createSpan({ cls: "bob-nh-notice-icon" });
  applyIcon(iconEl, model.iconName);
  headerEl.createSpan({ cls: "bob-nh-notice-level", text: model.pill });
  if (model.countPill) {
    headerEl.createSpan({ cls: "bob-nh-notice-count", text: model.countPill });
  }
  headerEl.createSpan({ cls: "bob-nh-notice-receipt", text: model.receipt });

  const dateEl = card.createDiv({ cls: "bob-nh-notice-date" });
  const dateHeadingEl = dateEl.createDiv({
    cls: "bob-nh-notice-date-heading",
  });
  const dateIconEl = dateHeadingEl.createSpan({ cls: "bob-nh-notice-date-icon" });
  applyIcon(dateIconEl, "dices");
  dateHeadingEl.createSpan({
    cls: "bob-nh-notice-date-label",
    text: model.dateLabel,
  });
  if (model.relativeText) {
    dateHeadingEl.createSpan({
      cls: "bob-nh-notice-relative",
      text: model.relativeText,
    });
  }
  const receiptEl = dateEl.createDiv({
    cls: "bob-nh-notice-date-receipt",
  });
  receiptEl.createSpan({
    cls: "bob-nh-notice-date-iso",
    text: model.dateStartText || model.exactDateText || "",
  });
  if (model.dateEndText) {
    receiptEl.createSpan({
      cls: "bob-nh-notice-date-arrow",
      text: "→",
      attr: { "aria-hidden": "true" },
    });
    receiptEl.createSpan({
      cls: "bob-nh-notice-date-iso",
      text: model.dateEndText,
    });
  } else if (model.weekdayText) {
    receiptEl.createSpan({
      cls: "bob-nh-notice-date-separator",
      text: "·",
      attr: { "aria-hidden": "true" },
    });
    receiptEl.createSpan({
      cls: "bob-nh-notice-date-weekday",
      text: model.weekdayText,
    });
  }

  if (model.chips.length > 0) {
    const chipsEl = card.createDiv({ cls: "bob-nh-notice-chips" });
    model.chips.forEach((chip) => {
      chipsEl.createSpan({
        cls: `bob-nh-notice-chip is-${chip.tone}`,
        text: chip.text,
      });
    });
  }

  return card;
}

function showPriorityNotice(model, options = {}) {
  const fallbackText =
    model && typeof model.text === "string" ? model.text : String(model || "");
  try {
    if (typeof document === "undefined") {
      showBulletPropertyNotice(fallbackText, options);
      return;
    }
    const fragment = document.createDocumentFragment();
    if (!fragment || typeof fragment.createDiv !== "function") {
      showBulletPropertyNotice(fallbackText, options);
      return;
    }
    renderPriorityNoticeFragment(model, fragment);
    showBulletPropertyNotice(fragment, options);
  } catch (error) {
    showBulletPropertyNotice(fallbackText, options);
  }
}

// Read the ledger-tools plan budget for a cancel notice chip, or "" when the
// API is missing or unusable. `dailyContent` is the post-prune daily note
// text, the same input block-id-prompt's unlink notices use.
function getCancelPlanBudgetChip(app, dailyContent) {
  if (typeof dailyContent !== "string") {
    return "";
  }
  try {
    const plugins = app && app.plugins && app.plugins.plugins;
    const api =
      plugins &&
      plugins["bob-ledger-tools"] &&
      plugins["bob-ledger-tools"].api;
    if (!api || typeof api.planBudget !== "function") {
      return "";
    }
    const budget = api.planBudget({ content: dailyContent });
    if (
      !budget ||
      typeof budget !== "object" ||
      typeof budget.then === "function"
    ) {
      return "";
    }
    const themes = budget.themes;
    const links = budget.links;
    if (
      !themes ||
      !links ||
      !Number.isInteger(themes.count) ||
      !Number.isInteger(themes.cap) ||
      !Number.isInteger(links.count) ||
      !Number.isInteger(links.cap)
    ) {
      return "";
    }
    const over =
      budget.status === "over" || themes.over === true || links.over === true;
    return `plan ${themes.count}/${themes.cap} · ${links.count}/${links.cap}${over ? " 🔴" : ""}`;
  } catch (error) {
    return "";
  }
}

// Pure model for the Cancelled notice card: header (ban icon, `Cancelled`
// level pill, count pill, `[cancelled:: date]` receipt), an italic
// `❌ <reason>` quote (or the muted no-reason/fallback text), and one chip
// per side effect. `model.text` is the aria-label and plain-text fallback.
function buildCancelNoticeModel(options = {}) {
  const count = Math.max(
    1,
    Math.floor(numericOrDefault(options.count, 1)),
  );
  const viaLinks = Boolean(options.viaLinks);
  const dateText = normalizeBulletPropertyValue(options.date);
  const reason = String(options.reason || "");
  const fallbackUsed = Boolean(options.fallbackUsed);
  const scopeText =
    viaLinks && count === 1
      ? "task via Task Link"
      : viaLinks
        ? `${formatCountLabel(count, "task")} via Task Links`
        : count === 1
          ? "task"
          : formatCountLabel(count, "task");
  const countPill =
    viaLinks && count === 1
      ? "via Task Link"
      : !viaLinks && count === 1
        ? ""
        : viaLinks
          ? `${formatCountLabel(count, "task")} via Task Links`
          : formatCountLabel(count, "task");
  const chips = [];
  const removedPomodoroLinkCount = Math.max(
    0,
    Math.floor(numericOrDefault(options.removedPomodoroLinkCount, 0)),
  );
  if (removedPomodoroLinkCount > 0) {
    chips.push(
      Object.freeze({
        text: `removed ${formatCountLabel(removedPomodoroLinkCount, "Pomodoro link")}`,
        tone: "info",
      }),
    );
  }
  const reopened = Math.max(
    0,
    Math.floor(numericOrDefault(options.reopenedDependents, 0)),
  );
  if (options.recoveryRan === true && reopened > 0) {
    chips.push(
      Object.freeze({
        text: `unblocked ${formatCountLabel(reopened, "dependent")}`,
        tone: "ok",
      }),
    );
  }
  const planChip = String(options.planChip || "");
  if (planChip) {
    chips.push(Object.freeze({ text: planChip, tone: "info" }));
  }
  const skippedClosedCount = Math.max(
    0,
    Math.floor(numericOrDefault(options.skippedClosedCount, 0)),
  );
  if (skippedClosedCount > 0) {
    chips.push(
      Object.freeze({
        text: `skipped ${formatCountLabel(skippedClosedCount, "closed")}`,
        tone: "muted",
      }),
    );
  }
  if (options.pomodoroPruneFailed === true) {
    chips.push(
      Object.freeze({ text: "Pomodoro links not removed", tone: "warn" }),
    );
  }
  const parts = [`Cancelled ${scopeText}`];
  if (reason) {
    parts.push(`\u201c${reason}\u201d`);
  } else if (fallbackUsed) {
    parts.push(`\u201c${SCHEDULE_LOG_SKIPPED_REASON_TEXT} · logged\u201d`);
  }
  for (const chip of chips) {
    parts.push(chip.text);
  }
  const reasonBody = reason
    ? `${CANCEL_LOG_EMOJI} ${reason}`
    : fallbackUsed
      ? `${SCHEDULE_LOG_SKIPPED_REASON_TEXT} · logged`
      : "No reason recorded";
  return Object.freeze({
    iconName: "ban",
    level: "Cancelled",
    countPill,
    receipt: `[cancelled:: ${dateText}]`,
    reasonBody,
    reasonMuted: !reason,
    chips: Object.freeze(chips),
    text: parts.join(" · "),
  });
}

function renderCancelNoticeFragment(model, root) {
  const card = root.createDiv({
    cls: "bob-nh-notice is-cancel",
    attr: { "aria-label": model.text },
  });
  const headerEl = card.createDiv({ cls: "bob-nh-notice-header" });
  const iconEl = headerEl.createSpan({ cls: "bob-nh-notice-icon" });
  applyIcon(iconEl, model.iconName || "ban");
  headerEl.createSpan({ cls: "bob-nh-notice-level", text: model.level });
  if (model.countPill) {
    headerEl.createSpan({ cls: "bob-nh-notice-count", text: model.countPill });
  }
  headerEl.createSpan({ cls: "bob-nh-notice-receipt", text: model.receipt });

  const reasonEl = card.createDiv({
    cls: `bob-nh-notice-reason${model.reasonMuted ? " is-muted" : ""}`,
  });
  reasonEl.createSpan({ cls: "bob-nh-notice-reason-text", text: model.reasonBody });

  if (model.chips.length > 0) {
    const chipsEl = card.createDiv({ cls: "bob-nh-notice-chips" });
    model.chips.forEach((chip) => {
      chipsEl.createSpan({
        cls: `bob-nh-notice-chip is-${chip.tone}`,
        text: chip.text,
      });
    });
  }

  return card;
}

function showCancelNotice(model, options = {}) {
  const fallbackText =
    model && typeof model.text === "string" ? model.text : String(model || "");
  try {
    if (typeof document === "undefined") {
      showBulletPropertyNotice(fallbackText, options);
      return;
    }
    const fragment = document.createDocumentFragment();
    if (!fragment || typeof fragment.createDiv !== "function") {
      showBulletPropertyNotice(fallbackText, options);
      return;
    }
    renderCancelNoticeFragment(model, fragment);
    showBulletPropertyNotice(fragment, options);
  } catch (error) {
    showBulletPropertyNotice(fallbackText, options);
  }
}

function parseBulletPropertyTypedDate(query, baseDate) {
  const text = String(query || "").trim();
  if (!text) {
    return null;
  }

  const ymdMatch = text.match(/^(\d{4})-(\d{2})-(\d{2})$/);
  if (
    ymdMatch &&
    isValidDateParts(ymdMatch[1], ymdMatch[2], ymdMatch[3])
  ) {
    return new Date(
      parseIntegerText(ymdMatch[1]),
      parseIntegerText(ymdMatch[2]) - 1,
      parseIntegerText(ymdMatch[3]),
    );
  }

  const monthDayMatch = text.match(/^(\d{1,2})[/-](\d{1,2})$/);
  if (monthDayMatch) {
    const monthText = monthDayMatch[1];
    const dayText = monthDayMatch[2];
    let year = baseDate.getFullYear();
    if (!isValidDateParts(String(year), monthText, dayText)) {
      return null;
    }

    let date = new Date(
      year,
      parseIntegerText(monthText) - 1,
      parseIntegerText(dayText),
    );
    if (compareLocalDates(date, baseDate) <= 0) {
      year += 1;
      if (!isValidDateParts(String(year), monthText, dayText)) {
        return null;
      }
      date = new Date(
        year,
        parseIntegerText(monthText) - 1,
        parseIntegerText(dayText),
      );
    }
    return date;
  }

  const offsetMatch = text.match(/^\+(\d+)([dwm])$/i);
  if (offsetMatch) {
    const count = parseIntegerText(offsetMatch[1]);
    const unit = offsetMatch[2].toLowerCase();
    if (!Number.isInteger(count) || count < 0) {
      return null;
    }

    if (unit === "d") {
      return addLocalDateDays(baseDate, count);
    }
    if (unit === "w") {
      return addLocalDateDays(baseDate, count * 7);
    }
    return addLocalDateMonths(baseDate, count);
  }

  return null;
}

function createBulletPropertyTypedDateItem(query, baseDate, currentValue) {
  const date = parseBulletPropertyTypedDate(query, baseDate);
  if (!date) {
    return null;
  }

  const value = formatBulletPropertyDate(date);
  return createBulletPropertyDateValueItem(`Use ${value}`, date, currentValue, {
    dynamic: true,
  });
}

const TYPED_SCHEDULE_ERROR_INVALID = "invalid date";
const TYPED_SCHEDULE_ERROR_NEGATIVE = "negative offset";
const TYPED_SCHEDULE_ERROR_OVERFLOW = "overflow offset";
const TYPED_SCHEDULE_ERROR_AMBIGUOUS = "ambiguous input";
const TYPED_SCHEDULE_MAX_COUNT_DIGITS = 5;
const TYPED_SCHEDULE_WEEKDAY_INDEX = Object.freeze({
  sun: 0,
  sunday: 0,
  mon: 1,
  monday: 1,
  tue: 2,
  tuesday: 2,
  wed: 3,
  wednesday: 3,
  thu: 4,
  thursday: 4,
  fri: 5,
  friday: 5,
  sat: 6,
  saturday: 6,
});

function freezeTypedScheduleResult(date, reason, valid, error) {
  return Object.freeze({
    date: valid && date instanceof Date ? getLocalDateStart(date) : null,
    reason: String(reason || ""),
    valid: valid === true,
    error: valid ? null : error || null,
  });
}

function parseTypedScheduleCount(text) {
  const digits = String(text || "");
  if (!/^\d+$/.test(digits)) {
    return { error: TYPED_SCHEDULE_ERROR_INVALID };
  }
  if (digits.length > TYPED_SCHEDULE_MAX_COUNT_DIGITS) {
    return { error: TYPED_SCHEDULE_ERROR_OVERFLOW };
  }
  const count = Number.parseInt(digits, 10);
  if (!Number.isInteger(count) || count < 0) {
    return { error: TYPED_SCHEDULE_ERROR_OVERFLOW };
  }
  return { count };
}

function typedScheduleDateOrError(date) {
  if (!(date instanceof Date) || !Number.isFinite(date.getTime())) {
    return { error: TYPED_SCHEDULE_ERROR_OVERFLOW };
  }
  const year = date.getFullYear();
  if (year < 1 || year > 9999) {
    return { error: TYPED_SCHEDULE_ERROR_OVERFLOW };
  }
  return { date: getLocalDateStart(date) };
}

function parseTypedScheduleMonthDay(monthText, dayText, baseDate) {
  let year = baseDate.getFullYear();
  if (!isValidDateParts(String(year), monthText, dayText)) {
    return { error: TYPED_SCHEDULE_ERROR_INVALID };
  }
  let date = new Date(
    year,
    parseIntegerText(monthText) - 1,
    parseIntegerText(dayText),
  );
  if (compareLocalDates(date, baseDate) <= 0) {
    year += 1;
    if (!isValidDateParts(String(year), monthText, dayText)) {
      return { error: TYPED_SCHEDULE_ERROR_INVALID };
    }
    date = new Date(
      year,
      parseIntegerText(monthText) - 1,
      parseIntegerText(dayText),
    );
  }
  return typedScheduleDateOrError(date);
}

function applyTypedScheduleUnit(baseDate, count, unit) {
  if (unit === "d") {
    return typedScheduleDateOrError(addLocalDateDays(baseDate, count));
  }
  if (unit === "w") {
    return typedScheduleDateOrError(addLocalDateDays(baseDate, count * 7));
  }
  return typedScheduleDateOrError(addLocalDateMonths(baseDate, count));
}

function matchTypedSchedulePrefix(text) {
  const patterns = [
    { kind: "iso", re: /^(\d{4})-(\d{2})-(\d{2})/ },
    { kind: "month-day", re: /^(\d{1,2})[/-](\d{1,2})/ },
    { kind: "unit", re: /^([+-]?)(\d+)([dwm])/i },
    { kind: "days", re: /^([+-]?)(\d+)/ },
    {
      kind: "weekday",
      re: /^(sunday|monday|tuesday|wednesday|thursday|friday|saturday|sun|mon|tue|wed|thu|fri|sat)/i,
    },
  ];
  for (const pattern of patterns) {
    const match = pattern.re.exec(text);
    if (!match) {
      continue;
    }
    const token = match[0];
    const restRaw = text.slice(token.length);
    if (restRaw !== "" && !/^\s/.test(restRaw)) {
      return Object.freeze({ kind: "attached", token, rest: restRaw });
    }
    return Object.freeze({
      kind: pattern.kind,
      token,
      rest: restRaw.trim(),
      match,
    });
  }
  return null;
}

// Conservative Task Card date grammar. An inline reason is the remainder
// after a complete recognized date token and whitespace; it is never parsed
// as further commands. Unrecognized input returns valid=false with no error
// so ordinary preset filtering can keep the query.
function resolveTypedSchedule(query, baseDate) {
  const text = String(query || "").trim();
  const start = getLocalDateStart(
    baseDate instanceof Date ? baseDate : new Date(),
  );
  if (!text) {
    return freezeTypedScheduleResult(null, "", false, null);
  }

  const prefix = matchTypedSchedulePrefix(text);
  if (!prefix) {
    return freezeTypedScheduleResult(null, "", false, null);
  }
  if (prefix.kind === "attached") {
    return freezeTypedScheduleResult(
      null,
      "",
      false,
      TYPED_SCHEDULE_ERROR_AMBIGUOUS,
    );
  }

  const reason = prefix.rest;
  if (prefix.kind === "iso") {
    const yearText = prefix.match[1];
    const monthText = prefix.match[2];
    const dayText = prefix.match[3];
    if (!isValidDateParts(yearText, monthText, dayText)) {
      return freezeTypedScheduleResult(
        null,
        reason,
        false,
        TYPED_SCHEDULE_ERROR_INVALID,
      );
    }
    const resolved = typedScheduleDateOrError(
      new Date(
        parseIntegerText(yearText),
        parseIntegerText(monthText) - 1,
        parseIntegerText(dayText),
      ),
    );
    if (resolved.error) {
      return freezeTypedScheduleResult(null, reason, false, resolved.error);
    }
    return freezeTypedScheduleResult(resolved.date, reason, true, null);
  }

  if (prefix.kind === "month-day") {
    const resolved = parseTypedScheduleMonthDay(
      prefix.match[1],
      prefix.match[2],
      start,
    );
    if (resolved.error) {
      return freezeTypedScheduleResult(null, reason, false, resolved.error);
    }
    return freezeTypedScheduleResult(resolved.date, reason, true, null);
  }

  if (prefix.kind === "unit" || prefix.kind === "days") {
    const sign = prefix.match[1] || "";
    const countText = prefix.match[2];
    const unit = prefix.kind === "unit" ? prefix.match[3].toLowerCase() : "d";
    if (sign === "-") {
      return freezeTypedScheduleResult(
        null,
        reason,
        false,
        TYPED_SCHEDULE_ERROR_NEGATIVE,
      );
    }
    if (prefix.kind === "days" && sign === "+") {
      return freezeTypedScheduleResult(
        null,
        reason,
        false,
        TYPED_SCHEDULE_ERROR_AMBIGUOUS,
      );
    }
    const parsedCount = parseTypedScheduleCount(countText);
    if (parsedCount.error) {
      return freezeTypedScheduleResult(null, reason, false, parsedCount.error);
    }
    const resolved = applyTypedScheduleUnit(start, parsedCount.count, unit);
    if (resolved.error) {
      return freezeTypedScheduleResult(null, reason, false, resolved.error);
    }
    return freezeTypedScheduleResult(resolved.date, reason, true, null);
  }

  const weekday =
    TYPED_SCHEDULE_WEEKDAY_INDEX[String(prefix.token || "").toLowerCase()];
  if (!Number.isInteger(weekday)) {
    return freezeTypedScheduleResult(
      null,
      reason,
      false,
      TYPED_SCHEDULE_ERROR_INVALID,
    );
  }
  const resolved = typedScheduleDateOrError(
    addLocalDateDays(start, getDaysUntilWeekday(start, weekday, false)),
  );
  if (resolved.error) {
    return freezeTypedScheduleResult(null, reason, false, resolved.error);
  }
  return freezeTypedScheduleResult(resolved.date, reason, true, null);
}

function createTypedScheduleValueItem(resolved, baseDate, currentValue) {
  if (!resolved) {
    return null;
  }
  const reason = String(resolved.reason || "");
  if (resolved.valid === true && resolved.date instanceof Date) {
    const date = getLocalDateStart(resolved.date);
    const value = formatBulletPropertyDate(date);
    const weekday = getBulletPropertyDateWeekday(date);
    const relative = formatRelativeDayOffset(
      getLocalDayOffset(baseDate, date),
    );
    const yearRollover =
      date.getFullYear() !== getLocalDateStart(baseDate).getFullYear();
    const label = `Use ${weekday} ${value}`;
    const detailParts = [relative];
    if (yearRollover) {
      detailParts.push(String(date.getFullYear()));
    }
    if (reason) {
      detailParts.push(reason);
    }
    return {
      kind: "value",
      value,
      label,
      detail: detailParts.join(" · "),
      current: value === currentValue,
      dynamic: true,
      typedSchedule: true,
      valid: true,
      inlineReason: reason,
      yearRollover,
      weekday,
      relative,
      searchText: `${label} ${detailParts.join(" ")}`,
    };
  }
  if (resolved.error) {
    return {
      kind: "value",
      value: "",
      label: "Invalid date",
      detail: resolved.error,
      current: false,
      dynamic: true,
      typedSchedule: true,
      valid: false,
      error: resolved.error,
      inlineReason: reason,
      searchText: `invalid date ${resolved.error}`,
    };
  }
  return null;
}

function getLocalTaskDependencyIdentifier(task, filePath = "") {
  if (!task) {
    return "";
  }
  if (task.existingBlockId && filePath) {
    return tryDependencyId(filePath, task.existingBlockId) || "";
  }
  return task.existingIdField || task.existingBlockId || "";
}

// ---- src/290-local-task-items.js ----
function createBulletPropertyLocalTaskItems(content, options = {}) {
  const dependencyValues =
    options.dependencyValues instanceof Set
      ? options.dependencyValues
      : new Set(options.dependencyValues || []);
  const dependencyValueSets = Array.isArray(options.dependencyValueSets)
    ? options.dependencyValueSets.map((values) =>
        values instanceof Set ? values : new Set(values || []),
      )
    : [dependencyValues];

  return getOpenLocalTasks(content, {
    excludeLine: options.excludeLine,
    excludeLines: options.excludeLines,
  }).map(
    (task) => {
      // The dependency value stored in `[dependsOn:: ...]` (prefers an existing
      // `[id::]`, then the trailing block ID). The link block ID is the trailing
      // `^block-id` the navigation bullet points at, which may be absent even
      // when a dependency value exists.
      const dependencyValue = getLocalTaskDependencyIdentifier(
        task,
        options.filePath || "",
      );
      const legacyDependencyValue = task.existingIdField || task.existingBlockId || "";
      const linkBlockId = task.existingBlockId || "";
      const linkedSourceCount = dependencyValue
        ? dependencyValueSets.filter(
            (values) =>
              values.has(dependencyValue) ||
              (legacyDependencyValue !== dependencyValue &&
                values.has(legacyDependencyValue)),
          ).length
        : 0;
      const linkState =
        linkedSourceCount === 0
          ? "none"
          : linkedSourceCount === dependencyValueSets.length
            ? "all"
            : "mixed";
      const alreadyLinked = linkState === "all";
      const needsBlockIdPrompt = !linkBlockId;
      const needsDependencyValue = !dependencyValue;
      const needsPromptForAdd = !alreadyLinked && needsBlockIdPrompt;

      return Object.freeze({
        kind: "local-task",
        ...task,
        value: dependencyValue,
        dependencyValue,
        legacyDependencyValue,
        linkBlockId,
        alreadyLinked,
        linkedSourceCount,
        sourceCount: dependencyValueSets.length,
        linkState,
        needsBlockIdPrompt,
        needsDependencyValue,
        needsPromptForAdd,
        searchText: [
          task.displayText,
          `line ${task.line + 1}`,
          task.status,
          dependencyValue,
          alreadyLinked ? "depends linked" : "",
          linkState === "mixed" ? "mixed partially linked" : "",
          needsPromptForAdd
            ? "needs id block create"
            : dependencyValue
              ? "block id"
              : "create id",
        ]
          .filter(Boolean)
          .join(" "),
      });
    },
  );
}

// ---------- Vault-wide Depends on stage (nav-stage) ----------
// `docs/task-dependencies.md` §6 in bob-cli is authoritative: the candidate
// pool is vault-wide (Tasks cache with open-buffer overrides, falling back
// to a one-time vault scan), ranking ports `capture_link_tasks.rs::rank`,
// and rows group into CURRENT / RESULTS / BLOCKED with guards. Every helper
// here is pure and synchronous so the stage never reads from disk on a
// keystroke; the plugin methods below supply the pool and the commit path.
const DEPENDENCY_STAGE_MAX_ROWS = 60;
const DEPENDENCY_STAGE_SECTION_RE = /^#{1,6}\s+(.*?)\s*#*\s*$/;

// Identity key for one stage row or graph node: the NUL separator keeps
// paths with spaces unambiguous (block ids never contain whitespace).
function dependencyStageRowKey(path, blockId) {
  const normalized = normalizeVaultRelativePath(path || "");
  const id = normalizeBulletPropertyValue(blockId || "");
  if (!normalized || !id) {
    return null;
  }
  return `${normalized}\x00${id}`;
}

// One tier check, ported from `field_tier` in
// `src/native/capture_link_tasks.rs`: 3 for a field prefix, 2 for a word
// prefix (the preceding character is not alphanumeric), 1 for a substring,
// and 0 for an in-order subsequence. Both sides are already lowercased.
function dependencyStageFieldTier(field, term) {
  const text = String(field || "");
  const needle = String(term || "");
  if (!needle) {
    return null;
  }
  if (text.startsWith(needle)) {
    return 3;
  }
  let from = text.indexOf(needle, 1);
  while (from !== -1) {
    const before = text[from - 1];
    if (before !== undefined && !/[\p{L}\p{N}]/u.test(before)) {
      return 2;
    }
    from = text.indexOf(needle, from + 1);
  }
  if (text.includes(needle)) {
    return 1;
  }
  let wanted = 0;
  for (const cell of text) {
    if (cell === needle[wanted]) {
      wanted += 1;
      if (wanted >= needle.length) {
        return 0;
      }
    }
  }
  return null;
}

// A term's best tier over the searchable fields, or null when it matches
// nothing: the cleaned description, `route:blockId`, the block id, the note
// route, and the section heading (`docs/task-dependencies.md` §6.3).
function dependencyStageTermTier(candidate, term) {
  const needle = String(term || "").toLowerCase();
  if (!needle || !candidate) {
    return null;
  }
  const fields = [];
  if (candidate.blockId) {
    fields.push(`${candidate.route || ""}:${candidate.blockId}`);
    fields.push(candidate.blockId);
  }
  fields.push(candidate.text || "");
  fields.push(candidate.route || "");
  if (candidate.section) {
    fields.push(candidate.section);
  }
  let best = null;
  for (const field of fields) {
    const tier = dependencyStageFieldTier(
      String(field || "").toLowerCase(),
      needle,
    );
    if (tier !== null && (best === null || tier > best)) {
      best = tier;
    }
  }
  return best;
}

// Rank candidates for a query, ported from `rank` in
// `src/native/capture_link_tasks.rs`: every whitespace-separated term must
// match, tasks order by the summed tiers descending, and ties (and the empty
// query) keep the input order. The sort is stable, so callers pre-sort into
// canonical order first.
function dependencyStageRank(candidates, query) {
  const list = Array.isArray(candidates) ? candidates.slice() : [];
  const terms = String(query || "")
    .split(/\s+/)
    .map((term) => term.toLowerCase())
    .filter(Boolean);
  if (terms.length === 0) {
    return list;
  }
  const scored = [];
  for (const candidate of list) {
    let total = 0;
    let matched = true;
    for (const term of terms) {
      const tier = dependencyStageTermTier(candidate, term);
      if (tier === null) {
        matched = false;
        break;
      }
      total += tier;
    }
    if (matched) {
      scored.push({ candidate, total });
    }
  }
  scored.sort((left, right) => right.total - left.total);
  return scored.map((entry) => entry.candidate);
}

function dependencyStageRouteOf(path) {
  return String(path || "").replace(/\.md$/i, "");
}

function dependencyStageBasenameOf(path) {
  const route = dependencyStageRouteOf(path);
  const at = route.lastIndexOf("/");
  return at === -1 ? route : route.slice(at + 1);
}

// RESULTS exclusions (`docs/task-dependencies.md` §6.2): daily notes
// (`YYYY/YYYYMMDD.md`), `done/`, `_templates`, `_generated`, `_conflicts`
// (matched as a path segment), dot-dirs, and the dependent itself (handled
// by the caller through `dependentLines`). Fenced code never reaches here:
// the task scanner skips it.
function isDependencyStageExcludedPath(path) {
  const normalized = String(path || "").replace(/\\/g, "");
  if (!normalized || isUnsafeVaultPath(normalized)) {
    return true;
  }
  if (/^\d{4}\/\d{8}\.md$/i.test(normalized)) {
    return true;
  }
  const segments = normalized.split("/");
  if (
    segments.some(
      (segment) =>
        segment.startsWith(".") ||
        segment === "_templates" ||
        segment === "_generated" ||
        segment === "_conflicts",
    )
  ) {
    return true;
  }
  return segments[0] === "done";
}

function findDependencyStageSection(lines, line) {
  const sourceLines = Array.isArray(lines) ? lines : [];
  for (let index = line - 1; index >= 0; index -= 1) {
    const match = DEPENDENCY_STAGE_SECTION_RE.exec(
      String(sourceLines[index] || ""),
    );
    if (match) {
      return (match[1] || "").trim() || null;
    }
  }
  return null;
}

// Every `#task` line in one note, open or closed, plus non-task block-id
// carriers (for the "not a task" CURRENT state). Fenced code and frontmatter
// are skipped through the shared line contexts. Sections are carried forward
// during the single scan instead of searching backward per task.
function scanDependencyStageNoteTasks(content) {
  return createDependencyNoteSnapshot(content).entries;
}

function createDependencySnapshotMap(notes) {
  const snapshots = new Map();
  for (const note of Array.isArray(notes) ? notes : []) {
    if (!note) {
      continue;
    }
    const path = normalizeVaultRelativePath(note.path || "");
    if (!path) {
      continue;
    }
    if (!snapshots.has(path)) {
      snapshots.set(path, createDependencyNoteSnapshot(note.content));
    } else {
      snapshots.set(path, createDependencyNoteSnapshot(note.content));
    }
  }
  return snapshots;
}

function collectVaultDependencyCandidatesFromSnapshots(snapshots, options = {}) {
  const dependentPath = normalizeVaultRelativePath(options.dependentPath || "");
  const dependentLines =
    options.dependentLines instanceof Set
      ? options.dependentLines
      : new Set(options.dependentLines || []);
  const out = [];
  for (const [path, snapshot] of snapshots) {
    if (!path || isDependencyStageExcludedPath(path)) {
      continue;
    }
    const route = dependencyStageRouteOf(path);
    const noteName = dependencyStageBasenameOf(path);
    for (const entry of snapshot.entries) {
      if (!entry.isTask || !entry.open) {
        continue;
      }
      if (path === dependentPath && dependentLines.has(entry.line)) {
        continue;
      }
      out.push(
        Object.freeze({
          path,
          route,
          note: noteName,
          line: entry.line,
          rawLine: entry.rawLine,
          status: entry.status,
          displayText: entry.text,
          text: entry.text,
          blockId: entry.blockId,
          existingBlockId: entry.blockId,
          idField: entry.idField,
          existingIdField: entry.idField,
          section: entry.section,
          open: true,
          blocked: entry.blocked,
          hidden: entry.hidden,
        }),
      );
    }
  }
  return Object.freeze(out);
}

function indexDependencyStageNotesFromSnapshots(snapshots) {
  const byKey = new Map();
  const byBlockId = new Map();
  const byIdField = new Map();
  const basenames = new Map();
  const register = (path, entry) => {
    const record = Object.freeze({ path, ...entry });
    if (entry.blockId) {
      const key = dependencyStageRowKey(path, entry.blockId);
      if (!byKey.has(key)) {
        byKey.set(key, record);
      }
      if (!byBlockId.has(entry.blockId)) {
        byBlockId.set(entry.blockId, []);
      }
      byBlockId.get(entry.blockId).push(record);
    }
    if (entry.idField && !byIdField.has(entry.idField)) {
      byIdField.set(entry.idField, record);
    }
    return record;
  };
  for (const [path, snapshot] of snapshots) {
    if (!path) {
      continue;
    }
    const basename = dependencyStageBasenameOf(path);
    if (!basenames.has(basename)) {
      basenames.set(basename, []);
    }
    basenames.get(basename).push(path);
    for (const entry of snapshot.entries) {
      register(path, entry);
    }
  }
  return Object.freeze({ byKey, byBlockId, byIdField, basenames });
}

// The vault-wide RESULTS pool (`docs/task-dependencies.md` §6.2): open
// tasks passing the `#task` global filter, including `ref/`, inbox,
// Blocked, and `#hide`. `notes` is `[{path, content}]`; open editor buffers
// must already override the cache in that list, so unsaved edits count.
function collectVaultDependencyCandidates(notes, options = {}) {
  return collectVaultDependencyCandidatesFromSnapshots(
    createDependencySnapshotMap(notes),
    options,
  );
}

// Lookup over everything — including closed, archived, hidden, and missing
// targets — so CURRENT rows can still be removed
// (`docs/task-dependencies.md` §6.2).
function indexDependencyStageNotes(notes) {
  return indexDependencyStageNotesFromSnapshots(createDependencySnapshotMap(notes));
}

// Resolve one Depends-On line link to its note path: same-note links stay
// put, bare basenames resolve when unique (case-insensitive), otherwise the
// full vault-relative route wins.
function resolveDependencyStageLinkTarget(linkNote, blockId, parentPath, index) {
  const id = normalizeBulletPropertyValue(blockId);
  if (!id || !index) {
    return null;
  }
  const note = String(linkNote || "");
  if (!note) {
    return normalizeVaultRelativePath(parentPath || "");
  }
  if (note.includes("/")) {
    return normalizeVaultRelativePath(`${note}.md`);
  }
  const paths = index.basenames.get(note) || [];
  const lowered = note.toLowerCase();
  const matches = paths.length > 0 ? paths : [];
  if (matches.length === 0) {
    for (const [basename, candidates] of index.basenames) {
      if (basename.toLowerCase() === lowered) {
        return normalizeVaultRelativePath(candidates[0] || "");
      }
    }
    return null;
  }
  return normalizeVaultRelativePath(matches[0] || "");
}

// CURRENT rows: the dependent's existing prerequisites resolved against
// everything, so closed, archived, hidden, and missing targets stay
// removable. Returns `{ok, rows}` or `{ok: false, reason}` for a malformed
// line (left alone, never projected).
function resolveDependencyStageCurrent(content, parentLine, parentPath, index, snapshot = null) {
  const text = String(content || "");
  const lines = snapshot && Array.isArray(snapshot.lines)
    ? snapshot.lines
    : text.split(/\r?\n/);
  const at = Math.floor(numericOrDefault(parentLine, Number.NaN));
  if (!Number.isFinite(at) || at < 0 || at >= lines.length) {
    return Object.freeze({ ok: false, reason: "parent-out-of-range", rows: [] });
  }
  const collection = snapshot
    ? getCachedDependencyCollection(snapshot, text, at)
    : collectDependencyNavigationBullets(text, at);
  if (collection.reason) {
    return Object.freeze({ ok: false, reason: collection.reason, rows: [] });
  }
  const rows = [];
  for (const target of collection.targets) {
    const targetPath = resolveDependencyStageLinkTarget(
      target.note,
      target.blockId,
      parentPath,
      index,
    );
    const key =
      targetPath && target.blockId
        ? dependencyStageRowKey(targetPath, target.blockId)
        : null;
    const record = (key && index.byKey.get(key)) || null;
    if (!record) {
      const siblings =
        (target.blockId && index.byBlockId.get(target.blockId)) || [];
      if (siblings.length === 0) {
        rows.push(
          Object.freeze({
            kind: "current",
            path: targetPath,
            blockId: target.blockId,
            status: "?",
            displayText: `^${target.blockId} not found`,
            text: `^${target.blockId} not found`,
            missing: true,
            open: true,
            blocked: false,
            rawLine: null,
            section: null,
          }),
        );
        continue;
      }
    }
    if (record && !record.isTask) {
      rows.push(
        Object.freeze({
          kind: "current",
          path: record.path,
          blockId: record.blockId,
          status: record.status,
          displayText: record.text,
          text: record.text,
          nonTask: true,
          open: false,
          blocked: false,
          rawLine: record.rawLine,
          section: record.section,
        }),
      );
      continue;
    }
    if (record) {
      rows.push(
        Object.freeze({
          kind: "current",
          path: record.path,
          blockId: record.blockId,
          status: record.status,
          displayText: record.text,
          text: record.text,
          open: record.open,
          blocked: record.blocked,
          closed: !record.open,
          rawLine: record.rawLine,
          section: record.section,
        }),
      );
      continue;
    }
    rows.push(
      Object.freeze({
        kind: "current",
        path: targetPath,
        blockId: target.blockId,
        status: "?",
        displayText: `^${target.blockId} not found`,
        text: `^${target.blockId} not found`,
        missing: true,
        open: true,
        blocked: false,
        rawLine: null,
        section: null,
      }),
    );
  }
  return Object.freeze({ ok: true, reason: null, rows: Object.freeze(rows) });
}

// Dependency edges for cycle guards: each open task's Depends-On line links
// plus its `[dependsOn::]` field ids, resolved to `path blockId` keys.
// Unresolvable links are skipped: they never block and never guard.
function collectDependencyStageEdgesFromSnapshots(snapshots, index) {
  const edges = new Map();
  const add = (from, to) => {
    if (!from || !to || from === to) {
      return;
    }
    if (!edges.has(from)) {
      edges.set(from, []);
    }
    if (!edges.get(from).includes(to)) {
      edges.get(from).push(to);
    }
  };
  for (const [path, snapshot] of snapshots) {
    if (!path || !snapshot) {
      continue;
    }
    const { lines, contexts, text } = snapshot;
    for (const entry of snapshot.entries) {
      if (!entry.isTask || !entry.open) {
        continue;
      }
      const line = entry.line;
      const rawLine = String(lines[line] || "");
      const selfBlockId = entry.blockId;
      const selfIdField = entry.idField;
      const from =
        (selfBlockId && dependencyStageRowKey(path, selfBlockId)) ||
        (selfIdField && `id:${selfIdField}`) ||
        `${path}#line:${line}`;
      const collection = getCachedDependencyCollection(snapshot, text, line);
      if (!collection.reason) {
        for (const target of collection.targets) {
          const targetPath = resolveDependencyStageLinkTarget(
            target.note,
            target.blockId,
            path,
            index,
          );
          if (targetPath && target.blockId) {
            add(from, dependencyStageRowKey(targetPath, target.blockId));
          }
        }
      }
      const field = findBulletPropertyField(rawLine, "dependsOn");
      if (field && index) {
        for (const id of parseLocalTaskIdList(field.value)) {
          const record = index.byIdField.get(id);
          if (record && record.blockId) {
            add(from, dependencyStageRowKey(record.path, record.blockId));
          }
        }
      }
    }
  }
  return edges;
}

function collectDependencyStageEdges(notes, index) {
  return collectDependencyStageEdgesFromSnapshots(createDependencySnapshotMap(notes), index);
}

// Whether linking `fromKey` to `toKey` would create a cycle: `toKey` already
// reaches `fromKey` through the current graph. Returns the cycle path
// (for the tooltip) or null.
function findDependencyStageCycle(edges, fromKey, toKey) {
  if (!fromKey || !toKey || !edges) {
    return null;
  }
  if (fromKey === toKey) {
    return Object.freeze([fromKey]);
  }
  const visited = new Set([toKey]);
  const stack = [{ key: toKey, trail: [toKey] }];
  while (stack.length > 0) {
    const { key, trail } = stack.pop();
    const next = edges instanceof Map ? edges.get(key) : edges[key];
    for (const edge of next || []) {
      if (edge === fromKey) {
        return Object.freeze([...trail, fromKey]);
      }
      if (!visited.has(edge)) {
        visited.add(edge);
        stack.push({ key: edge, trail: [...trail, edge] });
      }
    }
  }
  return null;
}

// Canonical order for ties and the empty query
// (`docs/task-dependencies.md` §6.3): same-note tasks in document order,
// then In Progress, Next, Ready (by path, then line), then `#hide`.
function compareDependencyStageCanonical(first, second, dependentPath) {
  const firstSame = first.path === dependentPath;
  const secondSame = second.path === dependentPath;
  if (firstSame !== secondSame) {
    return firstSame ? -1 : 1;
  }
  if (firstSame && secondSame) {
    return first.line - second.line;
  }
  // `#hide` ranks last, ahead of the lane: a hidden In Progress task sorts
  // after a visible Ready one (`docs/task-dependencies.md` §6.3).
  if (Boolean(first.hidden) !== Boolean(second.hidden)) {
    return first.hidden ? 1 : -1;
  }
  const lane = (status) =>
    status === "/" ? 0 : status === "*" ? 1 : status === " " ? 2 : 3;
  const laneDiff = lane(first.status) - lane(second.status);
  if (laneDiff !== 0) {
    return laneDiff;
  }
  if (first.path !== second.path) {
    return first.path < second.path ? -1 : 1;
  }
  return first.line - second.line;
}

// The staged view: CURRENT, then RESULTS, then BLOCKED
// (`docs/task-dependencies.md` §6). Guards disable rows with a reason: the
// dependent itself, a cycle (checked on the graph after the whole batch,
// with the path), an unencodable target, or a stale target/dependent
// (refused at commit time, then reopened fresh). Removing a link is always
// allowed, so CURRENT rows are never disabled. At most about 60 rows
// render; typing reaches the rest.
// ---- src/300-dependency-stage.js ----
function planDependencyStageView(args = {}) {
  const current = Array.isArray(args.current) ? args.current : [];
  const pool = Array.isArray(args.candidates) ? args.candidates : [];
  const query = String(args.query || "");
  const dependent = args.dependent || {};
  const dependentPath = normalizeVaultRelativePath(dependent.path || "");
  const dependentLine = Math.floor(numericOrDefault(dependent.line, -1));
  const dependentKey = dependent.key || null;
  const edges = args.edges || new Map();
  const linkedKeys = args.linkedKeys instanceof Set ? args.linkedKeys : new Set();
  // Counted sessions (`N<Ctrl+Shift+P>`) match each candidate against every
  // source task's field set, so partially linked rows stay visible with a
  // `k/n depend` badge instead of being folded into CURRENT.
  const sourceValueSets =
    Array.isArray(args.sourceValueSets) && args.sourceValueSets.length > 0
      ? args.sourceValueSets.map((values) =>
          values instanceof Set ? values : new Set(values || []),
        )
      : null;
  const maxRows = Math.max(
    1,
    Math.floor(numericOrDefault(args.maxRows, DEPENDENCY_STAGE_MAX_ROWS)),
  );
  const markedCurrent = current.map((row, index) =>
    Object.freeze({
      ...row,
      stageSection: "current",
      alreadyLinked: true,
      firstInSection: index === 0,
      markKey:
        row.markKey ||
        (row.path
          ? `${normalizeVaultRelativePath(row.path)}#${row.blockId || `line:${row.line}`}`
          : row.line),
    }),
  );
  const candidateAliases = (candidate) => {
    const depValue =
      candidate.idField ||
      (candidate.blockId
        ? tryDependencyId(candidate.path, candidate.blockId)
        : null) ||
      "";
    return [depValue, candidate.idField, candidate.blockId]
      .map(normalizeBulletPropertyValue)
      .filter(Boolean);
  };
  const seen = new Set(linkedKeys);
  const fresh = [];
  for (const candidate of pool) {
    const key =
      candidate.path && candidate.blockId
        ? dependencyStageRowKey(candidate.path, candidate.blockId)
        : null;
    if (
      candidate.path === dependentPath &&
      candidate.line === dependentLine
    ) {
      continue;
    }
    if (sourceValueSets) {
      const aliases = candidateAliases(candidate);
      const linkedCount = sourceValueSets.filter((values) =>
        aliases.some((alias) => values.has(alias)),
      ).length;
      // Fully linked rows live in CURRENT; mixed and unlinked stay in RESULTS.
      if (linkedCount > 0 && linkedCount === sourceValueSets.length) {
        continue;
      }
      fresh.push({ candidate, key, linkedCount });
      continue;
    }
    if (key && seen.has(key)) {
      continue;
    }
    if (key) {
      seen.add(key);
    }
    fresh.push({ candidate, key, linkedCount: 0 });
  }
  let ordered;
  if (!query.trim()) {
    // Empty query shows only what the design lists: CURRENT is separate,
    // RESULTS is same-note tasks plus the In Progress and Next lanes.
    // Ready tasks from other notes (and Blocked elsewhere) need typing.
    const emptyPool = fresh.filter(
      (entry) =>
        entry.candidate.path === dependentPath ||
        entry.candidate.status === "/" ||
        entry.candidate.status === "*",
    );
    ordered = emptyPool
      .slice()
      .sort((left, right) =>
        compareDependencyStageCanonical(
          left.candidate,
          right.candidate,
          dependentPath,
        ),
      )
      .map((entry) => entry.candidate);
  } else {
    const ranked = dependencyStageRank(
      fresh.map((entry) => entry.candidate),
      query,
    );
    const rankIndex = new Map(ranked.map((candidate, index) => [candidate, index]));
    ordered = fresh
      .slice()
      .sort((left, right) => {
        const leftRank = rankIndex.has(left.candidate)
          ? rankIndex.get(left.candidate)
          : Number.POSITIVE_INFINITY;
        const rightRank = rankIndex.has(right.candidate)
          ? rankIndex.get(right.candidate)
          : Number.POSITIVE_INFINITY;
        if (leftRank !== rightRank) {
          return leftRank - rightRank;
        }
        return compareDependencyStageCanonical(
          left.candidate,
          right.candidate,
          dependentPath,
        );
      })
      .map((entry) => entry.candidate)
      .filter((candidate) => rankIndex.has(candidate));
  }
  const results = [];
  const blocked = [];
  for (const candidate of ordered) {
    if (candidate.blocked) {
      blocked.push(candidate);
    } else {
      results.push(candidate);
    }
  }
  const room = Math.max(0, maxRows - markedCurrent.length);
  const picked = [...results, ...blocked].slice(0, room);
  const linkedByCandidate = new Map(
    fresh.map((entry) => [entry.candidate, entry.linkedCount || 0]),
  );
  // Task descriptions by stage row key, so disabled cycle rows tooltip
  // readable `description → description` paths instead of raw
  // `path blockId` keys (`docs/task-dependencies.md` §6.4). Keys without a
  // row (the dependent itself, `id:` values) keep the raw key.
  const labelByKey = new Map();
  for (const row of [...current, ...pool]) {
    if (!row) {
      continue;
    }
    const rowKey =
      row.path && row.blockId
        ? dependencyStageRowKey(row.path, row.blockId)
        : null;
    const label = row.displayText || row.text || null;
    if (rowKey && label && !labelByKey.has(rowKey)) {
      labelByKey.set(rowKey, label);
    }
  }
  const labelDependencyStageCycle = (cycle) =>
    Object.freeze(
      (Array.isArray(cycle) ? cycle : []).map((key) =>
        labelByKey.has(key) ? labelByKey.get(key) : key,
      ),
    );
  // The dependent line itself is never a pool row, so its description would
  // otherwise fall back to the raw key at the end of every cycle path.
  if (
    dependentKey &&
    !labelByKey.has(dependentKey) &&
    (dependent.displayText || dependent.text)
  ) {
    labelByKey.set(dependentKey, dependent.displayText || dependent.text);
  }
  const guard = (candidate) => {
    const key =
      candidate.path && candidate.blockId
        ? dependencyStageRowKey(candidate.path, candidate.blockId)
        : null;
    if (key && dependentKey) {
      if (key === dependentKey) {
        const selfCycle = Object.freeze([dependentKey]);
        return {
          disabled: true,
          reason: "this task",
          cycle: selfCycle,
          cycleLabels: labelDependencyStageCycle(selfCycle),
        };
      }
      const cycle = findDependencyStageCycle(edges, dependentKey, key);
      if (cycle) {
        return {
          disabled: true,
          reason: "would create a cycle",
          cycle: Object.freeze(cycle),
          cycleLabels: labelDependencyStageCycle(cycle),
        };
      }
    }
    if (
      candidate.blockId &&
      !candidate.idField &&
      !tryDependencyId(candidate.path, candidate.blockId)
    ) {
      return {
        disabled: true,
        reason: "path can't be an id",
        cycle: null,
        cycleLabels: null,
      };
    }
    return { disabled: false, reason: null, cycle: null, cycleLabels: null };
  };
  const shape = (candidate, section, first) => {
    const verdict = guard(candidate);
    const depValue =
      candidate.idField ||
      (candidate.blockId
        ? tryDependencyId(candidate.path, candidate.blockId)
        : null) ||
      "";
    // BLOCKED rows name what blocks them (`docs/task-dependencies.md` §6.3):
    // `🔒 waits on N` only when N >= 1 open prerequisites remain (the
    // candidate's own open count when the builder attached one, else the
    // post-batch graph edges, else 0 — never `waits on 0`); with no open
    // prerequisite, a future `scheduled` date reads `🔒 scheduled
    // YYYY-MM-DD`, and otherwise the row reads `🔒 blocked`.
    let waitsOn = null;
    let blockedBadge = null;
    if (section === "blocked") {
      const rowKey =
        candidate.path && candidate.blockId
          ? dependencyStageRowKey(candidate.path, candidate.blockId)
          : null;
      const edgeCount =
        rowKey && edges instanceof Map && edges.get(rowKey)
          ? edges.get(rowKey).length
          : null;
      const open =
        Number.isInteger(candidate.openCount) && candidate.openCount >= 0
          ? candidate.openCount
          : Number.isInteger(edgeCount) && edgeCount > 0
            ? edgeCount
            : 0;
      if (open >= 1) {
        waitsOn = open;
        blockedBadge = `🔒 waits on ${open}`;
      } else {
        const scheduled =
          typeof candidate.scheduledDate === "string" &&
          /^\d{4}-\d{2}-\d{2}$/.test(candidate.scheduledDate)
            ? candidate.scheduledDate
            : null;
        blockedBadge = scheduled ? `🔒 scheduled ${scheduled}` : "🔒 blocked";
      }
    }
    return Object.freeze({
      kind: "local-task",
      stageSection: section,
      firstInSection: first,
      path: candidate.path,
      blockId: candidate.blockId,
      route: candidate.route,
      note: candidate.note,
      noteLabel:
        candidate.path && candidate.path !== dependentPath
          ? dependencyStageBasenameOf(candidate.path)
          : null,
      line: candidate.line,
      rawLine: candidate.rawLine,
      status: candidate.status,
      displayText: candidate.displayText,
      text: candidate.text,
      searchText: [
        candidate.displayText,
        candidate.route,
        candidate.blockId
          ? `${candidate.route}:${candidate.blockId}`
          : "",
        candidate.blockId || "",
        candidate.section || "",
        candidate.note || "",
      ]
        .filter(Boolean)
        .join(" "),
      value: depValue,
      dependencyValue: depValue,
      legacyDependencyValue: candidate.idField || candidate.blockId || "",
      linkBlockId: candidate.blockId || "",
      badgeId: candidate.blockId || "",
      existingBlockId: candidate.blockId,
      existingIdField: candidate.idField,
      alreadyLinked: sourceValueSets
        ? (linkedByCandidate.get(candidate) || 0) === sourceValueSets.length &&
          sourceValueSets.length > 0
        : false,
      linkedSourceCount: linkedByCandidate.get(candidate) || 0,
      sourceCount: sourceValueSets ? sourceValueSets.length : 1,
      linkState: !sourceValueSets
        ? "none"
        : (linkedByCandidate.get(candidate) || 0) === 0
          ? "none"
          : (linkedByCandidate.get(candidate) || 0) >= sourceValueSets.length
            ? "all"
            : "mixed",
      needsBlockIdPrompt: !candidate.blockId,
      needsDependencyValue: !depValue,
      needsPromptForAdd: !candidate.blockId,
      hidden: candidate.hidden,
      section: candidate.section,
      markKey: `${candidate.path}#${candidate.line >= 0 ? candidate.line : (candidate.blockId || candidate.displayText)}`,
      disabled: verdict.disabled,
      disabledReason: verdict.reason,
      cycle: verdict.cycle,
      cycleLabels: verdict.cycleLabels || null,
      waitsOn,
      blockedBadge,
    });
  };
  const out = [...markedCurrent];
  const pickedResults = picked.filter((candidate) => !candidate.blocked);
  const pickedBlocked = picked.filter((candidate) => candidate.blocked);
  pickedResults.forEach((candidate, index) =>
    out.push(shape(candidate, "results", index === 0)),
  );
  pickedBlocked.forEach((candidate, index) =>
    out.push(shape(candidate, "blocked", index === 0)),
  );
  // The ~60-row cap truncates: append the "type to search N more" hint row
  // so keyboard filtering reaches the rest (`docs/task-dependencies.md` §6.3).
  const totalOrdered = [...results, ...blocked].length;
  const hiddenCount = Math.max(0, totalOrdered - picked.length);
  if (hiddenCount > 0) {
    out.push(
      Object.freeze({
        kind: "stage-more",
        stageSection: pickedBlocked.length > 0 ? "blocked" : "results",
        firstInSection: false,
        path: null,
        blockId: null,
        displayText: `type to search ${hiddenCount} more`,
        text: `type to search ${hiddenCount} more`,
        searchText: "",
        hiddenCount,
        disabled: true,
        disabledReason: `type to search ${hiddenCount} more`,
        cycle: null,
        cycleLabels: null,
        waitsOn: null,
      }),
    );
  }
  return Object.freeze(out);
}

// Normalize one Tasks cache task to pool shape, or null when it carries no
// usable location. Field names differ across Tasks versions, so every known
// alias is tried; the vault scan covers whatever falls through.
function normalizeStageCacheTask(entry) {
  const task = entry && typeof entry === "object" ? entry : null;
  if (!task) {
    return null;
  }
  const location =
    task.taskLocation && typeof task.taskLocation === "object"
      ? task.taskLocation
      : {};
  const file = task.file && typeof task.file === "object" ? task.file : {};
  const path = normalizeVaultRelativePath(
    task.path || location.path || file.path || "",
  );
  if (!path) {
    return null;
  }
  const status =
    (task.status && task.status.symbol) ||
    task.statusSymbol ||
    (typeof task.status === "string" ? task.status : null) ||
    " ";
  const lineCandidates = [
    task.lineNumber,
    task.line,
    location.lineNumber,
    location.line,
  ];
  let line = -1;
  for (const candidate of lineCandidates) {
    const numeric = Math.floor(numericOrDefault(candidate, Number.NaN));
    if (Number.isFinite(numeric) && numeric >= 0) {
      line = numeric;
      break;
    }
  }
  const rawLine =
    typeof task.originalMarkdown === "string" ? task.originalMarkdown : null;
  const text =
    (typeof task.description === "string" && task.description) ||
    (typeof task.text === "string" && task.text) ||
    (rawLine ? cleanTaskDisplayText(rawLine) : "(untitled task)");
  const trailingId =
    (typeof task.blockId === "string" && task.blockId) ||
    (rawLine ? getTrailingBlockId(rawLine) : null) ||
    null;
  const idField =
    (typeof task.id === "string" && task.id) ||
    (task.taskId && String(task.taskId)) ||
    null;
  const dependsOn = Array.isArray(task.dependsOn)
    ? task.dependsOn
        .map(normalizeBulletPropertyValue)
        .filter(Boolean)
    : [];
  return Object.freeze({
    path,
    route: dependencyStageRouteOf(path),
    note: dependencyStageBasenameOf(path),
    line,
    rawLine,
    status,
    displayText: text,
    text,
    blockId: trailingId ? normalizeBulletPropertyValue(trailingId) : null,
    existingBlockId: trailingId ? normalizeBulletPropertyValue(trailingId) : null,
    idField: idField ? normalizeBulletPropertyValue(idField) : null,
    existingIdField: idField ? normalizeBulletPropertyValue(idField) : null,
    section:
      (typeof task.section === "string" && task.section) ||
      (typeof task.precedingHeader === "string" && task.precedingHeader) ||
      null,
    open: OPEN_OBSIDIAN_TASK_STATUSES.has(status),
    blocked: status === "?",
    hidden: Boolean(task.hidden),
    dependsOn: Object.freeze(dependsOn),
  });
}

// Merge Tasks cache records under open-buffer notes: buffers win per note
// (unsaved edits count), cache-only notes fill the rest. Exclusions and the
// dependent match the note parser exactly.
function mergeStageCacheCandidates(cacheTasks, notes, options = {}) {
  const dependentPath = normalizeVaultRelativePath(options.dependentPath || "");
  const dependentLines =
    options.dependentLines instanceof Set
      ? options.dependentLines
      : new Set(options.dependentLines || []);
  const buffered = new Set(
    (Array.isArray(notes) ? notes : []).map((note) =>
      normalizeVaultRelativePath(note.path || ""),
    ),
  );
  const out = collectVaultDependencyCandidates(notes, {
    dependentPath,
    dependentLines,
  }).slice();
  for (const record of cacheTasks || []) {
    if (!record || buffered.has(record.path)) {
      continue;
    }
    if (isDependencyStageExcludedPath(record.path)) {
      continue;
    }
    if (!record.open) {
      continue;
    }
    if (
      record.path === dependentPath &&
      dependentLines.has(record.line)
    ) {
      continue;
    }
    out.push(record);
  }
  return Object.freeze(out);
}

// Register cache-only records in the lookup (for CURRENT rows and pill
// counts) and the basename table (for link resolution).
function registerStageCacheRecords(index, cacheTasks) {
  if (!index) {
    return;
  }
  for (const record of cacheTasks || []) {
    if (!record) {
      continue;
    }
    const basename = dependencyStageBasenameOf(record.path);
    if (index.basenames && !index.basenames.has(basename)) {
      index.basenames.set(basename, []);
    }
    if (index.basenames && !index.basenames.get(basename).includes(record.path)) {
      index.basenames.get(basename).push(record.path);
    }
    if (record.blockId) {
      const key = dependencyStageRowKey(record.path, record.blockId);
      if (key && index.byKey && !index.byKey.has(key)) {
        index.byKey.set(key, record);
      }
      if (index.byBlockId) {
        if (!index.byBlockId.has(record.blockId)) {
          index.byBlockId.set(record.blockId, []);
        }
        index.byBlockId.get(record.blockId).push(record);
      }
    }
    if (record.idField && index.byIdField && !index.byIdField.has(record.idField)) {
      index.byIdField.set(record.idField, record);
    }
  }
}

// Cycle-guard edges from cache `[dependsOn::]` fields for notes with no
// open buffer: identity through the block id when present, else the stable
// `id:` key shared with the note parser's edge scheme.
function mergeStageCacheEdges(edges, cacheTasks, index) {
  if (!(edges instanceof Map)) {
    return;
  }
  for (const record of cacheTasks || []) {
    if (!record || !Array.isArray(record.dependsOn) || record.dependsOn.length === 0) {
      continue;
    }
    const from =
      (record.blockId && dependencyStageRowKey(record.path, record.blockId)) ||
      (record.idField ? `id:${record.idField}` : null);
    if (!from) {
      continue;
    }
    for (const id of record.dependsOn) {
      const target = index && index.byIdField ? index.byIdField.get(id) : null;
      const to =
        target && target.blockId
          ? dependencyStageRowKey(target.path, target.blockId)
          : null;
      if (to && to !== from) {
        if (!edges.has(from)) {
          edges.set(from, []);
        }
        if (!edges.get(from).includes(to)) {
          edges.get(from).push(to);
        }
      }
    }
  }
}

// Locate one open task by its cleaned display text: cache-only `+ id` rows
// carry no staged line text, so the target is matched fresh. Exactly one
// block-id-less match links; anything else refuses as stale.
function locateStageDisplayText(content, displayText) {
  const text = String(content || "");
  const lines = text.split(/\r?\n/);
  const contexts = getMarkdownLineContextsForLines(lines);
  const want = String(displayText || "");
  const matches = [];
  for (let line = 0; line < lines.length; line += 1) {
    if (!isObsidianTaskAtLine(text, line, contexts, lines)) {
      continue;
    }
    if (!isOpenObsidianTaskLine(lines[line])) {
      continue;
    }
    if (cleanTaskDisplayText(lines[line]) !== want) {
      continue;
    }
    matches.push(
      Object.freeze({
        line,
        rawLine: String(lines[line] || ""),
        blockId: getTrailingBlockId(lines[line]),
      }),
    );
    if (matches.length > 1) {
      return null;
    }
  }
  // The unique match, with or without a block id (the caller routes `+ id`
  // prompts versus ready adds); ambiguous or absent matches refuse.
  return matches.length === 1 ? matches[0] : null;
}

// True when a non-collapsed selection covers two or more `#task` lines: the
// stage edits one dependent, so such selections are refused with a reason.
function editorSelectionSpansTasks(cm, content) {
  try {
    if (!cm || typeof cm.listSelections !== "function") {
      return false;
    }
    const text = String(content || "");
    const lines = text.split(/\r?\n/);
    const contexts = getMarkdownLineContextsForLines(lines);
    for (const selection of cm.listSelections() || []) {
      const anchor = selection && selection.anchor;
      const head = selection && selection.head;
      if (!anchor || !head) {
        continue;
      }
      if (anchor.line === head.line && anchor.ch === head.ch) {
        continue;
      }
      const from = Math.max(0, Math.min(anchor.line, head.line));
      const to = Math.max(0, Math.max(anchor.line, head.line));
      let tasks = 0;
      for (let line = from; line <= to && tasks < 2; line += 1) {
        if (isObsidianTaskAtLine(text, line, contexts, lines)) {
          tasks += 1;
        }
      }
      if (tasks >= 2) {
        return true;
      }
    }
    return false;
  } catch (_error) {
    return false;
  }
}

// Entry-point resolution (`docs/task-dependencies.md` §6.1): anywhere on a
// Depends-On line resolves to the owning task and skips the property step;
// a `#task` line (or any other line of its block) resolves to the owning
// task through the property step; prose with no owning task is refused.
function resolveDependencyStageEntry(content, line) {
  const text = String(content || "");
  const lines = text.split(/\r?\n/);
  const at = Math.floor(numericOrDefault(line, Number.NaN));
  if (!Number.isFinite(at) || at < 0 || at >= lines.length) {
    return Object.freeze({ ok: false, parentLine: null, reason: "no-task" });
  }
  const owning = findOwningTaskLine(lines, at);
  if (owning === null) {
    return Object.freeze({ ok: false, parentLine: null, reason: "no-task" });
  }
  if (
    findDependencyLineIndex(lines, owning) === at &&
    parseDependencyLine(String(lines[at] || ""), { isDirectChildOfTask: true })
      .verdict === "accept"
  ) {
    return Object.freeze({
      ok: true,
      parentLine: owning,
      skipPropertyStep: true,
      reason: null,
    });
  }
  return Object.freeze({
    ok: true,
    parentLine: owning,
    skipPropertyStep: false,
    reason: null,
  });
}

function taskStatusLabel(status) {
  return `[${status || " "}]`;
}

function taskStatusClass(status) {
  if (status === "/") {
    return "active";
  }

  if (status === "*") {
    return "next";
  }

  return "todo";
}

function validateBlockIdCandidate(id, content, options = {}) {
  const reservedIds =
    options.reservedIds instanceof Set
      ? options.reservedIds
      : new Set(options.reservedIds || []);
  const value = normalizeBulletPropertyValue(id);
  if (!value) {
    return Object.freeze({
      id: value,
      valid: false,
      state: "invalid",
      message: "Enter a block ID",
    });
  }

  if (!BULLET_PROPERTY_BLOCK_ID_RE.test(value)) {
    return Object.freeze({
      id: value,
      valid: false,
      state: "invalid",
      message: "Use only letters, numbers, and hyphens",
    });
  }

  if (blockIdExistsInContent(content, value)) {
    return Object.freeze({
      id: value,
      valid: false,
      state: "duplicate",
      message: "Already exists in this file",
    });
  }

  if (reservedIds.has(value)) {
    return Object.freeze({
      id: value,
      valid: false,
      state: "duplicate",
      message: "Already chosen in this batch",
    });
  }

  return Object.freeze({
    id: value,
    valid: true,
    state: "valid",
    message: "Ready to create",
  });
}

function createBulletPropertyValueItems(propertyItem, baseDate) {
  const property = propertyItem.property;
  const currentValue = propertyItem.currentValue || "";
  if (property.values === "date") {
    return createBulletPropertyDateItems(baseDate, currentValue);
  }

  if (property.values === "local_task_id") {
    return [];
  }

  if (property.values === "priority") {
    return property.levels.map((level) => ({
      kind: "value",
      value: level.value,
      label: level.label,
      detail: `${level.value} · in ${level.minDays}–${level.maxDays} days`,
      current: level.value === currentValue,
      dynamic: false,
      priorityLevel: level,
      searchText: `${level.label} ${level.value} ${level.minDays}–${level.maxDays} days`,
    }));
  }

  return property.values.map((value) => ({
    kind: "value",
    value,
    label: value,
    detail: value === currentValue ? "Current value" : "",
    current: value === currentValue,
    dynamic: false,
    searchText: value,
  }));
}

function taskCardSessionContext(context = {}) {
  const content = String(context.content || "");
  const cursorLine = Math.floor(
    numericOrDefault(
      context.cursorLine ?? (context.cursor && context.cursor.line),
      0,
    ),
  );
  const lines = content.split(/\r?\n/);
  const lineText = String(
    context.lineText ?? lines[cursorLine] ?? "",
  );
  const linkSession = context.linkSession || null;
  const taskSession = context.taskSession || null;
  if (
    linkSession &&
    linkSession.kind === "task-link" &&
    Array.isArray(linkSession.resolved)
  ) {
    const resolvedTargets = deduplicateTaskCardTargets(linkSession.resolved).map(
      (entry) => entry.target,
    );
    return Object.freeze({
      type: "linked",
      content,
      lineText,
      cursorLine,
      taskSession,
      linkSession,
      targets: resolvedTargets,
      sourceTargets: linkSession.targets || [],
      targetCount: resolvedTargets.length,
      requestedCount: linkSession.requestedCount || linkSession.resolved.length,
      clamped: linkSession.clamped === true,
      valid: linkSession.valid !== false && resolvedTargets.length > 0,
      error:
        linkSession.valid === false
          ? linkSession.error || "Linked task context is unavailable"
          : resolvedTargets.length > 0
            ? null
            : "No linked tasks are available",
    });
  }
  if (
    taskSession &&
    taskSession.explicit &&
    Array.isArray(taskSession.targets) &&
    taskSession.targets.length > 0
  ) {
    const validation = validateCountedTaskSession(content, taskSession);
    return Object.freeze({
      type: "counted",
      content,
      lineText,
      cursorLine,
      taskSession,
      linkSession: null,
      targets: taskSession.targets,
      sourceTargets: taskSession.targets,
      targetCount: taskSession.targets.length,
      requestedCount: taskSession.requestedCount || taskSession.targets.length,
      clamped: taskSession.clamped === true,
      valid: validation.valid,
      error: validation.valid ? null : validation.error,
    });
  }
  const target = Object.freeze({
    line: cursorLine,
    rawLine: lineText,
    path: context.filePath || "",
  });
  return Object.freeze({
    type: "single",
    content: content || lineText,
    lineText,
    cursorLine,
    taskSession: null,
    linkSession: null,
    targets: lineText ? [target] : [],
    sourceTargets: lineText ? [target] : [],
    targetCount: lineText ? 1 : 0,
    requestedCount: lineText ? 1 : 0,
    clamped: false,
    valid: Boolean(lineText),
    error: lineText ? null : "No task or bullet is selected",
  });
}

function taskCardTargetIdentity(target, index = 0) {
  const item = target && typeof target === "object" ? target : {};
  const path = normalizeVaultRelativePath(
    item.path || item.filePath || (item.file && item.file.path) || "",
  );
  const rawLine = String(item.rawLine || "");
  const blockId = normalizeBulletPropertyValue(
    item.blockId || item.id || getTrailingBlockId(rawLine),
  );
  if (blockId) {
    return `${path}#^${blockId}`;
  }
  if (Number.isInteger(item.line)) {
    return `${path}:line:${item.line}`;
  }
  return `${path}:target:${index}:${rawLine}`;
}

function deduplicateTaskCardTargets(targets) {
  const items = Array.isArray(targets) ? targets : [];
  const seen = new Set();
  const unique = [];
  for (let index = 0; index < items.length; index += 1) {
    const target = items[index];
    const id = taskCardTargetIdentity(target, index);
    if (seen.has(id)) {
      continue;
    }
    seen.add(id);
    unique.push(Object.freeze({ id, target }));
  }
  return Object.freeze(unique);
}

// ---- src/310-task-card-previews.js ----
function buildTaskCardPriorityPreviews(options = {}) {
  const config = options.config || null;
  const property =
    options.property ||
    (config && Array.isArray(config.properties)
      ? config.properties.find((entry) => entry && entry.values === "priority")
      : null) ||
    null;
  const levels =
    property && Array.isArray(property.levels) ? property.levels : [];
  const baseDate =
    options.baseDate instanceof Date
      ? getLocalDateStart(options.baseDate)
      : getLocalDateStart(new Date());
  const random = typeof options.random === "function" ? options.random : Math.random;
  const uniqueTargets = deduplicateTaskCardTargets(options.targets);
  const propertyName = normalizeBulletPropertyName(property && property.name);
  const unavailable = !propertyName
    ? "Priority is not configured"
    : normalizeBulletPropertyValue(options.unavailableReason) ||
      (uniqueTargets.length === 0 ? "No task targets are available" : "");
  const targetPreviews = uniqueTargets.map(({ id, target }) => {
    const rawLine = String((target && target.rawLine) || "");
    const field = propertyName ? findBulletPropertyField(rawLine, propertyName) : null;
    const currentValue = normalizeBulletPropertyValue(field && field.value);
    return {
      id,
      path: String((target && target.path) || ""),
      line: Number.isInteger(target && target.line) ? target.line : null,
      currentValue,
      currentLabel: property
        ? getBulletPropertyCurrentLabel(property, currentValue)
        : currentValue,
      previews: [],
    };
  });
  const levelPreviews = levels.map((level, index) => {
    const label = normalizeBulletPropertyValue(level && level.label);
    const value = normalizeBulletPropertyValue(level && level.value);
    const key = index < 9 ? String(index + 1) : null;
    if (unavailable || !label || !value) {
      const reason = unavailable || "Priority level is not configured";
      return Object.freeze({
        id: `${propertyName || "priority"}:${index}`,
        index,
        key,
        label: label || `Level ${index + 1}`,
        value,
        available: false,
        unavailableReason: reason,
        targetCount: uniqueTargets.length,
        mixed: false,
        currentValues: Object.freeze([]),
        targetPreviews: Object.freeze([]),
        date: "",
        dateStart: "",
        dateEnd: "",
      });
    }
    const bounds = getPriorityRollBounds(level);
    if (!bounds) {
      return Object.freeze({
        id: `${propertyName}:${index}`,
        index,
        key,
        label,
        value,
        available: false,
        unavailableReason: "Priority level has an invalid date window",
        targetCount: uniqueTargets.length,
        mixed: false,
        currentValues: Object.freeze([]),
        targetPreviews: Object.freeze([]),
        date: "",
        dateStart: "",
        dateEnd: "",
      });
    }
    const entries = [];
    for (const targetPreview of targetPreviews) {
      const currentLabel = targetPreview.currentLabel || IMPLICIT_PRIORITY_LEVEL_LABEL;
      const roll = rollPriorityScheduledDateWithOffset(level, baseDate, random);
      const date = formatBulletPropertyDate(roll.date);
      const reason = formatPriorityRollScheduleReason({
        source: "priority",
        fromLevelLabel: currentLabel,
        level,
        rolledDays: roll.offset,
      });
      const entry = Object.freeze({
        targetId: targetPreview.id,
        path: targetPreview.path,
        line: targetPreview.line,
        currentValue: targetPreview.currentValue,
        currentLabel,
        available: Boolean(date && reason),
        unavailableReason: date && reason ? null : "Could not preview this priority level",
        date,
        offset: roll.offset,
        reason,
      });
      entries.push(entry);
      targetPreview.previews.push(entry);
    }
    const dates = entries.map((entry) => entry.date).filter(Boolean).sort();
    const currentValues = Array.from(
      new Set(entries.map((entry) => entry.currentValue)),
    );
    const available = entries.length > 0 && entries.every((entry) => entry.available);
    return Object.freeze({
      id: `${propertyName}:${index}`,
      index,
      key,
      label,
      value,
      available,
      unavailableReason: available
        ? null
        : entries.find((entry) => !entry.available)?.unavailableReason ||
          "No task targets are available",
      targetCount: entries.length,
      mixed: dates.length > 1 || currentValues.length > 1,
      currentValues: Object.freeze(currentValues),
      targetPreviews: Object.freeze(entries),
      date: dates.length === 1 ? dates[0] : "",
      dateStart: dates.length > 0 ? dates[0] : "",
      dateEnd: dates.length > 0 ? dates[dates.length - 1] : "",
    });
  });
  const frozenTargets = Object.freeze(
    targetPreviews.map((target) =>
      Object.freeze({
        ...target,
        previews: Object.freeze(target.previews),
      }),
    ),
  );
  return Object.freeze({
    propertyName,
    property,
    available: !unavailable && levelPreviews.some((level) => level.available),
    unavailableReason: unavailable || null,
    targetCount: uniqueTargets.length,
    levels: Object.freeze(levelPreviews),
    targets: frozenTargets,
  });
}

function taskCardPropertyItems(context, session, config) {
  if (session.type === "linked") {
    const aggregate = createLinkPickerPropertyItems(config, session.targets);
    return aggregate.valid ? aggregate.items : [];
  }
  if (session.type === "counted") {
    const aggregate = createCountedBulletPropertyItems(
      config,
      session.content,
      session.taskSession,
    );
    return aggregate.valid ? aggregate.items : [];
  }
  return createBulletPropertyItems(
    config,
    session.lineText,
    context.propertyContext || {},
  );
}

function taskCardPriorityRecommendation(context, session, priorityProperty) {
  if (Object.prototype.hasOwnProperty.call(context, "frozenRecommendation")) {
    return context.frozenRecommendation || null;
  }
  if (!priorityProperty || !session.valid) {
    return null;
  }
  const baseDate =
    context.baseDate instanceof Date ? getLocalDateStart(context.baseDate) : new Date();
  const random = typeof context.random === "function" ? context.random : Math.random;
  if (session.type === "linked") {
    const summary = planLinkRollBatchSummary(
      session.targets,
      priorityProperty,
      { baseDate, random },
    );
    const actionable =
      (summary.counts.roll || 0) +
      (summary.counts.decay || 0) +
      (summary.counts.cancel || 0);
    if (actionable === 0 && !summary.unavailableReason) {
      return null;
    }
    return Object.freeze({
      kind: "batch",
      source: summary,
      preview: buildLinkRollPreviewModel(summary, baseDate),
      available: actionable > 0 && !summary.unavailableReason,
      unavailableReason:
        summary.unavailableReason ||
        (actionable > 0 ? null : "No priority recommendation is available"),
      effects: summary.counts,
      targetCount: summary.total,
      actionableCount: summary.actionableCount,
      skippedCount: summary.skippedCount,
    });
  }
  if (session.type === "counted") {
    const summary = planPriorityRollRecommendationsForTargets(
      session.content,
      session.targets,
      priorityProperty,
      { baseDate, random },
    );
    const actionable =
      (summary.counts.roll || 0) +
      (summary.counts.decay || 0) +
      (summary.counts.cancel || 0);
    if (actionable === 0 && !summary.unavailableReason) {
      return null;
    }
    return Object.freeze({
      kind: "batch",
      source: summary,
      preview: buildBatchPriorityRollPreviewModel(summary),
      available: actionable > 0 && !summary.unavailableReason,
      unavailableReason:
        summary.unavailableReason ||
        (actionable > 0 ? null : "No priority recommendation is available"),
      effects: summary.counts,
      targetCount: summary.total,
      actionableCount: summary.actionableCount,
      skippedCount: summary.skippedCount,
    });
  }
  const line = session.lineText;
  const status = getObsidianTaskCheckboxStatus(line);
  if (
    !isObsidianTaskLine(line) ||
    !OPEN_OBSIDIAN_TASK_STATUSES.has(status)
  ) {
    return null;
  }
  const liveContext = getProjectNotePropertyContext(
    session.content,
    session.cursorLine,
  );
  const scheduledName = normalizeBulletPropertyName(priorityProperty.schedules);
  const scheduledTarget = resolveBulletPropertyTarget(scheduledName, liveContext);
  const scheduledField = findBulletPropertyField(line, scheduledName);
  const currentScheduled =
    scheduledTarget.kind === "project-frontmatter"
      ? liveContext.frontmatter && liveContext.frontmatter.scheduledDefined
        ? liveContext.frontmatter.scheduledValue
        : ""
      : scheduledField
        ? scheduledField.value
        : "";
  const recommendation = planPriorityRollRecommendation({
    property: priorityProperty,
    content: session.content,
    taskLine: session.cursorLine,
    currentScheduled,
    baseDate,
    random,
  });
  if (!recommendation) {
    return null;
  }
  return Object.freeze({
    kind: "single",
    source: Object.freeze({
      ...recommendation,
      priorityName: priorityProperty.name,
      schedulesName: normalizeBulletPropertyName(priorityProperty.schedules),
      taskLine: session.cursorLine,
    }),
    preview: buildPriorityRollPreviewModel(recommendation, baseDate),
    available:
      recommendation.kind !== "unavailable" &&
      Boolean(recommendation.date || recommendation.kind === "cancel"),
    unavailableReason:
      recommendation.kind === "unavailable"
        ? recommendation.reason || "Recommendation is unavailable"
        : null,
    effects: Object.freeze({
      roll: recommendation.kind === "roll" ? 1 : 0,
      decay: recommendation.kind === "decay" ? 1 : 0,
      cancel: recommendation.kind === "cancel" ? 1 : 0,
      unavailable: recommendation.kind === "unavailable" ? 1 : 0,
    }),
    targetCount: 1,
    actionableCount: recommendation.kind === "unavailable" ? 0 : 1,
    skippedCount: 0,
  });
}

function taskCardAvailabilityReason(session, rowName) {
  if (!session.valid) {
    return session.error || "Task context is unavailable";
  }
  if (session.targetCount === 0) {
    return "No task targets are available";
  }
  if (session.type === "single" && !isObsidianTaskLine(session.lineText)) {
    return rowName === "depends-on"
      ? "Depends on requires a #task checkbox"
      : rowName === "cancel"
        ? "Only #task checkboxes can be cancelled"
        : "Task action requires a #task checkbox";
  }
  return "No eligible task targets";
}

function taskCardPropertyProjection(item) {
  const property = item && item.property;
  const propertyName = normalizeBulletPropertyName(property && property.name);
  const currentValues = Array.isArray(item && item.currentValues)
    ? item.currentValues.map((value) => normalizeBulletPropertyValue(value))
    : item && item.defined
      ? [normalizeBulletPropertyValue(item.currentValue)]
      : [];
  const valueState = item && item.valueState
    ? item.valueState
    : item && item.defined
      ? "common"
      : "absent";
  return Object.freeze({
    id: `property:${propertyName}`,
    propertyName,
    values: property && property.values,
    label: propertyName,
    enabled: Boolean(propertyName),
    unavailableReason: propertyName ? null : "Property is not configured",
    currentValue: normalizeBulletPropertyValue(item && item.currentValue),
    currentLabel: normalizeBulletPropertyValue(item && item.currentLabel),
    currentValues: Object.freeze(currentValues),
    currentLabels: Object.freeze(
      (Array.isArray(item && item.currentLabels) ? item.currentLabels : []).map(
        (value) => normalizeBulletPropertyValue(value),
      ),
    ),
    valueState,
    mixed: valueState === "mixed" || item?.mixed === true,
    defined: item?.defined === true,
    definedCount: Math.max(0, Math.floor(numericOrDefault(item?.definedCount, 0))),
    targetCount: Math.max(0, Math.floor(numericOrDefault(item?.targetCount, 0))),
    deletable: property && property.values !== "local_task_id",
  });
}

function planTaskCard(context = {}) {
  const config = context.config || { properties: [] };
  const properties = Array.isArray(config.properties) ? config.properties : [];
  const session = taskCardSessionContext(context);
  const propertyItems = taskCardPropertyItems(context, session, config);
  const priorityProperty = properties.find(
    (property) => property && property.values === "priority",
  ) || null;
  const dateProperties = properties.filter(
    (property) => property && property.values === "date",
  );
  const scheduleProperty = priorityProperty
    ? dateProperties.find((property) => property.name === priorityProperty.schedules)
    : dateProperties.find((property) => property.name === "scheduled") ||
      dateProperties[0] ||
      null;
  const propertyProjections = propertyItems.map(taskCardPropertyProjection);
  const propertyByName = new Map(
    propertyProjections.map((item) => [item.propertyName, item]),
  );
  const scheduleProjection = scheduleProperty
    ? propertyByName.get(normalizeBulletPropertyName(scheduleProperty.name)) ||
      taskCardPropertyProjection({ property: scheduleProperty })
    : null;
  const priorityProjection = priorityProperty
    ? propertyByName.get(normalizeBulletPropertyName(priorityProperty.name)) ||
      taskCardPropertyProjection({ property: priorityProperty })
    : null;
  const dependencyProperty = properties.find(
    (property) =>
      property &&
      property.values === "local_task_id" &&
      normalizeBulletPropertyName(property.name) === "dependsOn",
  ) || null;
  const dependencyItem = dependencyProperty
    ? propertyByName.get("dependsOn") || null
    : null;
  const dependencyProjection = dependencyProperty
    ? dependencyItem || taskCardPropertyProjection({ property: dependencyProperty })
    : null;
  const targets = session.targets;
  const targetStatuses = targets.map((target) =>
    getObsidianTaskCheckboxStatus((target && target.rawLine) || ""),
  );
  const distinctStatuses = Array.from(new Set(targetStatuses));
  const previewTargets = deduplicateTaskCardTargets(targets).map((entry) => entry.target);
  const recommendation = taskCardPriorityRecommendation(context, session, priorityProperty);
  const priorityStrip = buildTaskCardPriorityPreviews({
    property: priorityProperty,
    targets: session.valid ? previewTargets : [],
    unavailableReason: session.error,
    baseDate: context.baseDate,
    random: context.random,
  });
  const laneDescription =
    session.type === "linked"
      ? describeLaneRow("", { linkResolved: session.targets })
      : session.type === "counted"
        ? describeLaneRow(session.content, { taskSession: session.taskSession })
        : describeLaneRow(session.content, { cursorLine: session.cursorLine });
  const freshnessApi = context.freshnessApi || null;
  const refreshDescription =
    session.type === "linked"
      ? describeRefreshRow("", {
          linkResolved: session.targets,
          freshnessApi,
        })
      : session.type === "counted"
        ? describeRefreshRow(session.content, {
            taskSession: session.taskSession,
            freshnessApi,
          })
        : describeRefreshRow(session.content, {
            cursorLine: session.cursorLine,
            freshnessApi,
          });
  const cancelDescription =
    session.type === "linked"
      ? describeCancelTaskRow("", { linkResolved: session.targets })
      : session.type === "counted"
        ? describeCancelTaskRow(session.content, { taskSession: session.taskSession })
        : describeCancelTaskRow(session.content, { cursorLine: session.cursorLine });
  const row = (value) => Object.freeze(value);
  const scheduleAvailable = Boolean(
    scheduleProperty && session.targetCount > 0 && session.valid,
  );
  const laneAvailable = Boolean(laneDescription && session.valid);
  const dependencyAvailable = Boolean(
    dependencyProperty && dependencyItem && session.valid,
  );
  const refreshAvailable = Boolean(refreshDescription && session.valid);
  const cancelAvailable = Boolean(
    cancelDescription && !cancelDescription.recurring && session.valid,
  );
  const rows = Object.freeze([
    row({
      id: "schedule",
      kind: "property",
      action: "schedule",
      propertyName: scheduleProperty ? scheduleProperty.name : "",
      label: "Schedule",
      enabled: scheduleAvailable,
      unavailableReason: scheduleAvailable
        ? null
        : scheduleProperty
          ? taskCardAvailabilityReason(session, "schedule")
          : "Schedule is not configured",
      currentValue: scheduleProjection && scheduleProjection.currentValue,
      currentLabel: scheduleProjection && scheduleProjection.currentLabel,
      currentValues: scheduleProjection ? scheduleProjection.currentValues : Object.freeze([]),
      mixed: Boolean(scheduleProjection && scheduleProjection.mixed),
      valueState: scheduleProjection ? scheduleProjection.valueState : "absent",
      deletable: Boolean(scheduleProperty),
      targetCount: session.targetCount,
    }),
    row({
      id: "depends-on",
      kind: "action",
      action: "dependencies",
      label: "Depends on",
      enabled: dependencyAvailable,
      unavailableReason: dependencyAvailable
        ? null
        : dependencyProperty
          ? taskCardAvailabilityReason(session, "depends-on")
          : "Depends on is not configured",
      propertyName: dependencyProperty ? dependencyProperty.name : "",
      detail: dependencyProjection && dependencyProjection.currentLabel,
      mixed: Boolean(dependencyProjection && dependencyProjection.mixed),
      targetCount: session.targetCount,
      deletable: false,
    }),
    row({
      id: "review-every",
      kind: "action",
      action: "refresh",
      label: "Review every",
      enabled: refreshAvailable,
      unavailableReason: refreshAvailable
        ? null
        : freshnessApi
          ? taskCardAvailabilityReason(session, "refresh")
          : "Freshness API is unavailable",
      detail: refreshDescription && refreshDescription.detail,
      mixed: Boolean(refreshDescription && refreshDescription.mixed),
      targetCount: session.targetCount,
      deletable: false,
    }),
    row({
      id: "cancel",
      kind: "action",
      action: "cancel",
      label: cancelDescription
        ? getCancelTaskRowTitle(cancelDescription)
        : "Cancel task",
      enabled: cancelAvailable,
      unavailableReason: cancelAvailable
        ? null
        : cancelDescription && cancelDescription.recurring
          ? "Recurring tasks are cancelled with Obsidian Tasks"
          : taskCardAvailabilityReason(session, "cancel"),
      detail: cancelDescription && cancelDescription.detail,
      targetCount: cancelDescription ? cancelDescription.openCount : session.targetCount,
      deletable: false,
    }),
    row({
      id: "lane",
      kind: "action",
      action: "toggle-lane",
      label: laneDescription
        ? laneDescription.mode === "release"
          ? "Release to Ready"
          : "Commit to Next"
        : "Next / Ready",
      enabled: laneAvailable,
      unavailableReason: laneAvailable
        ? null
        : session.valid && session.targets.length > 0 && session.targets.every(
            (target) => getObsidianTaskCheckboxStatus(target.rawLine || "") === "?",
          )
          ? "Blocked is derived"
          : taskCardAvailabilityReason(session, "lane"),
      detail: laneDescription && laneDescription.detail,
      needsReason: Boolean(laneDescription && laneDescription.needsReason),
      targetCount: laneDescription ? laneDescription.count : session.targetCount,
      deletable: false,
    }),
  ]);
  const selectedRowId = rows.some((item) => item.id === context.selectedRowId)
    ? context.selectedRowId
    : "schedule";
  const mixedMetadata = {};
  for (const projection of propertyProjections) {
    mixedMetadata[projection.propertyName] = Object.freeze({
      valueState: projection.valueState,
      mixed: projection.mixed,
      currentValues: projection.currentValues,
      targetCount: projection.targetCount || session.targetCount,
      definedCount: projection.definedCount,
    });
  }
  const frozenMixedMetadata = Object.freeze(mixedMetadata);
  const baseDate =
    context.baseDate instanceof Date
      ? getLocalDateStart(context.baseDate)
      : getLocalDateStart(new Date());
  const header = buildTaskCardHeader({
    session,
    lineText: session.lineText,
    filePath: context.filePath || "",
    schedule: scheduleProjection,
    priorityStrip,
    mixedMetadata: frozenMixedMetadata,
    refreshDescription,
    rows,
    baseDate,
  });
  const timeline = buildTaskCardTimeline({
    recommendation,
    schedule: scheduleProjection,
    baseDate,
  });
  return Object.freeze({
    kind: "task-card",
    session: Object.freeze({
      type: session.type,
      targetCount: session.targetCount,
      linkCount: session.type === "linked" ? session.sourceTargets.length : 0,
      requestedCount: session.requestedCount,
      clamped: session.clamped,
      valid: session.valid,
      error: session.error,
      currentStatus:
        distinctStatuses.length === 1
          ? distinctStatuses[0]
          : getObsidianTaskCheckboxStatus(session.lineText),
      statuses: Object.freeze(distinctStatuses),
      mixedStatus: distinctStatuses.length > 1,
    }),
    title: truncateBulletPropertySubtitle(session.lineText),
    header,
    timeline,
    baseDate: formatBulletPropertyDate(baseDate),
    rows,
    selectedRowId,
    inputActive: context.inputActive === true,
    schedule: scheduleProjection,
    priorityStrip,
    recommendation,
    properties: Object.freeze(propertyProjections),
    moreProperties: Object.freeze(
      propertyProjections.filter(
        (item) =>
          item.propertyName !== (scheduleProperty && scheduleProperty.name) &&
          item.propertyName !== (priorityProperty && priorityProperty.name) &&
          item.propertyName !== (dependencyProperty && dependencyProperty.name),
      ),
    ),
    mixedMetadata: frozenMixedMetadata,
    availability: Object.freeze({
      schedule: scheduleAvailable,
      priority: priorityStrip.available,
      recommendation: Boolean(recommendation && recommendation.available),
      dependencies: dependencyAvailable,
      refresh: refreshAvailable,
      cancel: cancelAvailable,
      lane: laneAvailable,
    }),
  });
}

function taskCardIntentForRow(row) {
  if (!row) {
    return Object.freeze({
      type: "unavailable",
      action: "open-row",
      reason: "No card action is selected",
    });
  }
  if (!row.enabled) {
    return Object.freeze({
      type: "unavailable",
      action: row.action || row.id,
      rowId: row.id,
      reason: row.unavailableReason || "This action is unavailable",
    });
  }
  return Object.freeze({
    type: "open-action",
    action: row.action,
    rowId: row.id,
    propertyName: row.propertyName || "",
    targetCount: row.targetCount || 0,
  });
}

function resolveTaskCardKey(model, event) {
  if (!model || model.kind !== "task-card" || !event) {
    return null;
  }
  if (
    event.isComposing === true ||
    event.keyCode === 229 ||
    model.inputActive === true ||
    event.inputActive === true ||
    event.inTextInput === true
  ) {
    return null;
  }
  const target = event.target;
  if (
    target &&
    (target.isContentEditable === true ||
      /^(INPUT|TEXTAREA|SELECT)$/.test(String(target.tagName || "").toUpperCase()))
  ) {
    return null;
  }
  const key = String(event.key || "");
  const lower = key.toLowerCase();
  const ctrl = event.ctrlKey === true;
  const meta = event.metaKey === true;
  const shift = event.shiftKey === true;
  const alt = event.altKey === true;
  const modified = ctrl || meta || shift || alt;
  const repeatedAction = event.repeat === true;
  const rows = Array.isArray(model.rows) ? model.rows : [];
  const selected = rows.find((row) => row.id === model.selectedRowId) || null;
  const rowById = (id) => rows.find((row) => row.id === id) || null;
  const unavailable = (action, reason) =>
    Object.freeze({ type: "unavailable", action, reason });
  const movement = (direction) =>
    Object.freeze({ type: "move-selection", direction, fromRowId: model.selectedRowId });
  const actionKey =
    (!modified && /^[0-9bfx]$/i.test(key)) ||
    (ctrl && !meta && !shift && !alt && ["Enter", "r", "d"].includes(key)) ||
    (meta && !ctrl && !shift && !alt && key === "Enter") ||
    (alt && !ctrl && !meta && !shift && lower === "n");
  if (repeatedAction && actionKey) {
    return Object.freeze({ type: "ignored", reason: "repeated-action-key" });
  }
  if (
    (!modified && key === "ArrowUp") ||
    (ctrl && !meta && !shift && !alt && lower === "p")
  ) {
    return movement("previous");
  }
  if (
    (!modified && key === "ArrowDown") ||
    (ctrl && !meta && !shift && !alt && lower === "n")
  ) {
    return movement("next");
  }
  if ((ctrl || meta) && !shift && !alt && key === "Enter") {
    const recommendation = model.recommendation;
    if (!recommendation || !recommendation.available) {
      return unavailable(
        "apply-recommendation",
        recommendation?.unavailableReason || "No recommendation is available",
      );
    }
    return Object.freeze({
      type: "apply-recommendation",
      recommendation: recommendation.source,
      effects: recommendation.effects,
      targetCount: recommendation.targetCount,
    });
  }
  if (ctrl && !meta && !shift && !alt && lower === "r") {
    if (!model.priorityStrip || !model.priorityStrip.available) {
      return unavailable(
        "refresh-priority-previews",
        model.priorityStrip?.unavailableReason || "Priority is not configured",
      );
    }
    return Object.freeze({
      type: "refresh-previews",
      includeRecommendation: true,
      includePriorityStrip: true,
    });
  }
  if (alt && !ctrl && !meta && !shift && lower === "n") {
    return taskCardIntentForRow(rowById("lane"));
  }
  if (ctrl && !meta && !shift && !alt && lower === "d") {
    if (!selected || selected.kind !== "property" || !selected.deletable) {
      return unavailable("delete-property", "Only a selected property can be deleted");
    }
    if (!selected.enabled) {
      return unavailable(
        "delete-property",
        selected.unavailableReason || "The selected property is unavailable",
      );
    }
    return Object.freeze({
      type: "delete-property",
      rowId: selected.id,
      propertyName: selected.propertyName,
      targetCount: selected.targetCount || model.session.targetCount,
    });
  }
  if (!modified && /^[1-9]$/.test(key)) {
    const level = model.priorityStrip?.levels?.find((item) => item.key === key);
    if (!level) {
      return unavailable("set-priority", "Priority level is not configured");
    }
    if (!level.available) {
      return unavailable("set-priority", level.unavailableReason || "Priority level is unavailable");
    }
    return Object.freeze({
      type: "set-priority",
      propertyName: model.priorityStrip.propertyName,
      levelIndex: level.index,
      levelLabel: level.label,
      value: level.value,
      key,
      previews: level.targetPreviews,
      targetCount: level.targetCount,
      mixed: level.mixed,
    });
  }
  if (!modified && key === "0") {
    if (!model.priorityStrip?.propertyName) {
      return unavailable("clear-priority", "Priority is not configured");
    }
    return Object.freeze({
      type: "clear-priority",
      propertyName: model.priorityStrip.propertyName,
      value: "",
      keepScheduled: true,
      targetCount: model.priorityStrip.targetCount,
    });
  }
  if (!modified && lower === "b") {
    return taskCardIntentForRow(rowById("depends-on"));
  }
  if (!modified && lower === "f") {
    return taskCardIntentForRow(rowById("review-every"));
  }
  if (!modified && lower === "x") {
    return taskCardIntentForRow(rowById("cancel"));
  }
  if (!modified && key === "Enter") {
    return taskCardIntentForRow(selected);
  }
  if (isTaskCardCloseKeydown(event)) {
    return Object.freeze({ type: "close-card" });
  }
  if (!modified && key === "Backspace") {
    return Object.freeze({ type: "back" });
  }
  return null;
}

const TASK_CARD_ROW_ORDER = Object.freeze([
  "schedule",
  "depends-on",
  "review-every",
  "lane",
  "cancel",
]);

const TASK_CARD_ROW_SHORTCUTS = Object.freeze({
  schedule: "Enter",
  "depends-on": "b",
  "review-every": "f",
  lane: "Alt+N",
  cancel: "x",
});

function getTaskCardLaneChipLabel(status) {
  switch (String(status ?? "")) {
    case " ":
      return "READY";
    case "*":
      return "NEXT";
    case "/":
      return "PENDING";
    case "?":
      return "BLOCKED";
    default:
      return null;
  }
}

function parseTaskCardIsoDate(value) {
  const match = /^(\d{4})-(\d{2})-(\d{2})/.exec(
    normalizeBulletPropertyValue(value),
  );
  if (!match) {
    return null;
  }
  const date = new Date(
    Number(match[1]),
    Number(match[2]) - 1,
    Number(match[3]),
  );
  return Number.isFinite(date.getTime()) ? date : null;
}

function formatTaskCardCompactRelative(offset) {
  const days = Number(offset);
  if (!Number.isFinite(days)) {
    return "";
  }
  if (days === 0) {
    return "today";
  }
  if (days > 0) {
    return `in ${days}d`;
  }
  return `${Math.abs(days)}d overdue`;
}

function buildTaskCardDateDisplay(iso, baseDate) {
  const date = parseTaskCardIsoDate(iso);
  if (!date) {
    return null;
  }
  const start =
    baseDate instanceof Date
      ? getLocalDateStart(baseDate)
      : getLocalDateStart(new Date());
  const offset = getLocalDayOffset(start, date);
  return Object.freeze({
    iso: formatBulletPropertyDate(date),
    weekday: getBulletPropertyDateWeekday(date),
    offset,
    relative: formatTaskCardCompactRelative(offset),
    today: offset === 0,
    overdue: offset < 0,
  });
}

// ---- src/320-task-card-header.js ----
function buildTaskCardHeader(details = {}) {
  const session = details.session || {};
  const lineText = String(details.lineText || session.lineText || "");
  const fullTitle = lineText ? cleanTaskDisplayText(lineText) : "";
  const filePath = String(details.filePath || "");
  const note = getVaultPathBasenameWithoutExtension(filePath);
  const statusFromTargets = Array.isArray(session.targets)
    ? session.targets.map((target) =>
        getObsidianTaskCheckboxStatus((target && target.rawLine) || ""),
      )
    : [];
  const statuses = Array.isArray(session.statuses) && session.statuses.length > 0
    ? session.statuses
    : statusFromTargets.length > 0
      ? statusFromTargets
      : [session.currentStatus];
  const laneLabels = Array.from(
    new Set(statuses.map(getTaskCardLaneChipLabel).filter(Boolean)),
  );
  const lane =
    laneLabels.length === 0
      ? null
      : laneLabels.length === 1
        ? laneLabels[0]
        : "mixed";
  const priorityStrip = details.priorityStrip || {};
  const mixedPriority = details.mixedMetadata && details.mixedMetadata.priority;
  let priority = null;
  if (!priorityStrip.propertyName) {
    priority = Object.freeze({ available: false, label: "unavailable" });
  } else if (mixedPriority && mixedPriority.mixed) {
    priority = Object.freeze({ available: true, label: "mixed", mixed: true });
  } else {
    const currentValue = normalizeBulletPropertyValue(
      mixedPriority && Array.isArray(mixedPriority.currentValues)
        ? mixedPriority.currentValues[0]
        : priorityStrip.targets &&
            priorityStrip.targets[0] &&
            priorityStrip.targets[0].currentValue,
    );
    const currentLabel = currentValue
      ? getBulletPropertyCurrentLabel(priorityStrip.property, currentValue) ||
        currentValue
      : IMPLICIT_PRIORITY_LEVEL_LABEL;
    priority = Object.freeze({
      available: true,
      label: currentLabel,
      value: currentValue,
      mixed: false,
    });
  }
  const scheduleProjection = details.schedule || null;
  let schedule = Object.freeze({ available: false, label: "unavailable" });
  if (scheduleProjection && scheduleProjection.enabled !== false) {
    if (scheduleProjection.mixed) {
      schedule = Object.freeze({
        available: true,
        mixed: true,
        label: "mixed",
      });
    } else {
      const display = buildTaskCardDateDisplay(
        scheduleProjection.currentValue,
        details.baseDate,
      );
      schedule = display
        ? Object.freeze({
            available: true,
            mixed: false,
            label: `${display.weekday} ${display.iso} · ${display.relative}`,
            ...display,
          })
        : Object.freeze({ available: false, label: "unavailable" });
    }
  }
  const dependsRow =
    (Array.isArray(details.rows) ? details.rows : []).find(
      (row) => row && row.id === "depends-on",
    ) || null;
  const dependencies = dependsRow
    ? Object.freeze({
        available: dependsRow.enabled,
        label: dependsRow.enabled
          ? dependsRow.detail || "none"
          : dependsRow.unavailableReason || "unavailable",
        mixed: Boolean(dependsRow.mixed),
      })
    : Object.freeze({ available: false, label: "unavailable" });
  const refresh = details.refreshDescription
    ? Object.freeze({
        available: true,
        days: details.refreshDescription.days,
        source: details.refreshDescription.source,
        mixed: Boolean(details.refreshDescription.mixed),
        label: details.refreshDescription.mixed
          ? "mixed"
          : details.refreshDescription.detail ||
            `${details.refreshDescription.days}d`,
      })
    : Object.freeze({
        available: false,
        label: "unavailable",
      });
  const targetNotes = Array.from(
    new Set(
      (priorityStrip.targets || [])
        .map((target) =>
          getVaultPathBasenameWithoutExtension((target && target.path) || ""),
        )
        .filter(Boolean),
    ),
  );
  const chips = [];
  if (session.type === "linked") {
    chips.push("via Task Link");
  }
  if (isProjectLifecycleTaskLine(lineText)) {
    chips.push("project");
  }
  if (note) {
    chips.push(note);
  }
  if (lane) {
    chips.push(lane);
  }
  if (priority && priority.available) {
    chips.push(priority.label);
  }
  if (schedule && schedule.available) {
    chips.push(schedule.label);
  }
  if (dependencies.available && dependsRow && dependsRow.detail) {
    chips.push(dependsRow.detail);
  }
  if (refresh.available && refresh.label && refresh.label !== "unavailable") {
    chips.push(refresh.label);
  }
  if (session.type === "counted") {
    const countLabel = session.clamped
      ? `${formatCountLabel(session.targetCount, "task")} of ${session.requestedCount} requested · end of note`
      : formatCountLabel(session.targetCount, "task");
    chips.push(countLabel);
  }
  if (session.type === "linked" && targetNotes.length > 0) {
    chips.push(targetNotes.join(", "));
  }
  return Object.freeze({
    title: fullTitle || "Task Card",
    fullTitle: fullTitle || "Task Card",
    note: note || "",
    lane,
    laneMixed: lane === "mixed",
    priority,
    schedule,
    dependencies,
    review: refresh,
    chips: Object.freeze(chips),
    viaTaskLink: session.type === "linked",
    project: isProjectLifecycleTaskLine(lineText),
    targetNotes: Object.freeze(targetNotes),
    error: session.valid ? null : session.error || "Task context is unavailable",
    empty: !session.valid || session.targetCount === 0,
  });
}

function buildTaskCardTimeline(details = {}) {
  const recommendation = details.recommendation;
  if (!recommendation || !recommendation.available) {
    return null;
  }
  const source = recommendation.source || {};
  const preview = recommendation.preview || {};
  const scheduleDisplay = buildTaskCardDateDisplay(
    details.schedule && details.schedule.currentValue,
    details.baseDate,
  );
  if (recommendation.kind === "batch") {
    return Object.freeze({
      kind: "batch",
      dateStart: normalizeBulletPropertyValue(source.dateStart || preview.dateValue),
      dateEnd: normalizeBulletPropertyValue(source.dateEnd || ""),
      currentOffset:
        scheduleDisplay && Number.isFinite(scheduleDisplay.offset)
          ? scheduleDisplay.offset
          : null,
      frozenOffset: null,
      minDays: null,
      maxDays: null,
      outOfWindow: false,
      label:
        source.dateStart && source.dateEnd && source.dateStart !== source.dateEnd
          ? `${source.dateStart} → ${source.dateEnd}`
          : source.dateStart || source.dateEnd || preview.dateText || "",
    });
  }
  const level = source.toLevel || source.level || null;
  const bounds = getPriorityRollBounds(level);
  const frozenOffset = Number.isFinite(Number(source.offset))
    ? Number(source.offset)
    : null;
  const minDays = bounds ? bounds.minDays : null;
  const maxDays = bounds ? bounds.maxDays : null;
  const outOfWindow =
    frozenOffset !== null &&
    minDays !== null &&
    maxDays !== null &&
    (frozenOffset < minDays || frozenOffset > maxDays);
  return Object.freeze({
    kind: source.kind || preview.kind || "roll",
    dateStart: "",
    dateEnd: "",
    currentOffset:
      scheduleDisplay && Number.isFinite(scheduleDisplay.offset)
        ? scheduleDisplay.offset
        : 0,
    frozenOffset,
    minDays,
    maxDays,
    outOfWindow,
    label:
      frozenOffset === null
        ? ""
        : `${formatTaskCardCompactRelative(frozenOffset)} · ${minDays ?? "?"}–${maxDays ?? "?"}d`,
  });
}

function presentTaskCardRow(row) {
  if (!row) {
    return null;
  }
  const shortcut = TASK_CARD_ROW_SHORTCUTS[row.id] || "";
  let label = row.label || "";
  if (row.id === "schedule") {
    label = "Schedule…";
  } else if (row.id === "depends-on") {
    label = "Blocked by…";
  } else if (row.id === "review-every") {
    label = "Review every…";
  } else if (row.id === "cancel" && label && !label.endsWith("…")) {
    label = `${label}…`;
  }
  return Object.freeze({
    id: row.id,
    kind: row.kind,
    action: row.action,
    shortcut,
    label,
    detail: row.enabled
      ? row.currentLabel || row.detail || ""
      : row.unavailableReason || row.detail || "",
    enabled: Boolean(row.enabled),
    unavailableReason: row.unavailableReason || null,
    selected: false,
    destructive: row.id === "cancel",
    dividerBefore: row.id === "cancel",
  });
}

function orderedTaskCardRows(model) {
  const rows = Array.isArray(model && model.rows) ? model.rows : [];
  const byId = new Map(rows.map((row) => [row.id, row]));
  const ordered = [];
  for (const id of TASK_CARD_ROW_ORDER) {
    const row = byId.get(id);
    if (!row) {
      continue;
    }
    const presented = presentTaskCardRow(row);
    ordered.push(
      Object.freeze({
        ...presented,
        selected: row.id === (model && model.selectedRowId),
      }),
    );
  }
  for (const row of rows) {
    if (TASK_CARD_ROW_ORDER.includes(row.id)) {
      continue;
    }
    const presented = presentTaskCardRow(row);
    ordered.push(
      Object.freeze({
        ...presented,
        selected: row.id === (model && model.selectedRowId),
      }),
    );
  }
  return Object.freeze(ordered);
}

function taskCardLevelToneClass(index) {
  if (index === 0) {
    return "is-p1";
  }
  if (index === 1) {
    return "is-p2";
  }
  if (index === 2) {
    return "is-p3";
  }
  if (index === 3) {
    return "is-p4";
  }
  return "is-extra";
}

function currentTaskCardPriorityValue(model) {
  const mixed = model && model.mixedMetadata && model.mixedMetadata.priority;
  if (!mixed || mixed.mixed) {
    return mixed && mixed.mixed ? "mixed" : "";
  }
  return normalizeBulletPropertyValue(
    Array.isArray(mixed.currentValues) ? mixed.currentValues[0] : "",
  );
}

function appendTaskCardKeycap(parent, text) {
  if (!parent || !text) {
    return null;
  }
  return parent.createEl("kbd", {
    cls: "bob-key-card-key bob-task-card-key",
    text,
  });
}

function renderTaskCardTimelineTrack(container, timeline) {
  if (!container || !timeline) {
    return;
  }
  const track = container.createDiv({ cls: "bob-task-card-timeline-track" });
  track.createSpan({
    cls: "bob-task-card-timeline-today",
    text: "today",
  });
  if (timeline.kind === "batch") {
    track.createSpan({
      cls: "bob-task-card-timeline-span",
      text: timeline.label || "multiple dates",
    });
    return;
  }
  const min = Number(timeline.minDays);
  const max = Number(timeline.maxDays);
  const frozen = Number(timeline.frozenOffset);
  const current = Number(timeline.currentOffset);
  const points = [0];
  if (Number.isFinite(min)) {
    points.push(min);
  }
  if (Number.isFinite(max)) {
    points.push(max);
  }
  if (Number.isFinite(frozen)) {
    points.push(frozen);
  }
  if (Number.isFinite(current)) {
    points.push(current);
  }
  const lo = Math.min(...points);
  const hi = Math.max(...points);
  const span = Math.max(1, hi - lo);
  const place = (value, cls, label) => {
    if (!Number.isFinite(value)) {
      return;
    }
    const tick = track.createDiv({ cls: `bob-task-card-timeline-tick ${cls}` });
    const percent = ((value - lo) / span) * 100;
    tick.style.left = `${Math.max(0, Math.min(100, percent))}%`;
    tick.setAttribute("title", label);
    tick.setAttribute("aria-label", label);
  };
  if (Number.isFinite(min) && Number.isFinite(max)) {
    const windowEl = track.createDiv({
      cls: "bob-task-card-timeline-window",
    });
    windowEl.style.left = `${Math.max(0, Math.min(100, ((min - lo) / span) * 100))}%`;
    windowEl.style.width = `${Math.max(0, Math.min(100, ((max - min) / span) * 100))}%`;
    windowEl.setAttribute("aria-hidden", "true");
    track.createSpan({
      cls: "bob-task-card-timeline-bound is-min",
      text: `${min}d`,
    });
    track.createSpan({
      cls: "bob-task-card-timeline-bound is-max",
      text: `${max}d`,
    });
  }
  place(current, "is-current", "current date");
  if (Number.isFinite(frozen)) {
    place(
      frozen,
      timeline.outOfWindow ? "is-frozen is-out-of-window" : "is-frozen",
      `preview ${formatTaskCardCompactRelative(frozen)}`,
    );
  }
}

// ---- src/330-task-card-view.js ----
function renderTaskCardView(container, model, options = {}) {
  if (!container) {
    return null;
  }
  container.empty();
  addElementClasses(container, "bob-task-card", "bob-key-card");
  const headerModel = (model && model.header) || {};
  const titleId = "bob-task-card-title";
  const header = container.createDiv({ cls: "bob-task-card-header" });
  const titleEl = header.createDiv({
    cls: "bob-task-card-title bob-key-card-title",
    text: headerModel.title || "Task Card",
    attr: {
      id: titleId,
      title: headerModel.fullTitle || headerModel.title || "Task Card",
    },
  });
  titleEl.setAttribute("id", titleId);
  titleEl.setAttribute(
    "title",
    headerModel.fullTitle || headerModel.title || "Task Card",
  );
  const closeButton = header.createEl("button", {
    cls: "bob-task-card-close",
    text: "Close",
    attr: { type: "button", "aria-label": "Close" },
  });
  closeButton.addEventListener("click", (event) => {
    if (event && typeof event.preventDefault === "function") {
      event.preventDefault();
    }
    if (typeof options.onClose === "function") {
      options.onClose();
    }
  });
  // Preserve native Enter/Space activation; every other key bubbles to the
  // card-level router.
  closeButton.addEventListener("keydown", (event) => {
    if (isCardActivationKey(event)) {
      event.stopPropagation();
    }
  });
  const meta = container.createDiv({
    cls: "bob-task-card-meta",
    attr: { "aria-label": "Task metadata" },
  });
  const chips = Array.isArray(headerModel.chips) ? headerModel.chips : [];
  if (chips.length === 0) {
    meta.createSpan({
      cls: "bob-task-card-chip is-muted",
      text: headerModel.error || "unavailable",
    });
  } else {
    for (const chip of chips) {
      const text = String(chip || "");
      const laneClass =
        text === "NEXT"
          ? " is-lane-next"
          : text === "PENDING"
            ? " is-lane-pending"
            : text === "READY"
              ? " is-lane-ready"
              : text === "BLOCKED"
                ? " is-lane-blocked"
                : "";
      const dateTone =
        headerModel.schedule &&
        headerModel.schedule.overdue &&
        text === headerModel.schedule.label
          ? " is-overdue"
          : headerModel.schedule &&
              headerModel.schedule.today &&
              text === headerModel.schedule.label
            ? " is-today"
            : "";
      meta.createSpan({
        cls: `bob-task-card-chip${laneClass}${dateTone}`,
        text,
      });
    }
  }
  if (headerModel.error) {
    const errorEl = container.createDiv({
      cls: "bob-task-card-error",
      text: headerModel.error,
      attr: { role: "alert" },
    });
    errorEl.setAttribute("role", "alert");
  }
  const isCardActivationKey = (event) =>
    Boolean(event) &&
    (event.key === "Enter" || event.key === " ") &&
    !event.ctrlKey &&
    !event.metaKey &&
    !event.altKey;
  const isHeldOrComposingKey = (event) =>
    event.repeat === true || event.isComposing === true || event.keyCode === 229;
  const recommendation = model && model.recommendation;
  if (recommendation && recommendation.available) {
    const preview = recommendation.preview || {};
    const tone =
      preview.tone ||
      (preview.kind === "cancel" || recommendation.source.kind === "cancel"
        ? "danger"
        : preview.kind === "decay"
          ? "warn"
          : "accent");
    const banner = container.createDiv({
      cls: `bob-task-card-banner is-${preview.kind || recommendation.source.kind || "roll"} is-${tone}`,
      attr: { role: "button", tabindex: "0", "aria-label": "Apply recommendation" },
    });
    const activateRecommendation = (event) => {
      if (event && typeof event.preventDefault === "function") {
        event.preventDefault();
      }
      if (event && typeof event.stopPropagation === "function") {
        event.stopPropagation();
      }
      if (typeof options.onApplyRecommendation === "function") {
        options.onApplyRecommendation();
      }
    };
    banner.addEventListener("click", activateRecommendation);
    banner.addEventListener("keydown", (event) => {
      if (isCardActivationKey(event)) {
        if (isHeldOrComposingKey(event)) {
          event.preventDefault();
          event.stopPropagation();
          return;
        }
        activateRecommendation(event);
        return;
      }
    });
    const bannerMain = banner.createDiv({ cls: "bob-task-card-banner-main" });
    appendTaskCardKeycap(bannerMain, "Ctrl+Enter");
    const actionText =
      preview.kind === "cancel" ||
      (recommendation.source && recommendation.source.kind === "cancel")
        ? "Cancel task"
        : preview.action || "Roll";
    bannerMain.createSpan({
      cls: "bob-task-card-banner-action",
      text: actionText,
    });
    if (preview.dateText || preview.dateValue) {
      const dateEl = bannerMain.createSpan({
        cls: "bob-task-card-banner-date",
        text: preview.dateText || preview.dateValue,
      });
      if (preview.kind === "cancel") {
        addElementClasses(dateEl, "is-danger");
      }
    }
    if (preview.meta) {
      bannerMain.createSpan({
        cls: "bob-task-card-banner-meta",
        text: preview.meta,
      });
    }
    if (recommendation.kind === "batch") {
      const counts = recommendation.effects || {};
      const skipped = recommendation.skippedCount || 0;
      banner.createDiv({
        cls: "bob-task-card-banner-batch",
        text: [
          recommendation.actionableCount
            ? `${recommendation.actionableCount} actions`
            : "",
          counts.roll ? `${counts.roll} roll` : "",
          counts.decay ? `${counts.decay} decay` : "",
          counts.cancel ? `${counts.cancel} cancel` : "",
          skipped ? `${skipped} skipped` : "",
        ]
          .filter(Boolean)
          .join(" · "),
      });
    }
    const timeline = model.timeline;
    if (timeline) {
      const timelineEl = banner.createDiv({
        cls: "bob-task-card-timeline",
      });
      renderTaskCardTimelineTrack(timelineEl, timeline);
      const regen = timelineEl.createDiv({
        cls: "bob-task-card-timeline-regen",
      });
      appendTaskCardKeycap(regen, "Ctrl+R");
      regen.addEventListener("click", (event) => {
        if (event && typeof event.preventDefault === "function") {
          event.preventDefault();
        }
        if (typeof options.onRefreshPreviews === "function") {
          options.onRefreshPreviews();
        }
      });
    }
  }
  const strip = model && model.priorityStrip;
  const stripEl = container.createDiv({
    cls: "bob-task-card-strip",
    attr: {
      role: "radiogroup",
      "aria-label": "Priority levels",
    },
  });
  stripEl.setAttribute("role", "radiogroup");
  stripEl.setAttribute("aria-label", "Priority levels");
  const priorityRadios = [];
  const currentPriority = currentTaskCardPriorityValue(model);
  const levels = strip && Array.isArray(strip.levels) ? strip.levels : [];
  if (!strip || !strip.propertyName || levels.length === 0) {
    stripEl.createDiv({
      cls: "bob-task-card-strip-empty",
      text: (strip && strip.unavailableReason) || "Priority is unavailable",
    });
  } else {
    for (const level of levels) {
      const isCurrent =
        currentPriority !== "mixed" &&
        normalizeBulletPropertyValue(level.value) === currentPriority &&
        currentPriority !== "";
      const dateDisplay = buildTaskCardDateDisplay(
        level.mixed ? "" : level.date,
        model && model.baseDate ? parseTaskCardIsoDate(model.baseDate) : null,
      );
      const dateLabel = level.mixed
        ? `${level.dateStart || ""} → ${level.dateEnd || ""}`.trim()
        : dateDisplay
          ? `${dateDisplay.weekday} ${dateDisplay.iso}`
          : level.date || "";
      const levelEl = stripEl.createDiv({
        cls: `bob-task-card-level bob-key-card-row ${taskCardLevelToneClass(level.index)}${
          isCurrent ? " is-current" : ""
        }${level.available ? "" : " is-disabled"}${level.mixed ? " is-mixed" : ""}`,
        attr: {
          role: "radio",
          "aria-checked": isCurrent ? "true" : "false",
          "aria-disabled": level.available ? "false" : "true",
          tabindex: isCurrent ? "0" : "-1",
          "aria-label": `${level.key ? `${level.key} ` : ""}${level.label}${dateLabel ? ` ${dateLabel}` : ""}`,
        },
      });
      levelEl.setAttribute("role", "radio");
      levelEl.setAttribute("aria-checked", isCurrent ? "true" : "false");
      levelEl.setAttribute("tabindex", isCurrent ? "0" : "-1");
      levelEl.addEventListener("click", (event) => {
        if (event && typeof event.preventDefault === "function") {
          event.preventDefault();
        }
        if (typeof options.onSelectPriority === "function") {
          options.onSelectPriority(level);
        }
      });
      levelEl.addEventListener("keydown", (event) => {
        if (event && ["ArrowLeft", "ArrowUp", "ArrowRight", "ArrowDown", "Home", "End"].includes(event.key)) {
          event.preventDefault();
          event.stopPropagation();
          const current = priorityRadios.indexOf(levelEl);
          const next = event.key === "Home"
            ? 0
            : event.key === "End"
              ? priorityRadios.length - 1
              : (current + (event.key === "ArrowLeft" || event.key === "ArrowUp" ? -1 : 1) + priorityRadios.length) % priorityRadios.length;
          if (priorityRadios[next] && typeof priorityRadios[next].focus === "function") {
            priorityRadios[next].focus();
          }
          return;
        }
        if (isCardActivationKey(event)) {
          event.preventDefault();
          event.stopPropagation();
          if (!isHeldOrComposingKey(event) && typeof options.onSelectPriority === "function") {
            options.onSelectPriority(level);
          }
          return;
        }
      });
      priorityRadios.push(levelEl);
      if (level.key) {
        appendTaskCardKeycap(levelEl, level.key);
      }
      const body = levelEl.createDiv({ cls: "bob-task-card-level-body" });
      body.createDiv({
        cls: "bob-task-card-level-label",
        text: level.label,
      });
      body.createDiv({
        cls: "bob-task-card-level-date",
        text: dateLabel || (level.available ? "" : level.unavailableReason || ""),
      });
      if (isCurrent) {
        body.createDiv({
          cls: "bob-task-card-level-hint",
          text: "re-pick · resets streak",
        });
      }
    }
    const zeroCurrent = currentPriority === "";
    const zeroEl = stripEl.createDiv({
      cls: `bob-task-card-level bob-key-card-row is-p0${
        zeroCurrent ? " is-current" : ""
      }`,
      attr: {
        role: "radio",
        "aria-checked": zeroCurrent ? "true" : "false",
        "aria-label": "P0 clear, keeps date",
      },
    });
    zeroEl.setAttribute("role", "radio");
    zeroEl.setAttribute("aria-checked", zeroCurrent ? "true" : "false");
    zeroEl.setAttribute("tabindex", zeroCurrent ? "0" : "-1");
    appendTaskCardKeycap(zeroEl, "0");
    const zeroBody = zeroEl.createDiv({ cls: "bob-task-card-level-body" });
    zeroBody.createDiv({
      cls: "bob-task-card-level-label",
      text: IMPLICIT_PRIORITY_LEVEL_LABEL,
    });
    zeroBody.createDiv({
      cls: "bob-task-card-level-date",
      text: "clear · keeps date",
    });
    zeroEl.addEventListener("click", (event) => {
      if (event && typeof event.preventDefault === "function") {
        event.preventDefault();
      }
      if (typeof options.onClearPriority === "function") {
        options.onClearPriority();
      }
    });
    zeroEl.addEventListener("keydown", (event) => {
      if (isCardActivationKey(event)) {
        event.preventDefault();
        event.stopPropagation();
        if (!isHeldOrComposingKey(event) && typeof options.onClearPriority === "function") {
          options.onClearPriority();
        }
      } else if (event && ["ArrowLeft", "ArrowUp", "ArrowRight", "ArrowDown", "Home", "End"].includes(event.key)) {
        event.preventDefault();
        event.stopPropagation();
        const current = priorityRadios.indexOf(zeroEl);
        const next = event.key === "Home"
          ? 0
          : event.key === "End"
            ? priorityRadios.length - 1
            : (current + (event.key === "ArrowLeft" || event.key === "ArrowUp" ? -1 : 1) + priorityRadios.length) % priorityRadios.length;
        if (priorityRadios[next] && typeof priorityRadios[next].focus === "function") {
          priorityRadios[next].focus();
        }
      }
    });
    priorityRadios.push(zeroEl);
    if (currentPriority === "mixed") {
      stripEl.createDiv({
        cls: "bob-task-card-strip-mixed",
        text: "mixed priorities",
      });
    }
  }
  const listEl = container.createDiv({
    cls: "bob-task-card-actions",
    attr: {
      role: "listbox",
      "aria-label": "Task Card actions",
      tabindex: "0",
    },
  });
  listEl.setAttribute("role", "listbox");
  listEl.setAttribute("aria-label", "Task Card actions");
  listEl.setAttribute("tabindex", "0");
  const presentedRows = orderedTaskCardRows(model);
  let selectedOptionId = "";
  for (const row of presentedRows) {
    if (row.dividerBefore) {
      listEl.createDiv({
        cls: "bob-task-card-divider",
        attr: { role: "separator" },
      });
    }
    const optionId = `bob-task-card-row-${row.id}`;
    const rowEl = listEl.createDiv({
      cls: `bob-task-card-row bob-key-card-row${
        row.selected ? " is-selected" : ""
      }${row.enabled ? "" : " is-disabled"}${
        row.destructive ? " is-destructive" : ""
      }`,
      attr: {
        id: optionId,
        role: "option",
        "aria-selected": row.selected ? "true" : "false",
        "aria-disabled": row.enabled ? "false" : "true",
      },
    });
    rowEl.setAttribute("id", optionId);
    rowEl.setAttribute("role", "option");
    rowEl.setAttribute("aria-selected", row.selected ? "true" : "false");
    if (row.selected) {
      selectedOptionId = optionId;
    }
    if (row.shortcut) {
      appendTaskCardKeycap(rowEl, row.shortcut);
    } else {
      rowEl.createDiv({ cls: "bob-task-card-key-spacer" });
    }
    const body = rowEl.createDiv({ cls: "bob-task-card-row-body" });
    body.createDiv({ cls: "bob-task-card-row-label", text: row.label });
    if (row.detail) {
      body.createDiv({
        cls: row.enabled
          ? "bob-task-card-row-detail"
          : "bob-task-card-row-reason",
        text: row.detail,
      });
    }
    rowEl.addEventListener("click", (event) => {
      if (event && typeof event.preventDefault === "function") {
        event.preventDefault();
      }
      if (typeof options.onOpenRow === "function") {
        options.onOpenRow(row.id);
      } else if (typeof options.onSelectRow === "function") {
        options.onSelectRow(row.id);
      }
    });
  }
  if (selectedOptionId) {
    listEl.setAttribute("aria-activedescendant", selectedOptionId);
  }
  const moreProperties = (model && model.moreProperties) || [];
  if (moreProperties.length > 0) {
    const more = container.createDiv({
      cls: "bob-task-card-more",
      attr: { "aria-label": "More properties" },
    });
    more.createDiv({
      cls: "bob-task-card-more-title",
      text: "More",
    });
    for (const item of moreProperties) {
      const moreRow = more.createDiv({
        cls: "bob-task-card-more-row",
        attr: { role: "button", tabindex: "0", "aria-label": `Open ${item.propertyName || item.label || "property"}` },
      });
      const openProperty = (event) => {
        if (event && typeof event.preventDefault === "function") {
          event.preventDefault();
        }
        if (typeof options.onOpenProperty === "function") {
          options.onOpenProperty(item.propertyName || item.label || "");
        }
      };
      moreRow.addEventListener("click", openProperty);
      moreRow.addEventListener("keydown", (event) => {
        if (event && (event.key === "Enter" || event.key === " ")) {
          if (typeof event.stopPropagation === "function") {
            event.stopPropagation();
          }
          openProperty(event);
          return;
        }
      });
      moreRow.createSpan({
        cls: "bob-task-card-more-name",
        text: item.propertyName || item.label || "property",
      });
      moreRow.createSpan({
        cls: "bob-task-card-more-value",
        text: item.mixed
          ? "mixed"
          : item.currentLabel || item.currentValue || "unset",
      });
    }
  }
  if (model && model.session && model.session.type !== "single") {
    const disclosure = container.createDiv({
      cls: "bob-task-card-disclosure",
    });
    if (model.session.type === "counted") {
      disclosure.createDiv({
        cls: "bob-task-card-disclosure-title",
        text: model.session.clamped
          ? `${model.session.targetCount} of ${model.session.requestedCount} requested · end of note`
          : formatCountLabel(model.session.targetCount, "task"),
      });
    } else if (model.session.type === "linked") {
      disclosure.createDiv({
        cls: "bob-task-card-disclosure-title",
        text: `via Task Link · ${formatCountLabel(model.session.targetCount, "task")}`,
      });
      const notes = (model.header && model.header.targetNotes) || [];
      if (notes.length > 0) {
        disclosure.createDiv({
          cls: "bob-task-card-disclosure-notes",
          text: notes.join(" · "),
        });
      }
    }
    if (recommendation && recommendation.kind === "batch") {
      const entries =
        recommendation.source && Array.isArray(recommendation.source.entries)
          ? recommendation.source.entries
          : [];
      for (const entry of entries.slice(0, 8)) {
        const rec = entry && entry.recommendation;
        disclosure.createDiv({
          cls: "bob-task-card-disclosure-item",
          text: rec
            ? `${rec.kind}${rec.date ? ` · ${rec.date}` : ""}`
            : entry.skipped || "skipped",
        });
      }
    }
  }
  if (headerModel.empty && !headerModel.error) {
    container.createDiv({
      cls: "bob-task-card-empty",
      text: "No task targets are available",
    });
  }
  const footer = container.createDiv({
    cls: "bob-task-card-footer bob-key-card-footer",
  });
  footer.createSpan({
    text: "Ctrl+D clear selected property · Esc / q / Ctrl+[ close",
  });
  if (typeof options.onFocusList === "function") {
    options.onFocusList(listEl);
  } else if (listEl && typeof listEl.focus === "function") {
    listEl.focus();
  }
  return Object.freeze({
    titleId,
    listEl,
    closeButton,
  });
}

// Between the Task Card and the stage it opens the modal borrows the filtered
// picker chrome for one synchronous step. These options paint no title,
// rows, or hints, so no frame can show a property list.
const TASK_CARD_PENDING_STAGE = "stage-pending";

function taskCardNeutralStageOptions() {
  return {
    items: [],
    title: "",
    headerIcon: "list-checks",
    inputLabel: "Filter",
    placeholder: "",
    resultsLabel: "Task Card stage",
    emptyText: "",
    footerHints: [],
    getSubtitle: () => "",
    filterItem: () => true,
    renderItem: () => {},
    openItem: () => false,
  };
}

// ---- src/340-picker-core.js ----
class BulletPropertyPickerModal extends FilteredPickerModal {
  constructor(app, plugin, editor, cursor, lineText, config, context = {}) {
    super(app, taskCardNeutralStageOptions());

    this.plugin = plugin;
    this.editor = editor;
    this.cursor = cursor;
    this.lineText = lineText;
    this.config = config;
    this.propertyContext = context.propertyContext || {};
    this.filePath = context.filePath || "";
    this.taskSession = context.taskSession || null;
    this.linkSession = context.linkSession || null;
    this.bulletSubtitle = truncateBulletPropertySubtitle(lineText);
    this.stage = TASK_CARD_PENDING_STAGE;
    this.selectedPropertyItem = null;
    this.pendingTask = null;
    this.markedLines = new Set();
    this.taskItemsByLine = new Map();
    this.priorityRandom =
      typeof context.random === "function" ? context.random : Math.random;
    // The Task Card is this modal's home surface. A direct stage (the
    // `initialProperty: "dependsOn"` skip, the decay Less often picker) opens
    // its value stage without ever painting the card, so it has no card to
    // return to: Back, empty-Backspace and refused stages close it instead.
    this.directStage =
      Boolean(context.initialProperty) || context.directStage === true;
    this.hasTaskCard = !this.directStage;
    this.linkResolving = context.linkResolving === true;
    this.taskCardModel = null;
    this.taskCardSelectedRowId = "schedule";
    this.taskCardListEl = null;
    this.fixedValueBaseDate =
      context.baseDate instanceof Date
        ? getLocalDateStart(context.baseDate)
        : null;
    // Batch block-ID prompting state; populated only while the modal is
    // collecting block IDs for a pending multi-task apply (see commit flow).
    this.pendingBatch = null;
    this.pendingCountedDependency = null;
    this.pendingVaultSingle = null;
    this.pendingVaultCounted = null;
    this.blockIdMode = "single";
    this.blockIdContext = null;
    this.pendingScheduleReason = null;
    this.pendingCancel = null;
    this.pendingLaneRelease = null;
    this.pendingScheduleWorkLog = null;
    // Vault-wide Depends on stage (nav-stage) state: the sync pool built when
    // the local-task value stage opens, plus the property rows for the
    // `initialProperty` skip. `initialProperty: "dependsOn"` opens the
    // Depends on value stage straight from the cursor entry points.
    this.initialProperty = context.initialProperty || null;
    this.propertyItems = [];
    this.vaultStage = null;
    this.vaultStageRefreshId = 0;
    this.valueBaseDate = this.fixedValueBaseDate || getLocalDateStart(new Date());
    // The Ctrl+Enter recommendation is previewed once when the picker opens
    // (what you see is what you get): the write reuses exactly this date and
    // offset. Only Ctrl+R and the stale-write path replace it.
    this.priorityRollRecommendation = null;
    this.priorityRollRecommendationReady = false;
    this.countedRollBatch = null;
    this.countedRollBatchReady = false;
    this.linkRollBatch = null;
    this.linkRollBatchReady = false;
    this.refreshPriorityRollRecommendation();
    this.refreshCountedRollBatch();
    this.refreshLinkRollBatch();
    if (!this.linkResolving) {
      this.refreshPropertyItems();
    }
    if (this.hasTaskCard) {
      this.showTaskCard({ rebuild: true });
    }
  }

}
// ---- src/350-picker-task-card.js ----
class BulletPropertyPickerTaskCardMixin extends FilteredPickerModal {
  applyTaskCardChrome(options = {}) {
    if (!this.modalEl) {
      return;
    }
    const add =
      typeof this.modalEl.addClass === "function"
        ? (name) => this.modalEl.addClass(name)
        : () => {};
    const remove =
      typeof this.modalEl.removeClass === "function"
        ? (name) => this.modalEl.removeClass(name)
        : () => {};
    if (this.hasTaskCard) {
      add("bob-task-card-modal");
      if (options.wide) {
        add("bob-task-card-wide");
      } else {
        remove("bob-task-card-wide");
      }
    } else {
      remove("bob-task-card-modal");
      remove("bob-task-card-wide");
    }
  }

  getTaskCardFreshnessApi() {
    if (this.plugin && typeof this.plugin.getFreshnessApi === "function") {
      return this.plugin.getFreshnessApi();
    }
    return getReviewFreshnessApi(this.app);
  }

  buildTaskCardContext() {
    return {
      config: this.config,
      content: this.getEditorContent(),
      lineText: this.lineText,
      cursorLine: this.cursor ? this.cursor.line : 0,
      filePath: this.filePath,
      propertyContext: this.propertyContext,
      taskSession: this.taskSession,
      linkSession: this.linkSession,
      baseDate: this.fixedValueBaseDate || this.valueBaseDate,
      random: this.priorityRandom,
      freshnessApi: this.getTaskCardFreshnessApi(),
      frozenRecommendation: this.getTaskCardFrozenRecommendation(),
      selectedRowId: this.taskCardSelectedRowId,
    };
  }

  showTaskCard(options = {}) {
    this.stage = "task-card";
    this.selectedPropertyItem = null;
    this.pendingTask = null;
    if (typeof this.clearPendingBatch === "function") {
      this.clearPendingBatch();
    }
    if (options.rebuild === true || !this.taskCardModel) {
      this.taskCardModel = planTaskCard(this.buildTaskCardContext());
      this.taskCardSelectedRowId =
        this.taskCardModel.selectedRowId || "schedule";
    } else if (this.taskCardSelectedRowId) {
      this.taskCardModel = Object.freeze({
        ...this.taskCardModel,
        selectedRowId: this.taskCardSelectedRowId,
      });
    }
    this.applyTaskCardChrome({ wide: false });
    if (this.isOpen && this.contentEl && this.modalEl) {
      this.contentEl.empty();
      this.modalEl.addClass("bob-cnp-modal");
      this.contentEl.addClass("bob-cnp");
      this.renderTaskCard();
    }
  }

  renderTaskCard() {
    if (!this.contentEl || !this.taskCardModel) {
      return;
    }
    this.contentEl.empty();
    this.contentEl.addClass("bob-cnp");
    this.contentEl.addClass("bob-task-card-root");
    this.contentEl.setAttribute("tabindex", "-1");
    this.modalEl.addClass("bob-cnp-modal");
    this.applyTaskCardChrome({ wide: false });
    this.modalEl.setAttribute("role", "dialog");
    this.modalEl.setAttribute("aria-modal", "true");
    this.modalEl.setAttribute("aria-labelledby", "bob-task-card-title");
    const rendered = renderTaskCardView(this.contentEl, this.taskCardModel, {
      onClose: () => this.close(),
      onSelectRow: (rowId) => {
        this.taskCardSelectedRowId = rowId;
        this.taskCardModel = Object.freeze({
          ...this.taskCardModel,
          selectedRowId: rowId,
        });
        this.renderTaskCard();
      },
      onOpenRow: (rowId) => {
        const row = (this.taskCardModel && this.taskCardModel.rows || []).find((item) => item.id === rowId);
        void this.dispatchTaskCardIntent(taskCardIntentForRow(row));
      },
      onSelectPriority: (level) => {
        void this.dispatchTaskCardIntent({ type: "set-priority", key: level && level.key, value: level && level.value });
      },
      onClearPriority: () => {
        void this.dispatchTaskCardIntent({ type: "clear-priority" });
      },
      onApplyRecommendation: () => {
        void this.dispatchTaskCardIntent({ type: "apply-recommendation" });
      },
      onRefreshPreviews: () => this.refreshTaskCardPreviews(),
      onOpenProperty: (propertyName) => {
        void this.dispatchTaskCardIntent({ type: "open-property", propertyName });
      },
      onFocusList: (listEl) => {
        this.taskCardListEl = listEl;
        if (listEl && typeof listEl.focus === "function") {
          listEl.focus();
        }
      },
    });
    this.taskCardListEl = rendered && rendered.listEl;
    this.inputEl = null;
    this.resultsEl = null;
    this.headerEl = null;
    this.headerIconEl = null;
    this.titleEl = null;
    this.subtitleEl = null;
    this.footerEl = null;
  }

  getTaskCardFrozenRecommendation() {
    const baseDate = this.valueBaseDate instanceof Date
      ? this.valueBaseDate
      : getLocalDateStart(new Date());
    if (this.linkSession && this.linkSession.kind === "task-link") {
      const source = this.linkRollBatch;
      if (!source) {
        return null;
      }
      return Object.freeze({
        kind: "batch",
        source,
        preview: buildLinkRollPreviewModel(source, baseDate),
        available: source.actionableCount > 0 && !source.unavailableReason,
        unavailableReason: source.unavailableReason || null,
        effects: source.counts,
        targetCount: source.total,
        actionableCount: source.actionableCount,
        skippedCount: source.skippedCount,
      });
    }
    if (this.isCountedSession()) {
      const source = this.countedRollBatch;
      if (!source) {
        return null;
      }
      return Object.freeze({
        kind: "batch",
        source,
        preview: buildBatchPriorityRollPreviewModel(source),
        available: source.actionableCount > 0 && !source.unavailableReason,
        unavailableReason: source.unavailableReason || null,
        effects: source.counts,
        targetCount: source.total,
        actionableCount: source.actionableCount,
        skippedCount: source.skippedCount,
      });
    }
    const source = this.priorityRollRecommendation;
    if (!source) {
      return null;
    }
    const preview = buildPriorityRollPreviewModel(source, baseDate);
    const available = source.kind !== "unavailable" && Boolean(source.date || source.kind === "cancel");
    return Object.freeze({
      kind: "single",
      source,
      preview,
      available,
      unavailableReason: source.kind === "unavailable" ? source.reason || "Recommendation is unavailable" : null,
      effects: Object.freeze({
        roll: source.kind === "roll" ? 1 : 0,
        decay: source.kind === "decay" ? 1 : 0,
        cancel: source.kind === "cancel" ? 1 : 0,
      }),
      targetCount: 1,
      actionableCount: available ? 1 : 0,
      skippedCount: 0,
    });
  }

  getTaskCardPropertyItems() {
    if (this.isLinkSession()) {
      const aggregate = createLinkPickerPropertyItems(this.config, this.linkSession.resolved);
      return aggregate.valid ? aggregate.items : [];
    }
    if (this.isCountedSession()) {
      const aggregate = createCountedBulletPropertyItems(this.config, this.getEditorContent(), this.taskSession);
      return aggregate.valid ? aggregate.items : [];
    }
    return createBulletPropertyItems(this.config, this.lineText, this.propertyContext);
  }

  getTaskCardPropertyItem(propertyName) {
    const normalized = normalizeBulletPropertyName(propertyName);
    return this.getTaskCardPropertyItems().find(
      (item) => item && item.property && normalizeBulletPropertyName(item.property.name) === normalized,
    ) || null;
  }

  // Swaps the card for the filtered-picker chrome a value, reason, or review
  // stage paints into. The caller opens that stage in the same synchronous
  // step; `openTaskCardStage` returns to the card when nothing took over.
  ensureTaskCardStageChrome() {
    if (this.stage !== "task-card") {
      return;
    }
    this.stage = TASK_CARD_PENDING_STAGE;
    this.applyOptions(taskCardNeutralStageOptions());
    FilteredPickerModal.prototype.onOpen.call(this);
    this.applyTaskCardChrome({ wide: false });
  }

  openTaskCardStage(open) {
    this.ensureTaskCardStageChrome();
    try {
      open();
    } finally {
      if (this.isOpen && this.stage === TASK_CARD_PENDING_STAGE) {
        this.returnToTaskCard();
      }
    }
  }

  // Where a refused or stale stage lands: back on the card, or closed when
  // this modal was opened straight into a stage and never had a card.
  returnHome(options = {}) {
    if (this.hasTaskCard) {
      this.returnToTaskCard(options);
    } else if (this.isOpen) {
      this.close();
    }
  }

  selectTaskCardRow(rowId) {
    this.taskCardSelectedRowId = rowId;
    if (this.taskCardModel) {
      this.taskCardModel = Object.freeze({ ...this.taskCardModel, selectedRowId: rowId });
    }
    this.renderTaskCard();
  }

  returnToTaskCard(options = {}) {
    this.pendingScheduleReason = null;
    this.pendingScheduleReview = null;
    this.pendingCancel = null;
    this.pendingLaneRelease = null;
    this.pendingScheduleWorkLog = null;
    this.pendingTask = null;
    this.pendingBatch = null;
    this.pendingVaultSingle = null;
    this.pendingVaultCounted = null;
    this.pendingCountedDependency = null;
    this.scheduleReviewFormEl = null;
    this.scheduleReviewReasonEl = null;
    this.scheduleReviewSummaryEl = null;
    this.clearLocalTaskMarks();
    this.showTaskCard(options.rebuild === true ? { rebuild: true } : {});
  }

  handleTaskCardKeydown(event) {
    if (!event) {
      return;
    }
    const stop = () => {
      if (typeof event.preventDefault === "function") event.preventDefault();
      if (typeof event.stopPropagation === "function") event.stopPropagation();
    };
    if (event.isComposing === true || event.keyCode === 229) {
      stop();
      return;
    }
    if (this.linkResolving) {
      stop();
      if (isTaskCardCloseKeydown(event)) this.close();
      return;
    }
    const model = this.taskCardModel;
    const intent = resolveTaskCardKey(model, event);
    if (!intent) {
      return;
    }
    stop();
    if (intent.type === "ignored") {
      return;
    }
    if (intent.type === "move-selection") {
      const rows = orderedTaskCardRows(model);
      if (rows.length === 0) return;
      const current = rows.findIndex((row) => row.id === this.taskCardSelectedRowId);
      const delta = intent.direction === "previous" ? -1 : 1;
      const next = (Math.max(0, current) + delta + rows.length) % rows.length;
      this.selectTaskCardRow(rows[next].id);
      return;
    }
    if (intent.type === "back") {
      this.returnToTaskCard();
      return;
    }
    void this.dispatchTaskCardIntent(intent).catch(() => {
      new Notice("Could not apply Task Card action");
    });
  }

  async dispatchTaskCardIntent(intent) {
    if (!intent) return false;
    if (intent.type === "unavailable") {
      if (intent.reason) new Notice(intent.reason);
      return false;
    }
    if (intent.type === "close-card") {
      this.close();
      return true;
    }
    if (this.linkResolving || this.taskCardDispatching || this.opening) {
      return false;
    }
    this.taskCardDispatching = true;
    try {
      let result = false;
      if (intent.type === "refresh-previews") {
        this.refreshTaskCardPreviews();
      } else if (intent.type === "apply-recommendation") {
        result = await this.applyTaskCardRecommendation();
      } else if (intent.type === "set-priority") {
        const level = this.taskCardModel.priorityStrip.levels.find((item) =>
          intent.key ? item.key === intent.key : item.value === intent.value,
        );
        result = await this.commitTaskCardPriority(level);
      } else if (intent.type === "clear-priority") {
        result = await this.clearTaskCardPriority();
      } else if (intent.type === "delete-property") {
        result = await this.deleteTaskCardProperty(intent.propertyName);
      } else if (intent.type === "open-action") {
        result = await this.openTaskCardAction(intent.rowId, intent.action);
      } else if (intent.type === "open-property") {
        result = await this.openTaskCardProperty(intent.propertyName);
      }
      if (result === true && this.isOpen) this.close();
      return result;
    } finally {
      this.taskCardDispatching = false;
    }
  }

  async openTaskCardAction(rowId, action) {
    if (action === "schedule" || rowId === "schedule") {
      const scheduleRow = (this.taskCardModel && this.taskCardModel.rows || []).find((row) => row.id === "schedule");
      const item = this.getTaskCardPropertyItem(scheduleRow && scheduleRow.propertyName || "scheduled");
      if (!item) {
        new Notice("Schedule is not configured");
        return false;
      }
      this.valueBaseDate = this.fixedValueBaseDate || this.valueBaseDate;
      this.openTaskCardStage(() => this.showValueStage(item));
      return false;
    }
    this.refreshPropertyItems();
    const findItem = (predicate) =>
      this.propertyItems.find((candidate) => candidate && predicate(candidate));
    if (rowId === "depends-on" || action === "dependencies") {
      const item = findItem((candidate) => candidate.property && candidate.property.values === "local_task_id");
      if (item) this.openTaskCardStage(() => this.showValueStage(item));
      return false;
    }
    if (rowId === "review-every" || action === "refresh") {
      const item = findItem((candidate) => candidate.kind === "refresh-interval");
      if (item) this.openTaskCardStage(() => this.showRefreshValueStage(item));
      return false;
    }
    if (rowId === "cancel" || action === "cancel") {
      const item = findItem((candidate) => candidate.kind === "cancel-task");
      if (item) this.openTaskCardStage(() => this.showCancelReasonStage(item));
      return false;
    }
    if (rowId === "lane" || action === "toggle-lane") {
      const item = findItem((candidate) => candidate.kind === "lane-toggle");
      if (!item) return false;
      if (item.needsReason) {
        this.openTaskCardStage(() => this.showLaneReleaseReasonStage(item));
        return false;
      }
      this.ensureTaskCardStageChrome();
      const applied = await this.plugin.applyLaneToggleFromPicker(this);
      if (applied !== true && this.isOpen && this.stage === TASK_CARD_PENDING_STAGE) {
        this.returnHome({ rebuild: true });
      }
      return applied;
    }
    return false;
  }

  // A More-section row opens that property's existing value stage; the
  // `scheduled` property takes the same schedule commit path as its card row.
  async openTaskCardProperty(propertyName) {
    this.refreshPropertyItems();
    const wanted = normalizeBulletPropertyName(propertyName);
    const item = this.propertyItems.find(
      (candidate) =>
        candidate &&
        candidate.kind === "property" &&
        candidate.property &&
        normalizeBulletPropertyName(candidate.property.name) === wanted,
    );
    if (!item) {
      new Notice(`${propertyName || "Property"} is not available`);
      return false;
    }
    this.openTaskCardStage(() => this.showValueStage(item));
    return false;
  }

  taskCardPrecomputedPriorityOptions(level) {
    const previews = Array.isArray(level && level.targetPreviews) ? level.targetPreviews : [];
    const byPath = new Map();
    const byLine = new Map();
    const scheduledByLine = new Map();
    for (const preview of previews) {
      const roll = Object.freeze({ date: preview.date, offset: preview.offset });
      if (this.isLinkSession()) {
        const path = normalizeVaultRelativePath(preview.path || "");
        if (!byPath.has(path)) byPath.set(path, { rollByLine: new Map(), scheduledValueByLine: new Map() });
        byPath.get(path).rollByLine.set(preview.line, roll);
        byPath.get(path).scheduledValueByLine.set(preview.line, preview.date);
      } else {
        byLine.set(preview.line, roll);
        scheduledByLine.set(preview.line, preview.date);
      }
    }
    for (const [path, value] of byPath) byPath.set(path, Object.freeze(value));
    const first = previews[0];
    return {
      precomputedRoll: first ? Object.freeze({ date: first.date, offset: first.offset }) : null,
      precomputedRollByLine: byLine,
      precomputedScheduledValueByLine: scheduledByLine,
      precomputedByPath: byPath,
      scheduleSummary: formatSchedulingWorkLogDateSpan(previews.map((item) => item.date)),
    };
  }

  async commitTaskCardPriority(level) {
    if (!level || !level.available || this.linkResolving || this.opening) {
      if (level && level.unavailableReason) new Notice(level.unavailableReason);
      return false;
    }
    const item = this.getTaskCardPropertyItem(this.taskCardModel && this.taskCardModel.priorityStrip && this.taskCardModel.priorityStrip.propertyName);
    if (!item) {
      new Notice("Priority is not configured");
      return false;
    }
    const valueItem = createBulletPropertyValueItems(item, this.valueBaseDate).find(
      (entry) => entry.value === level.value,
    );
    if (!valueItem) {
      new Notice("Priority level is not configured");
      return false;
    }
    this.selectedPropertyItem = item;
    const previewOptions = this.taskCardPrecomputedPriorityOptions(level);
    return await this.maybeOfferPriorityWorkLog(valueItem, previewOptions);
  }

  async clearTaskCardPriority() {
    const name = this.taskCardModel && this.taskCardModel.priorityStrip && this.taskCardModel.priorityStrip.propertyName;
    return await this.deleteTaskCardProperty(name);
  }

  async deleteTaskCardProperty(propertyName) {
    if (!propertyName) {
      new Notice("This action has no deletable property");
      return false;
    }
    if (!this.isLinkSession() && !this.isCountedSession()) {
      const item = this.getTaskCardPropertyItem(propertyName);
      if (!item || item.kind !== "property" || !item.defined) {
        new Notice(
          item && item.target && item.target.kind === "project-frontmatter"
            ? `${propertyName} is not set on this project`
            : `${propertyName} is not set on this bullet`,
        );
        return false;
      }
    }
    this.refreshPropertyItems();
    const item = this.propertyItems.find(
      (candidate) =>
        candidate &&
        candidate.kind === "property" &&
        candidate.property &&
        candidate.property.name === propertyName,
    );
    if (!item) {
      new Notice(`${propertyName} is not a deletable property`);
      this.returnToTaskCard({ rebuild: true });
      return false;
    }
    this.ensureTaskCardStageChrome();
    const deleted = await this.deletePropertyItem(item);
    if (deleted !== true && this.isOpen) {
      this.returnToTaskCard({ rebuild: true });
    }
    return deleted;
  }

  async applyTaskCardRecommendation() {
    if (!this.taskCardModel || !this.taskCardModel.recommendation || !this.taskCardModel.recommendation.available) {
      new Notice(this.taskCardModel?.recommendation?.unavailableReason || "No recommendation is available");
      return false;
    }
    if (this.isLinkSession()) return await this.applyLinkRecommendedRoll();
    if (this.isCountedSession()) return await this.applyCountedRecommendedRoll();
    return await this.applyRecommendedRoll();
  }

  refreshTaskCardPreviews() {
    if (this.linkSession && this.linkSession.kind === "task-link") {
      this.refreshLinkRollBatch();
    } else if (this.isCountedSession()) {
      this.refreshCountedRollBatch();
    } else {
      this.refreshPriorityRollRecommendation();
    }
    this.showTaskCard({ rebuild: true });
  }

  // Ctrl+[ closes the modal from any focused element inside it. The date,
  // filter, reason, and Work summary fields reach `handleKeydown`; this
  // catches the rest (the Back button, a card row) as the event bubbles.
  bindCloseChord() {
    if (
      this.closeChordBound ||
      !this.modalEl ||
      typeof this.modalEl.addEventListener !== "function"
    ) {
      return;
    }
    this.closeChordBound = true;
    if (!this.taskCardKeyRouterBound && this.contentEl) {
      this.taskCardKeyRouterBound = true;
      this.contentEl.addEventListener("keydown", (event) => {
        if (
          this.stage === "task-card" &&
          !(event && event.defaultPrevented)
        ) {
          this.handleTaskCardKeydown(event);
        }
      });
    }
    this.modalEl.addEventListener("keydown", (event) => {
      if (
        !event ||
        event.isComposing === true ||
        event.keyCode === 229 ||
        !isCtrlLeftBracketKeydown(event)
      ) {
        return;
      }
      event.preventDefault();
      event.stopPropagation();
      this.close();
    });
  }

  onOpen() {
    this.bindCloseChord();
    if (this.stage === "task-card") {
      this.contentEl.empty();
      this.modalEl.addClass("bob-cnp-modal");
      this.contentEl.addClass("bob-cnp");
      this.applyTaskCardChrome({ wide: false });
      this.renderTaskCard();
      const openingList = this.taskCardListEl;
      window.setTimeout(() => {
        if (
          this.isOpen &&
          this.stage === "task-card" &&
          this.taskCardListEl === openingList &&
          openingList &&
          typeof openingList.focus === "function"
        ) {
          openingList.focus();
        }
      }, 0);
      return;
    }
    super.onOpen();
    this.applyTaskCardChrome({ wide: Boolean(this.vaultStage) });
  }

  // Dismissing the modal mid-prompt is a clean cancel: no writes happen until
  // the final block ID is confirmed, so just drop the pending batch state.
  // Invalidate any pending vault-stage refresh so it never paints into the
  // closed modal.
  onClose() {
    if (this.plugin && this.plugin.activeBulletPropertyPicker === this) {
      this.plugin.activeBulletPropertyPicker = null;
    }
    this.vaultStageRefreshId = -1;
    this.clearPendingBatch();
    super.onClose();
  }

  renderAll(options = {}) {
    if (this.stage === "task-card") {
      this.renderTaskCard();
      return;
    }
    if (this.stage === "schedule-review") {
      super.renderAll({ ...options, clearQuery: false });
      this.applyTaskCardChrome({ wide: false });
      this.addTaskCardBackButton();
      this.renderScheduleReviewForm();
      return;
    }
    super.renderAll(options);
    this.applyTaskCardChrome({ wide: Boolean(this.vaultStage) });
    this.addTaskCardBackButton();
    this.deferStageInputFocus();
  }

  deferStageInputFocus() {
    const stage = this.stage;
    const openingInput = this.inputEl;
    if (!openingInput || typeof openingInput.focus !== "function") {
      return;
    }
    window.setTimeout(() => {
      if (
        this.isOpen &&
        this.stage === stage &&
        this.stage !== "task-card" &&
        this.inputEl === openingInput
      ) {
        openingInput.focus();
      }
    }, 0);
  }

  addTaskCardBackButton() {
    if (!this.hasTaskCard || this.stage === "task-card" || !this.headerEl) {
      return;
    }
    if (this.taskCardBackHeaderEl === this.headerEl && this.taskCardBackButtonEl) {
      return;
    }
    const back = this.headerEl.createEl("button", {
      cls: "bob-task-card-back bob-key-card-key",
      text: "Back",
      attr: { type: "button", "aria-label": "Back to Task Card" },
    });
    back.addEventListener("click", (event) => {
      if (event && typeof event.preventDefault === "function") event.preventDefault();
      this.returnToTaskCard();
    });
    this.taskCardBackHeaderEl = this.headerEl;
    this.taskCardBackButtonEl = back;
  }

}
// ---- src/360-picker-schedule-review.js ----
class BulletPropertyPickerScheduleReviewMixin extends FilteredPickerModal {
  isCountedSession() {
    return Boolean(
      this.taskSession &&
      this.taskSession.explicit &&
      Array.isArray(this.taskSession.targets) &&
      this.taskSession.targets.length > 0,
    );
  }

  isLinkSession() {
    return Boolean(
      this.linkSession &&
        this.linkSession.kind === "task-link" &&
        Array.isArray(this.linkSession.targets) &&
        this.linkSession.targets.length > 0,
    );
  }

  getTaskSessionSubtitle() {
    if (this.isLinkSession()) {
      return getLinkPickerSessionSubtitle(this.linkSession);
    }
    if (!this.isCountedSession()) {
      return this.bulletSubtitle;
    }
    if (this.taskSession.clamped) {
      return `${formatCountLabel(
        this.taskSession.actualCount,
        "task",
      )} of ${this.taskSession.requestedCount} requested · end of note`;
    }
    return formatCountLabel(this.taskSession.actualCount, "task");
  }

  // The property rows the card's actions and its More section open stages
  // for. Built without painting: no stage lists them.
  buildPropertyItems() {
    let items;
    if (this.isLinkSession()) {
      const aggregate = createLinkPickerPropertyItems(
        this.config,
        this.linkSession.resolved,
      );
      if (!aggregate.valid) {
        new Notice(aggregate.error);
        items = [];
      } else {
        items = aggregate.items;
      }
    } else if (this.isCountedSession()) {
      const aggregate = createCountedBulletPropertyItems(
        this.config,
        this.getEditorContent(),
        this.taskSession,
      );
      if (!aggregate.valid) {
        new Notice(aggregate.error);
        items = [];
      } else {
        items = aggregate.items;
      }
    } else {
      items = createBulletPropertyItems(
        this.config,
        this.lineText,
        this.propertyContext,
      );
    }
    const laneDescription = this.isLinkSession()
      ? describeLaneRow("", {
          linkResolved: this.linkSession.resolved,
        })
      : this.isCountedSession()
        ? describeLaneRow(this.getEditorContent(), {
            taskSession: this.taskSession,
          })
        : describeLaneRow(this.getEditorContent(), {
            cursorLine: this.cursor ? this.cursor.line : NaN,
          });
    let propertyItems = Array.isArray(items) ? items : [];
    if (laneDescription) {
      const laneItem = Object.freeze({
        kind: "lane-toggle",
        property: Object.freeze({ name: "lane" }),
        title: laneDescription.mode === "release" ? "Release to Ready" : "Commit to Next",
        detail: laneDescription.detail,
        mode: laneDescription.mode,
        needsReason: laneDescription.needsReason,
        targetCount: laneDescription.count,
        laneKind: laneDescription.kind,
        order: -1,
      });
      propertyItems = [laneItem, ...propertyItems];
    }
    // Pinned refresh row (nav-stamps), right after the lane row, in task,
    // counted and link mode. Without the freshness api the row stays hidden.
    // It writes through `api.freshness.setRefreshLine`, which also stamps.
    {
      const freshnessApi =
        this.plugin && typeof this.plugin.getFreshnessApi === "function"
          ? this.plugin.getFreshnessApi()
          : getReviewFreshnessApi(this.app);
      const refreshDescription = this.isLinkSession()
        ? describeRefreshRow("", {
            linkResolved: this.linkSession.resolved,
            freshnessApi,
          })
        : this.isCountedSession()
          ? describeRefreshRow(this.getEditorContent(), {
              taskSession: this.taskSession,
              freshnessApi,
            })
          : describeRefreshRow(this.getEditorContent(), {
              cursorLine: this.cursor ? this.cursor.line : NaN,
              freshnessApi,
            });
      if (refreshDescription) {
        const refreshItem = Object.freeze({
          kind: "refresh-interval",
          property: Object.freeze({ name: "refresh" }),
          title: "Refresh every",
          detail: refreshDescription.detail,
          days: refreshDescription.days,
          source: refreshDescription.source,
          mixed: refreshDescription.mixed === true,
          openCount: refreshDescription.openCount,
          targetCount: refreshDescription.count,
          refreshKind: refreshDescription.kind,
          order: -0.5,
          searchText: `refresh interval every ${refreshDescription.detail || ""} refresh`,
        });
        const laneIndex = propertyItems.findIndex((item) => item && item.kind === "lane-toggle");
        if (laneIndex >= 0) {
          propertyItems = [
            ...propertyItems.slice(0, laneIndex + 1),
            refreshItem,
            ...propertyItems.slice(laneIndex + 1),
          ];
        } else {
          propertyItems = [refreshItem, ...propertyItems];
        }
      }
    }
    const cancelDescription = this.isLinkSession()
      ? describeCancelTaskRow("", {
          linkResolved: this.linkSession.resolved,
        })
      : this.isCountedSession()
        ? describeCancelTaskRow(this.getEditorContent(), {
            taskSession: this.taskSession,
          })
        : describeCancelTaskRow(this.getEditorContent(), {
            cursorLine: this.cursor ? this.cursor.line : NaN,
          });
    if (cancelDescription) {
      const cancelTitle = getCancelTaskRowTitle(cancelDescription);
      const cancelItem = Object.freeze({
        kind: "cancel-task",
        property: Object.freeze({ name: "cancel" }),
        title: cancelTitle,
        detail: cancelDescription.detail,
        recurring: cancelDescription.recurring === true,
        cancelKind: cancelDescription.kind,
        openCount: cancelDescription.openCount,
        closedCount: cancelDescription.closedCount,
        fromStatus: cancelDescription.fromStatus,
        searchText: `cancel cancelled canceled abandon drop obsolete wontfix won't do close ❌ ${cancelTitle} ${cancelDescription.detail || ""}`,
      });
      propertyItems = [...propertyItems, cancelItem];
    }
    return propertyItems;
  }

  refreshPropertyItems() {
    const propertyItems = this.buildPropertyItems();
    this.propertyItems = Array.isArray(propertyItems) ? propertyItems : [];
    return this.propertyItems;
  }

  showValueStage(propertyItem) {
    if (propertyItem && propertyItem.kind === "refresh-interval") {
      this.showRefreshValueStage(propertyItem);
      return;
    }
    if (propertyItem && propertyItem.kind === "cancel-task") {
      if (propertyItem.recurring) {
        new Notice(
          "Recurring tasks are cancelled with Obsidian Tasks so the next occurrence is handled; no tasks were updated",
        );
        return;
      }
      this.showCancelReasonStage(propertyItem);
      return;
    }
    if (propertyItem && propertyItem.kind === "lane-toggle") {
      if (propertyItem.needsReason) {
        this.showLaneReleaseReasonStage(propertyItem);
        return;
      }
      void this.plugin
        .applyLaneToggleFromPicker(this)
        .then((applied) => {
          if (applied !== true) {
            this.returnHome();
          }
        })
        .catch(() => {
          this.returnHome();
        });
      return;
    }
    this.stage = "value";
    this.selectedPropertyItem = propertyItem;
    this.pendingTask = null;
    this.valueBaseDate =
      this.fixedValueBaseDate || getLocalDateStart(new Date());
    this.selectedIndex = 0;
    const property = propertyItem.property;
    if (property.values === "local_task_id") {
      if (this.isLinkSession()) {
        // Task Link mode: the Depends on row edits the linked task in its
        // own note (`docs/task-dependencies.md` §6.1), for single links and
        // batches alike. Batches open each linked task's stage in turn.
        if (propertyItem.linkDependency) {
          const resolved = Array.isArray(this.linkSession.resolved)
            ? this.linkSession.resolved
            : [];
          if (resolved.length === 1) {
            const target = resolved[0];
            this.close();
            void this.plugin.openLinkedDependencyStage(target);
            return;
          }
          if (resolved.length > 1) {
            const [first, ...rest] = resolved;
            this.close();
            void this.plugin.openLinkedDependencyStage(first);
            if (rest.length > 0) {
              new Notice(
                `⛓ Opened the first of ${resolved.length} linked tasks; reopen Depends on for the rest`,
              );
            }
            return;
          }
        }
        new Notice("No linked task to edit dependencies for");
        this.returnHome();
        return;
      }
      const validation = this.isCountedSession()
        ? validateCountedTaskSession(
            this.getEditorContent(),
            this.taskSession,
          )
        : validateDependencyParentForEditor(
            this.editor,
            this.cursor,
            this.lineText,
          );
      if (!validation.valid) {
        new Notice(validation.message || validation.error);
        this.returnHome();
        return;
      }
      if (!tryDependencyId(this.filePath, "task")) {
        new Notice(
          "Dependencies are unavailable: this note path cannot be encoded as a dependency ID",
        );
        this.returnHome();
        return;
      }
      this.showLocalTaskValueStage(propertyItem);
      return;
    }
    this.clearLocalTaskMarks();

    const isDateProperty = property.values === "date";
    const isScheduledProperty =
      isDateProperty &&
      normalizeBulletPropertyName(property.name) === "scheduled";
    const isPriorityProperty = property.values === "priority";
    const items = createBulletPropertyValueItems(
      propertyItem,
      this.valueBaseDate,
    );
    const priorityRollLevel = this.getPriorityRollLevel(property);
    // Counted batches use per-target rolls: when every target is a same-level
    // roll at one shared level the recommendation replaces the shared-date
    // pinned row, avoiding a duplicate. Otherwise the pinned row stays as the
    // explicit override.
    const countedBatchForStage =
      this.isCountedSession() && !this.isLinkSession()
        ? this.getCountedRollBatchForDateProperty(property.name)
        : null;
    const suppressCountedPinnedRoll = Boolean(
      countedBatchForStage && countedBatchForStage.allRollSameLevel,
    );
    if (priorityRollLevel && !suppressCountedPinnedRoll) {
      // For a same-level recommendation the pinned row shares the previewed
      // date, so Ctrl+Enter and Enter on the pinned row write the identical
      // date. For a decay or cancel it keeps its own same-level roll as the
      // explicit override, marked as over the ladder's limit.
      const sharedRoll = this.getScheduledRollRecommendation(property.name);
      if (sharedRoll && sharedRoll.kind === "roll") {
        items.unshift(
          createPriorityRollDateItemFromRecommendation(
            sharedRoll,
            propertyItem.currentValue || "",
          ) ||
            createPriorityRollDateItem(
              priorityRollLevel,
              this.valueBaseDate,
              propertyItem.currentValue || "",
              this.priorityRandom,
            ),
        );
      } else {
        const pinnedRoll = createPriorityRollDateItem(
          priorityRollLevel,
          this.valueBaseDate,
          propertyItem.currentValue || "",
          this.priorityRandom,
        );
        if (
          sharedRoll &&
          (sharedRoll.kind === "decay" ||
            sharedRoll.kind === "cancel" ||
            sharedRoll.kind === "unavailable")
        ) {
          const overLabel = getPriorityRollCurrentLabel(sharedRoll);
          if (overLabel) {
            pinnedRoll.detail = `${pinnedRoll.detail} · over ${overLabel}'s roll limit`;
          }
        }
        items.unshift(pinnedRoll);
      }
    }
    this.applyOptions({
      items,
      title: property.name,
      headerIcon: isDateProperty
        ? "calendar-days"
        : isPriorityProperty
          ? "signal-high"
          : "list-checks",
      inputLabel: `Filter ${property.name} values`,
      placeholder: isDateProperty
        ? isScheduledProperty
          ? "Type 3, 3d, mon, +3d, or 6/24"
          : "Type date, +3d, or 6/24"
        : isPriorityProperty
          ? "Filter priorities"
          : "Filter values",
      resultsLabel: isPriorityProperty
        ? "priority levels"
        : `${property.name} values`,
      emptyText: "No matching values",
      footerHints: getBulletPropertyStageTwoHints(
        Boolean(priorityRollLevel),
        this.getRollPreviewForDateProperty(property.name),
        {
          skipReason: isScheduledProperty,
        },
      ),
      getSubtitle: () => {
        const scope = this.isCountedSession()
          ? `${this.getTaskSessionSubtitle()} · `
          : "";
        if (propertyItem.valueState === "mixed") {
          return isPriorityProperty
            ? `${scope}Choose a level · rolls a scheduled date · current values mixed`
            : `${scope}Choose a value · current values mixed`;
        }
        const currentLabel = propertyItem.currentLabel || "";
        if (isPriorityProperty) {
          return currentLabel
            ? `${scope}Choose a level · rolls a scheduled date · current: ${currentLabel}`
            : `${scope}Choose a level · rolls a scheduled date`;
        }
        return currentLabel
          ? `${scope}Choose a value · current: ${currentLabel}`
          : `${scope}Choose a value`;
      },
      filterItem: (item, query) => fuzzyMatchesText(item.searchText, query),
      renderItem: (item, rowEl, query) =>
        this.renderValueItem(item, rowEl, query),
      openItem:
        normalizeBulletPropertyName(property.name) === "scheduled"
          ? (item) => this.commitScheduledDateItem(item)
          : (item) => this.maybeOfferPriorityWorkLog(item),
    });

    if (this.resultsEl) {
      this.renderAll({ clearQuery: true });
    }
  }

  // Refresh interval value stage (nav-stamps): presets plus "use default"
  // (clears `[refresh:: N]` via `setRefreshLine` with null, which also
  // stamps). A typed integer 1-365 applies as a custom value.
  showRefreshValueStage(refreshItem) {
    this.stage = "value";
    this.selectedPropertyItem = refreshItem;
    this.pendingTask = null;
    this.selectedIndex = 0;
    const currentDays =
      refreshItem && Number.isInteger(refreshItem.days) ? refreshItem.days : null;
    const items = createRefreshValueItems(currentDays);
    this.applyOptions({
      items,
      title: "Refresh every",
      headerIcon: "refresh-ccw",
      inputLabel: "Filter refresh intervals",
      placeholder: "Type days (1-365) or filter",
      resultsLabel: "refresh intervals",
      emptyText: "No matching intervals",
      footerHints: [
        { keys: ["↵"], label: "Apply" },
        { keys: ["esc"], label: "Close or dismiss" },
      ],
      getSubtitle: () => {
        const scope = this.isCountedSession()
          ? `${this.getTaskSessionSubtitle()} · `
          : "";
        if (refreshItem && refreshItem.mixed) {
          return `${scope}Choose days · current values mixed`;
        }
        if (Number.isInteger(currentDays)) {
          return `${scope}Choose days · current: every ${currentDays} d`;
        }
        return `${scope}Choose days · using default`;
      },
      filterItem: (item, query) => {
        if (!query || !String(query).trim()) {
          return true;
        }
        const custom = parseRefreshCustomValue(query);
        if (custom !== null && item && item.refreshDays === custom) {
          return true;
        }
        return fuzzyMatchesText(item.searchText || "", query);
      },
      renderItem: (item, rowEl, query) =>
        this.renderValueItem(item, rowEl, query),
      openItem: (item) => this.applySelectedValue(item),
    });
    if (this.resultsEl) {
      this.renderAll({ clearQuery: true });
    }
  }

  // Custom refresh entry: when the value-stage query itself is an integer
  // 1-365 with no matching preset row selected, apply it directly.
  applyRefreshCustomFromQuery(query) {
    const custom = parseRefreshCustomValue(query);
    if (custom === null) {
      return false;
    }
    return this.plugin.applyRefreshIntervalFromPicker(
      this,
      Object.freeze({
        kind: "value",
        value: custom,
        label: `${custom} days`,
        refreshDays: custom,
      }),
    );
  }

  // The scheduled value a picked date replaces: frontmatter for a ^prj task,
  // the inline field otherwise. Empty in a counted session, where each target's
  // own previous value is resolved by the counted planner instead.
  getPendingScheduleFrom() {
    const propertyItem = this.selectedPropertyItem;
    if (
      !propertyItem ||
      this.isCountedSession() ||
      this.isLinkSession()
    ) {
      return "";
    }

    return normalizeBulletPropertyValue(
      propertyItem.target && propertyItem.target.kind === "project-frontmatter"
        ? propertyItem.currentValue
        : this.getCurrentPropertyValue(propertyItem.property.name),
    );
  }

  // Whether pressing ↵ on an empty input still logs an entry: only when the
  // date actually moves and the task already keeps a log. A counted session
  // answers yes on behalf of the batch — each target is decided at write time.
  willLogWithoutReason() {
    const pending = this.pendingScheduleReason;
    if (!pending || !pending.to || pending.from === pending.to) {
      return false;
    }

    return (
      this.isCountedSession() ||
      this.isLinkSession() ||
      Boolean(findScheduleLogParent(this.getEditorContent(), this.cursor.line))
    );
  }

  // The pinned priority-roll row is a date the plugin chose, so it never prompts:
  // it writes straight through with a deterministic reason. Null when the roll
  // landed on the date the task already has.
  buildPriorityRollScheduleLogForItem(item) {
    if (!item || !item.priorityRoll || !item.level) {
      return null;
    }

    return buildPriorityRollScheduleLog({
      source: "scheduled",
      level: item.level,
      rolledDays: item.rolledDays,
      from: this.getPendingScheduleFrom(),
      to: item.value,
    });
  }

  // Live explicit targets for scheduling review/Work Log prompts. Counted and
  // single-note rows re-read the editor so a mid-review edit is visible.
  getSchedulingWorkLogTargets() {
    const path = typeof this.filePath === "string" ? this.filePath : "";
    if (this.isLinkSession()) {
      const resolved = Array.isArray(this.linkSession.resolved)
        ? this.linkSession.resolved
        : [];
      return resolved.map((target) => ({
        ...target,
        path: typeof target.path === "string" ? target.path : path,
      }));
    }
    if (this.isCountedSession() && this.taskSession) {
      return this.taskSession.targets.map((target) => ({
        ...target,
        path: typeof target.path === "string" ? target.path : path,
        rawLine:
          getEditorLine(this.editor, target.line) ?? target.rawLine,
      }));
    }
    if (this.cursor && Number.isInteger(this.cursor.line)) {
      return [
        {
          line: this.cursor.line,
          path,
          rawLine:
            getEditorLine(this.editor, this.cursor.line) ?? this.lineText,
        },
      ];
    }
    return [];
  }

  // Freeze a scheduled date pick and route it through the combined review:
  // one optional Reason plus Work summary form that commits nothing until
  // Enter, or an immediate write when an inline reason or Shift+Enter
  // blank-reason makes the Reason known and no Work Log target qualifies.
  // Invalid typed previews never write. Pinned rolls keep their deterministic
  // reason and skip this path.
  commitScheduledDateItem(item, options = {}) {
    if (!item) {
      return false;
    }
    if (item.priorityRoll) {
      return this.maybeOfferPinnedRollWorkLog(item);
    }
    if (item.typedSchedule && item.valid === false) {
      return false;
    }
    const skipReason = options.skipReason === true;
    const normalizedInline = normalizeScheduleReasonText(
      skipReason ? "" : String(item.inlineReason || ""),
    );
    return this.openScheduleReviewOrDispatch(item, {
      reason: skipReason ? "" : normalizedInline.reason,
      reasonSupplied: skipReason || !normalizedInline.empty,
    });
  }

  // Task Card explicit-date review: one optional Reason field plus Work
  // summary when any Next/Pending target qualifies. Inline/skip reasons with
  // no Work target dispatch immediately through the existing writer.
  openScheduleReviewOrDispatch(item, options = {}) {
    const from = this.getPendingScheduleFrom();
    const plan = planScheduleReview({
      dateItem: item,
      from,
      to: item && item.value,
      reason: options.reason,
      reasonSupplied: options.reasonSupplied === true,
      targets: this.getSchedulingWorkLogTargets(),
      isProject: Boolean(
        this.selectedPropertyItem &&
          this.selectedPropertyItem.target &&
          this.selectedPropertyItem.target.kind === "project-frontmatter",
      ),
      baseDate: this.valueBaseDate,
    });
    if (!plan.needsReview) {
      return this.applySelectedValue(item, {
        scheduleLog: {
          from: plan.from,
          to: plan.to,
          reason: plan.reason,
          fallbackReason: SCHEDULE_LOG_SKIPPED_REASON_TEXT,
        },
        schedulingWorkLog: null,
      });
    }
    this.showScheduleReviewStage(plan);
    return false;
  }

  // Combined Task Card review: Reason plus optional Work summary in one
  // uncommitted state. Nothing is written until Enter confirms both fields.
  showScheduleReviewStage(plan) {
    if (!plan || !plan.dateItem) {
      return;
    }
    this.ensureTaskCardStageChrome();
    this.stage = "schedule-review";
    this.pendingScheduleReview = Object.freeze({
      ...plan,
      resume: async ({ reason, summary }) => {
        const scheduleLog = {
          from: plan.from,
          to: plan.to,
          reason,
          fallbackReason: SCHEDULE_LOG_SKIPPED_REASON_TEXT,
        };
        return await this.applySelectedValue(plan.dateItem, {
          scheduleLog,
          schedulingWorkLog: summary
            ? {
                summary,
                dateText: formatBulletPropertyDate(
                  this.valueBaseDate instanceof Date
                    ? this.valueBaseDate
                    : getLocalDateStart(new Date()),
                ),
              }
            : null,
        });
      },
    });
    this.pendingScheduleReason = Object.freeze({
      dateItem: plan.dateItem,
      from: plan.from,
      to: plan.to,
    });
    this.scheduleReviewFormEl = null;
    this.clearLocalTaskMarks();
    this.selectedIndex = 0;
    this.applyOptions({
      items: [],
      title: plan.title || "Schedule task",
      headerIcon: "calendar-clock",
      inputLabel: "Reason for this date",
      placeholder: "Why this date? (optional)",
      resultsLabel: "Schedule review",
      emptyText: "Nothing written yet",
      footerHints: getScheduleReviewHints({
        empty: plan.reasonEmpty && !plan.needsWorkLog,
        hasWorkLog: plan.needsWorkLog,
      }),
      getSubtitle: () => this.getScheduleReviewSubtitle(),
      filterItem: () => true,
      renderItem: (item, rowEl, query) =>
        this.renderScheduleReviewPreview(item, rowEl, query),
      openItem: () => this.confirmScheduleReview(),
    });
    if (!this.headerEl || !this.searchEl || !this.resultsEl) {
      FilteredPickerModal.prototype.onOpen.call(this);
      return;
    }
    this.renderAll();
  }

}
// ---- src/370-picker-schedule-work-log.js ----
class BulletPropertyPickerScheduleWorkLogMixin extends FilteredPickerModal {
  getScheduleReviewSubtitle() {
    const pending = this.pendingScheduleReview;
    if (!pending) {
      return "";
    }
    return (pending.effects || []).join(" · ");
  }

  getScheduleReviewReasonText() {
    if (this.scheduleReviewReasonEl) {
      return String(this.scheduleReviewReasonEl.value || "");
    }
    const pending = this.pendingScheduleReview;
    return pending ? String(pending.reason || "") : "";
  }

  getScheduleReviewSummaryText() {
    if (!this.pendingScheduleReview || !this.pendingScheduleReview.needsWorkLog) {
      return "";
    }
    if (this.scheduleReviewSummaryEl) {
      return String(this.scheduleReviewSummaryEl.value || "");
    }
    return "";
  }

  renderScheduleReviewForm() {
    const pending = this.pendingScheduleReview;
    if (!pending || !this.searchEl) {
      return;
    }
    const reasonValue = this.getScheduleReviewReasonText() || pending.reason || "";
    const summaryValue = this.getScheduleReviewSummaryText();
    this.searchEl.empty();
    addElementClasses(this.searchEl, "bob-task-card-review");
    const form = this.searchEl.createDiv({
      cls: "bob-task-card-review-form",
    });
    this.scheduleReviewFormEl = form;

    const reasonField = form.createDiv({ cls: "bob-task-card-review-field" });
    reasonField.createEl("label", {
      text: "Reason for this date (optional)",
      attr: { for: "bob-schedule-review-reason" },
    });
    const reasonInput = reasonField.createEl("input", {
      cls: "bob-cnp-input bob-task-card-review-input",
      attr: {
        id: "bob-schedule-review-reason",
        type: "text",
        "aria-label": "Reason for this date",
        placeholder: "Why this date? (optional)",
      },
    });
    reasonInput.value = reasonValue;
    this.inputEl = reasonInput;
    this.scheduleReviewReasonEl = reasonInput;
    reasonInput.addEventListener("input", () => {
      this.selectedIndex = 0;
      this.renderResults();
    });
    reasonInput.addEventListener("keydown", (event) =>
      this.handleKeydown(event),
    );

    this.scheduleReviewSummaryEl = null;
    if (pending.needsWorkLog) {
      const summaryField = form.createDiv({
        cls: "bob-task-card-review-field",
      });
      const countLabel =
        pending.eligibleCount === 1
          ? "1 Next/Pending target only"
          : `${pending.eligibleCount} Next/Pending targets only`;
      summaryField.createEl("label", {
        text: `Work summary (optional · ${countLabel})`,
        attr: { for: "bob-schedule-review-summary" },
      });
      const summaryInput = summaryField.createEl("input", {
        cls: "bob-cnp-input bob-task-card-review-input",
        attr: {
          id: "bob-schedule-review-summary",
          type: "text",
          "aria-label": "Work summary",
          placeholder: "What did you get done? (optional · ↵ to skip)",
        },
      });
      summaryInput.value = summaryValue;
      this.scheduleReviewSummaryEl = summaryInput;
      summaryInput.addEventListener("input", () => {
        this.selectedIndex = 0;
        this.renderResults();
      });
      summaryInput.addEventListener("keydown", (event) =>
        this.handleKeydown(event),
      );
    }

    this.renderResults();
    const focusEl =
      pending.focusField === "summary" && this.scheduleReviewSummaryEl
        ? this.scheduleReviewSummaryEl
        : reasonInput;
    if (focusEl && typeof focusEl.focus === "function") {
      focusEl.focus();
    }
  }

  cycleScheduleReviewFocus(event, reverse) {
    const fields = [
      this.scheduleReviewReasonEl,
      this.scheduleReviewSummaryEl,
      this.taskCardBackButtonEl,
    ].filter(Boolean);
    if (fields.length === 0) {
      return;
    }
    const current = fields.indexOf(event && event.target);
    const delta = reverse ? -1 : 1;
    const start = current >= 0 ? current : 0;
    const next = fields[(start + delta + fields.length) % fields.length];
    if (next && typeof next.focus === "function") {
      next.focus();
    }
  }

  renderScheduleReviewPreview(item, rowEl, query) {
    const pending = this.pendingScheduleReview;
    addElementClasses(rowEl, "bob-cnp-schedule-reason-row", "bob-task-card-review-preview");
    const textEl = rowEl.createDiv({ cls: "bob-cnp-row-text" });
    const titleEl = textEl.createDiv({ cls: "bob-cnp-row-title" });
    if (item && item.reasonEmpty) {
      appendHighlighted(
        titleEl,
        item.reasonFallback ? SCHEDULE_LOG_SKIPPED_REASON_TEXT : "No reason",
        query,
      );
    } else {
      appendHighlighted(
        titleEl,
        formatScheduleLogEntryText({
          from: pending ? pending.from : "",
          to: pending ? pending.to : "",
          reason: item && item.reason,
        }),
        query,
      );
    }
    if (item && item.reasonHasInlineField) {
      textEl.createDiv({
        cls: "bob-cnp-row-meta",
        text: '"::" creates a Dataview inline field on this bullet',
      });
    }
    if (pending && pending.needsWorkLog) {
      textEl.createDiv({
        cls: "bob-cnp-schedule-work-log-preview",
        text: item && item.summaryEmpty
          ? "Schedule only; no Work Log"
          : pending.eligibleCount === 1
            ? `Prepends under 🛠️ **WORK LOG** on the qualifying task`
            : `Prepends under 🛠️ **WORK LOG** on each of the ${pending.eligibleCount} qualifying tasks`,
      });
      if (item && !item.summaryEmpty) {
        textEl.createDiv({
          cls: "bob-cnp-schedule-work-log-effects",
          text: formatLaneWorkLogEntry(
            item.summary,
            formatBulletPropertyDate(
              this.valueBaseDate instanceof Date
                ? this.valueBaseDate
                : getLocalDateStart(new Date()),
            ),
          ),
        });
      }
    }
    if (pending && Array.isArray(pending.effects)) {
      textEl.createDiv({
        cls: "bob-task-card-review-effects",
        text: pending.effects.join(" · "),
      });
    }
  }

  async confirmScheduleReview() {
    const pending = this.pendingScheduleReview;
    if (!pending || typeof pending.resume !== "function") {
      return false;
    }
    if (schedulingWorkLogSnapshotChanged(pending.targets, this.getSchedulingWorkLogTargets())) {
      new Notice("Task changed while the picker was open; nothing was written");
      this.pendingScheduleReview = null;
      this.pendingScheduleReason = null;
      this.returnHome();
      return false;
    }
    const reason = normalizeScheduleReasonText(this.getScheduleReviewReasonText());
    const summary = normalizeSchedulingWorkSummary(this.getScheduleReviewSummaryText());
    let applied = false;
    try {
      applied = await pending.resume({
        reason: reason.empty ? "" : reason.reason,
        summary,
      });
    } catch (_error) {
      applied = false;
    }
    if (applied === true) {
      return true;
    }
    this.pendingScheduleReview = null;
    this.pendingScheduleReason = null;
    this.returnHome();
    return false;
  }

  // Optional Work Log stage for scheduling Pending/Next tasks. Entered after
  // the schedule-reason stage (explicit dates) or directly (priority picks,
  // pinned rolls, recommended rolls/decays). `pending.resume` commits the
  // frozen scheduling action with the given normalized summary ("" skips).
  // Escape or dismissal discards all pending state with zero writes via
  // clearPendingBatch/onClose.
  showSchedulingWorkLogStage(pending) {
    if (!pending || typeof pending.resume !== "function") {
      return;
    }
    this.ensureTaskCardStageChrome();
    this.stage = "schedule-work-log";
    this.pendingScheduleWorkLog = pending;
    this.clearLocalTaskMarks();
    this.selectedIndex = 0;
    this.applyOptions({
      items: [],
      title: pending.title || "Schedule task",
      headerIcon: "briefcase",
      inputLabel: "Work summary",
      placeholder: "What did you get done? (optional · ↵ to skip)",
      resultsLabel: "Work Log preview",
      emptyText: "Type a summary",
      footerHints: getSchedulingWorkLogHints({ empty: true }),
      getSubtitle: () => this.getSchedulingWorkLogSubtitle(),
      filterItem: () => true,
      renderItem: (item, rowEl, query) =>
        this.renderSchedulingWorkLogPreviewItem(item, rowEl, query),
      openItem: (item) => this.confirmSchedulingWorkLog(item),
    });

    if (this.resultsEl) {
      this.renderAll({ clearQuery: true });
    }
  }

  getSchedulingWorkLogSubtitle() {
    const pending = this.pendingScheduleWorkLog;
    if (!pending) {
      return "";
    }
    const parts = [];
    if (pending.scheduleSummary) {
      parts.push(String(pending.scheduleSummary));
    }
    if (Number.isInteger(pending.eligibleCount) && pending.eligibleCount > 0) {
      const taskWord = pending.eligibleCount === 1 ? "task" : "tasks";
      if (pending.isBatch) {
        parts.push(`${pending.eligibleCount} of ${pending.totalCount || pending.eligibleCount} ${taskWord} qualify`);
      } else {
        parts.push(pending.eligibleCount === 1 ? "1 task qualifies" : `${pending.eligibleCount} tasks qualify`);
      }
    }
    parts.push("nothing written yet");
    return parts.filter(Boolean).join(" · ");
  }

  renderSchedulingWorkLogPreviewItem(item, rowEl, query) {
    const pending = this.pendingScheduleWorkLog;
    const dateText = pending ? pending.dateText : "";
    const state = item.empty ? "empty" : item.hasInlineField ? "warning" : "valid";
    addElementClasses(rowEl, "bob-cnp-schedule-work-log-row", `is-${state}`);

    const rowIcon = rowEl.createDiv({ cls: "bob-cnp-row-icon" });
    applyIcon(rowIcon, item.empty ? "minus-circle" : item.hasInlineField ? "alert-triangle" : "check-circle-2");

    const textEl = rowEl.createDiv({ cls: "bob-cnp-row-text" });
    const titleEl = textEl.createDiv({ cls: "bob-cnp-row-title" });
    if (item.empty) {
      appendHighlighted(titleEl, "No summary", query);
      textEl.createDiv({
        cls: "bob-cnp-row-meta",
        text: "Schedule only; no Work Log",
      });
    } else {
      appendHighlighted(
        titleEl,
        formatLaneWorkLogEntry(item.reason, dateText),
        query,
      );
      if (item.hasInlineField) {
        textEl.createDiv({
          cls: "bob-cnp-row-meta",
          text: '"::" creates a Dataview inline field on this bullet',
        });
      }
      const eligible = pending ? Math.max(1, Math.floor(numericOrDefault(pending.eligibleCount, 1))) : 1;
      textEl.createDiv({
        cls: "bob-cnp-schedule-work-log-preview",
        text:
          eligible === 1
            ? `Prepends under 🛠️ **WORK LOG** on the qualifying task`
            : `Prepends under 🛠️ **WORK LOG** on each of the ${eligible} qualifying tasks`,
      });
    }
    if (pending && pending.scheduleSummary) {
      textEl.createDiv({
        cls: "bob-cnp-schedule-work-log-effects",
        text: String(pending.scheduleSummary),
      });
    }
  }

  async confirmSchedulingWorkLog(item) {
    const pending = this.pendingScheduleWorkLog;
    if (!pending || !item || typeof pending.resume !== "function") {
      return false;
    }
    const summary = item.empty ? "" : String(item.reason || "");
    let applied = false;
    try {
      applied = await pending.resume(summary);
    } catch (error) {
      applied = false;
    }
    if (applied === true) {
      return true;
    }
    // Refusals must not carry a stale summary forward: drop the frozen action
    // and return to the card with fresh recommendations.
    this.pendingScheduleWorkLog = null;
    this.pendingScheduleReason = null;
    this.returnHome({ rebuild: true });
    return false;
  }

  // Count qualifying Pending/Next explicit targets for the current picker
  // state. `targets` are `{ line, rawLine }` in original coordinates.
  countSchedulingWorkLogEligible(targets) {
    return collectSchedulingWorkLogEligibleOriginalLines(targets).size;
  }

  // Route one accepted scheduling gesture through the optional Work Log
  // stage when any explicit target qualifies, else dispatch immediately.
  // `dispatch` commits the frozen scheduling action given a normalized
  // summary ("" skips the Work Log). Returns the dispatch result when no
  // prompt is needed, else false to keep the modal open on the new stage.
  async offerSchedulingWorkLogOrDispatch(options = {}) {
    const targets = Array.isArray(options.targets) ? options.targets : [];
    const dispatch = options.dispatch;
    if (typeof dispatch !== "function") {
      return false;
    }
    // Deduplicate by note plus identity so linked notes with equal line
    // numbers still count separately, and duplicate links to one task count
    // once.
    const totalCount = collectSchedulingWorkLogTargetIdentities(targets).size;
    const eligibleCount = collectSchedulingWorkLogEligibleIdentities(targets).size;
    if (eligibleCount === 0) {
      return await dispatch("");
    }
    const isBatch = totalCount > 1;
    const dateText = formatBulletPropertyDate(
      this.valueBaseDate instanceof Date
        ? this.valueBaseDate
        : getLocalDateStart(new Date()),
    );
    const title = isBatch
      ? `Schedule ${totalCount} tasks`
      : "Schedule task";
    const pending = Object.freeze({
      title,
      isBatch,
      eligibleCount,
      totalCount,
      dateText,
      scheduleSummary: String(options.scheduleSummary || ""),
      resume: dispatch,
    });
    this.showSchedulingWorkLogStage(pending);
    return false;
  }

  // Pinned roll row in the `scheduled` stage: deterministic Schedule Log
  // reason, frozen date in `item.value`; offer the Work Log stage when any
  // explicit target qualifies.
  async maybeOfferPinnedRollWorkLog(item) {
    if (!item) {
      return false;
    }
    const scheduleLog = this.buildPriorityRollScheduleLogForItem(item);
    const targets = this.isLinkSession()
      ? Array.isArray(this.linkSession.resolved)
        ? this.linkSession.resolved
        : []
      : this.isCountedSession() && this.taskSession
        ? this.taskSession.targets
        : this.cursor && Number.isInteger(this.cursor.line)
          ? [
              {
                line: this.cursor.line,
                rawLine: getEditorLine(this.editor, this.cursor.line) ?? this.lineText,
              },
            ]
          : [];
    const scheduleSummary = item.value
      ? `scheduled → ${normalizeBulletPropertyValue(item.value)}`
      : "";
    return await this.offerSchedulingWorkLogOrDispatch({
      targets,
      scheduleSummary,
      dispatch: async (summary) =>
        await this.applySelectedValue(item, {
          scheduleLog,
          schedulingWorkLog: summary
            ? {
                summary,
                dateText: formatBulletPropertyDate(
                  this.valueBaseDate instanceof Date
                    ? this.valueBaseDate
                    : getLocalDateStart(new Date()),
                ),
              }
            : null,
        }),
    });
  }

  // Priority-level picks (and any non-scheduled property): only priority
  // scheduling gestures offer the Work Log stage. All other properties keep
  // the existing immediate flow. Priority rolls are materialized once before
  // the prompt and reused on resume, so opening/submitting the prompt never
  // consumes extra randomness or changes the chosen schedule.
  async maybeOfferPriorityWorkLog(item, precomputed = {}) {
    const property =
      this.selectedPropertyItem && this.selectedPropertyItem.property;
    if (!property || property.values !== "priority") {
      return await this.applySelectedValue(item);
    }
    const level = item && item.priorityLevel;
    if (!level) {
      return await this.applySelectedValue(item);
    }
    const baseDate =
      this.valueBaseDate instanceof Date
        ? getLocalDateStart(this.valueBaseDate)
        : getLocalDateStart(new Date());
    const random =
      typeof this.priorityRandom === "function"
        ? this.priorityRandom
        : Math.random;
    if (this.isLinkSession()) {
      const resolved = Array.isArray(this.linkSession.resolved)
        ? this.linkSession.resolved
        : [];
      const eligible = collectSchedulingWorkLogEligibleOriginalLines(resolved);
      if (eligible.size === 0) {
        return await this.applySelectedValue(item, precomputed);
      }
      const groups = groupLinkPickerTargetsByNote(resolved);
      const precomputedByPath = precomputed.precomputedByPath instanceof Map
        ? precomputed.precomputedByPath
        : new Map();
      const allDates = [];
      for (const group of groups) {
        let frozen = precomputedByPath.get(group.path);
        if (!frozen) {
          const rollByLine = new Map(
            group.session.targets.map((target) => [
              target.line,
              rollPriorityScheduledDateWithOffset(level, baseDate, random),
            ]),
          );
          const scheduledValueByLine = new Map(
            Array.from(rollByLine, ([line, roll]) => [
              line,
              formatBulletPropertyDate(roll.date),
            ]),
          );
          frozen = Object.freeze({ rollByLine, scheduledValueByLine });
          precomputedByPath.set(group.path, frozen);
        }
        const scheduledValueByLine = frozen.scheduledValueByLine;
        for (const date of scheduledValueByLine.values()) {
          allDates.push(date);
        }
      }
      const scheduleSummary = precomputed.scheduleSummary || formatSchedulingWorkLogDateSpan(allDates);
      return await this.offerSchedulingWorkLogOrDispatch({
        targets: resolved,
        scheduleSummary,
        dispatch: async (summary) =>
          await this.plugin.applyLinkPickerPriorityValue(this, item, {
            schedulingWorkLog: summary
              ? { summary, dateText: formatBulletPropertyDate(baseDate) }
              : null,
            precomputedByPath,
          }),
      });
    }
    if (this.isCountedSession() && this.taskSession) {
      const targets = this.taskSession.targets;
      const eligible = collectSchedulingWorkLogEligibleOriginalLines(targets);
      if (eligible.size === 0) {
        return await this.applySelectedValue(item, precomputed);
      }
      const rollByLine = precomputed.precomputedRollByLine instanceof Map
        ? precomputed.precomputedRollByLine
        : new Map(
            targets.map((target) => [
              target.line,
              rollPriorityScheduledDateWithOffset(level, baseDate, random),
            ]),
          );
      const scheduledValueByLine = precomputed.precomputedScheduledValueByLine instanceof Map
        ? precomputed.precomputedScheduledValueByLine
        : new Map(
            Array.from(rollByLine, ([line, roll]) => [
              line,
              formatBulletPropertyDate(roll.date),
            ]),
          );
      const scheduleSummary = precomputed.scheduleSummary || formatSchedulingWorkLogDateSpan(Array.from(scheduledValueByLine.values()));
      return await this.offerSchedulingWorkLogOrDispatch({
        targets,
        scheduleSummary,
        dispatch: async (summary) =>
          await this.applySelectedValue(item, {
            schedulingWorkLog: summary
              ? { summary, dateText: formatBulletPropertyDate(baseDate) }
              : null,
            precomputedRollByLine: rollByLine,
            precomputedScheduledValueByLine: scheduledValueByLine,
          }),
      });
    }
    const targets =
      this.cursor && Number.isInteger(this.cursor.line)
        ? [
            {
              line: this.cursor.line,
              rawLine: getEditorLine(this.editor, this.cursor.line) ?? this.lineText,
            },
          ]
        : [];
    const eligible = collectSchedulingWorkLogEligibleOriginalLines(targets);
    if (eligible.size === 0) {
      return await this.applySelectedValue(item, precomputed);
    }
    const frozenRoll = precomputed.precomputedRoll || rollPriorityScheduledDateWithOffset(level, baseDate, random);
    const rolledValue = typeof frozenRoll.date === "string"
      ? normalizeBulletPropertyValue(frozenRoll.date)
      : formatBulletPropertyDate(frozenRoll.date);
    const precomputedRoll = Object.freeze({ date: rolledValue, offset: frozenRoll.offset });
    const scheduleSummary = precomputed.scheduleSummary || `scheduled → ${rolledValue}`;
    return await this.offerSchedulingWorkLogOrDispatch({
      targets,
      scheduleSummary,
      dispatch: async (summary) =>
        await this.applySelectedValue(item, {
          schedulingWorkLog: summary
            ? { summary, dateText: formatBulletPropertyDate(baseDate) }
            : null,
          precomputedRoll,
        }),
    });
  }

  // Free-text prompt shown after the pinned Cancel row is chosen, mirroring
  // the schedule-reason stage: nothing is written until this prompt is
  // confirmed (Enter, empty or not) or the modal is dismissed (Esc, a clean
  // cancel — see onClose's contract).
}
// ---- src/380-picker-cancel-and-lane.js ----
class BulletPropertyPickerCancelLaneMixin extends FilteredPickerModal {
  showCancelReasonStage(cancelItem) {
    this.stage = "cancel-reason";
    this.valueBaseDate =
      this.fixedValueBaseDate || getLocalDateStart(new Date());
    const openCount = Math.max(
      1,
      Math.floor(numericOrDefault(cancelItem && cancelItem.openCount, 1)),
    );
    this.pendingCancel = Object.freeze({
      title:
        (cancelItem && cancelItem.title) ||
        getCancelTaskRowTitle({
          kind: (cancelItem && cancelItem.cancelKind) || "task",
          openCount,
        }),
      cancelKind: (cancelItem && cancelItem.cancelKind) || "task",
      openCount,
      fromStatus: (cancelItem && cancelItem.fromStatus) || null,
      dateText: formatBulletPropertyDate(this.valueBaseDate),
    });
    this.clearLocalTaskMarks();
    this.selectedIndex = 0;
    this.applyOptions({
      items: [],
      title: this.pendingCancel.title,
      headerIcon: "ban",
      inputLabel: "Cancel reason",
      placeholder: "Why cancel it? (optional · ↵ to skip)",
      resultsLabel: "Cancel reason preview",
      emptyText: "Type a reason",
      footerHints: getCancelReasonHints({ empty: true, count: openCount }),
      getSubtitle: () => this.getCancelReasonSubtitle(),
      filterItem: () => true,
      renderItem: (item, rowEl, query) =>
        this.renderCancelReasonPreviewItem(item, rowEl, query),
      openItem: (item) => this.confirmCancelReason(item),
    });

    if (this.resultsEl) {
      this.renderAll({ clearQuery: true });
    }
  }

  getCancelReasonSubtitle() {
    const pending = this.pendingCancel;
    if (!pending) {
      return "";
    }

    let summary;
    if (pending.cancelKind === "link" && this.linkSession) {
      summary = `${getLinkPickerSessionSubtitle(this.linkSession)} → Cancelled`;
    } else if (pending.openCount > 1) {
      summary = `${formatCountLabel(pending.openCount, "task")} → Cancelled`;
    } else {
      summary = `${pending.fromStatus || "Task"} → Cancelled`;
    }
    const parts = [
      summary,
      `${getBulletPropertyDateWeekday(this.valueBaseDate)} ${pending.dateText}`,
      "nothing written yet",
    ];
    return parts.filter(Boolean).join(" · ");
  }

  // Cheap synchronous facts for the cancel preview's effects line: whether
  // any target has a block ID (prune applies) and whether any target already
  // keeps a Cancel Log (empty reasons fall back).
  getCancelReasonFacts() {
    const facts = { anyLog: false, hasBlockId: false };
    if (this.isLinkSession()) {
      const resolved = Array.isArray(this.linkSession.resolved)
        ? this.linkSession.resolved
        : [];
      const contentByPath = new Map();
      for (const group of groupLinkPickerTargetsByNote(resolved)) {
        contentByPath.set(group.path, group.content);
      }
      for (const target of resolved) {
        const rawLine = String((target && target.rawLine) || "");
        if (target && target.blockId) {
          facts.hasBlockId = true;
        }
        const content = contentByPath.get(target && target.path);
        if (
          content !== undefined &&
          Number.isInteger(target && target.line) &&
          findCancelLogParent(content, target.line)
        ) {
          facts.anyLog = true;
        }
      }
      return facts;
    }
    const content = this.getEditorContent();
    const lines =
      this.isCountedSession() && this.taskSession
        ? this.taskSession.targets.map((target) => target.line)
        : [this.cursor ? this.cursor.line : NaN];
    for (const line of lines) {
      if (!Number.isInteger(line)) {
        continue;
      }
      if (findCancelLogParent(content, line)) {
        facts.anyLog = true;
      }
    }
    const rawLines =
      this.isCountedSession() && this.taskSession
        ? this.taskSession.targets.map((target) =>
            String((target && target.rawLine) || ""),
          )
        : [String(getEditorLine(this.editor, this.cursor.line) || "")];
    for (const rawLine of rawLines) {
      if (getTrailingBlockId(rawLine)) {
        facts.hasBlockId = true;
      }
    }
    return facts;
  }

  renderCancelReasonPreviewItem(item, rowEl, query) {
    const pending = this.pendingCancel;
    const dateText = pending ? pending.dateText : "";
    const state = item.empty
      ? (item.fallback ? "fallback" : "empty")
      : item.hasInlineField
        ? "warning"
        : "valid";
    addElementClasses(rowEl, "bob-cnp-cancel-reason-row", `is-${state}`);

    const rowIcon = rowEl.createDiv({ cls: "bob-cnp-row-icon" });
    applyIcon(
      rowIcon,
      item.empty
        ? "minus-circle"
        : item.hasInlineField
          ? "alert-triangle"
          : "check-circle-2",
    );

    const textEl = rowEl.createDiv({ cls: "bob-cnp-row-text" });
    const titleEl = textEl.createDiv({ cls: "bob-cnp-row-title" });

    if (item.empty && !item.fallback) {
      appendHighlighted(titleEl, "No reason", query);
      textEl.createDiv({
        cls: "bob-cnp-row-meta",
        text: `[-] + [cancelled:: ${dateText}] only; no Cancel Log`,
      });
    } else {
      appendHighlighted(
        titleEl,
        formatCancelLogEntryText({
          date: dateText,
          reason: item.empty
            ? SCHEDULE_LOG_SKIPPED_REASON_TEXT
            : item.reason,
        }),
        query,
      );

      if (item.hasInlineField) {
        textEl.createDiv({
          cls: "bob-cnp-row-meta",
          text: '"::" creates a Dataview inline field on this bullet',
        });
      }

      textEl.createDiv({
        cls: "bob-cnp-cancel-reason-preview",
        text: item.counted
          ? item.empty
            ? `Logged on tasks that already keep a ${CANCEL_LOG_MARKER_TEXT}`
            : `Adds or prepends a ${CANCEL_LOG_MARKER_TEXT} entry on each task`
          : item.fallback
            ? `Logged because this task already keeps a ${CANCEL_LOG_LABEL}`
            : item.empty
              ? `[-] + [cancelled:: ${dateText}] only; no Cancel Log`
              : findCancelLogParent(
                    this.getEditorContent(),
                    this.cursor.line,
                  ) ||
                  (this.isLinkSession() && item.anyLog)
                ? `Prepends to the existing ${CANCEL_LOG_MARKER_TEXT}`
                : `Adds ${CANCEL_LOG_MARKER_TEXT} as the first child`,
      });
    }

    const effects = [];
    if (item.hasBlockId) {
      effects.push("Removes its links from today's open Pomodoros");
    }
    effects.push("unblocks dependents");
    textEl.createDiv({
      cls: "bob-cnp-cancel-reason-effects",
      text: effects.join(" · "),
    });
  }

  confirmCancelReason(item) {
    const pending = this.pendingCancel;
    if (!pending || !item) {
      return false;
    }

    // The payload is supplied even for an empty input: a task that already
    // keeps a log records the fallback entry, and planTaskCancelBatch is what
    // decides that per task (per target, in counted and link sessions).
    return this.plugin.applyTaskCancelFromPicker(this, {
      reason: item.empty ? "" : item.reason,
      fallbackReason: SCHEDULE_LOG_SKIPPED_REASON_TEXT,
    });
  }

  showLaneReleaseReasonStage(laneItem) {
    this.stage = "lane-release-reason";
    this.valueBaseDate =
      this.fixedValueBaseDate || getLocalDateStart(new Date());
    const openCount = Math.max(
      1,
      Math.floor(numericOrDefault(laneItem && laneItem.targetCount, 1)),
    );
    this.pendingLaneRelease = Object.freeze({
      title: "Release task",
      laneKind: (laneItem && laneItem.laneKind) || "task",
      openCount,
      dateText: formatBulletPropertyDate(this.valueBaseDate),
    });
    this.clearLocalTaskMarks();
    this.selectedIndex = 0;
    this.applyOptions({
      items: [],
      title: this.pendingLaneRelease.title,
      headerIcon: "arrow-down-to-line",
      inputLabel: "Release summary",
      placeholder: "Why is this pending? (optional · ↵ to skip)",
      resultsLabel: "Release summary preview",
      emptyText: "Type a summary",
      footerHints: getLaneReleaseReasonHints({ empty: true }),
      getSubtitle: () => this.getLaneReleaseReasonSubtitle(),
      filterItem: () => true,
      renderItem: (item, rowEl, query) =>
        this.renderLaneReleaseReasonPreviewItem(item, rowEl, query),
      openItem: (item) => this.confirmLaneReleaseReason(item),
    });

    if (this.resultsEl) {
      this.renderAll({ clearQuery: true });
    }
  }

  getLaneReleaseReasonSubtitle() {
    const pending = this.pendingLaneRelease;
    if (!pending) {
      return "";
    }
    const summary =
      pending.laneKind === "link" && this.linkSession
        ? `${getLinkPickerSessionSubtitle(this.linkSession)} → Ready`
        : pending.openCount > 1
          ? `${formatCountLabel(pending.openCount, "task")} → Ready`
          : "Task → Ready";
    const parts = [
      summary,
      `${getBulletPropertyDateWeekday(this.valueBaseDate)} ${pending.dateText}`,
      "nothing written yet",
    ];
    return parts.filter(Boolean).join(" · ");
  }

  getLaneReleaseReasonFacts() {
    const facts = { anyLog: false, hasBlockId: false };
    if (this.isLinkSession()) {
      const resolved = Array.isArray(this.linkSession.resolved)
        ? this.linkSession.resolved
        : [];
      const contentByPath = new Map();
      for (const group of groupLinkPickerTargetsByNote(resolved)) {
        contentByPath.set(group.path, group.content);
      }
      for (const target of resolved) {
        if (target && target.blockId) {
          facts.hasBlockId = true;
        }
        const content = contentByPath.get(target && target.path);
        if (
          content !== undefined &&
          Number.isInteger(target && target.line) &&
          findLaneWorkLogParent(
            String(content || "").split(/\r?\n/),
            target.line,
          )
        ) {
          facts.anyLog = true;
        }
      }
      return facts;
    }
    const content = this.getEditorContent();
    const lines =
      this.isCountedSession() && this.taskSession
        ? this.taskSession.targets.map((target) => target.line)
        : [this.cursor ? this.cursor.line : NaN];
    for (const line of lines) {
      if (!Number.isInteger(line)) {
        continue;
      }
      if (
        findLaneWorkLogParent(String(content || "").split(/\r?\n/), line)
      ) {
        facts.anyLog = true;
      }
    }
    const rawLines =
      this.isCountedSession() && this.taskSession
        ? this.taskSession.targets.map((target) =>
            String((target && target.rawLine) || ""),
          )
        : [String(getEditorLine(this.editor, this.cursor.line) || "")];
    for (const rawLine of rawLines) {
      if (getTrailingBlockId(rawLine)) {
        facts.hasBlockId = true;
      }
    }
    return facts;
  }

  renderLaneReleaseReasonPreviewItem(item, rowEl, query) {
    const pending = this.pendingLaneRelease;
    const dateText = pending ? pending.dateText : "";
    addElementClasses(rowEl, "bob-cnp-lane-release-reason-row", "is-valid");
    const rowIcon = rowEl.createDiv({ cls: "bob-cnp-row-icon" });
    applyIcon(rowIcon, "arrow-down-to-line");
    const textEl = rowEl.createDiv({ cls: "bob-cnp-row-text" });
    const titleEl = textEl.createDiv({ cls: "bob-cnp-row-title" });
    if (item.empty) {
      appendHighlighted(titleEl, "No summary", query);
      textEl.createDiv({
        cls: "bob-cnp-row-meta",
        text: "Release to Ready only; no Work Log",
      });
    } else {
      appendHighlighted(
        titleEl,
        formatLaneWorkLogEntry(item.reason, dateText),
        query,
      );
      if (item.hasInlineField) {
        textEl.createDiv({
          cls: "bob-cnp-row-meta",
          text: '"::" creates a Dataview inline field on this bullet',
        });
      }
      textEl.createDiv({
        cls: "bob-cnp-cancel-reason-preview",
        text: "Prepends to the Work Log of each released In Progress task",
      });
    }
    const effects = [];
    if (item.hasBlockId) {
      effects.push("Removes its links from today's open Pomodoros");
    }
    effects.push("releases Next and In Progress to Ready");
    textEl.createDiv({
      cls: "bob-cnp-cancel-reason-effects",
      text: effects.join(" · "),
    });
  }

  confirmLaneReleaseReason(item) {
    const pending = this.pendingLaneRelease;
    if (!pending || !item) {
      return false;
    }
    return this.plugin.applyLaneToggleFromPicker(this, {
      summary: item.empty ? "" : item.reason,
      dateText: pending.dateText,
    });
  }


  getEditorContent() {
    if (this.editor && typeof this.editor.getValue === "function") {
      return String(this.editor.getValue() || "");
    }

    return this.lineText || "";
  }

  getCurrentPropertyValue(name) {
    const lineText = getEditorLine(this.editor, this.cursor.line);
    const field = findBulletPropertyField(
      lineText === null ? this.lineText : lineText,
      name,
    );
    return field ? field.value : "";
  }

  getPriorityRollLevel(dateProperty) {
    if (!dateProperty || dateProperty.values !== "date") {
      return null;
    }
    if (this.isLinkSession()) {
      return null;
    }

    const priorityProperty = this.config.properties.find(
      (property) =>
        property.values === "priority" &&
        property.schedules === dateProperty.name,
    );
    if (!priorityProperty) {
      return null;
    }

    let currentValue;
    if (this.isCountedSession()) {
      const aggregate = createCountedBulletPropertyItems(
        this.config,
        this.getEditorContent(),
        this.taskSession,
      );
      if (!aggregate.valid) {
        return null;
      }
      const priorityItem = aggregate.items.find(
        (item) => item.property === priorityProperty,
      );
      if (!priorityItem || priorityItem.valueState !== "common") {
        return null;
      }
      currentValue = priorityItem.currentValue;
    } else {
      currentValue = this.getCurrentPropertyValue(priorityProperty.name);
    }

    return priorityProperty.levelsByValue.get(currentValue) || null;
  }

  // The Ctrl+Enter recommendation for this single (or ^prj) task, planned
  // from the live note content. Null in counted and link sessions (later
  // phases own those), and whenever there is no recommendation: a closed or
  // non-task line, no priority property naming a date property, or a current
  // value outside the configured levels.
}
// ---- src/390-picker-roll-write.js ----
class BulletPropertyPickerRollWriteMixin extends FilteredPickerModal {
  computePriorityRollRecommendation() {
    if (this.isCountedSession() || this.isLinkSession()) {
      return null;
    }
    const cursor = this.cursor;
    if (!cursor || !Number.isInteger(cursor.line)) {
      return null;
    }
    const content = this.getEditorContent();
    if (!isObsidianTaskAtLine(content, cursor.line)) {
      return null;
    }
    const lines = splitMarkdownContent(content).lines;
    const lineText = lines[cursor.line] || "";
    if (!OPEN_OBSIDIAN_TASK_STATUSES.has(getObsidianTaskCheckboxStatus(lineText))) {
      return null;
    }
    const properties =
      this.config && Array.isArray(this.config.properties)
        ? this.config.properties
        : [];
    const liveContext = getProjectNotePropertyContext(content, cursor.line);
    for (const priorityProperty of properties) {
      if (!priorityProperty || priorityProperty.values !== "priority") {
        continue;
      }
      const schedulesName = normalizeBulletPropertyName(
        priorityProperty.schedules,
      );
      if (!schedulesName) {
        continue;
      }
      const scheduledTarget = resolveBulletPropertyTarget(
        schedulesName,
        liveContext,
      );
      let currentScheduled = "";
      if (scheduledTarget.kind === "project-frontmatter") {
        currentScheduled =
          liveContext.frontmatter && liveContext.frontmatter.scheduledDefined
            ? liveContext.frontmatter.scheduledValue
            : "";
      } else {
        const scheduledField = findBulletPropertyField(lineText, schedulesName);
        currentScheduled = scheduledField ? scheduledField.value : "";
      }
      const planned = planPriorityRollRecommendation({
        property: priorityProperty,
        content,
        taskLine: cursor.line,
        currentScheduled,
        baseDate: this.valueBaseDate,
        random: this.priorityRandom,
      });
      if (!planned) {
        continue;
      }
      return Object.freeze({
        ...planned,
        priorityName: priorityProperty.name,
        schedulesName,
        taskLine: cursor.line,
      });
    }
    return null;
  }

  refreshPriorityRollRecommendation() {
    this.priorityRollRecommendation = this.computePriorityRollRecommendation();
    this.priorityRollRecommendationReady = true;
    return this.priorityRollRecommendation;
  }

  // The counted Ctrl+Enter batch, planned once when the picker opens (what you
  // see is what you get): each target keeps its own pre-rolled date. Null in
  // single and link sessions, and when no target has a recommendation.
  computeCountedRollBatch() {
    if (!this.isCountedSession() || this.isLinkSession()) {
      return null;
    }
    const content = this.getEditorContent();
    const properties =
      this.config && Array.isArray(this.config.properties)
        ? this.config.properties
        : [];
    for (const priorityProperty of properties) {
      if (!priorityProperty || priorityProperty.values !== "priority") {
        continue;
      }
      const schedulesName = normalizeBulletPropertyName(
        priorityProperty.schedules,
      );
      if (!schedulesName) {
        continue;
      }
      const summary = planPriorityRollRecommendationsForTargets(
        content,
        this.taskSession.targets,
        priorityProperty,
        {
          baseDate: this.valueBaseDate,
          random: this.priorityRandom,
        },
      );
      const actionable =
        (summary.counts.roll || 0) +
        (summary.counts.decay || 0) +
        (summary.counts.cancel || 0);
      const hasAny =
        actionable > 0 || Boolean(summary.unavailableReason);
      if (!hasAny) {
        continue;
      }
      return Object.freeze({
        ...summary,
        priorityName: priorityProperty.name,
      });
    }
    return null;
  }

  refreshCountedRollBatch() {
    this.countedRollBatch = this.computeCountedRollBatch();
    this.countedRollBatchReady = true;
    return this.countedRollBatch;
  }

  // The link-session Ctrl+Enter batch, planned once when the picker opens
  // (what you see is what you get): each resolved target keeps its own
  // pre-rolled date, read from its own note's content. Null in single and
  // counted sessions, and when no target has a recommendation.
  computeLinkRollBatch() {
    if (!this.isLinkSession()) {
      return null;
    }
    const resolved = Array.isArray(this.linkSession.resolved)
      ? this.linkSession.resolved
      : [];
    const properties =
      this.config && Array.isArray(this.config.properties)
        ? this.config.properties
        : [];
    for (const priorityProperty of properties) {
      if (!priorityProperty || priorityProperty.values !== "priority") {
        continue;
      }
      const schedulesName = normalizeBulletPropertyName(
        priorityProperty.schedules,
      );
      if (!schedulesName) {
        continue;
      }
      const summary = planLinkRollBatchSummary(
        resolved,
        priorityProperty,
        {
          baseDate: this.valueBaseDate,
          random: this.priorityRandom,
        },
      );
      const actionable =
        (summary.counts.roll || 0) +
        (summary.counts.decay || 0) +
        (summary.counts.cancel || 0);
      const hasAny =
        actionable > 0 || Boolean(summary.unavailableReason);
      if (!hasAny) {
        continue;
      }
      return Object.freeze({
        ...summary,
        priorityName: priorityProperty.name,
      });
    }
    return null;
  }

  refreshLinkRollBatch() {
    this.linkRollBatch = this.computeLinkRollBatch();
    this.linkRollBatchReady = true;
    return this.linkRollBatch;
  }

  getLinkRollBatchForDateProperty(datePropertyName) {
    const batch = this.linkRollBatch;
    if (!batch) {
      return null;
    }
    if (
      normalizeBulletPropertyName(batch.schedulesName) !==
      normalizeBulletPropertyName(datePropertyName)
    ) {
      return null;
    }
    return batch;
  }

  // Link sessions use the single-task copy for exactly one target and the
  // batch copy otherwise. They keep no pinned stage-two roll row.
  getLinkRollPreviewForDateProperty(datePropertyName) {
    const batch = this.getLinkRollBatchForDateProperty(datePropertyName);
    if (!batch) {
      return null;
    }
    return buildLinkRollPreviewModel(batch, this.valueBaseDate);
  }

  hasLinkRollBatchForDateProperty(datePropertyName) {
    const batch = this.getLinkRollBatchForDateProperty(datePropertyName);
    if (!batch) {
      return false;
    }
    return (
      batch.actionableCount > 0 || Boolean(batch.unavailableReason)
    );
  }

  // Ctrl+R re-rolls every pre-rolled link date. Only dated
  // targets (roll and decay) have one.
  rerollLinkRollBatch() {
    const cached = this.linkRollBatch;
    if (!cached || cached.actionableCount <= 0 || cached.unavailableReason) {
      return false;
    }
    const fresh = this.computeLinkRollBatch();
    if (!fresh || fresh.actionableCount <= 0 || fresh.unavailableReason) {
      return false;
    }
    if (
      fresh.counts.roll !== cached.counts.roll ||
      fresh.counts.decay !== cached.counts.decay ||
      fresh.counts.cancel !== cached.counts.cancel
    ) {
      return false;
    }
    this.linkRollBatch = fresh;
    this.linkRollBatchReady = true;
    return true;
  }

  getCountedRollBatchForDateProperty(datePropertyName) {
    const batch = this.countedRollBatch;
    if (!batch) {
      return null;
    }
    if (
      normalizeBulletPropertyName(batch.schedulesName) !==
      normalizeBulletPropertyName(datePropertyName)
    ) {
      return null;
    }
    return batch;
  }

  getCountedRollPreviewForDateProperty(datePropertyName) {
    const batch = this.getCountedRollBatchForDateProperty(datePropertyName);
    if (!batch) {
      return null;
    }
    return buildBatchPriorityRollPreviewModel(batch);
  }

  // Ctrl+R re-rolls every pre-rolled counted date. Only dated
  // targets (roll and decay) have one.
  rerollCountedRollBatch() {
    const cached = this.countedRollBatch;
    if (!cached || cached.actionableCount <= 0 || cached.unavailableReason) {
      return false;
    }
    const fresh = this.computeCountedRollBatch();
    if (!fresh || fresh.actionableCount <= 0 || fresh.unavailableReason) {
      return false;
    }
    if (
      fresh.counts.roll !== cached.counts.roll ||
      fresh.counts.decay !== cached.counts.decay ||
      fresh.counts.cancel !== cached.counts.cancel
    ) {
      return false;
    }
    this.countedRollBatch = fresh;
    this.countedRollBatchReady = true;
    return true;
  }

  getScheduledRollRecommendation(datePropertyName) {
    const recommendation = this.priorityRollRecommendation;
    if (!recommendation) {
      return null;
    }
    if (
      normalizeBulletPropertyName(recommendation.schedulesName) !==
      normalizeBulletPropertyName(datePropertyName)
    ) {
      return null;
    }
    return recommendation;
  }

  getRollPreviewForDateProperty(datePropertyName) {
    if (this.isLinkSession()) {
      return this.getLinkRollPreviewForDateProperty(datePropertyName);
    }
    if (this.isCountedSession()) {
      return this.getCountedRollPreviewForDateProperty(datePropertyName);
    }
    const recommendation = this.getScheduledRollRecommendation(datePropertyName);
    if (!recommendation) {
      return null;
    }
    return buildPriorityRollPreviewModel(recommendation, this.valueBaseDate);
  }

  // Ctrl+R in the schedule stage re-rolls the recommendation's date. Only
  // dated recommendations (roll and decay) have one.
  rerollPriorityRollRecommendation() {
    const cached = this.priorityRollRecommendation;
    if (!cached || !cached.date) {
      return false;
    }
    const fresh = this.computePriorityRollRecommendation();
    if (!fresh || !fresh.date || fresh.kind !== cached.kind) {
      return false;
    }
    this.priorityRollRecommendation = fresh;
    this.priorityRollRecommendationReady = true;
    return true;
  }

  findPriorityPropertyByName(name) {
    const properties =
      this.config && Array.isArray(this.config.properties)
        ? this.config.properties
        : [];
    return (
      properties.find(
        (candidate) =>
          candidate &&
          candidate.values === "priority" &&
          normalizeBulletPropertyName(candidate.name) ===
            normalizeBulletPropertyName(name),
      ) || null
    );
  }

  // Ctrl+Enter takes the previewed recommendation and closes the picker.
  // Before writing, the recommendation is recomputed from the live note: when
  // the kind, the from or to level, or the target line differs from the
  // preview, nothing is written and the card re-renders with the fresh
  // recommendation. Ctrl+Enter honours `opening`, so it never double-fires.
  async applyRecommendedRoll() {
    const cached = this.priorityRollRecommendation;
    if (!cached) {
      return false;
    }
    if (cached.kind === "unavailable") {
      new Notice(cached.reason);
      return false;
    }
    if (this.opening) {
      return false;
    }
    this.opening = true;
    try {
      const fresh = this.computePriorityRollRecommendation();
      if (!fresh || !isSamePriorityRollTarget(cached, fresh)) {
        new Notice("Task changed while the picker was open; nothing was written");
        this.priorityRollRecommendation = fresh || null;
        this.priorityRollRecommendationReady = true;
        this.returnHome({ rebuild: true });
        return false;
      }
      if (cached.kind === "roll" || cached.kind === "decay") {
        return await this.maybeOfferRecommendedWorkLog(cached);
      }
      if (cached.kind === "cancel") {
        return await this.applyRecommendedCancelWrite(cached);
      }
      return false;
    } finally {
      this.opening = false;
    }
  }

  async maybeOfferRecommendedWorkLog(cached) {
    const targets =
      this.cursor && Number.isInteger(this.cursor.line)
        ? [
            {
              line: this.cursor.line,
              rawLine: getEditorLine(this.editor, this.cursor.line) ?? this.lineText,
            },
          ]
        : [];
    const eligible = collectSchedulingWorkLogEligibleOriginalLines(targets);
    if (eligible.size === 0) {
      if (cached.kind === "roll") {
        return await this.applyRecommendedRollWrite(cached);
      }
      return await this.applyRecommendedDecayWrite(cached);
    }
    const scheduleSummary = cached.date
      ? `scheduled → ${normalizeBulletPropertyValue(cached.date)}`
      : "";
    return await this.offerSchedulingWorkLogOrDispatch({
      targets,
      scheduleSummary,
      dispatch: async (summary) => {
        const schedulingWorkLog = summary
          ? {
              summary,
              dateText: formatBulletPropertyDate(
                this.valueBaseDate instanceof Date
                  ? this.valueBaseDate
                  : getLocalDateStart(new Date()),
              ),
            }
          : null;
        if (cached.kind === "roll") {
          return await this.applyRecommendedRollWrite(cached, schedulingWorkLog);
        }
        return await this.applyRecommendedDecayWrite(cached, schedulingWorkLog);
      },
    });
  }

  async applyRecommendedRollWrite(recommendation, schedulingWorkLog = null) {
    const property = this.findPriorityPropertyByName(
      recommendation.priorityName,
    );
    if (!property) {
      new Notice("Task changed while the picker was open; nothing was written");
      return false;
    }
    const content = this.getEditorContent();
    const lines = splitMarkdownContent(content).lines;
    const liveLine = lines[this.cursor.line] || "";
    const liveContext = getProjectNotePropertyContext(content, this.cursor.line);
    const scheduledTarget = resolveBulletPropertyTarget(
      recommendation.schedulesName,
      liveContext,
    );
    const nextHint = planNextPriorityRollHint(property, recommendation);
    const rollOption = {
      kind: "roll",
      fromLevel: getPriorityRollCurrentLabel(recommendation),
      step: recommendation.step,
      limit: recommendation.limit,
      next: nextHint ? nextHint.next : null,
      nextLabel: nextHint ? nextHint.nextLabel : "",
    };
    const levelIndex = normalizePriorityLevelIndex(
      property,
      recommendation.level,
    );
    if (scheduledTarget.kind === "project-frontmatter") {
      const liveScheduled =
        liveContext.frontmatter && liveContext.frontmatter.scheduledDefined
          ? liveContext.frontmatter.scheduledValue
          : "";
      return await this.plugin.setProjectNoteScheduledValue(
        this.editor,
        this.cursor,
        this.filePath,
        this.lineText,
        liveScheduled,
        recommendation.date,
        {
          scheduleLog: buildPriorityRollScheduleLog({
            source: "scheduled",
            level: recommendation.level,
            rolledDays: recommendation.offset,
            from: liveScheduled,
            to: recommendation.date,
          }),
          schedulingWorkLog,
          buildNotice: (outcome) =>
            buildPriorityNoticeModel({
              property,
              level: recommendation.level,
              levelIndex,
              baseDate: this.valueBaseDate,
              scheduledValues: [outcome.scheduled || recommendation.date],
              taskCount: 1,
              scope: "project",
              roll: rollOption,
              outcome: {
                ...outcome,
                scheduleLoggedTaskCount:
                  outcome.scheduleLogOutcome === "added" ||
                  outcome.scheduleLogOutcome === "created"
                    ? 1
                    : 0,
              },
            }),
        },
      );
    }
    const scheduledField = findBulletPropertyField(
      liveLine,
      recommendation.schedulesName,
    );
    return await this.plugin.setBulletPropertyValue(
      this.editor,
      this.cursor,
      recommendation.schedulesName,
      recommendation.date,
      {
        filePath: this.filePath,
        expectedLine: this.lineText,
        scheduleLog: buildPriorityRollScheduleLog({
          source: "scheduled",
          level: recommendation.level,
          rolledDays: recommendation.offset,
          from: scheduledField ? scheduledField.value : "",
          to: recommendation.date,
        }),
        schedulingWorkLog,
        buildNotice: (outcome) =>
          buildPriorityNoticeModel({
            property,
            level: recommendation.level,
            levelIndex,
            baseDate: this.valueBaseDate,
            scheduledValues: [recommendation.date],
            taskCount: 1,
            scope: "task",
            roll: rollOption,
            outcome: {
              blockedTaskCount: outcome.blocked ? 1 : 0,
              recoveryCounts: outcome.recoveryCounts,
              scheduleLoggedTaskCount:
                outcome.scheduleLogOutcome === "added" ||
                outcome.scheduleLogOutcome === "created"
                  ? 1
                  : 0,
              schedulingWorkLogWrittenCount:
                outcome.schedulingWorkLogWrittenCount || 0,
              removedPomodoroLinkCount: outcome.removedPomodoroLinkCount,
              pomodoroPruneFailed: outcome.pomodoroPruneFailed,
            },
          }),
      },
    );
  }

  async applyRecommendedDecayWrite(recommendation, schedulingWorkLog = null) {
    const property = this.findPriorityPropertyByName(
      recommendation.priorityName,
    );
    if (!property || !recommendation.toLevel) {
      new Notice("Task changed while the picker was open; nothing was written");
      return false;
    }
    const nextHint = planNextPriorityRollHint(property, recommendation);
    const liveContext = getProjectNotePropertyContext(
      this.getEditorContent(),
      this.cursor.line,
    );
    return await this.plugin.setBulletPriorityValue(
      this.editor,
      this.cursor,
      this.filePath,
      this.lineText,
      property,
      recommendation.toLevel,
      {
        propertyContext: liveContext,
        baseDate: this.valueBaseDate,
        random: this.priorityRandom,
        precomputedRoll: {
          date: recommendation.date,
          offset: recommendation.offset,
        },
        scheduleReasonOverride: recommendation.reason,
        schedulingWorkLog,
        noticeRoll: {
          kind: "decay",
          fromLevel: getPriorityRollCurrentLabel(recommendation),
          step: null,
          limit: recommendation.limit,
          next: nextHint ? nextHint.next : null,
          nextLabel: nextHint ? nextHint.nextLabel : "",
        },
      },
    );
  }

  async applyRecommendedCancelWrite(recommendation) {
    return await this.plugin.applyTaskCancelFromPicker(this, {
      reason: formatPriorityDecayCancelReason({
        level: recommendation.level,
        streak: recommendation.streak,
      }),
    });
  }

}
// ---- src/400-picker-local-task.js ----
class BulletPropertyPickerLocalTaskMixin extends FilteredPickerModal {
  rerollPriorityDateSuggestion() {
    const rollIndex = this.items.findIndex((item) => item.priorityRoll);
    if (rollIndex === -1) {
      return false;
    }

    const previous = this.items[rollIndex];
    // The pinned row mirrors the card's recommendation for a roll, so
    // Ctrl+R re-rolls both together and keeps the shared date in sync.
    const shared =
      this.selectedPropertyItem && this.selectedPropertyItem.property
        ? this.getScheduledRollRecommendation(
            this.selectedPropertyItem.property.name,
          )
        : null;
    if (
      shared &&
      shared.kind === "roll" &&
      previous.level &&
      shared.level &&
      normalizeBulletPropertyValue(previous.level.label) ===
        normalizeBulletPropertyValue(shared.level.label)
    ) {
      if (!this.rerollPriorityRollRecommendation()) {
        return false;
      }
      const next = this.priorityRollRecommendation;
      const nextItems = [...this.items];
      nextItems[rollIndex] =
        createPriorityRollDateItemFromRecommendation(
          next,
          this.selectedPropertyItem.currentValue || "",
        ) ||
        createPriorityRollDateItem(
          previous.level,
          this.valueBaseDate,
          this.selectedPropertyItem.currentValue || "",
          this.priorityRandom,
        );
      this.applyOptions({ items: nextItems });
      this.selectedIndex = rollIndex;
      if (this.resultsEl) {
        this.renderAll({ clearQuery: true });
      }
      return true;
    }

    const nextItems = [...this.items];
    nextItems[rollIndex] = createPriorityRollDateItem(
      previous.level,
      this.valueBaseDate,
      this.selectedPropertyItem.currentValue || "",
      this.priorityRandom,
    );
    this.applyOptions({ items: nextItems });
    this.selectedIndex = rollIndex;
    if (this.resultsEl) {
      this.renderAll({ clearQuery: true });
    }
    return true;
  }

  clearLocalTaskMarks() {
    if (!this.markedLines) {
      this.markedLines = new Set();
    } else {
      this.markedLines.clear();
    }

    if (!this.taskItemsByLine) {
      this.taskItemsByLine = new Map();
    } else {
      this.taskItemsByLine.clear();
    }
  }

  resetLocalTaskMarks(items) {
    this.markedLines = new Set();
    this.taskItemsByLine = new Map();
    (Array.isArray(items) ? items : []).forEach((item) => {
      const key = bulletPropertyTaskMarkKey(item);
      if (key !== null) {
        this.taskItemsByLine.set(key, item);
      }
    });
  }

  clearPendingBatch() {
    this.pendingBatch = null;
    this.pendingCountedDependency = null;
    this.pendingVaultSingle = null;
    this.pendingVaultCounted = null;
    this.blockIdMode = "single";
    this.blockIdContext = null;
    this.pendingScheduleReason = null;
    this.pendingScheduleReview = null;
    this.pendingCancel = null;
    this.pendingLaneRelease = null;
    this.pendingScheduleWorkLog = null;
  }

  isScheduledValueStage() {
    return Boolean(
      this.stage === "value" &&
        this.selectedPropertyItem &&
        this.selectedPropertyItem.property &&
        this.selectedPropertyItem.property.values === "date" &&
        normalizeBulletPropertyName(this.selectedPropertyItem.property.name) ===
          "scheduled",
    );
  }

  isLocalTaskStage() {
    return (
      this.stage === "value" &&
      this.selectedPropertyItem &&
      this.selectedPropertyItem.property &&
      this.selectedPropertyItem.property.values === "local_task_id"
    );
  }

  getMarkedCount() {
    return this.markedLines ? this.markedLines.size : 0;
  }

  getMarkedTaskItems() {
    if (!this.markedLines || !this.taskItemsByLine) {
      return [];
    }

    return Array.from(this.markedLines)
      .map((line) => this.taskItemsByLine.get(line))
      .filter(Boolean);
  }

  getMarkedTaskDiff() {
    return this.getMarkedTaskItems().reduce(
      (counts, item) => {
        if (item.alreadyLinked) {
          counts.remove += 1;
        } else if (item.needsPromptForAdd) {
          counts.needId += 1;
        } else {
          counts.add += 1;
        }
        return counts;
      },
      { add: 0, needId: 0, remove: 0 },
    );
  }

  getLocalTaskFooterHints() {
    if (this.isCountedSession()) {
      return BULLET_PROPERTY_LOCAL_TASK_HINTS.filter(
        (hint) => !hint.keys.includes("⇥"),
      );
    }
    // The vault-wide Depends on stage footer per the design:
    // `↑↓ navigate · ⇥ mark · ↵ toggle · esc dismiss`, with ↵ reading
    // `apply N` when rows are marked.
    if (this.vaultStage) {
      const marked = this.getMarkedCount();
      return [
        { keys: ["↑", "↓"], label: "navigate" },
        { keys: ["⇥"], label: "mark" },
        { keys: ["↵"], label: marked > 0 ? `apply ${marked}` : "toggle" },
        { keys: ["esc"], label: "dismiss" },
      ];
    }
    const hints = getBulletPropertyLocalTaskHints(this.getMarkedCount() > 0);
    return hints;
  }

  refreshLocalTaskFooter() {
    if (!this.isLocalTaskStage()) {
      return;
    }

    this.footerHints = this.getLocalTaskFooterHints();
    this.renderFooter();
  }

  getLocalTaskSubtitle(visibleItems, allItems) {
    const countText =
      visibleItems.length === allItems.length
        ? ""
        : `Showing ${visibleItems.length} of ${allItems.length} · `;
    if (this.getMarkedCount() === 0) {
      return this.isCountedSession()
        ? `${countText}${this.getTaskSessionSubtitle()} · choose a dependency`
        : `${countText}Choose a task dependency · ⇥ to mark several`;
    }

    const diff = this.getMarkedTaskDiff();
    const parts = [];
    if (diff.add > 0) {
      parts.push(`${diff.add} to add`);
    }
    if (diff.needId > 0) {
      parts.push(`${diff.needId} ${diff.needId === 1 ? "needs ID" : "need IDs"}`);
    }
    if (diff.remove > 0) {
      parts.push(`${diff.remove} to remove`);
    }
    parts.push("↵ to apply");
    return `${countText}${parts.join(" · ")}`;
  }

  toggleHighlightedLocalTaskMark() {
    const item = this.visibleItems[this.selectedIndex];
    if (!item || item.kind !== "local-task") {
      return;
    }
    if (item.disabled) {
      new Notice(item.disabledReason || "That task cannot be linked");
      return;
    }
    const key = bulletPropertyTaskMarkKey(item);
    if (key === null) {
      return;
    }

    // Block-ID-less tasks can now be marked; their block IDs are collected via
    // sequential prompts when the batch is applied.
    if (this.markedLines.has(key)) {
      this.markedLines.delete(key);
    } else {
      this.markedLines.add(key);
    }

    this.refreshLocalTaskFooter();
    this.moveSelection(1);
  }

  // Vault-wide Depends on stage (nav-stage, `docs/task-dependencies.md`
  // §6): the CURRENT / RESULTS / BLOCKED layout over the vault-wide pool.
  // Ranking and guards come from `planDependencyStageView`; the commit
  // paths below write through the single-transaction writer, so one gesture
  // still commits the line, the field, target ids, status effects, legacy
  // folding, and the freshness stamp in one transaction.
  showLocalTaskValueStage(propertyItem) {
    this.stage = "value";
    this.selectedPropertyItem = propertyItem;
    this.pendingTask = null;
    this.clearPendingBatch();
    this.selectedIndex = 0;
    const property = propertyItem.property;
    const dependencyValueSets = this.isCountedSession()
      ? propertyItem.sourceStates.map(
          (state) => new Set(parseLocalTaskIdList(state.value)),
        )
      : [
          new Set(
            parseLocalTaskIdList(this.getCurrentPropertyValue(property.name)),
          ),
        ];
    const parentLines = this.isCountedSession()
      ? this.taskSession.targets.map((target) => target.line)
      : [this.cursor.line];
    // The vault pool is best-effort: anything unexpected falls back to the
    // current-note stage rather than refusing to open.
    let stage = null;
    try {
      stage =
        this.plugin &&
        typeof this.plugin.buildVaultDependencyStage === "function"
          ? this.plugin.buildVaultDependencyStage({
              filePath: this.filePath,
              content: this.getEditorContent(),
              parentLines,
              dependencyValueSets: this.isCountedSession()
                ? dependencyValueSets
                : null,
            })
          : null;
    } catch (_stageError) {
      stage = null;
    }
    this.vaultStage = stage;
    const items = stage
      ? planDependencyStageView({
          current: stage.current,
          candidates: stage.candidates,
          query: "",
          dependent: stage.dependent,
          edges: stage.edges,
          linkedKeys: stage.linkedKeys,
          sourceValueSets: stage.sourceValueSets,
        })
      : createBulletPropertyLocalTaskItems(this.getEditorContent(), {
          excludeLine: this.isCountedSession() ? null : this.cursor.line,
          excludeLines: this.isCountedSession()
            ? new Set(this.taskSession.targets.map((target) => target.line))
            : new Set(),
          dependencyValues: dependencyValueSets[0],
          dependencyValueSets,
          filePath: this.filePath,
        });
    this.resetLocalTaskMarks(items);

    this.applyOptions({
      items,
      title: stage ? stage.title : property.name,
      headerIcon: "link",
      inputLabel: "Filter tasks",
      placeholder: "Filter tasks",
      resultsLabel: "Depends on candidates",
      emptyText: stage ? "No matching tasks in the vault" : "No open tasks in this file",
      footerHints: this.getLocalTaskFooterHints(),
      getSubtitle: (visibleItems, allItems) =>
        this.vaultStage
          ? this.getVaultStageSubtitle(visibleItems, allItems)
          : this.getLocalTaskSubtitle(visibleItems, allItems),
      filterItem: (item, query) => fuzzyMatchesText(item.searchText, query),
      renderItem: (item, rowEl, query) =>
        this.renderTaskValueItem(item, rowEl, query),
      openItem: (item) => this.chooseTaskDependency(item),
    });

    if (this.resultsEl) {
      this.renderAll({ clearQuery: true });
    }
    this.applyTaskCardChrome({ wide: Boolean(this.vaultStage) });
    if (
      stage &&
      !stage.cacheReady &&
      this.plugin &&
      typeof this.plugin.refreshVaultDependencyStage === "function"
    ) {
      void this.plugin.refreshVaultDependencyStage(this, stage);
    }
  }

  // Swap in the vault-scan pool, keeping marks across the refresh: mark keys
  // are stable (`path#line`), so marked rows survive the pool replacement.
  applyVaultStageItems(stage) {
    if (!stage || this.vaultStage !== stage.refreshOf) {
      return;
    }
    const marked = this.markedLines instanceof Set
      ? new Set(this.markedLines)
      : new Set();
    this.vaultStage = stage;
    const items = planDependencyStageView({
      current: stage.current,
      candidates: stage.candidates,
      query: this.getQuery(),
      dependent: stage.dependent,
      edges: stage.edges,
      linkedKeys: stage.linkedKeys,
      sourceValueSets: stage.sourceValueSets,
    });
    this.resetLocalTaskMarks(items);
    for (const key of marked) {
      if (this.taskItemsByLine.has(key)) {
        this.markedLines.add(key);
      }
    }
    this.items = items;
    if (this.resultsEl) {
      this.renderResults();
    }
  }

  getVaultStageSubtitle(visibleItems, allItems) {
    const stage = this.vaultStage;
    if (!stage) {
      return this.getLocalTaskSubtitle(visibleItems, allItems);
    }
    const countText =
      visibleItems.length === allItems.length
        ? ""
        : `Showing ${visibleItems.length} of ${allItems.length} · `;
    const head = `${countText}${stage.current.length} prerequisite${stage.current.length === 1 ? "" : "s"} · ${stage.openCount} open · searching ${stage.poolSize} open tasks`;
    if (this.getMarkedCount() === 0) {
      return `${head} · ⇥ to mark several`;
    }
    const diff = this.getMarkedTaskDiff();
    const parts = [];
    if (diff.add > 0) {
      parts.push(`${diff.add} to add`);
    }
    if (diff.needId > 0) {
      parts.push(`${diff.needId} ${diff.needId === 1 ? "needs ID" : "need IDs"}`);
    }
    if (diff.remove > 0) {
      parts.push(`${diff.remove} to remove`);
    }
    parts.push("↵ to apply");
    return `${head} · ${parts.join(" · ")}`;
  }

  // The note whose content seeds `+ id` suggestions and uniqueness checks:
  // the target's own note for vault-wide rows, else the dependent's note.
  getBlockIdStageContent() {
    const task = this.pendingTask;
    const ownerPath = normalizeVaultRelativePath(this.filePath || "");
    const targetPath = normalizeVaultRelativePath(
      (task && task.path) || ownerPath,
    );
    if (
      targetPath &&
      targetPath !== ownerPath &&
      this.vaultStage &&
      this.vaultStage.files instanceof Map &&
      this.vaultStage.files.has(targetPath)
    ) {
      return String(this.vaultStage.files.get(targetPath) || "");
    }
    return this.getEditorContent();
  }

  // Reserved block IDs chosen earlier in the current batch prompt sequence, so
  // suggestions and validation avoid colliding with them before any write.
  getBlockIdReservedIds() {
    if (this.blockIdMode === "batch" && this.pendingBatch) {
      return this.pendingBatch.reservedIds;
    }
    if (this.blockIdMode === "vault-single" && this.pendingVaultSingle) {
      return this.pendingVaultSingle.reservedIds || new Set();
    }
    if (this.blockIdMode === "vault-counted" && this.pendingVaultCounted) {
      return this.pendingVaultCounted.reservedIds || new Set();
    }
    return new Set();
  }

  // Render the block-ID prompt for one task. Serves both the single-task flow
  // (mode "single") and each step of a batch (mode "batch"), which only differ
  // in the subtitle/footer wording and the reserved-ID set.
  showBlockIdStage(task, options = {}) {
    this.stage = "blockid";
    this.pendingTask = task;
    this.blockIdMode = [
      "batch",
      "counted-source",
      "vault-single",
      "vault-counted",
    ].includes(options.mode)
      ? options.mode
      : "single";
    this.blockIdContext =
      this.blockIdMode === "batch"
        ? {
            position: Math.max(1, Math.floor(options.position || 1)),
            total: Math.max(1, Math.floor(options.total || 1)),
          }
        : null;
    this.clearLocalTaskMarks();
    this.selectedIndex = 0;
    const reservedIds = this.getBlockIdReservedIds();
    // Prefill with the existing `[id::]` value when present (confirmation
    // replaces it with the canonical path-qualified ID); otherwise suggest a slug that avoids existing and
    // reserved block IDs in the target's own note.
    const suggestedId = task.existingIdField
      ? normalizeBulletPropertyValue(task.existingIdField)
      : suggestBlockIdFromTask(task.displayText, this.getBlockIdStageContent(), {
          reservedIds,
        });
    const isLast =
      this.blockIdMode !== "batch" ||
      this.blockIdContext.position >= this.blockIdContext.total;

    this.applyOptions({
      items: [],
      title: "New block ID",
      headerIcon: "hash",
      inputLabel: "Block ID",
      placeholder: "Block ID - letters, numbers, hyphens",
      resultsLabel: "Block ID preview",
      emptyText: "Type a block ID",
      footerHints: getBulletPropertyBlockIdHints({
        batch: this.blockIdMode === "batch",
        last: isLast,
        counted: this.blockIdMode === "counted-source",
      }),
      getSubtitle: () =>
        this.blockIdMode === "batch"
          ? `Block ID ${this.blockIdContext.position} of ${this.blockIdContext.total} · line ${task.line + 1}`
          : this.blockIdMode === "counted-source"
            ? `${this.getTaskSessionSubtitle()} · create an ID for dependency on line ${task.line + 1}`
            : `Create an ID for line ${task.line + 1}`,
      filterItem: () => true,
      renderItem: (item, rowEl, query) =>
        this.renderBlockIdPreviewItem(item, rowEl, query),
      openItem: (item) => this.confirmBlockId(item),
    });

    if (this.resultsEl) {
      this.renderAll({ clearQuery: true });
      if (this.inputEl) {
        this.inputEl.value = suggestedId;
        this.inputEl.select();
      }
      this.renderResults();
    }
  }

}
// ---- src/410-picker-filter-and-render.js ----
class BulletPropertyPickerFilterRenderMixin extends FilteredPickerModal {
  getFilteredItems() {
    // Ranked, section-ordered rows for the vault-wide Depends on stage. The
    // sync pool never reads from disk; the one-time vault scan (when the
    // Tasks cache is not Warm) refreshes through `applyVaultStageItems`.
    if (this.isLocalTaskStage() && this.vaultStage) {
      try {
        return planDependencyStageView({
          current: this.vaultStage.current,
          candidates: this.vaultStage.candidates,
          query: this.getQuery(),
          dependent: this.vaultStage.dependent,
          edges: this.vaultStage.edges,
          linkedKeys: this.vaultStage.linkedKeys,
          sourceValueSets: this.vaultStage.sourceValueSets,
        });
      } catch (_error) {
        return super.getFilteredItems();
      }
    }
    if (this.stage === "schedule-review") {
      const reason = normalizeScheduleReasonText(this.getScheduleReviewReasonText());
      const summary = normalizeSchedulingWorkSummary(
        this.getScheduleReviewSummaryText(),
      );
      const pending = this.pendingScheduleReview;
      const parentExists = Boolean(
        findScheduleLogParent(this.getEditorContent(), this.cursor.line),
      );
      const fallback = reason.empty && this.willLogWithoutReason();
      return [
        Object.freeze({
          kind: "schedule-review-preview",
          reason: reason.reason,
          reasonEmpty: reason.empty,
          reasonHasInlineField: reason.hasInlineField,
          reasonFallback: fallback,
          summary,
          summaryEmpty: !summary,
          summaryHasInlineField: /::/.test(summary),
          parentExists,
          counted: this.isCountedSession() || this.isLinkSession(),
          eligibleCount: pending ? pending.eligibleCount : 0,
          searchText: reason.reason,
        }),
      ];
    }

    if (this.stage === "schedule-work-log") {
      const normalized = normalizeScheduleReasonText(this.getRawQuery());
      return [
        Object.freeze({
          kind: "schedule-work-log-preview",
          ...normalized,
          counted: this.isCountedSession() || this.isLinkSession(),
          searchText: normalized.reason,
        }),
      ];
    }

    if (this.stage === "lane-release-reason") {
      const normalized = normalizeScheduleReasonText(this.getRawQuery());
      const facts = this.getLaneReleaseReasonFacts();
      return [
        Object.freeze({
          kind: "lane-release-reason-preview",
          ...normalized,
          ...facts,
          counted: this.isCountedSession() || this.isLinkSession(),
          searchText: normalized.reason,
        }),
      ];
    }

    if (this.stage === "cancel-reason") {
      const normalized = normalizeScheduleReasonText(this.getRawQuery());
      const facts = this.getCancelReasonFacts();
      return [
        Object.freeze({
          kind: "cancel-reason-preview",
          ...normalized,
          ...facts,
          counted: this.isCountedSession() || this.isLinkSession(),
          fallback: normalized.empty && facts.anyLog,
          searchText: normalized.reason,
        }),
      ];
    }

    if (this.stage === "blockid") {
      // Uniqueness is checked against the target's note: cross-note `+ id`
      // rows prompt for an id that must be fresh in that note, not this one.
      const validation = validateBlockIdCandidate(
        this.getRawQuery(),
        this.getBlockIdStageContent(),
        { reservedIds: this.getBlockIdReservedIds() },
      );
      return [
        Object.freeze({
          kind: "blockid-preview",
          ...validation,
          task: this.pendingTask,
          searchText: validation.id,
        }),
      ];
    }

    const items = super.getFilteredItems();
    if (
      this.stage !== "value" ||
      !this.selectedPropertyItem ||
      this.selectedPropertyItem.property.values !== "date"
    ) {
      return items;
    }

    const currentValue = this.selectedPropertyItem.currentValue || "";
    const isScheduledProperty =
      normalizeBulletPropertyName(this.selectedPropertyItem.property.name) ===
      "scheduled";
    if (isScheduledProperty) {
      const typedItem = createTypedScheduleValueItem(
        resolveTypedSchedule(this.getRawQuery(), this.valueBaseDate),
        this.valueBaseDate,
        currentValue,
      );
      if (!typedItem) {
        return items;
      }
      return [
        typedItem,
        ...items.filter(
          (item) => !typedItem.value || item.value !== typedItem.value,
        ),
      ];
    }

    const typedItem = createBulletPropertyTypedDateItem(
      this.getRawQuery(),
      this.valueBaseDate,
      currentValue,
    );
    if (!typedItem) {
      return items;
    }

    return [
      typedItem,
      ...items.filter((item) => item.value !== typedItem.value),
    ];
  }

  // The base class's input listener only calls renderResults(), so this is
  // what flips the reason-stage footer hint (Skip reason ⇄ Log reason) live
  // as the user types, mirroring refreshLocalTaskFooter.
  renderResults() {
    super.renderResults();
    if (this.stage === "cancel-reason") {
      const item = (this.visibleItems || [])[0];
      const pending = this.pendingCancel;
      this.footerHints = getCancelReasonHints({
        empty: Boolean(item && item.empty),
        fallback: Boolean(item && item.fallback),
        count: pending ? pending.openCount : 1,
      });
      this.renderFooter();
    }
    if (this.stage === "lane-release-reason") {
      const item = (this.visibleItems || [])[0];
      this.footerHints = getLaneReleaseReasonHints({
        empty: Boolean(item && item.empty),
      });
      this.renderFooter();
    }
    if (this.stage === "schedule-work-log") {
      const item = (this.visibleItems || [])[0];
      this.footerHints = getSchedulingWorkLogHints({
        empty: Boolean(item && item.empty),
      });
      this.renderFooter();
    }
    if (this.stage === "schedule-review") {
      const item = (this.visibleItems || [])[0];
      const pending = this.pendingScheduleReview;
      this.footerHints = getScheduleReviewHints({
        empty: Boolean(item && item.reasonEmpty && item.summaryEmpty),
        hasWorkLog: Boolean(pending && pending.needsWorkLog),
      });
      this.renderFooter();
    }
  }

  renderValueItem(item, rowEl, query) {
    addElementClasses(
      rowEl,
      "bob-cnp-property-value-row",
      item.priorityLevel ? "bob-cnp-priority-value-row" : "",
      item.priorityRoll ? "is-priority-roll" : "",
      item.current ? "is-current" : "",
      item.dynamic ? "is-dynamic" : "",
      item.typedSchedule && item.valid === false ? "is-invalid" : "",
    );

    const rowIcon = rowEl.createDiv({ cls: "bob-cnp-row-icon" });
    applyIcon(
      rowIcon,
      item.priorityRoll
        ? "dices"
        : item.typedSchedule && item.valid === false
          ? "alert-triangle"
          : item.current
            ? "check-circle-2"
            : item.dynamic
              ? "calendar-plus"
              : "circle",
    );

    const textEl = rowEl.createDiv({ cls: "bob-cnp-row-text" });
    const titleEl = textEl.createDiv({ cls: "bob-cnp-row-title" });
    appendHighlighted(titleEl, item.label, query);

    if (item.detail) {
      const detailEl = textEl.createDiv({ cls: "bob-cnp-row-path" });
      appendHighlighted(detailEl, item.detail, query);
    }

    if (item.current) {
      rowEl.createDiv({
        cls: "bob-cnp-pill bob-cnp-property-pill",
        text: "current",
      });
    }
    if (item.priorityLevel) {
      rowEl.createDiv({
        cls: "bob-cnp-pill bob-cnp-property-pill",
        text: `${item.priorityLevel.minDays}–${item.priorityLevel.maxDays}d`,
      });
    }
    if (item.priorityRoll) {
      rowEl.createDiv({
        cls: "bob-cnp-pill bob-cnp-property-pill",
        text: item.level.label,
      });
    }
  }

  renderTaskValueItem(item, rowEl, query) {
    // CURRENT / RESULTS / BLOCKED section headers for the vault-wide stage
    // (`docs/task-dependencies.md` §6).
    if (item && item.stageSection && item.firstInSection) {
      const sectionNames = { current: "CURRENT", results: "RESULTS", blocked: "BLOCKED" };
      rowEl.createDiv({
        cls: "bob-cnp-section-header",
        text: sectionNames[item.stageSection] || item.stageSection,
      });
    }
    // The ~60-row cap hint row: muted, non-interactive, styled on its own.
    if (item && item.kind === "stage-more") {
      addElementClasses(rowEl, "bob-cnp-task-value-row", "bob-cnp-dep-row", "bob-cnp-dep-more", "is-disabled");
      rowEl.setAttribute("aria-disabled", "true");
      const textEl = rowEl.createDiv({ cls: "bob-cnp-row-text bob-cnp-dep-text" });
      const titleEl = textEl.createDiv({ cls: "bob-cnp-row-title" });
      titleEl.setText(item.displayText || "type to search more");
      return;
    }
    const markKey = bulletPropertyTaskMarkKey(item);
    const marked =
      this.markedLines instanceof Set &&
      markKey !== null &&
      this.markedLines.has(markKey);
    const markedRemove = marked && item.alreadyLinked;
    const markedNeedsId = marked && !item.alreadyLinked && item.needsPromptForAdd;
    const markedAdd = marked && !item.alreadyLinked && !item.needsPromptForAdd;
    addElementClasses(
      rowEl,
      "bob-cnp-task-value-row",
      "bob-cnp-dep-row",
      item.hidden ? "bob-cnp-dep-hidden" : "",
      item.stageSection === "blocked" ? "bob-cnp-dep-blocked" : "",
      item.alreadyLinked ? "is-linked" : "",
      item.linkState === "mixed" ? "is-mixed" : "",
      item.needsBlockIdPrompt ? "is-create" : "is-existing",
      item.disabled ? "is-disabled" : "",
      item.stageSection ? `is-stage-${item.stageSection}` : "",
      marked ? "is-marked" : "",
      markedRemove ? "is-marked-remove" : "",
      markedAdd ? "is-marked-add" : "",
      markedNeedsId ? "is-marked-id-needed" : "",
    );
    if (item.disabled) {
      rowEl.setAttribute("aria-disabled", "true");
    }
    // Muted `#hide` rows carry the design tooltip; disabled rows expose
    // the short reason plus the cycle path when present.
    if (item.hidden) {
      rowEl.setAttribute("title", "#hide · muted · ranked last");
    }

    const markEl = rowEl.createDiv({
      cls: marked ? "bob-cnp-mark is-marked" : "bob-cnp-mark",
      attr: {
        "aria-hidden": "true",
      },
    });
    if (marked) {
      markEl.setText("✓");
    }

    rowEl.createDiv({
      cls: `bob-cnp-status-pill bob-cnp-dep-status is-${taskStatusClass(item.status)}`,
      text: taskStatusLabel(item.status),
    });

    const textEl = rowEl.createDiv({ cls: "bob-cnp-row-text bob-cnp-dep-text" });
    const titleEl = textEl.createDiv({ cls: "bob-cnp-row-title" });
    appendHighlighted(titleEl, item.displayText, query);

    const metaEl = textEl.createDiv({ cls: "bob-cnp-row-meta bob-cnp-dep-meta" });
    // Cross-note rows name their note (`↗ note`); the badge below always
    // shows the block id, never the path-encoded id (§6.3).
    const metaBits = [];
    if (item.noteLabel) {
      metaBits.push(`↗ ${item.noteLabel}`);
    }
    if (Number.isInteger(item.line) && item.line >= 0) {
      metaBits.push(`Line ${item.line + 1}`);
    }
    if (item.cycle && item.cycle.length > 0) {
      metaBits.push(`⟲ ${item.cycle.length - 1} back-link${item.cycle.length - 1 === 1 ? "" : "s"}`);
    }
    metaEl.createSpan({
      text:
        metaBits.join(" · ") ||
        (item.missing ? "missing link · removable" : ""),
    });
    if (item.disabled && item.disabledReason) {
      const guardEl = metaEl.createSpan({
        cls: "bob-cnp-row-guard bob-cnp-dep-guard",
        text: item.disabledReason,
      });
      // Disabled rows expose the cycle path in the tooltip when present:
      // task descriptions joined by `→`, with raw keys only where no row
      // names the key.
      if (item.cycle && item.cycle.length > 0 && guardEl) {
        try {
          const path =
            item.cycleLabels && item.cycleLabels.length === item.cycle.length
              ? item.cycleLabels
              : item.cycle;
          guardEl.setAttribute("title", path.join(" → "));
        } catch (_guardTitleError) {
          // Best-effort tooltip only.
        }
      }
    }

    const badgeClasses = [
      "bob-cnp-task-badge",
      markedRemove
        ? "is-marked-remove"
        : markedNeedsId
          ? "is-marked-id-needed"
          : markedAdd
            ? "is-marked-add"
            : item.alreadyLinked
              ? "is-linked"
              : item.needsBlockIdPrompt
                ? "is-create"
                : "is-existing",
    ];
    const badgeEl = rowEl.createDiv({ cls: `bob-cnp-dep-badge ${badgeClasses.join(" ")}` });
    if (markedRemove) {
      badgeEl.createSpan({
        cls: "bob-cnp-task-badge-action",
        text: "− remove",
      });
    } else if (markedNeedsId) {
      badgeEl.createSpan({ cls: "bob-cnp-task-badge-action", text: "＋ id" });
    } else if (markedAdd) {
      badgeEl.createSpan({ cls: "bob-cnp-task-badge-action", text: "＋ add" });
    } else if (
      item.stageSection === "blocked" &&
      (typeof item.blockedBadge === "string" || Number.isInteger(item.waitsOn))
    ) {
      // BLOCKED rows name what blocks them: `🔒 waits on N` (N >= 1), else
      // `🔒 scheduled YYYY-MM-DD`, else `🔒 blocked`.
      badgeEl.createSpan({
        cls: "bob-cnp-task-badge-action bob-cnp-dep-waits",
        text:
          typeof item.blockedBadge === "string"
            ? item.blockedBadge
            : `🔒 waits on ${item.waitsOn}`,
      });
    } else if (item.alreadyLinked) {
      badgeEl.createSpan({
        cls: "bob-cnp-task-badge-action",
        text: "−",
      });
    } else if (item.linkState === "mixed") {
      badgeEl.createSpan({
        cls: "bob-cnp-task-badge-action",
        text: `${item.linkedSourceCount}/${item.sourceCount} depend`,
      });
    } else if (item.needsBlockIdPrompt) {
      // Unmarked, not yet linked, and missing a trailing block ID: pressing
      // Enter prompts for one before linking.
      badgeEl.createSpan({ cls: "bob-cnp-task-badge-action", text: "＋ id" });
    } else {
      badgeEl.createSpan({ cls: "bob-cnp-task-badge-action", text: "＋" });
    }
  }

  renderBlockIdPreviewItem(item, rowEl, query) {
    addElementClasses(
      rowEl,
      "bob-cnp-blockid-preview-row",
      `is-${item.state}`,
    );

    const rowIcon = rowEl.createDiv({ cls: "bob-cnp-row-icon" });
    applyIcon(rowIcon, item.valid ? "check-circle-2" : "alert-triangle");

    const textEl = rowEl.createDiv({ cls: "bob-cnp-row-text" });
    const titleEl = textEl.createDiv({ cls: "bob-cnp-row-title" });
    appendHighlighted(titleEl, item.id || "(type an id)", query);

    textEl.createDiv({
      cls: "bob-cnp-row-meta",
      text: item.message,
    });

    const taskTitle =
      item.task && item.task.displayText
        ? item.task.displayText
        : "(untitled task)";
    const existingIdField =
      item.task && item.task.existingIdField
        ? normalizeBulletPropertyValue(item.task.existingIdField)
        : "";
    const idDisplay = item.id || "id";
    // Confirmation appends the trailing `^id` block target and replaces an
    // existing dependency value with the canonical path-qualified ID.
    const previewText = existingIdField
      ? `Appends ^${idDisplay}; replaces [id:: ${existingIdField}] with the canonical ID on: ${taskTitle}`
      : `Adds [id:: ${idDisplay}] ^${idDisplay} to: ${taskTitle}`;
    textEl.createDiv({
      cls: "bob-cnp-blockid-preview",
      text: previewText,
    });
  }

  async chooseTaskDependency(item) {
    if (!this.selectedPropertyItem) {
      return false;
    }

    if (this.isCountedSession()) {
      return this.chooseCountedTaskDependency(item);
    }

    if (!item) {
      return false;
    }

    if (this.getMarkedCount() > 0) {
      return this.commitMarkedDependencies();
    }

    // Guarded rows are disabled with their reason; removing a CURRENT link
    // is always allowed, so CURRENT rows are never disabled.
    if (item.disabled) {
      new Notice(item.disabledReason || "That task cannot be linked");
      return false;
    }

    const parentValidation = validateDependencyParentForEditor(
      this.editor,
      this.cursor,
      this.lineText,
    );
    if (!parentValidation.valid) {
      new Notice(parentValidation.message);
      return false;
    }

    // CURRENT rows toggle off: ↵ removes that prerequisite. Cross-note rows
    // commit through the vault path with a stale re-read.
    if (item.stageSection === "current" && item.alreadyLinked) {
      return this.removeSingleDependency(item);
    }
    if (
      item.path &&
      normalizeVaultRelativePath(item.path) !==
        normalizeVaultRelativePath(this.filePath)
    ) {
      return this.chooseVaultTaskDependency(item);
    }

    // Single-select path. Re-read the target so a stale row never writes:
    // refuse with `changed — reopen`, then reopen the stage fresh (§6.4).
    const targetLine = getEditorLine(this.editor, item.line);
    if (targetLine !== item.rawLine) {
      return this.refuseDependencyStale();
    }
    if (!isObsidianTaskAtLine(this.getEditorContent(), item.line)) {
      return this.refuseDependencyStale();
    }

    // A missing trailing block ID always prompts, even when an `[id:: value]`
    // is already present; confirmation replaces it with the canonical ID.
    const resolved = resolveTargetTaskIdentity(targetLine, {
      promptWhenBlockIdMissing: true,
      filePath: this.filePath,
    });
    if (resolved.needsBlockIdPrompt) {
      this.showBlockIdStage(item, { mode: "single" });
      return false;
    }

    if (!resolved.value) {
      new Notice("Could not identify task");
      return false;
    }

    // An existing valid `[id::]` is never rewritten (§3): the missing-id
    // edit folds into the writer's one transaction below (one Ctrl+Z). The
    // planner resolves the kept id for the field.
    const missingIdEdits = resolved.targetEdits.filter(
      (edit) => edit.kind === "add-id-field",
    );
    const pendingTargetLine =
      missingIdEdits.length > 0
        ? {
            line: item.line,
            expected: targetLine,
            text: missingIdEdits[missingIdEdits.length - 1].line,
          }
        : null;

    return this.plugin.setLocalTaskDependency(
      this.editor,
      this.cursor,
      this.selectedPropertyItem.property.name,
      resolved.value,
      {
        linkBlockId: resolved.linkBlockId,
        filePath: this.filePath,
        pendingTargetLine,
      },
    );
  }

}
// ---- src/420-picker-counted-dependency.js ----
class BulletPropertyPickerCountedDependencyMixin extends FilteredPickerModal {
  chooseCountedTaskDependency(item) {
    if (!item) {
      return false;
    }
    if (item.disabled) {
      new Notice(item.disabledReason || "That task cannot be linked");
      return false;
    }
    const sessionValidation = validateCountedTaskSession(
      this.getEditorContent(),
      this.taskSession,
    );
    if (!sessionValidation.valid) {
      new Notice(`${sessionValidation.error}; no tasks were updated`);
      return false;
    }
    // CURRENT rows carry no target line, so they toggle off through the
    // counted remover below instead of the line-pinned paths.
    if (item.stageSection === "current" && item.alreadyLinked) {
      return this.removeCountedDependency(item);
    }
    // Vault-wide rows plan every source on one working copy and commit once
    // through the writer; same-note rows keep the counted single-transaction
    // planner.
    if (
      item.stageSection &&
      item.path &&
      normalizeVaultRelativePath(item.path) !==
        normalizeVaultRelativePath(this.filePath)
    ) {
      return this.chooseVaultCountedDependency(item);
    }
    const targetLine = getEditorLine(this.editor, item.line);
    if (
      targetLine !== item.rawLine ||
      !isObsidianTaskAtLine(this.getEditorContent(), item.line)
    ) {
      return this.refuseDependencyStale();
    }

    const resolved = resolveTargetTaskIdentity(targetLine, {
      promptWhenBlockIdMissing: true,
      filePath: this.filePath,
    });
    if (resolved.needsBlockIdPrompt) {
      this.pendingCountedDependency = item;
      this.showBlockIdStage(item, { mode: "counted-source" });
      return false;
    }

    return this.plugin.applyCountedLocalTaskDependency(
      this.editor,
      this.cursor,
      this.filePath,
      this.taskSession,
      item,
    );
  }

  // Counted (`N<Ctrl+Shift+P>`) vault-wide commits: the existing
  // add-to-all / remove-from-all semantics, one writer transaction per
  // source task, with the target re-read fresh. Rows without a block id
  // detour through one `+ id` prompt first.
  async chooseVaultCountedDependency(item) {
    const sessionValidation = validateCountedTaskSession(
      this.getEditorContent(),
      this.taskSession,
    );
    if (!sessionValidation.valid) {
      new Notice(`${sessionValidation.error}; no tasks were updated`);
      return false;
    }
    const ownerPath = normalizeVaultRelativePath(this.filePath || "");
    const snapshot = {
      markKey: bulletPropertyTaskMarkKey(item),
      path: normalizeVaultRelativePath(item.path || ownerPath),
      line: item.line,
      rawLine: item.rawLine,
      displayText: item.displayText,
      existingIdField: item.existingIdField || null,
      blockId: item.blockId || item.existingBlockId || null,
    };
    if (item.alreadyLinked) {
      return this.applyVaultCountedDependencyRef(
        { ...snapshot, remove: true },
      );
    }
    if (!snapshot.blockId) {
      this.pendingVaultCounted = {
        snapshot,
        session: this.taskSession,
        reservedIds: new Set(),
      };
      this.showBlockIdStage(snapshot, { mode: "vault-counted" });
      return false;
    }
    return this.applyVaultCountedDependencyRef(snapshot);
  }

  // Counted CURRENT toggle-off: ↵ on a fully linked CURRENT row removes
  // that prerequisite from every source task. A same-note target that still
  // resolves keeps the counted one-transaction planner; anything else
  // (cross-note, or a target whose note is gone) plans every source on one
  // working copy bottom-up and commits once, so a missing target is always
  // removable.
  async removeCountedDependency(item) {
    const sessionValidation = validateCountedTaskSession(
      this.getEditorContent(),
      this.taskSession,
    );
    if (!sessionValidation.valid) {
      new Notice(`${sessionValidation.error}; no tasks were updated`);
      return false;
    }
    const ownerPath = normalizeVaultRelativePath(this.filePath || "");
    const blockId = normalizeBulletPropertyValue(
      item.blockId || item.existingBlockId || "",
    );
    const targetPath = normalizeVaultRelativePath(
      item.path || ownerPath,
    );
    if (!ownerPath || !blockId) {
      new Notice("⛓ Could not remove dependency (missing link target)");
      return false;
    }
    // A CURRENT row may be linked on only some sources: the counted
    // one-transaction planner toggles, so it runs only when every source
    // carries the link. Otherwise every linked source is planned onto one
    // working copy and removed in the single commit below.
    if (targetPath === ownerPath) {
      const content = String(this.editor.getValue() || "");
      const contentLines = content.split(/\r?\n/);
      const found = findTaskLineByTrailingBlockId(contentLines, blockId);
      if (found !== null && isObsidianTaskAtLine(content, found)) {
        const targetText = String(contentLines[found] || "");
        const targetIdField = findBulletPropertyField(targetText, "id");
        const aliases = new Set(
          [
            dependencyTargetId(targetText, ownerPath, blockId),
            targetIdField
              ? normalizeBulletPropertyValue(targetIdField.value)
              : "",
            blockId,
          ]
            .map(normalizeBulletPropertyValue)
            .filter(Boolean),
        );
        const everyLinked = (this.taskSession.targets || []).every(
          (target) => {
            const field = findBulletPropertyField(
              String(target.rawLine || ""),
              "dependsOn",
            );
            const values = new Set(
              field ? parseLocalTaskIdList(field.value) : [],
            );
            return [...aliases].some((alias) => values.has(alias));
          },
        );
        if (everyLinked) {
          return this.plugin.applyCountedLocalTaskDependency(
            this.editor,
            this.cursor,
            this.filePath,
            this.taskSession,
            {
              line: found,
              rawLine: contentLines[found],
              displayText: item.displayText,
              existingIdField: item.existingIdField || null,
              existingBlockId: blockId,
            },
          );
        }
      }
    }
    // One gesture plans every source on one working copy bottom-up,
    // refuses before any write when any source fails to plan, then commits
    // once (one Ctrl+Z) with one summary notice — the same shape as the
    // counted add above. The notice counts only sources that changed.
    const ordered = (this.taskSession.targets || [])
      .slice()
      .sort((first, second) => second.line - first.line);
    const originalContent = String(this.editor.getValue() || "");
    const removeRef = { path: targetPath, blockId };
    const resolveLinkpath =
      this.plugin && typeof this.plugin.dependencyLinkpathResolver === "function"
        ? this.plugin.dependencyLinkpathResolver()
        : null;
    const vaultFiles =
      this.plugin && typeof this.plugin.readDependencyVaultFileList === "function"
        ? this.plugin.readDependencyVaultFileList()
        : null;
    const registry = this.plugin
      ? await readTasksStatusRegistry(this.plugin.app)
      : null;
    const baseFiles = new Map();
    baseFiles.set(ownerPath, originalContent);
    {
      const wanted = new Set([targetPath]);
      for (const target of ordered) {
        if (!Number.isInteger(target.line)) {
          continue;
        }
        const collection = collectDependencyNavigationBullets(originalContent, target.line);
        if (collection.reason) {
          continue;
        }
        for (const entry of collection.targets) {
          const entryPath = dependencyPathForLinkNote(
            entry.note,
            ownerPath,
            resolveLinkpath,
          );
          if (entryPath) {
            wanted.add(entryPath);
          }
        }
      }
      for (const wantedPath of wanted) {
        if (baseFiles.has(wantedPath)) {
          continue;
        }
        const loaded = await this.plugin.readDependencyNoteContent(
          wantedPath,
          null,
          ownerPath,
        );
        if (loaded !== null) {
          baseFiles.set(wantedPath, String(loaded));
        }
      }
    }
    const removeNeedsSnapshot = String(originalContent || "")
      .split(/\r?\n/)
      .some((line, index) => {
        if (!ordered.some((target) => target.line === index)) {
          return false;
        }
        return getObsidianTaskCheckboxStatus(String(line || "")) === "?";
      });
    const baseVaultContents =
      this.plugin && removeNeedsSnapshot
        ? await this.plugin.readDependencyRecoveryVaultContents(ownerPath, originalContent)
        : null;
    const today = new Date();
    let working = originalContent;
    let removed = 0;
    const preparations = new Map();
    for (const target of ordered) {
      if (!Number.isInteger(target.line)) {
        new Notice(
          `⛓ Could not update the counted task (invalid line); no tasks were updated`,
        );
        return false;
      }
      const planFiles = new Map(baseFiles);
      planFiles.set(ownerPath, working);
      const plan = planDependencyEdit({
        content: working,
        parentLine: target.line,
        parentPath: ownerPath,
        add: [],
        remove: [removeRef],
        files: planFiles,
        vaultFiles,
        resolveLinkpath,
        recovery: { registry, today, vaultContents: baseVaultContents },
      });
      if (!plan.ok) {
        new Notice(
          plan.reason === "in-blockquote"
            ? "⛓ Dependencies can't be edited inside a blockquote; no tasks were updated"
            : `⛓ Could not update the task on line ${target.line + 1} (${plan.reason}); no tasks were updated`,
        );
        return false;
      }
      for (const preparation of plan.preparations || []) {
        const key = `${preparation.path}\x00${preparation.line}\x00${preparation.from}\x00${preparation.text}`;
        if (!preparations.has(key)) {
          preparations.set(key, preparation);
        }
      }
      if (plan.changed) {
        removed += 1;
        let nextWorking = plan.nextContent;
        if (this.plugin && typeof this.plugin.stampDependencyParentLine === "function") {
          nextWorking = this.plugin.stampDependencyParentLine(nextWorking, target.line);
        }
        working = nextWorking;
      }
    }
    for (const preparation of preparations.values()) {
      let result = null;
      try {
        result = await this.plugin.prepareDependencyTargetNote(preparation.path, preparation);
      } catch (_error) {
        result = { ok: false, reason: "target-preparation-threw" };
      }
      if (!result || result.ok !== true) {
        new Notice(
          `⛓ Could not prepare the dependency removal (${(result && result.reason) || "target-preparation-failed"}); no tasks were updated`,
        );
        return false;
      }
    }
    if (working === originalContent) {
      new Notice("No dependencies changed");
      return false;
    }
    // A concurrent edit refuses with `changed — reopen` and reopens the
    // stage fresh, like every other stale stage path (§6.4).
    if (String(this.editor.getValue() || "") !== originalContent) {
      return this.refuseDependencyStale();
    }
    if (!applyEditorContentTransaction(this.editor, originalContent, working)) {
      new Notice("Could not update counted dependencies; no tasks were updated");
      return false;
    }
    new Notice(
      `⛓ Removed from ${removed} task${removed === 1 ? "" : "s"}`,
    );
    return true;
  }

  // Apply one vault-wide counted toggle: linked everywhere removes from
  // every source, otherwise unlinked sources gain the link. One gesture
  // plans every source on one working copy bottom-up, refuses before any
  // write when any source fails to plan, then commits once; the notice
  // counts only sources that actually changed.
  async applyVaultCountedDependencyRef(snapshot) {
    const sessionValidation = validateCountedTaskSession(
      this.getEditorContent(),
      this.taskSession,
    );
    if (!sessionValidation.valid) {
      new Notice(`${sessionValidation.error}; no tasks were updated`);
      return false;
    }
    const ownerPath = normalizeVaultRelativePath(this.filePath || "");
    const targetPath = normalizeVaultRelativePath(
      snapshot.path || ownerPath,
    );
    const resolveLinkpath =
      this.plugin && typeof this.plugin.dependencyLinkpathResolver === "function"
        ? this.plugin.dependencyLinkpathResolver()
        : null;
    const files = await this.readVaultStageFiles([targetPath]);
    if (!files) {
      return false;
    }
    // The old per-source writer also loaded the notes behind each source's
    // existing links: a source with an unloaded cross-note link and a
    // missing or out-of-sync field must still add, not refuse
    // `target-not-found`. Best-effort (an unreadable note stays verbatim in
    // the planner), so one missing note never blocks the gesture.
    {
      const ownerContent = String(this.editor.getValue() || "");
      const wanted = new Set();
      for (const target of this.taskSession.targets || []) {
        if (!Number.isInteger(target.line)) {
          continue;
        }
        const collection = collectDependencyNavigationBullets(ownerContent, target.line);
        if (collection.reason) {
          continue;
        }
        for (const entry of collection.targets) {
          const entryPath = dependencyPathForLinkNote(
            entry.note,
            ownerPath,
            resolveLinkpath,
          );
          if (entryPath && !files.has(entryPath)) {
            wanted.add(entryPath);
          }
        }
      }
      for (const wantedPath of wanted) {
        const buffered =
          this.plugin && typeof this.plugin.readOpenBufferContent === "function"
            ? this.plugin.readOpenBufferContent(wantedPath)
            : null;
        if (buffered !== null) {
          files.set(wantedPath, buffered);
          continue;
        }
        if (
          this.vaultStage &&
          this.vaultStage.files instanceof Map &&
          this.vaultStage.files.has(wantedPath)
        ) {
          files.set(wantedPath, String(this.vaultStage.files.get(wantedPath) || ""));
          continue;
        }
        const loaded = await this.plugin.readDependencyNoteContent(
          wantedPath,
          null,
          ownerPath,
        );
        if (loaded !== null) {
          files.set(wantedPath, String(loaded));
        }
      }
    }
    const counters = { stale: 0, other: 0 };
    if (!snapshot.remove) {
      const addition = this.collectVaultAddition(snapshot, files, counters);
      if (!addition) {
        // A changed target refuses with `changed — reopen` and reopens the
        // stage fresh, exactly like the same-note `executeDependencyBatch`
        // (§6.4); anything else keeps the specific notice.
        if (counters.stale > 0) {
          return this.refuseDependencyStale();
        }
        new Notice("Could not identify the selected dependency");
        return false;
      }
      snapshot = { ...snapshot, blockId: addition.blockId };
    }
    const ref = { path: targetPath, blockId: snapshot.blockId };
    // One gesture commits every source in one editor transaction (one
    // Ctrl+Z): plan every source on one working copy bottom-up, refuse
    // before any write when any source fails to plan, then commit once.
    const orderedSources = (this.taskSession.targets || [])
      .slice()
      .sort((first, second) => second.line - first.line);
    const originalContent = String(this.editor.getValue() || "");
    let working = originalContent;
    let changedSources = 0;
    const preparations = new Map();
    const vaultFiles =
      this.plugin && typeof this.plugin.readDependencyVaultFileList === "function"
        ? this.plugin.readDependencyVaultFileList()
        : null;
    const countedRegistry = this.plugin
      ? await readTasksStatusRegistry(this.plugin.app)
      : null;
    const countedNeedsRecovery =
      Boolean(snapshot.remove) &&
      String(originalContent || "")
        .split(/\r?\n/)
        .some((line, index) => {
          if (!orderedSources.some((target) => target.line === index)) {
            return false;
          }
          return getObsidianTaskCheckboxStatus(String(line || "")) === "?";
        });
    const countedVaultContents =
      this.plugin && countedNeedsRecovery
        ? await this.plugin.readDependencyRecoveryVaultContents(ownerPath, originalContent)
        : null;
    for (const target of orderedSources) {
      const targetContent = files.get(targetPath);
      const planFiles = new Map();
      planFiles.set(ownerPath, working);
      if (targetPath !== ownerPath && targetContent !== undefined) {
        planFiles.set(targetPath, String(targetContent));
      }
      for (const [path, content] of files) {
        if (!planFiles.has(path)) {
          planFiles.set(path, String(content));
        }
      }
      const plan = planDependencyEdit({
        content: working,
        parentLine: target.line,
        parentPath: ownerPath,
        add: snapshot.remove ? [] : [ref],
        remove: snapshot.remove ? [ref] : [],
        files: planFiles,
        vaultFiles,
        resolveLinkpath,
        recovery: {
          registry: countedRegistry,
          today: new Date(),
          vaultContents: countedVaultContents,
        },
      });
      if (!plan.ok) {
        new Notice(
          plan.reason === "in-blockquote"
            ? "⛓ Dependencies can't be edited inside a blockquote; no tasks were updated"
            : `⛓ Could not update the task on line ${target.line + 1} (${plan.reason}); no tasks were updated`,
        );
        return false;
      }
      for (const preparation of plan.preparations || []) {
        const key = `${preparation.path}\x00${preparation.line}\x00${preparation.from}\x00${preparation.text}`;
        if (!preparations.has(key)) {
          preparations.set(key, preparation);
        }
      }
      let nextWorking = plan.nextContent;
      if (plan.changed) {
        changedSources += 1;
      }
      if (plan.changed && this.plugin && typeof this.plugin.stampDependencyParentLine === "function") {
        nextWorking = this.plugin.stampDependencyParentLine(nextWorking, target.line);
      }
      working = nextWorking;
    }
    for (const preparation of preparations.values()) {
      let result = null;
      try {
        result = await this.plugin.prepareDependencyTargetNote(preparation.path, preparation);
      } catch (_error) {
        result = { ok: false, reason: "target-preparation-threw" };
      }
      if (!result || result.ok !== true) {
        new Notice(
          `⛓ Could not prepare the selected dependency (${(result && result.reason) || "target-preparation-failed"}); no tasks were updated`,
        );
        return false;
      }
    }
    if (working === originalContent) {
      new Notice("No dependencies changed");
      return true;
    }
    if (String(this.editor.getValue() || "") !== originalContent) {
      return this.refuseDependencyStale();
    }
    if (
      !applyEditorContentTransaction(this.editor, originalContent, working)
    ) {
      new Notice("Could not update counted dependencies; no tasks were updated");
      return false;
    }
    const applied = changedSources;
    new Notice(
      snapshot.remove
        ? `⛓ Removed from ${applied} task${applied === 1 ? "" : "s"}`
        : `⛓ Linked ${applied} task${applied === 1 ? "" : "s"}`,
    );
    return true;
  }

  // Preparation phase for a marked batch apply. Guards the cursor bullet, then
  // partitions the marked rows into removals, ready additions (already have a
  // trailing block ID), and additions that still need a prompted block ID. When
  // prompts are needed it stashes a pending batch and opens the first prompt
  // (returning false so the modal stays open); otherwise it executes the batch
  // immediately. No editor writes happen in this phase.
  commitMarkedDependencies() {
    if (!this.selectedPropertyItem || this.getMarkedCount() === 0) {
      return false;
    }

    const propertyName = this.selectedPropertyItem.property.name;
    const parentValidation = validateDependencyParentForEditor(
      this.editor,
      this.cursor,
      this.lineText,
    );
    if (!parentValidation.valid) {
      new Notice(parentValidation.message);
      return false;
    }
    const cursorLineText = parentValidation.line;

    const removals = [];
    const readyAdditions = [];
    const promptQueue = [];

    const ownerPath = normalizeVaultRelativePath(this.filePath || "");
    this.getMarkedTaskItems().forEach((item) => {
      const itemPath = normalizeVaultRelativePath(item.path || ownerPath);
      if (item.alreadyLinked) {
        // alreadyLinked implies a non-empty dependency value.
        removals.push({
          path: itemPath,
          blockId: item.blockId || item.existingBlockId || null,
          depValue: item.value,
          legacyDepValue: item.legacyDependencyValue || null,
          linkBlockId:
            item.existingBlockId || item.existingIdField || item.value,
        });
        return;
      }

      const snapshot = {
        markKey: bulletPropertyTaskMarkKey(item),
        path: itemPath,
        line: item.line,
        rawLine: item.rawLine,
        displayText: item.displayText,
        existingIdField: item.existingIdField || null,
        blockId: item.existingBlockId || null,
      };

      if (item.needsPromptForAdd) {
        promptQueue.push(snapshot);
      } else {
        readyAdditions.push(snapshot);
      }
    });

    const batch = {
      propertyName,
      cursorLineText,
      removals,
      readyAdditions,
      promptQueue,
      promptIndex: 0,
      confirmedById: new Map(),
      reservedIds: new Set(),
      // Cross-note batches commit through the vault writer (stale re-read
      // per target, one dependent transaction); same-note batches keep the
      // existing single-transaction executor below.
      hasVault: removals.some(
        (removal) => removal.path && removal.path !== ownerPath,
      ),
    };
    if (!batch.hasVault) {
      batch.hasVault = [...readyAdditions, ...promptQueue].some(
        (snapshot) => snapshot.path && snapshot.path !== ownerPath,
      );
    }

    // Cross-note batches preload every prompt target (suggestion content
    // plus cache-only locating) before the first prompt opens.
    if (batch.hasVault) {
      return this.prepareVaultBatch(batch);
    }

    if (promptQueue.length === 0) {
      this.clearPendingBatch();
      return this.executeDependencyBatch(batch);
    }

    this.pendingBatch = batch;
    return this.promptNextBatchBlockId();
  }

  // Preload prompt-target contents for a vault batch: cache-only rows gain
  // fresh line snapshots (or drop as stale), and every prompt target lands
  // in the stage files so `+ id` suggestions validate against the right
  // note. Empty queues execute straight through.
}
// ---- src/430-picker-vault-batch.js ----
class BulletPropertyPickerVaultBatchMixin extends FilteredPickerModal {
  async prepareVaultBatch(batch) {
    const ownerPath = normalizeVaultRelativePath(this.filePath || "");
    const live = [];
    for (const snapshot of batch.promptQueue) {
      const targetPath = normalizeVaultRelativePath(
        snapshot.path || ownerPath,
      );
      const files = await this.readVaultStageFiles([targetPath]);
      if (!files) {
        return false;
      }
      if (this.vaultStage && this.vaultStage.files instanceof Map) {
        this.vaultStage.files.set(targetPath, files.get(targetPath));
      }
      if (snapshot.rawLine == null && !snapshot.blockId) {
        const located = locateStageDisplayText(
          files.get(targetPath),
          snapshot.displayText,
        );
        if (!located) {
          snapshot.dead = true;
          live.push(snapshot);
          continue;
        }
        snapshot.line = located.line;
        snapshot.rawLine = located.rawLine;
        if (located.blockId) {
          snapshot.blockId = located.blockId;
          batch.readyAdditions.push(snapshot);
          continue;
        }
      }
      live.push(snapshot);
    }
    batch.promptQueue = live.filter((snapshot) => !snapshot.dead);
    const deadCount = live.filter((snapshot) => snapshot.dead).length;
    if (deadCount > 0) {
      batch.deadPromptCount = (batch.deadPromptCount || 0) + deadCount;
    }
    if (batch.promptQueue.length === 0) {
      this.clearPendingBatch();
      return this.executeVaultDependencyBatch(batch, {
        skippedOther: batch.deadPromptCount || 0,
      });
    }
    this.pendingBatch = batch;
    return this.promptNextBatchBlockId();
  }

  // Open the block-ID prompt for the task at the current queue position. Returns
  // false so the modal stays open while prompts are collected.
  promptNextBatchBlockId() {
    const batch = this.pendingBatch;
    if (!batch) {
      return false;
    }

    const snapshot = batch.promptQueue[batch.promptIndex];
    if (!snapshot) {
      return false;
    }

    this.showBlockIdStage(snapshot, {
      mode: "batch",
      position: batch.promptIndex + 1,
      total: batch.promptQueue.length,
    });
    return false;
  }

  confirmBlockId(item) {
    if (!this.selectedPropertyItem || !this.pendingTask || !item) {
      return false;
    }

    if (!item.valid) {
      return false;
    }

    if (this.blockIdMode === "batch" && this.pendingBatch) {
      return this.confirmBatchBlockId(item);
    }

    if (
      this.blockIdMode === "counted-source" &&
      this.pendingCountedDependency
    ) {
      return this.confirmCountedDependencyBlockId(item);
    }

    if (this.blockIdMode === "vault-single" && this.pendingVaultSingle) {
      return this.confirmVaultSingleBlockId(item);
    }

    if (this.blockIdMode === "vault-counted" && this.pendingVaultCounted) {
      return this.confirmVaultCountedBlockId(item);
    }

    return this.confirmSingleBlockId(item);
  }

  // Single `+ id` for a cross-note row: the confirmed id is written to the
  // target note first (an unused target id is acceptable, a link to an
  // unprepared target is not), then the link commits through the writer.
  async confirmVaultSingleBlockId(item) {
    const pending = this.pendingVaultSingle;
    if (!pending || !item.valid) {
      return false;
    }
    const snapshot = pending.snapshot;
    const ownerPath = normalizeVaultRelativePath(this.filePath || "");
    const targetPath = normalizeVaultRelativePath(
      snapshot.path || ownerPath,
    );
    const files = await this.readVaultStageFiles([targetPath]);
    if (!files) {
      return false;
    }
    const targetContent = files.get(targetPath);
    const validation = validateBlockIdCandidate(item.id, targetContent, {
      reservedIds: pending.reservedIds || new Set(),
    });
    if (!validation.valid || !tryDependencyId(targetPath, validation.id)) {
      new Notice(
        validation.message || "That block ID cannot be used in the target note",
      );
      return false;
    }
    const targetLines = String(targetContent).split(/\r?\n/);
    if (
      targetLines[snapshot.line] !== snapshot.rawLine ||
      !isObsidianTaskAtLine(targetContent, snapshot.line, null, targetLines)
    ) {
      return this.refuseDependencyStale();
    }
    const updatedLine = applyPromptedBlockIdPreservingLegacyId(
      targetLines[snapshot.line],
      validation.id,
      targetPath,
    );
    if (updatedLine === null) {
      new Notice(
        "Dependency not added: this note path cannot be encoded as a dependency ID",
      );
      return false;
    }
    const prepared = await this.plugin.prepareDependencyTargetNote(
      targetPath,
      {
        line: snapshot.line,
        from: targetLines[snapshot.line],
        text: updatedLine,
      },
    );
    if (!prepared.ok) {
      new Notice(`⛓ Could not prepare ${targetPath} (${prepared.reason})`);
      return false;
    }
    this.clearPendingBatch();
    const counters = { stale: 0, other: 0 };
    return this.commitVaultRefs(
      [{ path: targetPath, blockId: validation.id }],
      [],
      counters,
    );
  }

  // Counted `+ id` for a cross-note row: one prompt, then the link applies
  // to every source task that is not already linked.
  async confirmVaultCountedBlockId(item) {
    const pending = this.pendingVaultCounted;
    if (!pending || !item.valid) {
      return false;
    }
    const snapshot = pending.snapshot;
    const targetPath = normalizeVaultRelativePath(
      snapshot.path || this.filePath || "",
    );
    const files = await this.readVaultStageFiles([targetPath]);
    if (!files) {
      return false;
    }
    const validation = validateBlockIdCandidate(
      item.id,
      files.get(targetPath),
      { reservedIds: pending.reservedIds || new Set() },
    );
    if (!validation.valid || !tryDependencyId(targetPath, validation.id)) {
      new Notice(
        validation.message || "That block ID cannot be used in the target note",
      );
      return false;
    }
    // The planner resolves targets by `^block-id`, so the confirmed id is
    // written to the target before the single commit below runs.
    const targetLines = String(files.get(targetPath)).split(/\r?\n/);
    if (
      targetLines[snapshot.line] !== snapshot.rawLine ||
      !isObsidianTaskAtLine(files.get(targetPath), snapshot.line, null, targetLines)
    ) {
      return this.refuseDependencyStale();
    }
    const updatedLine = applyPromptedBlockIdPreservingLegacyId(
      targetLines[snapshot.line],
      validation.id,
      targetPath,
    );
    if (updatedLine === null) {
      new Notice(
        "Dependency not added: this note path cannot be encoded as a dependency ID",
      );
      return false;
    }
    const prepared = await this.plugin.prepareDependencyTargetNote(
      targetPath,
      {
        line: snapshot.line,
        from: targetLines[snapshot.line],
        text: updatedLine,
      },
    );
    if (!prepared.ok) {
      new Notice(`⛓ Could not prepare ${targetPath} (${prepared.reason})`);
      return false;
    }
    const confirmed = { ...snapshot, blockId: validation.id, preparedId: true };
    this.clearPendingBatch();
    return this.applyVaultCountedDependencyRef(confirmed);
  }

  async confirmCountedDependencyBlockId(item) {
    const dependencyTask = this.pendingCountedDependency;
    if (!dependencyTask || !item.valid) {
      return false;
    }
    const applied = await this.plugin.applyCountedLocalTaskDependency(
      this.editor,
      this.cursor,
      this.filePath,
      this.taskSession,
      dependencyTask,
      { confirmedBlockId: item.id },
    );
    if (applied) {
      this.clearPendingBatch();
    }
    return applied;
  }

  // Record one confirmed block ID and either advance to the next prompt (modal
  // stays open) or, on the final prompt, run the batch executor and close only
  // when it succeeds.
  async confirmBatchBlockId(item) {
    const batch = this.pendingBatch;
    const snapshot = batch.promptQueue[batch.promptIndex];
    if (!snapshot) {
      return false;
    }

    batch.confirmedById.set(snapshot.line, item.id);
    if (snapshot.markKey !== undefined && snapshot.markKey !== null) {
      batch.confirmedById.set(snapshot.markKey, item.id);
    }
    batch.reservedIds.add(item.id);
    batch.promptIndex += 1;

    if (batch.promptIndex < batch.promptQueue.length) {
      return this.promptNextBatchBlockId();
    }

    // Cross-note and same-note batches both commit asynchronously (stale
    // re-read per target plus target preparation and recovery).
    if (batch.hasVault) {
      return this.executeVaultDependencyBatch(batch).then((applied) => {
        if (applied) {
          this.clearPendingBatch();
        }
        return applied;
      });
    }
    if (await this.executeDependencyBatch(batch)) {
      this.clearPendingBatch();
      return true;
    }

    // Executor aborted (e.g. cursor bullet changed). Leave the modal open with
    // the failure notice already shown; Esc cancels with nothing written.
    return false;
  }

  confirmSingleBlockId(item) {
    const parentValidation = validateDependencyParentForEditor(
      this.editor,
      this.cursor,
      this.lineText,
    );
    if (!parentValidation.valid) {
      new Notice(parentValidation.message);
      return false;
    }
    const task = this.pendingTask;
    const targetLine = getEditorLine(this.editor, task.line);
    if (targetLine !== task.rawLine) {
      return this.refuseDependencyStale();
    }
    if (!isObsidianTaskAtLine(this.getEditorContent(), task.line)) {
      new Notice("Selected dependency is no longer a #task checkbox");
      return false;
    }

    // An existing valid `[id::]` is never rewritten (§3); the planner
    // resolves the kept id for the field. Unencodable paths refuse only
    // when the target has no `[id::]` yet. The confirmed id folds into the
    // writer's one transaction below (one Ctrl+Z).
    const updatedLine = applyPromptedBlockIdPreservingLegacyId(
      targetLine,
      item.id,
      this.filePath,
    );
    if (updatedLine === null) {
      new Notice(
        "Dependency not added: this note path cannot be encoded as a dependency ID",
      );
      return false;
    }

    const confirmedIdField = findBulletPropertyField(updatedLine, "id");
    const depValue = confirmedIdField
      ? normalizeBulletPropertyValue(confirmedIdField.value)
      : "";

    const linked = this.plugin.setLocalTaskDependency(
      this.editor,
      this.cursor,
      this.selectedPropertyItem.property.name,
      depValue,
      {
        showNotice: false,
        linkBlockId: item.id,
        filePath: this.filePath,
        pendingTargetLine: {
          line: task.line,
          expected: targetLine,
          text: updatedLine,
        },
      },
    );
    if (!linked) {
      return false;
    }

    new Notice(`Added ^${item.id} + linked dependency + navigation link`);
    return true;
  }

  // Execution phase: re-guard the cursor bullet, apply each target's edits,
  // rewrite the `[dependsOn:: ...]` list once, then reconcile navigation
  // bullets. Target-line edits are single-line replaces, so target indices stay
  // stable; only the nav reconciliation shifts lines and re-reads as it goes.
  async executeDependencyBatch(batch) {
    const parentValidation = validateDependencyParentForEditor(
      this.editor,
      this.cursor,
      batch.cursorLineText,
    );
    if (!parentValidation.valid) {
      new Notice(parentValidation.message);
      return false;
    }

    // Batch Depends-On write through the pure planner: snapshots resolve
    // read-only here, then one gesture commits the line, the field,
    // same-note target ids, status effects, and legacy folding in one
    // editor transaction (one Ctrl+Z), with `[fresh:: today]` stamped last.
    const originalContent = String(this.editor.getValue() || "");
    const filePath = normalizeVaultRelativePath(this.filePath || "");
    if (!filePath) {
      new Notice(
        "Dependencies are unavailable: this note path cannot be encoded as a dependency ID",
      );
      return false;
    }
    const removals = batch.removals.slice();
    let skippedStale = 0;
    let skippedOther = 0;
    // Confirmed `+ id` targets are stamped into a working copy first (the
    // planner resolves by `^block-id`), so the single commit below writes
    // the target ids and the link together.
    const workingLines = originalContent.split(/\r?\n/);
    const collectAddition = (snapshot, confirmedId = null) => {
      const targetLine = getEditorLine(this.editor, snapshot.line);
      if (targetLine !== snapshot.rawLine) {
        skippedStale += 1;
        return null;
      }
      if (!isObsidianTaskAtLine(originalContent, snapshot.line)) {
        skippedOther += 1;
        return null;
      }
      if (confirmedId !== null) {
        // Validated against the working copy (an earlier stamp in this
        // batch already landed there), not the batch's reserved set, which
        // already holds this confirmed id.
        const validation = validateBlockIdCandidate(
          confirmedId,
          workingLines.join(originalContent.includes("\r\n") ? "\r\n" : "\n"),
        );
        if (!validation.valid) {
          skippedOther += 1;
          return null;
        }
        if (!tryDependencyId(filePath, confirmedId)) {
          skippedOther += 1;
          return null;
        }
        const stampedLine = applyPromptedBlockIdPreservingLegacyId(
          targetLine,
          confirmedId,
          filePath,
        );
        if (stampedLine === null) {
          skippedOther += 1;
          return null;
        }
        workingLines[snapshot.line] = stampedLine;
        return { blockId: confirmedId };
      }
      const resolved = resolveTargetTaskIdentity(targetLine, {
        promptWhenBlockIdMissing: true,
        filePath,
      });
      if (resolved.needsBlockIdPrompt || !resolved.value) {
        skippedOther += 1;
        return null;
      }
      return { blockId: resolved.linkBlockId };
    };

    const addRefs = [];
    batch.readyAdditions.forEach((snapshot) => {
      const addition = collectAddition(snapshot);
      if (addition) {
        addRefs.push({ path: filePath, blockId: addition.blockId });
      }
    });
    batch.promptQueue.forEach((snapshot) => {
      const confirmedId = batch.confirmedById.get(snapshot.line);
      if (!confirmedId) {
        skippedOther += 1;
        return;
      }
      const addition = collectAddition(snapshot, confirmedId);
      if (addition) {
        addRefs.push({ path: filePath, blockId: addition.blockId });
      }
    });

    // A stale target refuses the whole batch before any write, then reopens
    // the stage fresh — never a partial commit with a skip count.
    if (skippedStale > 0) {
      return this.refuseDependencyStale();
    }

    // Removal marks carry the field value; resolve each to its `^block-id`
    // in this note. Field-only values need no link edit: the planner sets
    // the field from the line, so they fall out on their own.
    const noteLines = originalContent.split(/\r?\n/);
    const removeRefs = [];
    removals.forEach((removal) => {
      const candidates = [
        removal.linkBlockId,
        removal.depValue,
        removal.legacyDepValue,
      ]
        .map(normalizeBulletPropertyValue)
        .filter(Boolean);
      for (const candidate of candidates) {
        if (findTaskLineByTrailingBlockId(noteLines, candidate) !== null) {
          removeRefs.push({ path: filePath, blockId: candidate });
          return;
        }
      }
      for (let index = 0; index < noteLines.length; index += 1) {
        if (!isObsidianTaskAtLine(originalContent, index)) {
          continue;
        }
        const idField = findBulletPropertyField(noteLines[index], "id");
        const idValue =
          idField && normalizeBulletPropertyValue(idField.value);
        if (idValue && candidates.includes(idValue)) {
          const blockId = getTrailingBlockId(noteLines[index]);
          if (blockId) {
            removeRefs.push({ path: filePath, blockId });
            return;
          }
        }
      }
    });

    // Cycle guard on the post-batch graph (§6.4): a marked row whose edge
    // closes a cycle back to the dependent refuses before any write, like
    // the vault path above (every added edge leaves the same dependent, so
    // one row alone closes a simple cycle). The single-note graph covers
    // same-note batches; cross-note rows commit through `commitVaultRefs`,
    // which guards the full graph.
    {
      const cursorLines = originalContent.split(/\r?\n/);
      const cursorText = String(cursorLines[this.cursor.line] || "");
      const cursorBlockId = getTrailingBlockId(cursorText);
      const cursorIdField = findBulletPropertyField(cursorText, "id");
      const cursorIdValue =
        cursorIdField && normalizeBulletPropertyValue(cursorIdField.value);
      const batchDependentKey =
        (cursorBlockId && dependencyStageRowKey(filePath, cursorBlockId)) ||
        (cursorIdValue ? `id:${cursorIdValue}` : null) ||
        `${filePath}#line:${this.cursor.line}`;
      const trialNotes = [{ path: filePath, content: originalContent }];
      const trialIndex = indexDependencyStageNotes(trialNotes);
      const trialEdges = collectDependencyStageEdges(trialNotes, trialIndex);
      const trial = new Map();
      for (const [from, targets] of trialEdges) {
        trial.set(from, targets.slice());
      }
      const dropKeys = new Set(
        removeRefs
          .map((ref) => dependencyStageRowKey(ref.path, ref.blockId))
          .filter(Boolean),
      );
      const current = (trial.get(batchDependentKey) || []).filter(
        (key) => !dropKeys.has(key),
      );
      for (const ref of addRefs) {
        const key = dependencyStageRowKey(ref.path, ref.blockId);
        if (key && !current.includes(key)) {
          current.push(key);
        }
      }
      trial.set(batchDependentKey, current);
      for (const ref of addRefs) {
        const key = dependencyStageRowKey(ref.path, ref.blockId);
        const cycle =
          key === batchDependentKey
            ? [batchDependentKey]
            : findDependencyStageCycle(trial, batchDependentKey, key);
        if (key && cycle) {
          new Notice(
            `⛓ Could not update dependencies (would create a cycle: ${cycle.length - 1} back-link${cycle.length - 1 === 1 ? "" : "s"})`,
          );
          return false;
        }
      }
    }
    const workingContent = workingLines.join(
      originalContent.includes("\r\n") ? "\r\n" : "\n",
    );
    const registry = await readTasksStatusRegistry(
      this.plugin ? this.plugin.app : null,
    );
    const vaultContents =
      this.plugin &&
      needsDependencyRecoverySnapshot(workingContent, this.cursor.line, removeRefs, false, addRefs)
        ? await this.plugin.readDependencyRecoveryVaultContents(
            filePath,
            workingContent,
          )
        : null;
    const plan = planDependencyEdit({
      content: workingContent,
      parentLine: this.cursor.line,
      parentPath: filePath,
      add: addRefs,
      remove: removeRefs,
      files: { [filePath]: workingContent },
      vaultFiles: this.plugin
        ? this.plugin.readDependencyVaultFileList()
        : null,
      resolveLinkpath: this.plugin
        ? this.plugin.dependencyLinkpathResolver()
        : null,
      recovery: { registry, today: new Date(), vaultContents },
    });
    if (!plan.ok) {
      new Notice(dependencyPlanFailureNotice(plan.reason, "update"));
      return false;
    }
    if (plan.changed) {
      const nextContent =
        this.plugin &&
        typeof this.plugin.stampDependencyParentLine === "function"
          ? this.plugin.stampDependencyParentLine(
              plan.nextContent,
              this.cursor.line,
              undefined,
              undefined,
            )
          : plan.nextContent;
      if (!applyEditorContentTransaction(this.editor, originalContent, nextContent)) {
        new Notice("Could not update bullet property");
        return false;
      }
    }

    const finalCursorLine =
      getEditorLine(this.editor, this.cursor.line) || this.cursor.line;
    setEditorCursorSafely(
      this.editor,
      this.cursor.line,
      Math.min(
        Math.max(this.cursor.ch, 0),
        String(finalCursorLine || "").length,
      ),
    );

    const skipped = skippedStale + skippedOther;
    new Notice(
      plan.notice + (skipped > 0 ? ` (${skipped} skipped)` : ""),
    );
    return true;
  }

  // Vault-wide single remove: CURRENT rows toggle off through the writer
  // (`docs/task-dependencies.md` §6.6). Removing a link is always allowed,
  // so the target is never re-read; the dependent is guarded by its
  // snapshot line text.
  // A stale target or dependent refuses with `changed — reopen` and then
  // reopens the stage fresh (`docs/task-dependencies.md` §6.4). Best-effort:
  // harness stubs without a picker opener just keep the refusal.
}
// ---- src/440-picker-vault-commit.js ----
class BulletPropertyPickerVaultCommitMixin extends FilteredPickerModal {
  reopenDependencyStageFresh() {
    try {
      const plugin = this.plugin;
      const editor = this.editor;
      if (
        !plugin ||
        !editor ||
        typeof plugin.openBulletPropertyPicker !== "function"
      ) {
        return;
      }
      try {
        this.close();
      } catch (_closeError) {
        // Best-effort close only.
      }
      void plugin.openBulletPropertyPicker(editor, {
        initialProperty: "dependsOn",
      });
    } catch (_reopenError) {
      // Best-effort reopen only.
    }
  }

  refuseDependencyStale(message = "changed — reopen") {
    new Notice(message);
    this.reopenDependencyStageFresh();
    return false;
  }

  async removeSingleDependency(item) {
    const ownerPath = normalizeVaultRelativePath(this.filePath || "");
    const blockId = normalizeBulletPropertyValue(
      item.blockId || item.existingBlockId || "",
    );
    if (!ownerPath || !blockId) {
      new Notice("⛓ Could not remove dependency (missing link target)");
      return false;
    }
    const outcome = await this.plugin.applyDependencyEdit({
      editor: this.editor,
      parentPath: ownerPath,
      parentLine: this.cursor.line,
      add: [],
      remove: [
        { path: normalizeVaultRelativePath(item.path || ownerPath), blockId },
      ],
    });
    if (!outcome.ok) {
      if (outcome.reason === "stale-editor") {
        // `applyDependencyEdit` already showed `changed — reopen`: only
        // reopen the stage fresh, without a second notice (§6.4).
        this.reopenDependencyStageFresh();
        return false;
      }
      new Notice(`⛓ Could not remove dependency (${outcome.reason})`);
      return false;
    }
    new Notice(outcome.notice || "⛓ Dependency removed");
    return true;
  }

  // Vault-wide single add: re-read the target note and refuse when the
  // target changed since the stage opened, then commit through the writer.
  // Rows without a block id detour through the `+ id` prompt first.
  async chooseVaultTaskDependency(item) {
    const parentValidation = validateDependencyParentForEditor(
      this.editor,
      this.cursor,
      this.lineText,
    );
    if (!parentValidation.valid) {
      new Notice(parentValidation.message);
      return false;
    }
    const ownerPath = normalizeVaultRelativePath(this.filePath || "");
    const snapshot = {
      markKey: bulletPropertyTaskMarkKey(item),
      path: normalizeVaultRelativePath(item.path || ownerPath),
      line: item.line,
      rawLine: item.rawLine,
      displayText: item.displayText,
      existingIdField: item.existingIdField || null,
      blockId: item.existingBlockId || null,
    };
    const ownerForSingle = normalizeVaultRelativePath(this.filePath || "");
    const singleTargetPath = normalizeVaultRelativePath(
      snapshot.path || ownerForSingle,
    );
    const singleFiles = await this.readVaultStageFiles([singleTargetPath]);
    if (!singleFiles) {
      return false;
    }
    if (this.vaultStage && this.vaultStage.files instanceof Map) {
      this.vaultStage.files.set(
        singleTargetPath,
        singleFiles.get(singleTargetPath),
      );
    }
    if (!snapshot.blockId && snapshot.rawLine == null) {
      // Cache-only `+ id` row: match the target fresh by display text.
      const located = locateStageDisplayText(
        singleFiles.get(singleTargetPath),
        snapshot.displayText,
      );
      if (!located) {
        return this.refuseDependencyStale();
      }
      snapshot.line = located.line;
      snapshot.rawLine = located.rawLine;
      if (located.blockId) {
        snapshot.blockId = located.blockId;
      }
    }
    if (!snapshot.blockId) {
      this.pendingVaultSingle = { snapshot, reservedIds: new Set() };
      this.showBlockIdStage(snapshot, { mode: "vault-single" });
      return false;
    }
    const files = singleFiles;
    const counters = { stale: 0, other: 0 };
    const addition = this.collectVaultAddition(snapshot, files, counters);
    if (!addition) {
      if (counters.stale > 0) {
        return this.refuseDependencyStale();
      }
      new Notice("Could not identify the selected dependency");
      return false;
    }
    return this.commitVaultRefs([addition], [], counters);
  }

  // Fresh contents for the parent plus every involved target note: stage
  // snapshots first (open buffers win), then a guarded vault read for the
  // rest. Returns null with a notice when an addition target is unreadable:
  // if preparation fails, the dependent is untouched (§6.6).
  async readVaultStageFiles(paths) {
    const ownerPath = normalizeVaultRelativePath(this.filePath || "");
    const files = new Map();
    if (this.vaultStage && this.vaultStage.files instanceof Map) {
      for (const [path, content] of this.vaultStage.files) {
        files.set(path, String(content || ""));
      }
    }
    files.set(ownerPath, String(this.editor.getValue() || ""));
    for (const rawPath of paths || []) {
      const path = normalizeVaultRelativePath(rawPath || "");
      if (!path) {
        continue;
      }
      // Open buffers win over stage snapshots (a `+ id` pre-write lands in
      // the buffer first); otherwise re-read, so validation and planning
      // see post-open edits.
      const buffered =
        this.plugin && typeof this.plugin.readOpenBufferContent === "function"
          ? this.plugin.readOpenBufferContent(path)
          : null;
      if (buffered !== null) {
        files.set(path, buffered);
        continue;
      }
      if (files.has(path)) {
        continue;
      }
      const loaded = await this.plugin.readDependencyNoteContent(
        path,
        null,
        ownerPath,
      );
      if (loaded === null) {
        new Notice(`⛓ Could not read ${path}; no tasks were updated`);
        return null;
      }
      files.set(path, String(loaded));
    }
    return files;
  }

  // Resolve one vault addition against fresh content: the target must still
  // carry the staged block id on the staged line text, else it is stale.
  // Prompt-queue snapshots (no block id yet) match by line text instead.
  collectVaultAddition(snapshot, files, counters, confirmedId = null) {
    const ownerPath = normalizeVaultRelativePath(this.filePath || "");
    const targetPath = normalizeVaultRelativePath(
      snapshot.path || ownerPath,
    );
    const targetContent = files.get(targetPath);
    if (targetContent === undefined) {
      counters.other += 1;
      return null;
    }
    const targetLines = String(targetContent).split(/\r?\n/);
    const at = Math.floor(numericOrDefault(snapshot.line, Number.NaN));
    const wantBlockId =
      confirmedId !== null
        ? normalizeBulletPropertyValue(confirmedId)
        : normalizeBulletPropertyValue(snapshot.blockId || "");
    if (confirmedId !== null) {
      const validation = validateBlockIdCandidate(
        confirmedId,
        targetContent,
        { reservedIds: this.getBlockIdReservedIds() },
      );
      if (!validation.valid || !tryDependencyId(targetPath, validation.id)) {
        counters.other += 1;
        return null;
      }
      if (
        !Number.isFinite(at) ||
        targetLines[at] !== snapshot.rawLine ||
        !isObsidianTaskAtLine(targetContent, at, null, targetLines)
      ) {
        counters.stale += 1;
        return null;
      }
      return { path: targetPath, blockId: validation.id };
    }
    if (!wantBlockId) {
      counters.other += 1;
      return null;
    }
    // Just-prepared `+ id` targets — and cache-only rows, which carry no
    // staged line text — resolve by block id with task-ness as the check.
    if (snapshot.preparedId || snapshot.rawLine == null) {
      const placed = findTaskLineByTrailingBlockId(targetLines, wantBlockId);
      if (
        placed === null ||
        !isObsidianTaskAtLine(targetContent, placed, null, targetLines)
      ) {
        counters.stale += 1;
        return null;
      }
      return { path: targetPath, blockId: wantBlockId };
    }
    const found = findTaskLineByTrailingBlockId(targetLines, wantBlockId);
    if (
      found === null ||
      String(targetLines[found] || "") !== String(snapshot.rawLine || "") ||
      !isObsidianTaskAtLine(targetContent, found, null, targetLines)
    ) {
      counters.stale += 1;
      return null;
    }
    return { path: targetPath, blockId: wantBlockId };
  }

  // One vault commit for a whole batch: guards the batch graph for cycles
  // after the whole batch (§6.4), then writes through `applyDependencyEdit`
  // — cross-note targets prepared first, the dependent committed in one
  // editor transaction, with the §6.7 notice.
  async commitVaultRefs(addRefs, removeRefs, counters = { stale: 0, other: 0 }) {
    const ownerPath = normalizeVaultRelativePath(this.filePath || "");
    const stage = this.vaultStage;
    const dependentKey = stage && stage.dependent ? stage.dependent.key : null;
    if (dependentKey && stage && stage.edges instanceof Map) {
      const trial = new Map();
      for (const [from, targets] of stage.edges) {
        trial.set(from, targets.slice());
      }
      const dropKeys = new Set(
        removeRefs
          .map((ref) => dependencyStageRowKey(ref.path, ref.blockId))
          .filter(Boolean),
      );
      const current = (trial.get(dependentKey) || []).filter(
        (key) => !dropKeys.has(key),
      );
      for (const ref of addRefs) {
        const key = dependencyStageRowKey(ref.path, ref.blockId);
        if (key && !current.includes(key)) {
          current.push(key);
        }
      }
      trial.set(dependentKey, current);
      for (const ref of addRefs) {
        const key = dependencyStageRowKey(ref.path, ref.blockId);
        const cycle =
          key === dependentKey
            ? [dependentKey]
            : findDependencyStageCycle(trial, dependentKey, key);
        if (key && cycle) {
          new Notice(
            `⛓ Could not update dependencies (would create a cycle: ${cycle.length - 1} back-link${cycle.length - 1 === 1 ? "" : "s"})`,
          );
          return false;
        }
      }
    }
    const outcome = await this.plugin.applyDependencyEdit({
      editor: this.editor,
      parentPath: ownerPath,
      parentLine: this.cursor.line,
      add: addRefs,
      remove: removeRefs,
    });
    if (!outcome.ok) {
      // A stale write refuses and reopens the stage fresh, exactly like the
      // same-note `executeDependencyBatch` (§6.4). `applyDependencyEdit`
      // already showed `changed — reopen`, so only reopen here.
      if (outcome.reason === "stale-editor") {
        this.reopenDependencyStageFresh();
        return false;
      }
      new Notice(dependencyPlanFailureNotice(outcome.reason, "update"));
      return false;
    }
    const skipped = (counters.stale || 0) + (counters.other || 0);
    new Notice(
      (outcome.notice || "⛓ Dependencies updated") +
        (skipped > 0 ? ` (${skipped} skipped)` : ""),
    );
    return true;
  }

  // Batch executor for stages containing cross-note rows: every target is
  // re-read fresh (a stale row refuses the whole batch before any write),
  // `+ id` prompts were collected up front, and the whole batch commits
  // once.
  async executeVaultDependencyBatch(batch, seedCounters = null) {
    const parentValidation = validateDependencyParentForEditor(
      this.editor,
      this.cursor,
      batch.cursorLineText,
    );
    if (!parentValidation.valid) {
      new Notice(parentValidation.message);
      return false;
    }
    const ownerPath = normalizeVaultRelativePath(this.filePath || "");
    if (!ownerPath) {
      new Notice(
        "Dependencies are unavailable: this note path cannot be encoded as a dependency ID",
      );
      return false;
    }
    const targetPaths = new Set();
    for (const snapshot of [...batch.readyAdditions, ...batch.promptQueue]) {
      targetPaths.add(normalizeVaultRelativePath(snapshot.path || ownerPath));
    }
    const files = await this.readVaultStageFiles([...targetPaths]);
    if (!files) {
      return false;
    }
    const counters = {
      stale: (seedCounters && seedCounters.stale) || 0,
      other: (seedCounters && seedCounters.skippedOther) || 0,
    };
    const addRefs = [];
    for (const snapshot of batch.readyAdditions) {
      const addition = this.collectVaultAddition(snapshot, files, counters);
      if (addition) {
        addRefs.push(addition);
      }
    }
    // A stale row refuses the whole batch before any write, then reopens
    // the stage fresh — never a partial commit with a skip count — exactly
    // like the same-note `executeDependencyBatch` (§6.4).
    if (counters.stale > 0) {
      return this.refuseDependencyStale();
    }
    // Prompt-queue targets validate before any `+ id` preparation writes:
    // a stale prompt row below refuses with nothing written, even when an
    // earlier target already validated.
    const pendingPreparations = [];
    for (const snapshot of batch.promptQueue) {
      const key = snapshot.markKey !== undefined && snapshot.markKey !== null
        ? snapshot.markKey
        : snapshot.line;
      const confirmedId = batch.confirmedById.get(key);
      if (!confirmedId) {
        counters.other += 1;
        continue;
      }
      const addition = this.collectVaultAddition(
        snapshot,
        files,
        counters,
        confirmedId,
      );
      if (!addition) {
        continue;
      }
      // The planner resolves targets by `^block-id`, so the confirmed id is
      // written to the target first (open editor, else a preimage-checked
      // vault update). If preparation fails the dependent is untouched.
      const targetPath = normalizeVaultRelativePath(
        snapshot.path || ownerPath,
      );
      const freshContent = files.get(targetPath);
      const freshLines = String(freshContent).split(/\r?\n/);
      const updatedLine = applyPromptedBlockIdPreservingLegacyId(
        freshLines[snapshot.line],
        addition.blockId,
        targetPath,
      );
      if (updatedLine === null) {
        counters.other += 1;
        continue;
      }
      pendingPreparations.push({
        snapshot,
        addition,
        targetPath,
        from: freshLines[snapshot.line],
        text: updatedLine,
      });
    }
    if (counters.stale > 0) {
      return this.refuseDependencyStale();
    }
    for (const preparation of pendingPreparations) {
      const prepared = await this.plugin.prepareDependencyTargetNote(
        preparation.targetPath,
        {
          line: preparation.snapshot.line,
          from: preparation.from,
          text: preparation.text,
        },
      );
      if (!prepared.ok) {
        new Notice(
          `⛓ Could not prepare ${preparation.targetPath} (${prepared.reason}); no tasks were updated`,
        );
        return false;
      }
      addRefs.push(preparation.addition);
    }
    // Removal marks carry the field value; cross-note removals resolve
    // through the staged block id, same-note removals through the existing
    // note scan. Field-only values need no link edit: the planner sets the
    // field from the line, so they fall out on their own.
    const noteLines = String(this.editor.getValue() || "").split(/\r?\n/);
    const removeRefs = [];
    for (const removal of batch.removals) {
      const removalPath = normalizeVaultRelativePath(
        removal.path || ownerPath,
      );
      if (removalPath !== ownerPath) {
        if (normalizeBulletPropertyValue(removal.blockId || "")) {
          removeRefs.push({ path: removalPath, blockId: removal.blockId });
        } else {
          counters.other += 1;
        }
        continue;
      }
      const candidates = [
        removal.linkBlockId,
        removal.depValue,
        removal.legacyDepValue,
      ]
        .map(normalizeBulletPropertyValue)
        .filter(Boolean);
      let resolved = null;
      for (const candidate of candidates) {
        if (findTaskLineByTrailingBlockId(noteLines, candidate) !== null) {
          resolved = candidate;
          break;
        }
      }
      if (!resolved) {
        for (let index = 0; index < noteLines.length; index += 1) {
          if (!isObsidianTaskAtLine(String(this.editor.getValue() || ""), index)) {
            continue;
          }
          const idField = findBulletPropertyField(noteLines[index], "id");
          const idValue = idField && normalizeBulletPropertyValue(idField.value);
          if (idValue && candidates.includes(idValue)) {
            const blockId = getTrailingBlockId(noteLines[index]);
            if (blockId) {
              resolved = blockId;
              break;
            }
          }
        }
      }
      if (resolved) {
        removeRefs.push({ path: ownerPath, blockId: resolved });
      }
    }
    if (addRefs.length === 0 && removeRefs.length === 0) {
      const skipped = counters.stale + counters.other;
      new Notice(
        skipped > 0
          ? `No dependencies changed (${skipped} skipped)`
          : "No dependencies changed",
      );
      return false;
    }
    return this.commitVaultRefs(addRefs, removeRefs, counters);
  }

  hasCountedRollBatchForDateProperty(datePropertyName) {
    if (!this.isCountedSession()) {
      return false;
    }
    const batch = this.getCountedRollBatchForDateProperty(datePropertyName);
    if (!batch) {
      return false;
    }
    return (
      batch.actionableCount > 0 || Boolean(batch.unavailableReason)
    );
  }

  async applyCountedRecommendedRoll() {
    const cached = this.countedRollBatch;
    if (!cached) {
      return false;
    }
    if (cached.unavailableReason) {
      new Notice(cached.unavailableReason);
      return false;
    }
    if (this.opening) {
      return false;
    }
    this.opening = true;
    try {
      const fresh = this.computeCountedRollBatch();
      if (
        !fresh ||
        fresh.actionableCount !== cached.actionableCount ||
        fresh.counts.roll !== cached.counts.roll ||
        fresh.counts.decay !== cached.counts.decay ||
        fresh.counts.cancel !== cached.counts.cancel ||
        Boolean(fresh.unavailableReason) !==
          Boolean(cached.unavailableReason)
      ) {
        new Notice("Task changed while the picker was open; nothing was written");
        this.countedRollBatch = fresh;
        this.countedRollBatchReady = true;
        this.returnHome({ rebuild: true });
        return false;
      }
      return await this.maybeOfferCountedRecommendedWorkLog(cached);
    } finally {
      this.opening = false;
    }
  }

  async maybeOfferCountedRecommendedWorkLog(cached) {
    const entries = Array.isArray(cached.entries) ? cached.entries : [];
    const schedulingEntries = entries.filter(
      (entry) =>
        entry &&
        entry.recommendation &&
        (entry.recommendation.kind === "roll" ||
          entry.recommendation.kind === "decay"),
    );
    if (schedulingEntries.length === 0) {
      return await this.plugin.applyCountedRecommendedRoll(this);
    }
    const targets = schedulingEntries.map((entry) => ({
      line: entry.line,
      rawLine: entry.rawLine,
    }));
    const eligible = collectSchedulingWorkLogEligibleOriginalLines(targets);
    if (eligible.size === 0) {
      return await this.plugin.applyCountedRecommendedRoll(this);
    }
    const dates = schedulingEntries
      .map((entry) => entry.recommendation && entry.recommendation.date)
      .filter(Boolean);
    const scheduleSummary = formatSchedulingWorkLogDateSpan(dates);
    return await this.offerSchedulingWorkLogOrDispatch({
      targets,
      scheduleSummary,
      dispatch: async (summary) =>
        await this.plugin.applyCountedRecommendedRoll(this, {
          schedulingWorkLog: summary
            ? {
                summary,
                dateText: formatBulletPropertyDate(
                  this.valueBaseDate instanceof Date
                    ? this.valueBaseDate
                    : getLocalDateStart(new Date()),
                ),
              }
            : null,
        }),
    });
  }

  async applyLinkRecommendedRoll() {
    const cached = this.linkRollBatch;
    if (!cached) {
      return false;
    }
    if (cached.unavailableReason) {
      new Notice(cached.unavailableReason);
      return false;
    }
    if (this.opening) {
      return false;
    }
    this.opening = true;
    try {
      const fresh = this.computeLinkRollBatch();
      if (
        !fresh ||
        fresh.actionableCount !== cached.actionableCount ||
        fresh.counts.roll !== cached.counts.roll ||
        fresh.counts.decay !== cached.counts.decay ||
        fresh.counts.cancel !== cached.counts.cancel ||
        Boolean(fresh.unavailableReason) !==
          Boolean(cached.unavailableReason)
      ) {
        new Notice("Task changed while the picker was open; nothing was written");
        this.linkRollBatch = fresh;
        this.linkRollBatchReady = true;
        this.returnHome({ rebuild: true });
        return false;
      }
      return await this.maybeOfferLinkRecommendedWorkLog(cached);
    } finally {
      this.opening = false;
    }
  }

  async maybeOfferLinkRecommendedWorkLog(cached) {
    const entries = Array.isArray(cached.entries) ? cached.entries : [];
    const schedulingEntries = entries.filter(
      (entry) =>
        entry &&
        entry.recommendation &&
        (entry.recommendation.kind === "roll" ||
          entry.recommendation.kind === "decay"),
    );
    if (schedulingEntries.length === 0) {
      return await this.plugin.applyLinkRecommendedRoll(this);
    }
    const targets = schedulingEntries.map((entry) => ({
      line: entry.line,
      rawLine: entry.rawLine,
      path: entry.path,
    }));
    const eligible = collectSchedulingWorkLogEligibleOriginalLines(targets);
    if (eligible.size === 0) {
      return await this.plugin.applyLinkRecommendedRoll(this);
    }
    const dates = schedulingEntries
      .map((entry) => entry.recommendation && entry.recommendation.date)
      .filter(Boolean);
    const scheduleSummary = formatSchedulingWorkLogDateSpan(dates);
    // Writers resolve per-note groups and deduplicate repeated links by
    // note and task identity so each qualifying task receives at most one
    // entry; the prompt names the qualifying count for the scheduling subset.
    return await this.offerSchedulingWorkLogOrDispatch({
      targets,
      scheduleSummary,
      dispatch: async (summary) =>
        await this.plugin.applyLinkRecommendedRoll(this, {
          schedulingWorkLog: summary
            ? {
                summary,
                dateText: formatBulletPropertyDate(
                  this.valueBaseDate instanceof Date
                    ? this.valueBaseDate
                    : getLocalDateStart(new Date()),
                ),
              }
            : null,
        }),
    });
  }

}
// ---- src/450-picker-keydown.js ----
class BulletPropertyPickerKeydownMixin extends FilteredPickerModal {
  handleKeydown(event) {
    if (this.stage === "task-card") {
      this.handleTaskCardKeydown(event);
      return;
    }
    // Ctrl+[ closes from every stage, including a focused date, filter,
    // reason, or Work summary field. Closing discards uncommitted state and
    // writes nothing, exactly as Escape does.
    if (
      event &&
      event.isComposing !== true &&
      event.keyCode !== 229 &&
      isCtrlLeftBracketKeydown(event)
    ) {
      event.preventDefault();
      event.stopPropagation();
      this.close();
      return;
    }
    if (this.stage === "schedule-review" && event) {
      if (event.key === "Tab") {
        event.preventDefault();
        event.stopPropagation();
        this.cycleScheduleReviewFocus(event, event.shiftKey === true);
        return;
      }
      if (event.key === "Enter") {
        event.preventDefault();
        event.stopPropagation();
        if (this.opening) {
          return;
        }
        this.opening = true;
        Promise.resolve(this.confirmScheduleReview())
          .then((applied) => {
            if (applied === true) {
              this.close();
            }
          })
          .catch(() => false)
          .finally(() => {
            this.opening = false;
          });
        return;
      }
      if (
        event.key === "Backspace" &&
        this.scheduleReviewSummaryEl &&
        event.target === this.scheduleReviewSummaryEl &&
        !String(this.scheduleReviewSummaryEl.value || "")
      ) {
        event.preventDefault();
        event.stopPropagation();
        if (this.scheduleReviewReasonEl && typeof this.scheduleReviewReasonEl.focus === "function") {
          this.scheduleReviewReasonEl.focus();
        }
        return;
      }
    }
    if (
      this.hasTaskCard &&
      this.stage !== "task-card" &&
      event &&
      event.key === "Backspace" &&
      event.target === this.inputEl &&
      this.inputEl &&
      !String(this.inputEl.value || "")
    ) {
      event.preventDefault();
      event.stopPropagation();
      this.returnToTaskCard();
      return;
    }
    // Ctrl+Enter (or Cmd+Enter) on `scheduled` takes the recommended roll in
    // both picker stages. Anywhere else it behaves exactly like Enter, as it
    // does today; other stages keep their existing key handling untouched.
    // Counted and link sessions use their batch recommendation through the
    // same gesture.
    if (isRecommendedRollKeydown(event) && this.stage === "value") {
      event.preventDefault();
      event.stopPropagation();
      if (!this.opening) {
        const rollPropertyName =
          this.selectedPropertyItem && this.selectedPropertyItem.property
            ? this.selectedPropertyItem.property.name
            : "";
        if (
          rollPropertyName &&
          this.hasCountedRollBatchForDateProperty(rollPropertyName)
        ) {
          void this.applyCountedRecommendedRoll()
            .then((applied) => {
              if (applied === true) {
                this.close();
              }
            })
            .catch(() => {
              new Notice("Could not apply the recommended roll");
            });
        } else if (
          rollPropertyName &&
          this.hasLinkRollBatchForDateProperty(rollPropertyName)
        ) {
          void this.applyLinkRecommendedRoll()
            .then((applied) => {
              if (applied === true) {
                this.close();
              }
            })
            .catch(() => {
              new Notice("Could not apply the recommended roll");
            });
        } else if (
          rollPropertyName &&
          this.getScheduledRollRecommendation(rollPropertyName)
        ) {
          void this.applyRecommendedRoll()
            .then((applied) => {
              if (applied === true) {
                this.close();
              }
            })
            .catch(() => {
              new Notice("Could not apply the recommended roll");
            });
        } else {
          super.handleKeydown(event);
        }
      }
      return;
    }

    if (
      this.isLocalTaskStage() &&
      !this.isCountedSession() &&
      event.key === "Tab"
    ) {
      event.preventDefault();
      event.stopPropagation();
      this.toggleHighlightedLocalTaskMark();
      return;
    }

    if (
      this.isLocalTaskStage() &&
      event.key === "Enter" &&
      this.getMarkedCount() > 0
    ) {
      event.preventDefault();
      event.stopPropagation();
      if (this.opening) {
        return;
      }

      this.opening = true;
      const markedOutcome = this.commitMarkedDependencies();
      // Batches commit asynchronously (stale re-read per target, target
      // preparation, and recovery); the modal closes when the outcome
      // resolves truthy.
      if (markedOutcome && typeof markedOutcome.then === "function") {
        markedOutcome
          .then((applied) => {
            if (applied) {
              this.close();
            }
          })
          .catch(() => false)
          .finally(() => {
            this.opening = false;
          });
      } else {
        try {
          if (markedOutcome) {
            this.close();
          }
        } finally {
          this.opening = false;
        }
      }
      return;
    }

    if (this.stage === "value" && isCtrlKey(event, "r")) {
      if (this.isLinkSession()) {
        // Link sessions keep no pinned roll row: re-roll the batch so the
        // stage-two footer preview stays in sync.
        if (this.rerollLinkRollBatch()) {
          this.applyOptions({
            footerHints: getBulletPropertyStageTwoHints(
              Boolean(
                this.items.some((item) => item && item.priorityRoll),
              ),
              this.selectedPropertyItem
                ? this.getRollPreviewForDateProperty(
                    this.selectedPropertyItem.property.name,
                  )
                : null,
              { skipReason: this.isScheduledValueStage() },
            ),
          });
          event.preventDefault();
          event.stopPropagation();
          return;
        }
      } else if (this.isCountedSession()) {
        let rerolled = false;
        if (this.rerollCountedRollBatch()) {
          this.applyOptions({
            footerHints: getBulletPropertyStageTwoHints(
              Boolean(
                this.items.some((item) => item && item.priorityRoll),
              ),
              this.selectedPropertyItem
                ? this.getRollPreviewForDateProperty(
                    this.selectedPropertyItem.property.name,
                  )
                : null,
              { skipReason: this.isScheduledValueStage() },
            ),
          });
          rerolled = true;
        }
        if (this.rerollPriorityDateSuggestion()) {
          rerolled = true;
        }
        if (rerolled) {
          event.preventDefault();
          event.stopPropagation();
          return;
        }
      } else if (this.rerollPriorityDateSuggestion()) {
        event.preventDefault();
        event.stopPropagation();
        return;
      }
    }

    if (
      this.isScheduledValueStage() &&
      event &&
      event.key === "Enter" &&
      event.shiftKey === true &&
      event.ctrlKey !== true &&
      event.metaKey !== true &&
      event.altKey !== true
    ) {
      event.preventDefault();
      event.stopPropagation();
      if (this.opening) {
        return;
      }
      const item = this.visibleItems[this.selectedIndex];
      if (!item) {
        return;
      }
      this.opening = true;
      Promise.resolve(this.commitScheduledDateItem(item, { skipReason: true }))
        .then((applied) => {
          if (applied === true) {
            this.close();
          }
        })
        .catch(() => false)
        .finally(() => {
          this.opening = false;
        });
      return;
    }

    super.handleKeydown(event);
  }

  async deletePropertyItem(item) {
    if (!item || item.kind !== "property") {
      return false;
    }

    const propertyName = item.property.name;
    if (!item.defined) {
      new Notice(
        item.target.kind === "project-frontmatter"
          ? `${propertyName} is not set on this project`
          : `${propertyName} is not set on this bullet`,
      );
      return false;
    }

    const result = await (this.isLinkSession()
      ? this.plugin.deleteLinkPickerPropertyValue(this, item)
      : this.isCountedSession()
        ? this.plugin.deleteCountedBulletPropertyValue(
            this.editor,
            this.cursor,
            this.filePath,
            this.taskSession,
            propertyName,
          )
        : item.target.kind === "project-frontmatter"
          ? await this.plugin.deleteProjectNoteScheduledValue(
              this.editor,
              this.cursor,
              this.filePath,
              this.lineText,
              item.currentValue,
            )
          : this.plugin.deleteBulletPropertyValue(
              this.editor,
              this.cursor,
              propertyName,
              {
                filePath: this.filePath,
                expectedLine: this.lineText,
              },
            ));
    if (!result || result.deleted !== true) {
      if (result && result.line) {
        this.lineText = result.line;
        this.bulletSubtitle = truncateBulletPropertySubtitle(result.line);
        this.refreshPropertyItems();
      }
      return false;
    }

    return true;
  }

  async applySelectedValue(item, options = {}) {
    if (!this.selectedPropertyItem || !item) {
      return false;
    }

    if (this.selectedPropertyItem.kind === "refresh-interval") {
      return await this.plugin.applyRefreshIntervalFromPicker(this, item, options);
    }

    const schedulingWorkLog =
      options.schedulingWorkLog || options.workLog || null;

    if (this.isLinkSession()) {
      return await this.plugin.applyLinkPickerPropertyValue(
        this,
        item,
        {
          ...options,
          schedulingWorkLog,
        },
      );
    }

    if (this.isCountedSession()) {
      if (this.selectedPropertyItem.property.values === "priority") {
        return await this.plugin.setCountedBulletPriorityValue(
          this.editor,
          this.cursor,
          this.filePath,
          this.taskSession,
          this.selectedPropertyItem.property,
          item.priorityLevel,
          {
            baseDate: this.valueBaseDate,
            random: this.priorityRandom,
            schedulingWorkLog,
            precomputedRollByLine: options.precomputedRollByLine,
            precomputedScheduledValueByLine:
              options.precomputedScheduledValueByLine,
            rollByLine: options.rollByLine,
            scheduledValueByLine: options.scheduledValueByLine,
          },
        );
      }
      return await this.plugin.setCountedBulletPropertyValue(
        this.editor,
        this.cursor,
        this.filePath,
        this.taskSession,
        this.selectedPropertyItem.property.name,
        item.value,
        { scheduleLog: options.scheduleLog, schedulingWorkLog },
      );
    }

    if (this.selectedPropertyItem.property.values === "priority") {
      return await this.plugin.setBulletPriorityValue(
        this.editor,
        this.cursor,
        this.filePath,
        this.lineText,
        this.selectedPropertyItem.property,
        item.priorityLevel,
        {
          propertyContext: this.propertyContext,
          baseDate: this.valueBaseDate,
          random: this.priorityRandom,
          schedulingWorkLog,
          precomputedRoll: options.precomputedRoll,
        },
      );
    }

    if (this.selectedPropertyItem.target.kind === "project-frontmatter") {
      return await this.plugin.setProjectNoteScheduledValue(
        this.editor,
        this.cursor,
        this.filePath,
        this.lineText,
        this.selectedPropertyItem.currentValue,
        item.value,
        { scheduleLog: options.scheduleLog, schedulingWorkLog },
      );
    }

    return await this.plugin.setBulletPropertyValue(
      this.editor,
      this.cursor,
      this.selectedPropertyItem.property.name,
      item.value,
      {
        filePath: this.filePath,
        expectedLine: this.lineText,
        scheduleLog: options.scheduleLog,
        schedulingWorkLog,
      },
    );
  }
}
// ---- src/460-install-picker-mixins.js ----
function installBulletPropertyPickerMixins(pluginClass, mixins) {
  const installedNames = new Set(
    Reflect.ownKeys(pluginClass.prototype).filter((name) => name !== "constructor"),
  );
  for (const Mixin of mixins) {
    const descriptors = Object.getOwnPropertyDescriptors(Mixin.prototype);
    const names = Reflect.ownKeys(descriptors).filter((name) => name !== "constructor");
    for (const name of names) {
      if (installedNames.has(name)) {
        throw new Error("Duplicate BulletPropertyPickerModal method: " + String(name));
      }
    }
    for (const name of names) {
      Object.defineProperty(pluginClass.prototype, name, descriptors[name]);
      installedNames.add(name);
    }
  }
}

installBulletPropertyPickerMixins(BulletPropertyPickerModal, [
  BulletPropertyPickerTaskCardMixin,
  BulletPropertyPickerScheduleReviewMixin,
  BulletPropertyPickerScheduleWorkLogMixin,
  BulletPropertyPickerCancelLaneMixin,
  BulletPropertyPickerRollWriteMixin,
  BulletPropertyPickerLocalTaskMixin,
  BulletPropertyPickerFilterRenderMixin,
  BulletPropertyPickerCountedDependencyMixin,
  BulletPropertyPickerVaultBatchMixin,
  BulletPropertyPickerVaultCommitMixin,
  BulletPropertyPickerKeydownMixin,
]);
// ---- src/470-keydown-and-freshness.js ----

// Ctrl+[ closes the Task Card and every stage its modal opens. Matches the
// requested chord only: Ctrl alone (no Alt, Meta, or Shift). This is the
// modal's own close path; it does not synthesize Escape or go through Vim.
function isCtrlLeftBracketKeydown(event) {
  return (
    Boolean(event) &&
    event.ctrlKey === true &&
    event.altKey !== true &&
    event.metaKey !== true &&
    event.shiftKey !== true &&
    (event.code === "BracketLeft" || event.key === "[")
  );
}

// The keys that close the Task Card without writing: Escape, bare q / Q
// (Shift allowed for Q; never Ctrl, Meta, or Alt), and Ctrl+[. Composition
// and text-field focus are the caller's guards.
function isTaskCardCloseKeydown(event) {
  if (!event) {
    return false;
  }
  const key = String(event.key || "");
  const ctrl = event.ctrlKey === true;
  const meta = event.metaKey === true;
  const alt = event.altKey === true;
  const shift = event.shiftKey === true;
  return (
    (key === "Escape" && !ctrl && !meta && !alt && !shift) ||
    (key.toLowerCase() === "q" && !ctrl && !meta && !alt) ||
    isCtrlLeftBracketKeydown(event)
  );
}

function isCtrlKey(event, key) {
  return (
    event.ctrlKey === true &&
    event.altKey !== true &&
    event.metaKey !== true &&
    typeof event.key === "string" &&
    event.key.toLowerCase() === key
  );
}

// ---------------------------------------------------------------------------
// freshness review (nav-review): vault-wide due-task jumps (Ctrl+Alt+J/K,
// `]s` / `[s` via the vimrc) and Alt+F / Ctrl+Alt+F refresh.
//
// Reads come from `api.freshness.queue()` / `api.freshness.counts()` on
// bob-ledger-tools (api `version >= 3`); writes go through
// `api.freshness.stampLine` only. Placement is the exception to the
// copy-small-helpers rule: nav never places `[fresh::]` itself, so when
// ledger-tools is absent or old the command shows
// "Bob Ledger Tools api v3 required" and changes nothing. A missing stamp
// only means Bryan sees the task once more; a misplaced stamp could hide
// Tasks fields, so the risky part lives in one place.

const REVIEW_FRESHNESS_API_REQUIRED_NOTICE = "Bob Ledger Tools api v3 required";
const REVIEW_FRESHNESS_KEEP_REQUIRED_NOTICE = "Bob Ledger Tools keep support required";
const REVIEW_QUEUE_CHANGED_NOTICE = "Review queue changed — try again";
const REVIEW_CHECKLIST_UPDATE_LEDGER_NOTICE =
  "Checklist rows close by completion — update bob-ledger-tools";
const REVIEW_CHECKLIST_UPDATE_CYCLER_NOTICE =
  "Checklist rows close by completion — update task-status-cycler";

// The ledger-tools freshness namespace, or null when it is absent or older
// than api `version >= 3`. Never throws.
function getReviewFreshnessApi(app) {
  try {
    const plugins = app && app.plugins && app.plugins.plugins;
    const holder = plugins ? plugins["bob-ledger-tools"] : null;
    const api = holder ? holder.api : null;
    if (!api || Number(api.version) < 3 || !api.freshness) {
      return null;
    }
    return api.freshness;
  } catch (error) {
    return null;
  }
}

// Tier-aware walk behavior (ledger-tools freshness namespace v4) requires
// `api.freshness.version >= 4`. With v3 the walk still works, but notices
// keep the legacy state text and the refresh row keeps the local chain.
function reviewFreshnessSupportsTiers(freshnessApi) {
  try {
    return (
      Boolean(freshnessApi) && Number(freshnessApi.version) >= 4
    );
  } catch (error) {
    return false;
  }
}

// Project/reference tracking review (ledger-tools freshness capability
// `trackerReview`). Legacy v3/v4 queues keep working when the
// capability is absent: they never carry `projects` or `references`
// entries, and every branch below treats a missing capability as "no
// tracker detail".
function reviewFreshnessSupportsTrackers(freshnessApi) {
  try {
    return (
      Boolean(freshnessApi) && freshnessApi.trackerReview === true
    );
  } catch (error) {
    return false;
  }
}

// PRE/POST checklist walk (ledger-tools freshness namespace v7) requires
// `api.freshness.version >= 7` and `checklistTiers === true`. Without it
// the rows still walk when a queue carries `pre`/`post`, but Alt+F
// refuses instead of completing.
function reviewFreshnessSupportsChecklistTiers(freshnessApi) {
  try {
    return (
      Boolean(freshnessApi) &&
      Number(freshnessApi.version) >= 7 &&
      freshnessApi.checklistTiers === true
    );
  } catch (error) {
    return false;
  }
}

// Cycler completion API (v2 `completeTaskAtCursor`), or null.
function getReviewCyclerApi(app) {
  try {
    const plugins = app && app.plugins && app.plugins.plugins;
    const holder = plugins ? plugins["task-status-cycler"] : null;
    const api = holder ? holder.api : null;
    if (
      !api ||
      Number(api.version) < 2 ||
      typeof api.completeTaskAtCursor !== "function"
    ) {
      return null;
    }
    return api;
  } catch (error) {
    return null;
  }
}

function reviewIsChecklistTier(tier) {
  return tier === "pre" || tier === "post";
}

// Machine walk tier for a queue entry: v4 `tier` (plus the `projects`
// and `references` tracker tiers and v7 `pre`/`post` checklist tiers),
// else the legacy v3 `state` mapping (`resurfaced` reads as the RETURNED
// tier). Returns "".
function reviewEntryMachineTier(entry) {
  const tier =
    entry && typeof entry.tier === "string"
      ? entry.tier.trim().toLowerCase()
      : "";
  if (
    tier === "pre" ||
    tier === "new" ||
    tier === "projects" ||
    tier === "pending" ||
    tier === "next" ||
    tier === "returned" ||
    tier === "references" ||
    tier === "rotten" ||
    tier === "post"
  ) {
    return tier;
  }
  const state =
    entry && typeof entry.state === "string"
      ? entry.state.trim().toLowerCase()
      : "";
  if (state === "new") {
    return "new";
  }
  if (state === "rotten") {
    return "rotten";
  }
  if (state === "resurfaced") {
    return "returned";
  }
  return "";
}

// Display tier for a queue entry: v4 `tierLabel`, else the machine tier.
function reviewEntryTierLabel(entry) {
  if (entry && typeof entry.tierLabel === "string" && entry.tierLabel) {
    return entry.tierLabel;
  }
  const tier = reviewEntryMachineTier(entry);
  return tier ? tier.toUpperCase() : "";
}

// True for v4 tiered entries (they carry per-tier ranks).
function reviewEntryHasTierRanks(entry) {
  return (
    Boolean(entry) &&
    Number.isInteger(entry.tierRank) &&
    Number.isInteger(entry.tierTotal)
  );
}

function reviewIsCommitmentTier(tier) {
  return (
    tier === "pre" ||
    tier === "new" ||
    tier === "projects" ||
    tier === "pending" ||
    tier === "next" ||
    tier === "returned" ||
    tier === "references"
  );
}

// Canonical `YYYY-MM-DD` as a day number, or null.
function reviewParseDayNumber(text) {
  const match = /^(\d{4})-(\d{2})-(\d{2})$/.exec(String(text || "").trim());
  if (!match) {
    return null;
  }
  const day = Date.UTC(
    Number(match[1]),
    Number(match[2]) - 1,
    Number(match[3]),
  );
  if (!Number.isFinite(day)) {
    return null;
  }
  return Math.round(day / 86400000);
}

// `2026-10-07` -> `Oct 7`, else the raw text.
function reviewShortDate(text) {
  const months = [
    "Jan", "Feb", "Mar", "Apr", "May", "Jun",
    "Jul", "Aug", "Sep", "Oct", "Nov", "Dec",
  ];
  const match = /^(\d{4})-(\d{2})-(\d{2})$/.exec(String(text || "").trim());
  if (!match) {
    return String(text || "");
  }
  const month = months[Number(match[2]) - 1];
  if (!month) {
    return String(text || "");
  }
  return `${month} ${Number(match[3])}`;
}

// Lane detail for a PENDING/NEXT entry: `never confirmed`,
// `confirmed yesterday`, or `confirmed {n} days ago`, from the age of
// `fresh`. Prefers an explicit `todayText`, else derives the age from
// `daysOverdue + interval` (`dueOn = fresh + interval`).
function reviewLaneConfirmedDetail(entry, todayText) {
  const fresh =
    entry && typeof entry.fresh === "string" && entry.fresh
      ? entry.fresh
      : null;
  if (!fresh) {
    return "never confirmed";
  }
  const freshDay = reviewParseDayNumber(fresh);
  const todayDay = reviewParseDayNumber(todayText);
  let age = null;
  if (freshDay !== null && todayDay !== null) {
    age = todayDay - freshDay;
  } else if (
    entry &&
    Number.isFinite(entry.daysOverdue) &&
    Number.isInteger(entry.interval)
  ) {
    age = Math.max(0, Math.floor(entry.daysOverdue)) + entry.interval;
  }
  if (age === null || !Number.isFinite(age)) {
    return `confirmed ${fresh}`;
  }
  if (age <= 0) {
    return "confirmed today";
  }
  if (age === 1) {
    return "confirmed yesterday";
  }
  return `confirmed ${age} days ago`;
}

// Task freshness stamping (nav-stamps): placement lives in bob-ledger-tools
// (`api.freshness.stampLine` / `setRefreshLine`, api `version >= 3`). This
// plugin never places `[fresh::]` itself: a missing stamp only means Bryan
// sees the task once more, while a misplaced stamp would hide Tasks fields.
// When ledger-tools is absent or old, gestures simply don't stamp. Pure
// planners take the stamper as an injected `stampLine` option (identity by
// default, never throws), applied as the last edit of every rewritten task
// line that stays open.
function identityFreshStampLine(line) {
  return String(line || "");
}

function applyFreshStampLine(line, stamper, dateText) {
  const fn = typeof stamper === "function" ? stamper : identityFreshStampLine;
  try {
    const stamped = fn(String(line || ""), dateText);
    if (typeof stamped === "string") {
      return stamped;
    }
    return String(line || "");
  } catch (error) {
    return String(line || "");
  }
}

function applyFreshRefreshLine(line, refresher, days, dateText) {
  const fn = typeof refresher === "function" ? refresher : null;
  if (!fn) {
    return String(line || "");
  }
  try {
    const out = fn(String(line || ""), days, dateText);
    if (typeof out === "string") {
      return out;
    }
    return String(line || "");
  } catch (error) {
    return String(line || "");
  }
}

function resolveFreshStamper(options) {
  if (options && typeof options.stampLine === "function") {
    return options.stampLine;
  }
  return null;
}

function resolveFreshDateText(options) {
  if (options && typeof options.freshDateText === "string" && options.freshDateText) {
    return options.freshDateText;
  }
  if (options && typeof options.dateText === "string" && options.dateText) {
    return options.dateText;
  }
  return undefined;
}

// First valid `[refresh:: N]` (1-365) on the line, or null. Mirrors the
// ledger-tools placement rule's "first valid existing one" without placing
// anything.
function parseRefreshDaysFromLine(lineText) {
  const text = String(lineText || "");
  const pattern = /(?:\[refresh\s*::\s*([^\]\n]*)\]|\((?:refresh)\s*::\s*([^)\n]*)\))/g;
  let match = pattern.exec(text);
  while (match) {
    const raw = String(match[1] ?? match[2] ?? "").trim();
    if (/^[+-]?\d+$/.test(raw)) {
      const number = Number(raw);
      if (Number.isSafeInteger(number) && number >= 1 && number <= 365) {
        return number;
      }
    }
    match = pattern.exec(text);
  }
  return null;
}

function parseNoteRefreshDays(raw) {
  if (raw === undefined || raw === null) {
    return null;
  }
  const text = String(raw)
    .trim()
    .replace(/^["']+|["']+$/g, "")
    .trim();
  if (!/^[+-]?\d+$/.test(text)) {
    return null;
  }
  const number = Number(text);
  if (!Number.isSafeInteger(number) || number < 1 || number > 365) {
    return null;
  }
  return number;
}

// Effective refresh interval for one task line: the task's `[refresh:: N]`,
// then the note's `task_refresh`, then `freshness.interval`, then 7. Returns
// `{ days, source }` with source one of `task`, `note`, `config`, `default`.
function describeRefreshInterval(lineText, noteRefreshRaw, freshnessApi) {
  // v4 ledger-tools exposes the lane-aware chain (with the Ready-chain
  // interval the task returns to after release) as
  // `api.freshness.intervalForLine`, so nav never re-implements it. v3
  // namespaces keep the local chain below.
  try {
    if (
      freshnessApi &&
      typeof freshnessApi.intervalForLine === "function"
    ) {
      const resolved = freshnessApi.intervalForLine(
        String(lineText || ""),
        noteRefreshRaw,
      );
      if (
        resolved &&
        Number.isInteger(resolved.days) &&
        resolved.days >= 1 &&
        resolved.days <= 365 &&
        typeof resolved.source === "string"
      ) {
        const ready =
          resolved.ready && Number.isInteger(resolved.ready.days)
            ? Object.freeze({
              days: resolved.ready.days,
              source: resolved.ready.source,
            })
            : null;
        return Object.freeze({
          days: resolved.days,
          source: resolved.source,
          ready,
        });
      }
    }
  } catch (error) {
    // Fall through to the local chain.
  }
  const taskDays = parseRefreshDaysFromLine(lineText);
  if (taskDays !== null) {
    return Object.freeze({ days: taskDays, source: "task", ready: null });
  }
  const noteDays = parseNoteRefreshDays(noteRefreshRaw);
  if (noteDays !== null) {
    return Object.freeze({ days: noteDays, source: "note", ready: null });
  }
  let configDays = null;
  try {
    const config = freshnessApi && typeof freshnessApi.config === "function"
      ? freshnessApi.config()
      : null;
    if (config && Number.isInteger(config.interval) && config.interval >= 1 && config.interval <= 365) {
      configDays = config.interval;
    }
  } catch (error) {
    configDays = null;
  }
  // `api.freshness.config()` only exposes `{ interval, ... }` without the
  // internal `intervalFromConfig` flag, so an explicit `interval: 7` and an
  // absent block both read as 7. Follow the plan's picker example and report
  // the fallback as `config` (e.g. `every 7 d (config)`); task and note
  // overrides still win above.
  if (configDays !== null) {
    return Object.freeze({ days: configDays, source: "config", ready: null });
  }
  return Object.freeze({ days: 7, source: "default", ready: null });
}

// Describe the pinned refresh picker row: null when the freshness api (with
// `setRefreshLine`) is absent, or when no open `#task` target exists.
// Otherwise the effective interval, its source, and the detail line the
// picker renders, e.g. `refresh · every 7 d (config)`.
function describeRefreshRow(content, options = {}) {
  const freshnessApi = options.freshnessApi || null;
  if (!freshnessApi || typeof freshnessApi.setRefreshLine !== "function") {
    return null;
  }
  const text = String(content || "");
  const cursorLine = Math.floor(numericOrDefault(options.cursorLine, NaN));
  const taskSession = options.taskSession || null;
  const linkResolved = Array.isArray(options.linkResolved) ? options.linkResolved : null;
  const fallbackNoteRefreshRaw =
    options.noteRefreshRaw !== undefined
      ? options.noteRefreshRaw
      : getNoteTaskRefreshRaw(text);
  const statusOf = (lineText) => getObsidianTaskCheckboxStatus(lineText);
  const isOpenStatus = (status) => status !== null && OPEN_OBSIDIAN_TASK_STATUSES.has(status);
  const detailFor = (lineText, noteRaw) => {
    const interval = describeRefreshInterval(
      lineText,
      noteRaw !== undefined ? noteRaw : fallbackNoteRefreshRaw,
      freshnessApi,
    );
    // Lane tasks read their lane interval, with the task's own refresh
    // kept as the once-Ready return value, e.g.
    // `refresh · every 1 d (next lane) · 14 d once Ready`.
    if (interval.source === "pending" || interval.source === "next") {
      let detail = `refresh · every ${interval.days} d (${interval.source} lane)`;
      if (interval.ready && interval.ready.source === "task") {
        detail += ` · ${interval.ready.days} d once Ready`;
      }
      return Object.freeze({
        days: interval.days,
        source: interval.source,
        detail,
      });
    }
    return Object.freeze({
      days: interval.days,
      source: interval.source,
      detail: `refresh · every ${interval.days} d (${interval.source})`,
    });
  };
  const noteRawForLinkTarget = (target) => {
    if (target && typeof target.content === "string") {
      return getNoteTaskRefreshRaw(target.content);
    }
    return fallbackNoteRefreshRaw;
  };
  if (linkResolved) {
    if (linkResolved.length === 0) {
      return null;
    }
    const open = linkResolved.filter((target) => {
      const raw = String((target && target.rawLine) || "");
      return isObsidianTaskLine(raw) && isOpenStatus(statusOf(raw));
    });
    if (open.length === 0) {
      return null;
    }
    const first = detailFor(String(open[0].rawLine || ""), noteRawForLinkTarget(open[0]));
    const mixed = open.some((target) => {
      const current = detailFor(String(target.rawLine || ""), noteRawForLinkTarget(target));
      return current.days !== first.days || current.source !== first.source;
    });
    return Object.freeze({
      kind: "link",
      count: linkResolved.length,
      openCount: open.length,
      days: mixed ? null : first.days,
      source: mixed ? null : first.source,
      detail: mixed ? "refresh · mixed" : first.detail,
      mixed,
    });
  }
  if (taskSession && Array.isArray(taskSession.targets) && taskSession.targets.length > 0) {
    const open = taskSession.targets.filter((target) => {
      const raw = String((target && target.rawLine) || "");
      return isObsidianTaskLine(raw) && isOpenStatus(statusOf(raw));
    });
    if (open.length === 0) {
      return null;
    }
    const first = detailFor(String(open[0].rawLine || ""));
    const mixed = open.some((target) => {
      const current = detailFor(String(target.rawLine || ""));
      return current.days !== first.days || current.source !== first.source;
    });
    return Object.freeze({
      kind: "task",
      count: taskSession.targets.length,
      openCount: open.length,
      days: mixed ? null : first.days,
      source: mixed ? null : first.source,
      detail: mixed ? "refresh · mixed" : first.detail,
      mixed,
    });
  }
  if (Number.isFinite(cursorLine)) {
    const lines = text.split(/\r?\n/);
    const line = String(lines[cursorLine] || "");
    if (!isObsidianTaskLine(line)) {
      return null;
    }
    if (!isOpenStatus(statusOf(line))) {
      return null;
    }
    const resolved = detailFor(line);
    return Object.freeze({
      kind: "task",
      count: 1,
      openCount: 1,
      days: resolved.days,
      source: resolved.source,
      detail: resolved.detail,
      mixed: false,
    });
  }
  return null;
}

const REFRESH_ROW_PRESET_DAYS = Object.freeze([2, 3, 7, 14, 30, 90, 180, 365]);

// Value-stage items for the refresh row: presets, plus "use default" which
// clears `[refresh:: N]` (via `setRefreshLine` with null, which also stamps).
function createRefreshValueItems(currentDays) {
  const items = REFRESH_ROW_PRESET_DAYS.map((days) => Object.freeze({
    kind: "value",
    value: days,
    label: `${days} days`,
    detail: days === currentDays ? "Current value" : `every ${days} d`,
    current: days === currentDays,
    dynamic: false,
    refreshDays: days,
    searchText: `${days} ${days} days every ${days} d refresh`,
  }));
  items.push(Object.freeze({
    kind: "value",
    value: null,
    label: "use default",
    detail: currentDays === null || currentDays === undefined ? "Current value" : "clear [refresh:: N]",
    current: currentDays === null || currentDays === undefined,
    dynamic: false,
    refreshDays: null,
    searchText: "use default clear default refresh",
  }));
  return Object.freeze(items);
}

// A typed custom refresh value: an integer 1-365, else null.
function parseRefreshCustomValue(query) {
  const text = String(query || "").trim();
  if (!/^[+-]?\d+$/.test(text)) {
    return null;
  }
  const number = Number(text);
  if (!Number.isSafeInteger(number) || number < 1 || number > 365) {
    return null;
  }
  return number;
}

// Raw `task_refresh` value from a note's frontmatter, or undefined when
// absent. Lightweight: no YAML dependency, mirrors the ledger-tools
// `task_refresh` parse (integer 1-365, quoted or not).
function getNoteTaskRefreshRaw(content) {
  try {
    const text = String(content || "");
    const match = /^---[ \t]*\r?\n([\s\S]*?)\r?\n---(?:\r?\n|$)/.exec(text);
    if (!match) {
      return undefined;
    }
    const frontmatter = match[1];
    const lineMatch = /^[ \t]*task_refresh[ \t]*:[ \t]*(.+?)[ \t]*$/m.exec(frontmatter);
    if (!lineMatch) {
      return undefined;
    }
    return lineMatch[1];
  } catch (error) {
    return undefined;
  }
}

// Stable identity for a queue entry across re-reads. Ledger-tools entries
// carry `key`; fall back to path plus the 1-based line.
function reviewQueueEntryKey(entry) {
  if (entry && typeof entry.key === "string" && entry.key) {
    return entry.key;
  }
  const path = entry && typeof entry.path === "string" ? entry.path : "";
  const line = entry && Number.isInteger(entry.line) ? entry.line : 0;
  return `${path}:${line}`;
}

// True when `anchor` was recorded on `todayText` (YYYY-MM-DD). A missing
// day on either side is treated as current so legacy anchors still walk.
function reviewAnchorIsCurrentDay(anchor, todayText) {
  if (!anchor || typeof anchor !== "object") {
    return false;
  }
  const day = typeof anchor.day === "string" ? anchor.day.trim() : "";
  if (!day) {
    return true;
  }
  const today = typeof todayText === "string" ? todayText.trim() : "";
  if (!today) {
    return true;
  }
  return day === today;
}

// Among unhandled entries in the cursor's file, match
// `originalMarkdown === cursorText` first. Several matches prefer the
// cursor line, then the nearest. Fall back to the line number only when
// no text matches. Returns a 0-based queue index or -1.
function findReviewCursorIndex(list, cursor, handledKeys) {
  if (!cursor || typeof cursor !== "object") {
    return -1;
  }
  const rows = Array.isArray(list) ? list : [];
  const cursorPath = String(cursor.path || "");
  const cursorLine = Math.floor(numericOrDefault(cursor.line, Number.NaN));
  const cursorText = String(cursor.text || "");
  const handled =
    handledKeys instanceof Set
      ? handledKeys
      : new Set(Array.isArray(handledKeys) ? handledKeys : []);
  const candidates = [];
  for (let index = 0; index < rows.length; index += 1) {
    const entry = rows[index];
    if (!entry || String(entry.path || "") !== cursorPath) {
      continue;
    }
    if (handled.has(reviewQueueEntryKey(entry))) {
      continue;
    }
    candidates.push({
      index,
      line: Number(entry.line),
      text: String(entry.originalMarkdown || ""),
    });
  }
  if (candidates.length === 0) {
    return -1;
  }
  if (cursorText) {
    const textHits = candidates.filter((item) => item.text === cursorText);
    if (textHits.length === 1) {
      return textHits[0].index;
    }
    if (textHits.length > 1) {
      if (Number.isInteger(cursorLine)) {
        const onLine = textHits.find((item) => item.line === cursorLine);
        if (onLine) {
          return onLine.index;
        }
        let nearest = textHits[0];
        let nearestDist = Math.abs(nearest.line - cursorLine);
        for (const item of textHits.slice(1)) {
          const dist = Math.abs(item.line - cursorLine);
          if (
            dist < nearestDist ||
            (dist === nearestDist && item.index < nearest.index)
          ) {
            nearest = item;
            nearestDist = dist;
          }
        }
        return nearest.index;
      }
      return textHits[0].index;
    }
  }
  if (Number.isInteger(cursorLine)) {
    const lineHit = candidates.find((item) => item.line === cursorLine);
    if (lineHit) {
      return lineHit.index;
    }
  }
  return -1;
}

function matchReviewChecklistCursor(queue, cursor) {
  const list = Array.isArray(queue) ? queue : [];
  const index = findReviewCursorIndex(list, cursor, new Set());
  if (index < 0) {
    return null;
  }
  const entry = list[index];
  return reviewIsChecklistTier(reviewEntryMachineTier(entry)) ? entry : null;
}

// Walk anchor: where the walk is. Recorded on every successful landing
// and every Alt+F / Ctrl+Alt+F stamp. Holds the handled entry keys, the
// handled task's path/line/tier, and the ordered keys after and before
// them in the queue they came from, so `]s` after an Alt+N release,
// Ctrl+Shift+Enter, or a roll continues from the successor (and `[s` from
// the predecessor) instead of restarting at rank 1.
function buildReviewAnchor(queue, handledKeys, fallbackRank, day) {
  const list = Array.isArray(queue) ? queue.slice() : [];
  const keys = list.map((entry) => reviewQueueEntryKey(entry));
  const handled = new Set(Array.isArray(handledKeys) ? handledKeys : []);
  const positions = [];
  keys.forEach((key, index) => {
    if (handled.has(key)) {
      positions.push(index);
    }
  });
  if (positions.length === 0) {
    return null;
  }
  const at = Math.max(...positions);
  const holder = list[at];
  const afterKeys = keys.slice(at + 1);
  const beforeKeys = keys.slice(0, at).filter((key) => !handled.has(key));
  const rank =
    holder && Number.isInteger(holder.rank)
      ? holder.rank
      : Number.isInteger(fallbackRank)
        ? fallbackRank
        : at + 1;
  const dayText =
    typeof day === "string" && day.trim() ? day.trim() : null;
  return Object.freeze({
    keys: Object.freeze(Array.from(handled)),
    rank,
    count: handled.size,
    path: holder && typeof holder.path === "string" ? holder.path : "",
    line: holder && Number.isInteger(holder.line) ? holder.line : null,
    tier: reviewEntryMachineTier(holder) || null,
    day: dayText,
    afterKeys: Object.freeze(afterKeys),
    beforeKeys: Object.freeze(beforeKeys),
  });
}

// Remaining walk counts after excluding handled keys: `{ commitments,
// rotten, post, pre }`. Commitments are the PRE/NEW/PROJECTS/PENDING/
// NEXT/RETURNED/REFERENCES tiers. POST is the closing tier.
function reviewWalkRemaining(queue, excludedKeys) {
  const excluded =
    excludedKeys instanceof Set
      ? excludedKeys
      : new Set(Array.isArray(excludedKeys) ? excludedKeys : []);
  let commitments = 0;
  let rotten = 0;
  let post = 0;
  let pre = 0;
  for (const entry of Array.isArray(queue) ? queue : []) {
    if (excluded.has(reviewQueueEntryKey(entry))) {
      continue;
    }
    const tier = reviewEntryMachineTier(entry);
    if (tier === "pre") {
      pre += 1;
      commitments += 1;
    } else if (reviewIsCommitmentTier(tier)) {
      commitments += 1;
    } else if (tier === "rotten") {
      rotten += 1;
    } else if (tier === "post") {
      post += 1;
    }
  }
  return Object.freeze({ commitments, rotten, post, pre });
}

// Boundary line prepended when a forward step leaves a commitment tier
// for ROTTEN or (ROTTEN empty) POST, or null when no boundary applies:
// - `Commitments done \u2014 {n} ROTTEN left` when none remain;
// - `ROTTEN next \u2014 {m} commitments still due` otherwise.
// Into ROTTEN, append ` · ]S closes the review` when POST remains.
// A step from an unknown origin only shows the done line (when zero
// remain); a step within ROTTEN never shows one.
function buildReviewBoundaryNotice(options = {}) {
  const dest = String(options.destTier || "").trim().toLowerCase();
  if (dest !== "rotten" && dest !== "post") {
    return null;
  }
  const origin =
    options.originTier === null ||
    options.originTier === undefined ||
    String(options.originTier).trim() === ""
      ? null
      : String(options.originTier).trim().toLowerCase();
  if (origin !== null && !reviewIsCommitmentTier(origin)) {
    return null;
  }
  const commitments = Number.isInteger(options.commitmentsLeft)
    ? options.commitmentsLeft
    : null;
  const rotten = Number.isInteger(options.rottenLeft)
    ? options.rottenLeft
    : null;
  const postLeft = Number.isInteger(options.postLeft)
    ? options.postLeft
    : 0;
  if (commitments === null) {
    return null;
  }
  let line = null;
  if (commitments === 0) {
    line = `Commitments done \u2014 ${rotten === null ? 0 : rotten} ROTTEN left`;
  } else if (origin === null) {
    return null;
  } else if (dest === "rotten") {
    line = `ROTTEN next \u2014 ${commitments} commitments still due`;
  } else {
    return null;
  }
  if (dest === "rotten" && postLeft > 0) {
    return `${line} · ]S closes the review`;
  }
  return line;
}

// Resolve one anchor step over `remaining` (the queue minus the handled
// keys). Forward takes the first surviving `afterKeys` entry, backward
// the last surviving `beforeKeys` entry, wrapping to the first/last
// remaining entry. Ranks count over `remaining` (1-based).
function resolveReviewAnchorTarget(remaining, anchor, direction) {
  const rest = Array.isArray(remaining) ? remaining : [];
  if (rest.length === 0) {
    return null;
  }
  const atRest = (key) =>
    rest.findIndex((entry) => reviewQueueEntryKey(entry) === key);
  if (direction < 0) {
    const before = anchor && Array.isArray(anchor.beforeKeys)
      ? anchor.beforeKeys
      : [];
    for (let index = before.length - 1; index >= 0; index -= 1) {
      const found = atRest(before[index]);
      if (found >= 0) {
        return Object.freeze({
          entry: rest[found],
          rank: found + 1,
          total: rest.length,
          wrapped: false,
        });
      }
    }
    return Object.freeze({
      entry: rest[rest.length - 1],
      rank: rest.length,
      total: rest.length,
      wrapped: true,
    });
  }
  const after = anchor && Array.isArray(anchor.afterKeys)
    ? anchor.afterKeys
    : [];
  for (const key of after) {
    const found = atRest(key);
    if (found >= 0) {
      return Object.freeze({
        entry: rest[found],
        rank: found + 1,
        total: rest.length,
        wrapped: false,
      });
    }
  }
  return Object.freeze({
    entry: rest[0],
    rank: 1,
    total: rest.length,
    wrapped: true,
  });
}

// After the one-step landing, move `repeat - 1` further indexes on the
// same walk list (full queue for a cursor hit or no-origin fallback;
// remaining for an anchor). Absent or invalid `repeat` is 1.
function applyReviewJumpRepeat(step, walkList, direction, repeatRaw) {
  if (!step || step.kind !== "jump") {
    return step;
  }
  const repeat = normalizeVimRepeat(repeatRaw);
  if (repeat <= 1) {
    return Object.freeze({
      kind: "jump",
      entry: step.entry,
      rank: step.rank,
      total: step.total,
      wrapped: step.wrapped,
      originTier: step.originTier,
    });
  }
  const list = Array.isArray(walkList) ? walkList : [];
  if (list.length === 0) {
    return Object.freeze({ kind: "empty" });
  }
  const wantKey = reviewQueueEntryKey(step.entry);
  const firstIndex = list.findIndex(
    (entry) =>
      entry === step.entry || reviewQueueEntryKey(entry) === wantKey,
  );
  if (firstIndex < 0) {
    return Object.freeze({
      kind: "jump",
      entry: step.entry,
      rank: step.rank,
      total: step.total,
      wrapped: step.wrapped,
      originTier: step.originTier,
    });
  }
  const extra = repeat - 1;
  const raw = firstIndex + direction * extra;
  const rem = raw % list.length;
  const finalIndex = rem < 0 ? rem + list.length : rem;
  return Object.freeze({
    kind: "jump",
    entry: list[finalIndex],
    rank: finalIndex + 1,
    total: list.length,
    wrapped: Boolean(step.wrapped) || raw < 0 || raw >= list.length,
    originTier: step.originTier,
  });
}

// Pure jump position over a freshly read queue. Returns `{ kind: "empty" }`
// or `{ kind: "jump", entry, rank, total, wrapped, originTier }`
// (`rank` is 1-based). `endpoint` ("first"/"last") selects that queue
// endpoint with full-queue rank/total, `wrapped: false`, and a null origin,
// ignoring cursor, anchor, and `repeat`. `direction` is +1 (next) or -1
// (prev); `repeat` is the total number of queue steps (default 1).
// `cursor` is `{ path, line, text }` with a 1-based line; `stamped` (or
// `anchor`) is the walk anchor from the last landing or Alt+F write (the
// Tasks cache lags, so handled keys are skipped by key). Origin resolves
// in order: the cursor on a live (unhandled) queue entry goes to its
// neighbor in `direction`; else the anchor goes to its first surviving
// successor (`]s`) or last surviving predecessor (`[s`), wrapping with
// the notice; else the first or last entry. Legacy `{ keys, rank, count }`
// anchors without before/after keys keep the rank-skip behavior forward,
// mirrored backward. Extra counted steps continue from that one-step
// landing on the same walk list; `originTier` stays the one-step origin.
// ---- src/480-review-jump-and-nav-api.js ----
function reviewLineChecklistKind(line) {
  const tokens = String(line || "").toLowerCase().match(/#[^\s#]+/g) || [];
  const tags = new Set(tokens);
  if (!tags.has("#gtd")) {
    return null;
  }
  if (tags.has("#pre")) {
    return "pre";
  }
  if (tags.has("#post")) {
    return "post";
  }
  return null;
}

function planReviewJump(queue, options = {}) {
  const list = Array.isArray(queue) ? queue.slice() : [];
  const direction = options.direction < 0 ? -1 : 1;
  if (list.length === 0) {
    return Object.freeze({ kind: "empty" });
  }
  const endpointRaw =
    options && typeof options.endpoint === "string"
      ? options.endpoint.trim().toLowerCase()
      : "";
  if (endpointRaw === "first" || endpointRaw === "last") {
    const index = endpointRaw === "first" ? 0 : list.length - 1;
    return Object.freeze({
      kind: "jump",
      entry: list[index],
      rank: index + 1,
      total: list.length,
      wrapped: false,
      originTier: null,
    });
  }
  const finish = (step, walkList) =>
    applyReviewJumpRepeat(step, walkList, direction, options.repeat);
  const todayText =
    options && typeof options.todayText === "string" ? options.todayText : "";
  let anchor =
    options.anchor && typeof options.anchor === "object"
      ? options.anchor
      : options.stamped && typeof options.stamped === "object"
        ? options.stamped
        : null;
  if (anchor && !reviewAnchorIsCurrentDay(anchor, todayText)) {
    anchor = null;
  }
  const handledKeys = new Set(
    anchor && Array.isArray(anchor.keys) ? anchor.keys : [],
  );
  const hasAnchorShape =
    Boolean(anchor) &&
    (Array.isArray(anchor.afterKeys) || Array.isArray(anchor.beforeKeys));
  const cursor =
    options.cursor && typeof options.cursor === "object"
      ? options.cursor
      : null;
  // The cursor on a just-handled (stamped, released, or rolled) task is
  // not a live queue entry, even when the lagging Tasks cache still
  // lists it: handled keys never match here, so the anchor below
  // continues the walk instead of stepping from a stale position.
  // Identity is text-first so a recurrence insert above the cursor
  // cannot make `]s` skip the next chore.
  const cursorIndex = findReviewCursorIndex(list, cursor, handledKeys);
  if (cursorIndex >= 0) {
    let index = cursorIndex + direction;
    let wrapped = false;
    if (index < 0) {
      index = list.length - 1;
      wrapped = true;
    } else if (index >= list.length) {
      index = 0;
      wrapped = true;
    }
    return finish(
      {
        kind: "jump",
        entry: list[index],
        rank: index + 1,
        total: list.length,
        wrapped,
        originTier: reviewEntryMachineTier(list[cursorIndex]) || null,
      },
      list,
    );
  }
  if (anchor && (handledKeys.size > 0 || hasAnchorShape)) {
    const remaining = list.filter(
      (entry) => !handledKeys.has(reviewQueueEntryKey(entry)),
    );
    if (remaining.length === 0) {
      return Object.freeze({ kind: "empty" });
    }
    if (hasAnchorShape) {
      const resolved = resolveReviewAnchorTarget(
        remaining,
        anchor,
        direction,
      );
      if (!resolved) {
        return Object.freeze({ kind: "empty" });
      }
      const originTier =
        anchor && typeof anchor.tier === "string" && anchor.tier
          ? String(anchor.tier).trim().toLowerCase() || null
          : null;
      return finish(
        {
          kind: "jump",
          entry: resolved.entry,
          rank: resolved.rank,
          total: resolved.total,
          wrapped: resolved.wrapped,
          originTier,
        },
        remaining,
      );
    }
    if (Number.isInteger(anchor.rank)) {
      const skip = Math.max(
        0,
        anchor.rank -
          Math.max(0, Math.floor(numericOrDefault(anchor.count, 0))),
      );
      const originTier =
        anchor && typeof anchor.tier === "string" && anchor.tier
          ? String(anchor.tier).trim().toLowerCase() || null
          : null;
      if (direction < 0) {
        const at = Math.min(skip - 1, remaining.length - 1);
        if (at >= 0) {
          return finish(
            {
              kind: "jump",
              entry: remaining[at],
              rank: at + 1,
              total: remaining.length,
              wrapped: false,
              originTier,
            },
            remaining,
          );
        }
        return finish(
          {
            kind: "jump",
            entry: remaining[remaining.length - 1],
            rank: remaining.length,
            total: remaining.length,
            wrapped: true,
            originTier,
          },
          remaining,
        );
      }
      if (skip < remaining.length) {
        return finish(
          {
            kind: "jump",
            entry: remaining[skip],
            rank: skip + 1,
            total: remaining.length,
            wrapped: false,
            originTier,
          },
          remaining,
        );
      }
      return finish(
        {
          kind: "jump",
          entry: remaining[0],
          rank: 1,
          total: remaining.length,
          wrapped: true,
          originTier,
        },
        remaining,
      );
    }
  }
  const index = direction < 0 ? list.length - 1 : 0;
  return finish(
    {
      kind: "jump",
      entry: list[index],
      rank: index + 1,
      total: list.length,
      wrapped: false,
      originTier: null,
    },
    list,
  );
}

// Resolve a queue entry to a 0-based line without writing: the entry's
// `originalMarkdown` still at `line`, else a unique exact match in the file
// (skipping frontmatter and fences). Anything else is a stale queue.
function resolveReviewQueueLine(content, entry) {
  const text = String(content || "");
  const { lines } = splitMarkdownContent(text);
  const want =
    entry && typeof entry.originalMarkdown === "string"
      ? entry.originalMarkdown
      : "";
  const oneBased = entry && Number.isInteger(entry.line) ? entry.line : null;
  if (
    oneBased !== null &&
    oneBased >= 1 &&
    oneBased <= lines.length &&
    lines[oneBased - 1] === want
  ) {
    return Object.freeze({ ok: true, line: oneBased - 1, source: "line" });
  }
  if (!want) {
    return Object.freeze({ ok: false, reason: "stale" });
  }
  const contexts = getMarkdownLineContexts(text);
  const hits = [];
  for (let index = 0; index < lines.length; index += 1) {
    if (lines[index] !== want) {
      continue;
    }
    const context = contexts[index];
    if (context && (context.inFrontmatter || context.inFence)) {
      continue;
    }
    hits.push(index);
  }
  if (hits.length === 1) {
    return Object.freeze({ ok: true, line: hits[0], source: "text" });
  }
  return Object.freeze({ ok: false, reason: "stale" });
}

// Tier-aware jump notice. v4 entries (with per-tier ranks) read
// `Review {rank}/{total} · {TIER} {tierRank}/{tierTotal} · {detail}`:
// NEW has no detail; PROJECTS names the empty-project confirmation;
// PENDING/NEXT name the confirmation age; RETURNED names the return
// date; ROTTEN names the overdue age and interval (or `due today`).
// Lane tiers add a second line with the keep/release/today actions.
// Legacy v3 entries keep today's state text.
function formatReviewJumpNoticeFromView(entry, rank, total, options = {}) {
  const viewFn =
    options && typeof options.reviewEntryView === "function"
      ? options.reviewEntryView
      : null;
  if (!viewFn || !reviewEntryHasTierRanks(entry)) {
    return null;
  }
  try {
    const todayText =
      options && typeof options.todayText === "string"
        ? options.todayText
        : null;
    const trackers =
      options && typeof options.trackers === "boolean"
        ? options.trackers
        : true;
    const presentation = viewFn(entry, { todayText });
    if (
      !presentation ||
      typeof presentation !== "object" ||
      presentation.ok === false ||
      !presentation.label
    ) {
      return null;
    }
    const label = String(presentation.label);
    const head = `Review ${rank}/${total} · ${label} ${entry.tierRank}/${entry.tierTotal}`;
    const tier =
      typeof presentation.tier === "string" && presentation.tier
        ? presentation.tier
        : reviewEntryMachineTier(entry);
    let detail =
      typeof presentation.detail === "string" ? presentation.detail : "";
    if ((tier === "projects" || tier === "references") && !trackers) {
      detail = "";
    }
    const actionHint =
      typeof presentation.actionHint === "string" ? presentation.actionHint : "";
    const lines = [detail ? `${head} · ${detail}` : head];
    if (actionHint && options.omitActionHint !== true) {
      lines.push(actionHint);
    }
    const wrapped =
      options && options.wrapped === true ? " · wrapped around" : "";
    return lines.join("\n") + wrapped;
  } catch (error) {
    return null;
  }
}

function buildReviewJumpNotice(entry, rank, total, options = {}) {
  const fromView = formatReviewJumpNoticeFromView(entry, rank, total, options);
  if (fromView !== null) {
    return fromView;
  }
  const todayText =
    options && typeof options.todayText === "string"
      ? options.todayText
      : null;
  const trackers =
    options && typeof options.trackers === "boolean"
      ? options.trackers
      : true;
  if (reviewEntryHasTierRanks(entry)) {
    const label = reviewEntryTierLabel(entry) || "REVIEW";
    const tier = reviewEntryMachineTier(entry);
    const head = `Review ${rank}/${total} · ${label} ${entry.tierRank}/${entry.tierTotal}`;
    let detail = "";
    if ((tier === "projects" || tier === "references") && trackers) {
      const fresh =
        entry && typeof entry.fresh === "string" && entry.fresh
          ? entry.fresh
          : null;
      const interval =
        entry && Number.isInteger(entry.interval) ? entry.interval : null;
      const every = interval !== null ? ` · every ${interval}d` : "";
      const kind = tier === "projects" ? "Empty project" : "Reference";
      if (!fresh) {
        detail = `${kind} · never confirmed${every}`;
      } else {
        const overdue =
          entry && Number.isFinite(entry.daysOverdue)
            ? Math.max(0, Math.floor(entry.daysOverdue))
            : null;
        const lead =
          overdue === null
            ? entry && typeof entry.dueOn === "string" && entry.dueOn
              ? `due ${reviewShortDate(entry.dueOn)}`
              : "due"
            : overdue < 1
              ? "due today"
              : `${overdue}d overdue`;
        detail = `${kind} · ${lead} · confirmed ${reviewShortDate(fresh)}${every}`;
      }
    } else if (tier === "pending" || tier === "next") {
      detail = reviewLaneConfirmedDetail(entry, todayText);
    } else if (tier === "returned") {
      const since =
        entry && typeof entry.dueOn === "string" && entry.dueOn
          ? entry.dueOn
          : entry && typeof entry.fresh === "string"
            ? entry.fresh
            : "";
      detail = since ? `back since ${reviewShortDate(since)}` : "returned";
    } else if (tier === "rotten") {
      const interval =
        entry && Number.isInteger(entry.interval) ? entry.interval : null;
      const every = interval !== null ? ` · every ${interval}d` : "";
      const overdue =
        entry && Number.isFinite(entry.daysOverdue)
          ? Math.max(0, Math.floor(entry.daysOverdue))
          : null;
      detail =
        overdue === null || overdue < 1
          ? `due today${every}`
          : `rotten ${overdue}d${every}`;
    } else if (tier === "pre") {
      detail = "checklist";
    } else if (tier === "post") {
      detail = "closeout";
    }
    const lines = [detail ? `${head} · ${detail}` : head];
    if (options.omitActionHint !== true && tier === "pending") {
      lines.push("Still pending? Alt+F keep · Alt+N release · Ctrl+Shift+Enter today");
    } else if (options.omitActionHint !== true && tier === "next") {
      lines.push("Still next? Alt+F keep · Alt+N release · Ctrl+Shift+Enter today");
    } else if (options.omitActionHint !== true && tier === "pre") {
      lines.push("Ctrl+Alt+F done → next · ]s skip");
    } else if (options.omitActionHint !== true && tier === "post") {
      lines.push("Alt+F done · closes the review");
    }
    const wrapped =
      options && options.wrapped === true ? " · wrapped around" : "";
    return lines.join("\n") + wrapped;
  }
  const state = entry && typeof entry.state === "string" ? entry.state : "";
  let detail = state;
  if (state === "new") {
    detail = "NEW";
  } else if (state === "rotten") {
    const overdue =
      entry && Number.isFinite(entry.daysOverdue)
        ? entry.daysOverdue
        : null;
    detail = overdue === null ? "rotten" : `rotten ${overdue}d`;
  } else if (state === "resurfaced") {
    detail = "resurfaced";
  }
  const wrapped =
    options && options.wrapped === true ? " · wrapped around" : "";
  return `Review ${rank}/${total} · ${detail}${wrapped}`;
}

function formatReviewPostLandingTail(remaining) {
  const counts = remaining && typeof remaining === "object" ? remaining : {};
  const commitments = Number.isInteger(counts.commitments)
    ? counts.commitments
    : 0;
  const rotten = Number.isInteger(counts.rotten) ? counts.rotten : 0;
  return ` · ${commitments} commitments due · ${rotten} ROTTEN left`;
}

function appendReviewPostLandingTail(notice, remaining) {
  const tail = formatReviewPostLandingTail(remaining);
  const lines = String(notice || "").split("\n");
  if (lines.length === 0 || (lines.length === 1 && !lines[0])) {
    return tail.trim();
  }
  lines[0] = `${lines[0]}${tail}`;
  return lines.join("\n");
}

// `Nothing due for review · ✓ 12 today` (the upkeep meter: tasks
// stamped today outside the Pending/Next lanes).
function buildReviewEmptyNotice(counts) {
  const upkeep =
    counts && Number.isInteger(counts.upkeepToday)
      ? counts.upkeepToday
      : counts && Number.isFinite(counts.refreshedToday)
        ? counts.refreshedToday
        : 0;
  return `Nothing due for review · ✓ ${upkeep} today`;
}

// Refusal class for one Alt+F target line: non-tasks, done and cancelled
// tasks, and recurring tasks are never stamped. Every open status
// (` `, `/`, `*`, `?`) stamps, because a Next, Pending or Blocked task may
// come back to Ready later.
function classifyFreshStampTarget(rawLine) {
  const line = String(rawLine || "");
  if (!isObsidianTaskLine(line)) {
    return Object.freeze({ ok: false, refusal: "not-task" });
  }
  const status = getObsidianTaskCheckboxStatus(line);
  if (status === null || !OPEN_OBSIDIAN_TASK_STATUSES.has(status)) {
    return Object.freeze({ ok: false, refusal: "closed" });
  }
  if (isRecurringTaskLine(line)) {
    return Object.freeze({ ok: false, refusal: "recurring" });
  }
  return Object.freeze({ ok: true, refusal: null });
}

function freshStampRefusalNotice(refusal) {
  if (refusal === "recurring") {
    return "recurring · not reviewed";
  }
  if (refusal === "closed") {
    return "Task is closed · not reviewed";
  }
  if (refusal === "stamp") {
    return "Could not update task; no tasks were updated";
  }
  return "Cursor is not on a task or Task Link";
}

// Pure stamp plan over 0-based targets: classify every target first so one
// refusal refuses the whole batch with the note unchanged, then stamp each
// line through the injected `stamper`. Each target is a 0-based line index
// (legacy) or `{ line, path, raw, counted }` with the pre-write 0-based
// line, the note path, the pre-write raw text, and the exact-eligibility
// decision (`docs/freshness.md` §2a). The stamper runs as
// `stamper(before, dateText, decision)` where `decision` is
// `{ counted, path, line, raw }` (legacy index targets decide
// `{ counted: false }` with no path/raw); keep stampers pass `counted`
// through to `api.freshness.keepLine`, while legacy stampers ignore the
// third argument. A throwing stamper refuses the batch (`stamp`) with no
// partial write, so a missing/throwing v5 `keepLine` fails without writing
// instead of falling back to the now-resetting generic stamper. Returns
// `{ ok, refusal, content, stamped }` where `stamped` is
// `[{ line, before, after, counted }]`.
function planFreshStampBatch(content, targetLines, stamper, dateText) {
  const text = String(content || "");
  const { lines, lineEnding } = splitMarkdownContent(text);
  const apply = typeof stamper === "function" ? stamper : (line) => line;
  const rawTargets = Array.isArray(targetLines) ? targetLines : [];
  const targets = rawTargets.map((target) => {
    if (target !== null && typeof target === "object") {
      const line = Math.floor(numericOrDefault(target.line, Number.NaN));
      return Object.freeze({
        line,
        path:
          target.path === undefined || target.path === null
            ? null
            : String(target.path),
        raw:
          target.raw === undefined || target.raw === null
            ? null
            : String(target.raw),
        counted: target.counted === true,
      });
    }
    return Object.freeze({
      line: Math.floor(numericOrDefault(target, Number.NaN)),
      path: null,
      raw: null,
      counted: false,
    });
  });
  for (const target of targets) {
    const check = classifyFreshStampTarget(lines[target.line]);
    if (!check.ok) {
      return Object.freeze({
        ok: false,
        refusal: check.refusal,
        content: text,
        stamped: Object.freeze([]),
      });
    }
  }
  const next = lines.slice();
  const stamped = [];
  for (const target of targets) {
    const before = String(lines[target.line] || "");
    const decision = Object.freeze({
      counted: target.counted,
      path: target.path,
      line: target.line,
      raw: target.raw === null ? before : target.raw,
    });
    let after;
    try {
      after = String(apply(before, dateText, decision) ?? before);
    } catch (error) {
      return Object.freeze({
        ok: false,
        refusal: "stamp",
        content: text,
        stamped: Object.freeze([]),
      });
    }
    next[target.line] = after;
    stamped.push(
      Object.freeze({
        line: target.line,
        before,
        after,
        counted: target.counted,
      }),
    );
  }
  return Object.freeze({
    ok: true,
    refusal: null,
    content: next.join(lineEnding),
    stamped: Object.freeze(stamped),
  });
}

// Pure freshness refresh plan with an optional Pending Work Log summary.
// Every target is stamped first, preserving the planner's all-or-nothing
// refusal behavior, then one entry is prepended for each stamped pre-write
// Pending (`[/]`) task. The shared inserter preserves marker ownership,
// indentation, line endings, and existing child blocks.
function planFreshStampBatchWithWorkLogs(
  content,
  targetLines,
  stamper,
  dateText,
  summary,
) {
  const stampPlan = planFreshStampBatch(content, targetLines, stamper, dateText);
  if (!stampPlan.ok) {
    return Object.freeze({ ...stampPlan, workLogWrittenCount: 0 });
  }
  const normalized = normalizeLaneWorkSummary(summary);
  if (!normalized) {
    return Object.freeze({ ...stampPlan, workLogWrittenCount: 0 });
  }
  const { lines, lineEnding } = splitMarkdownContent(stampPlan.content);
  const pendingLines = Array.from(
    new Set(
      stampPlan.stamped
        .filter((entry) => isPendingWorkLogTargetRawLine(entry.before))
        .map((entry) => entry.line),
    ),
  ).sort((a, b) => b - a);
  let workLogWrittenCount = 0;
  for (const line of pendingLines) {
    if (insertLaneWorkLogEntry(lines, line, normalized, dateText)) {
      workLogWrittenCount += 1;
    }
  }
  return Object.freeze({
    ...stampPlan,
    content: lines.join(lineEnding),
    workLogWrittenCount,
  });
}

// True when the line already carries today's stamp (re-stamping it repairs
// placement at most and does not grow the "refreshed today" count).
function freshStampLineHasToday(rawLine, dateText) {
  const day = String(dateText || "").trim();
  if (!day) {
    return false;
  }
  const escaped = day.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
  return new RegExp(`[\\[(]fresh\\s*::\\s*${escaped}`).test(
    String(rawLine || ""),
  );
}

// First valid `[keeps:: N]` semantic count (1-999) on the line, or 0.
// Mirrors the ledger-tools `freshnessParseKeepsValue` first-valid rule
// without placing anything; used only to measure actual increments for
// the `kept N×` notice tail.
function parseKeepsCount(lineText) {
  const text = String(lineText || "");
  const pattern = /(?:\[keeps\s*::\s*([^\]\n]*)\]|\((?:keeps)\s*::\s*([^)\n]*)\))/g;
  let match = pattern.exec(text);
  while (match) {
    const raw = String(match[1] ?? match[2] ?? "").trim();
    if (/^[+-]?\d+$/.test(raw)) {
      const number = Number(raw);
      if (Number.isSafeInteger(number) && number >= 1 && number <= 999) {
        return number;
      }
    }
    match = pattern.exec(text);
  }
  return 0;
}

// How many stamped entries actually incremented their streak: a counted
// entry whose after-line keeps is exactly one above the before-line keeps
// (saturating at 999). Uncounted preserves, same-day counted preserves,
// and stale-cache mismatches never inflate this number. Batch notices
// never promise `next review asks` — only the decision card's Keep does,
// where the installed card is the active capability.
function countFreshStampKept(stamped) {
  let kept = 0;
  for (const entry of Array.isArray(stamped) ? stamped : []) {
    if (!entry || entry.counted !== true) {
      continue;
    }
    const beforeKeeps = parseKeepsCount(entry.before);
    const afterKeeps = parseKeepsCount(entry.after);
    if (afterKeeps > 0 && afterKeeps === Math.min(beforeKeeps + 1, 999)) {
      kept += 1;
    }
  }
  return kept;
}

// Deduplicate stamp targets to one write per source task: the first entry
// wins for each `path + 0-based line` identity. Duplicate Task Links
// resolving to the same source line stamp and count once, never twice.
function deduplicateFreshStampTargets(targets) {
  const seen = new Set();
  const kept = [];
  for (const target of Array.isArray(targets) ? targets : []) {
    if (!target || typeof target !== "object") {
      continue;
    }
    const key = `${String(target.path || "")}::${Math.floor(numericOrDefault(target.line, Number.NaN))}`;
    if (seen.has(key)) {
      continue;
    }
    seen.add(key);
    kept.push(target);
  }
  return Object.freeze(kept);
}

// `Fresh ✓ 1 task · 22 due (3 new) · ✓ 13 today` from the pre-write counts
// adjusted by the change (the Tasks cache lags, so post-write counts would
// still show the old queue). With a budget the tail reads `✓ 13/15`; once
// the budget is met and no NEW task remains, ` · done for today` is added.
// With `kept > 0` actual streak increments, the tail gains ` · kept N×`.
function buildFreshStampNotice(details = {}) {
  const changed = Math.max(
    0,
    Math.floor(numericOrDefault(details.changed, 0)),
  );
  const dueAfter = Math.max(
    0,
    Math.floor(numericOrDefault(details.dueAfter, 0)),
  );
  const newAfter = Math.max(
    0,
    Math.floor(numericOrDefault(details.newAfter, 0)),
  );
  const refreshedAfter = Math.max(
    0,
    Math.floor(numericOrDefault(details.refreshedAfter, 0)),
  );
  const budgetRaw = details.budget === null || details.budget === undefined
    ? null
    : Math.floor(numericOrDefault(details.budget, Number.NaN));
  const budget =
    Number.isInteger(budgetRaw) && budgetRaw > 0 ? budgetRaw : null;
  const tasks = changed === 1 ? "task" : "tasks";
  const tail = budget !== null
    ? `✓ ${refreshedAfter}/${budget}`
    : `✓ ${refreshedAfter} today`;
  const done =
    budget !== null && refreshedAfter >= budget && newAfter === 0
      ? " · done for today"
      : "";
  const keptRaw = Math.floor(numericOrDefault(details.kept, 0));
  const keptTail =
    Number.isInteger(keptRaw) && keptRaw > 0 ? ` · kept ${keptRaw}×` : "";
  const workLogWrittenCount = Math.max(
    0,
    Math.floor(numericOrDefault(details.workLogWrittenCount, 0)),
  );
  const workLogTail = workLogWrittenCount > 0
    ? ` · ${formatCountLabel(workLogWrittenCount, "Work Log")}`
    : "";
  return `Fresh ✓ ${changed} ${tasks} · ${dueAfter} due (${newAfter} new) · ${tail}${done}${keptTail}${workLogTail}`;
}

// Match stamped `{ path, line, raw }` refs (0-based lines) against a
// pre-write queue read: the keys still present, the highest pre-write rank,
// and how many were NEW. Every queued entry is due, so `count` is also the
// number of due tasks just stamped.
function matchFreshStampRefs(queueBefore, refs) {
  const list = Array.isArray(queueBefore) ? queueBefore : [];
  const targets = Array.isArray(refs) ? refs : [];
  const keys = [];
  let rank = 0;
  let newCount = 0;
  for (const ref of targets) {
    if (!ref || typeof ref !== "object") {
      continue;
    }
    const refPath = String(ref.path || "");
    const refLine = Math.floor(numericOrDefault(ref.line, Number.NaN));
    const refRaw = String(ref.raw || "");
    const foundIndex = list.findIndex((entry) => {
      if (!entry || String(entry.path || "") !== refPath) {
        return false;
      }
      if (Number.isInteger(refLine) && Number(entry.line) === refLine + 1) {
        return true;
      }
      return Boolean(refRaw) && String(entry.originalMarkdown || "") === refRaw;
    });
    if (foundIndex < 0) {
      continue;
    }
    const found = list[foundIndex];
    keys.push(reviewQueueEntryKey(found));
    const foundRank = Number.isInteger(found.rank)
      ? found.rank
      : foundIndex + 1;
    if (foundRank > rank) {
      rank = foundRank;
    }
    if (found.state === "new") {
      newCount += 1;
    }
  }
  return Object.freeze({
    keys: Object.freeze(keys),
    rank,
    count: keys.length,
    newCount,
  });
}

// True when the freshness api can count keeps: namespace v5 with the sole
// increment helper. A v5 namespace missing `keepLine` must fail without
// writing (never fall back to the now-resetting generic stamper); a
// pre-v5 namespace stamps uncounted through the old stamper.
function freshnessSupportsKeeps(freshnessApi) {
  try {
    return (
      Boolean(freshnessApi) &&
      Number(freshnessApi.version) >= 5 &&
      typeof freshnessApi.keepLine === "function"
    );
  } catch (error) {
    return false;
  }
}

// True when the freshness api can intercept cards and skip decision
// targets: namespace v6 with the sole increment helper. A v5
// namespace still counts through `keepLine` but falls back to the
// counted keep path instead of opening a card or skipping. Never throws.
function freshnessSupportsDecayDecisions(freshnessApi) {
  try {
    return (
      Boolean(freshnessApi) &&
      Number(freshnessApi.version) >= 6 &&
      typeof freshnessApi.keepLine === "function"
    );
  } catch (error) {
    return false;
  }
}

// Strict keep-counting eligibility for one explicit keep (`docs/freshness.md`
// §2a): `ref` (`{ path, line, raw }` with the pre-write 0-based editor line)
// authorizes counting only when the pre-write queue holds exactly one row
// with `entry.path === path`, `entry.line === editorLine + 1`,
// `entry.originalMarkdown === rawLine`, `lane === 'ready'`, and
// `tier in {'rotten','returned'}`. Line-only or raw-only matches, age,
// glyph, bucket alone, block ID alone, a changed line number, or a selected
// DOM row never authorize. Anything else stamps uncounted through
// `keepLine` and preserves the streak. Returns `{ ok, entry, reason }`
// with `reason` one of `ok`, `missing`, `ambiguous`, `lane`, or `tier`.
function matchFreshStampExactEntry(queueBefore, ref) {
  const missing = (reason) =>
    Object.freeze({ ok: false, entry: null, reason });
  const list = Array.isArray(queueBefore) ? queueBefore : [];
  if (!ref || typeof ref !== "object") {
    return missing("missing");
  }
  const refPath = String(ref.path || "");
  const refLine = Math.floor(numericOrDefault(ref.line, Number.NaN));
  const refRaw = String(ref.raw || "");
  if (!Number.isInteger(refLine) || !refRaw) {
    return missing("missing");
  }
  const candidates = list.filter(
    (entry) =>
      Boolean(entry) &&
      String(entry.path || "") === refPath &&
      Number(entry.line) === refLine + 1 &&
      String(entry.originalMarkdown || "") === refRaw,
  );
  if (candidates.length === 0) {
    return missing("missing");
  }
  if (candidates.length > 1) {
    return missing("ambiguous");
  }
  const entry = candidates[0];
  if (entry.lane !== "ready") {
    return Object.freeze({ ok: false, entry, reason: "lane" });
  }
  const tier = reviewEntryMachineTier(entry);
  if (tier !== "rotten" && tier !== "returned") {
    return Object.freeze({ ok: false, entry, reason: "tier" });
  }
  return Object.freeze({ ok: true, entry, reason: "ok" });
}

// Alt+F (wantAdvance false) / Ctrl+Alt+F (wantAdvance true). CodeMirror Vim
// swallows Alt chords in normal mode, so these run on the capture-phase
// fallback like the counted lane toggle; the hotkeys below cover insert
// mode and non-Vim editing. Shift and Meta are never part of a supported
// refresh chord: Alt+Shift+F is retired.
function isReviewRefreshKeydown(event, wantAdvance) {
  if (!event || event.metaKey || event.shiftKey || !event.altKey) {
    return false;
  }
  if (Boolean(event.ctrlKey) !== Boolean(wantAdvance)) {
    return false;
  }
  return event.code === "KeyF" || event.key === "f" || event.key === "F";
}

async function openMarkdownFileWithLeafReuse(plugin, file, failureNotice) {
  if (!plugin || !plugin.isMarkdownFile(file)) {
    if (failureNotice) {
      new Notice(failureNotice);
    }
    return false;
  }

  const activeView = plugin.getActiveMarkdownView();
  if (activeView && activeView.file && activeView.file.path === file.path) {
    return true;
  }

  try {
    const existingLeaf = plugin.findMarkdownLeafByPath(file.path);
    if (existingLeaf && (await plugin.activateWorkspaceLeaf(existingLeaf))) {
      return true;
    }

    await plugin.app.workspace.getLeaf(false).openFile(file);
    return true;
  } catch (error) {
    if (failureNotice) {
      new Notice(failureNotice);
    }
    return false;
  }
}

// nav api v3 (`docs/task-dependencies.md` §9). Dependency calls return Promises
// resolving to `{ok, reason?}` and never throw; checklist claim synchronously
// declines with null or returns a settled Promise; `reviewWalk` is the
// review-walk auto-advance contract (`capture`/`continue`, version 1).
// `openDependencyStage`
// opens today's Depends on stage for the owning task of `ref` (`ref`:
// `{path, line}` — any line of the task block or its Depends-On line);
// `nav-stage` swaps in the vault-wide stage. `removeDependency` removes one
// prerequisite through the single-transaction writer (`parentRef`:
// `{path, line}`, `target`: `{path, blockId}`); it re-reads the dependent
// and refuses with a notice when stale. Plugins never import each other's
// `main.js`: bob-ledger-tools feature-detects `api?.version >= 1`.
function createDependencyNavApi(plugin) {
  const shape = (result) =>
    result && typeof result === "object" && "ok" in result
      ? result
      : { ok: false, reason: "unexpected-result" };
  const settle = (call) => {
    try {
      return Promise.resolve()
        .then(call)
        .then(shape, () => ({ ok: false, reason: "api-failed" }));
    } catch (_error) {
      return Promise.resolve({ ok: false, reason: "api-failed" });
    }
  };
  // The review-walk decision card (`docs/freshness.md` §2a): present
  // while the plugin is loaded so ledger-tools marks can promise the
  // leaf and `Alt+F to decide`. Removed again on unload (see `onunload`)
  // so marks degrade to counting pips instead of an absent card.
  return Object.freeze({
    version: 3,
    ...(plugin ? { freshnessDecayCard: FRESHNESS_DECAY_CARD_CAPABILITY } : null),
    reviewWalk: createReviewWalkApi(plugin),
    openDependencyStage(ref) {
      if (!plugin || typeof plugin.openDependencyStageForRef !== "function") {
        return Promise.resolve({ ok: false, reason: "unavailable" });
      }
      return settle(() => plugin.openDependencyStageForRef(ref || {}));
    },
    removeDependency(parentRef, target) {
      if (!plugin || typeof plugin.removeDependencyByRef !== "function") {
        return Promise.resolve({ ok: false, reason: "unavailable" });
      }
      return settle(() =>
        plugin.removeDependencyByRef(parentRef || {}, target || {}),
      );
    },
    claimReviewWalkCompletion(editor) {
      try {
        if (!plugin || typeof plugin.claimReviewWalkCtrlEnter !== "function") {
          return null;
        }
        const result = plugin.claimReviewWalkCtrlEnter(editor);
        if (!result || typeof result.then !== "function") {
          return null;
        }
        return Promise.resolve(result)
          .then(shape)
          .catch(() => ({ ok: false, reason: "api-failed" }));
      } catch (error) {
        return null;
      }
    },
  });
}
