class BobNavigationHotkeysFreshnessDecayMixin {

  async refreshTaskFreshnessOnLinks(cm, cursor, content, options = {}) {
    const discovery =
      options.linkDiscovery ||
      discoverLinkPickerTargets(
        content,
        cursor.line,
        options.countExplicit ? options.additionalTaskCount : 0,
      );
    if (!discovery.valid) {
      new Notice(
        discovery.notLink
          ? "Cursor is not on a task or Task Link"
          : discovery.error,
      );
      return false;
    }
    const activeView = this.getActiveMarkdownView();
    if (!activeView || activeView.editor !== cm || !activeView.file) {
      new Notice("No active markdown note");
      return false;
    }
    const api = getReviewFreshnessApi(this.app);
    if (!api) {
      new Notice(REVIEW_FRESHNESS_API_REQUIRED_NOTICE);
      return false;
    }
    const resolution = await this.resolveLinkPickerTargets(
      activeView.file.path,
      discovery,
    );
    if (resolution.error) {
      new Notice(resolution.error);
      return false;
    }
    if (
      cm &&
      typeof cm.getValue === "function" &&
      String(cm.getValue() || "") !== content
    ) {
      new Notice("Current note changed; no tasks were updated");
      return false;
    }
    const queueBefore = this.readFreshnessQueue(api);
    const countsBefore = this.readFreshnessCounts(api);
    // Duplicate references to the same source target stamp and count once:
    // dedupe before planning so a repeated Task Link cannot inflate keeps.
    const deduped = deduplicateFreshStampTargets(resolution.targets);
    const groups = groupLinkPickerTargetsByNote(deduped);
    if (groups.length === 0) {
      new Notice("Could not update task; no tasks were updated");
      return false;
    }
    // Task Link sessions never open cards — even a single link. Exact
    // at-limit targets skip without changing fresh/count; below
    // threshold they count normally. Skipped targets stay due for the
    // walk and never enter anchor exclusions.
    const linkResolved = groups.map((group) => {
      const groupLines = splitMarkdownContent(group.content).lines;
      return {
        group,
        resolved: group.session.targets.map((target) => {
          const raw = String(groupLines[target.line] || "");
          const match = matchFreshStampExactEntry(queueBefore, {
            path: group.path,
            line: target.line,
            raw,
          });
          return Object.freeze({
            target: Object.freeze({
              line: target.line,
              path: group.path,
              raw,
              counted: match.ok,
            }),
            match,
          });
        }),
      };
    });
    const skipDecisions = freshnessSupportsDecayDecisions(api);
    let linkDecisionSkipped = 0;
    let linkChecklistSkipped = 0;
    const stampTargetsByGroup = [];
    for (const { group, resolved } of linkResolved) {
      const checklistPart = partitionFreshStampChecklistSkips(
        resolved,
        queueBefore,
      );
      linkChecklistSkipped += checklistPart.skipped.length;
      const partition = partitionFreshStampDecisionSkips(checklistPart.stamp, {
        enabled: skipDecisions,
      });
      linkDecisionSkipped += partition.skipped.length;
      stampTargetsByGroup.push({ group, targets: partition.stamp });
    }
    const linkStamped = stampTargetsByGroup.reduce(
      (count, item) => count + item.targets.length,
      0,
    );
    const linkSkipTail =
      formatFreshStampSkipTail(linkDecisionSkipped) +
      formatFreshStampChecklistSkipTail(linkChecklistSkipped);
    if (
      linkStamped === 0 &&
      (linkDecisionSkipped > 0 || linkChecklistSkipped > 0)
    ) {
      if (linkDecisionSkipped > 0) {
        new Notice(
          formatFreshStampSkippedNotice(linkDecisionSkipped) +
            formatFreshStampChecklistSkipTail(linkChecklistSkipped),
        );
      } else {
        new Notice(formatFreshStampChecklistSkippedNotice(linkChecklistSkipped));
      }
      return true;
    }
    for (const { targets } of stampTargetsByGroup) {
      for (const target of targets) {
        const check = classifyFreshStampTarget(target.raw);
        if (!check.ok) {
          new Notice(freshStampRefusalNotice(check.refusal));
          return false;
        }
      }
    }
    const eligibleTargets = stampTargetsByGroup.flatMap(({ targets }) =>
      targets.filter((target) => isPendingWorkLogTargetRawLine(target.raw)),
    );
    let summary = "";
    if (eligibleTargets.length > 0) {
      const result = await this.requestFreshnessRefreshSummary({
        summary: options.summary,
        dateText: options.dateText,
        totalCount: linkStamped,
        eligibleCount: eligibleTargets.length,
      });
      if (result.failed) {
        new Notice("Could not open Work Log prompt; no tasks were updated");
        return false;
      }
      if (result.cancelled) {
        return false;
      }
      summary = result.summary;
      if (
        cm &&
        typeof cm.getValue === "function" &&
        String(cm.getValue() || "") !== content
      ) {
        new Notice("Current note changed; no tasks were updated");
        return false;
      }
      for (const { group } of stampTargetsByGroup) {
        const live = await this.readLinkPickerNoteContent(
          group.path,
          group.file,
        );
        if (live !== group.content) {
          new Notice("A linked note changed; no tasks were updated");
          return false;
        }
      }
    }
    const planned = [];
    const refs = [];
    const stampedAll = [];
    let workLogWrittenCount = 0;
    for (const { group, targets } of stampTargetsByGroup) {
      const plan = planFreshStampBatchWithWorkLogs(
        group.content,
        targets,
        options.stamper,
        options.dateText,
        summary,
      );
      if (!plan.ok) {
        new Notice(freshStampRefusalNotice(plan.refusal));
        return false;
      }
      workLogWrittenCount += plan.workLogWrittenCount;
      for (const entry of plan.stamped) {
        refs.push({ path: group.path, line: entry.line, raw: entry.before });
        stampedAll.push(entry);
      }
      if (plan.content !== group.content) {
        planned.push({ group, plan });
      }
    }
    if (planned.length > 0) {
      const commit = await this.commitLinkPickerNoteWrites(planned, {});
      if (!commit.ok) {
        new Notice("A linked note changed; no tasks were updated");
        return false;
      }
    }
    // Ctrl+Alt+F advances through the shared tail with the stamp text
    // as its preamble, giving one composed toast.
    const linkPreamble = this.finishFreshStamp(
      queueBefore,
      countsBefore,
      refs,
      stampedAll,
      options.dateText,
      {
        skipTail: linkSkipTail,
        workLogWrittenCount,
        deferNotice: options.advance === true,
      },
    );
    if (options.advance === true) {
      return await this.jumpToDueTask(1, {
        fromStamp: this.reviewAnchor,
        fromAdvance: true,
        preamble: linkPreamble,
      });
    }
    return true;
  }

  // Remember the walk anchor for the session (the Tasks cache lags, so
  // the jump reads the queue fresh but continues from the handled entry's
  // surviving successor or predecessor), then show the adjusted-counts
  // Notice on the upkeep meter. With `extra.deferNotice`, return the text
  // instead of showing it, so the shared advance tail can compose one
  // toast from the preamble and the landing.
  finishFreshStamp(queueBefore, countsBefore, refs, stamped, dateText, extra = {}) {
    const matched = matchFreshStampRefs(queueBefore, refs);
    this.reviewAnchor =
      matched.count > 0
        ? buildReviewAnchor(queueBefore, matched.keys, matched.rank, dateText)
        : null;
    const changed = stamped.filter(
      (entry) => entry.after !== entry.before,
    ).length;
    const counts =
      countsBefore && typeof countsBefore === "object" ? countsBefore : {};
    const dueBefore = Math.max(
      0,
      Math.floor(numericOrDefault(counts.due, 0)),
    );
    const newBefore = Math.max(
      0,
      Math.floor(numericOrDefault(counts.new, 0)),
    );
    const upkeepBefore = Number.isInteger(counts.upkeepToday)
      ? counts.upkeepToday
      : Math.max(
        0,
        Math.floor(numericOrDefault(counts.refreshedToday, 0)),
      );
    // Lane stamps (Pending/Next) never grow upkeep: only stamped tasks
    // that stay outside the lanes count.
    const newlyUpkept = stamped.filter((entry) => {
      if (freshStampLineHasToday(entry.before, dateText)) {
        return false;
      }
      const status = getObsidianTaskCheckboxStatus(entry.after);
      return status !== "/" && status !== "*";
    }).length;
    // Only actual streak increments tail the notice; preserves, same-day
    // repeats, and stale-cache mismatches report no `kept N×`.
    const kept = countFreshStampKept(stamped);
    const skipTail =
      extra && typeof extra.skipTail === "string" ? extra.skipTail : "";
    const message =
      buildFreshStampNotice({
        changed,
        dueAfter: Math.max(0, dueBefore - matched.count),
        newAfter: Math.max(0, newBefore - matched.newCount),
        refreshedAfter: upkeepBefore + newlyUpkept,
        budget:
          counts.budget === undefined || counts.budget === null
            ? null
            : counts.budget,
        kept,
        workLogWrittenCount: extra && extra.workLogWrittenCount,
      }) + skipTail;
    if (extra && extra.deferNotice === true) {
      return message;
    }
    new Notice(message);
    return undefined;
  }

  // Decision card: open, revalidate, and commit (`docs/freshness.md` §2a).
  // The card opens for one exact, due, at-limit source task and writes
  // nothing until approval. Every approval revalidates the task line,
  // the local day, the decay config, the trigger eligibility, the plan
  // inputs (keeps, interval, scheduled and priority values), the task's
  // child block (Schedule Log preimages), and the priority ladder
  // config, then reuses the previewed plan/date through the existing
  // transactional writers — one source-note decision is one undo step.
  // Stale inputs write nothing and rebuild for a fresh choice.

  // Normalized decay policy from the ledger api, with counting defaults
  // when the namespace is old or throwing. Never throws.
  readFreshnessDecayPolicy(api) {
    const fallback = Object.freeze({
      enabled: true,
      keeps: 3,
      enter: null,
      invalid: false,
    });
    try {
      if (api && typeof api.config === "function") {
        const config = api.config();
        const decay =
          config && config.decay && typeof config.decay === "object"
            ? config.decay
            : {};
        return Object.freeze({
          enabled: decay.enabled !== false,
          keeps:
            Number.isInteger(decay.keeps) && decay.keeps >= 0
              ? decay.keeps
              : 3,
          enter:
            typeof decay.enter === "string" && decay.enter !== ""
              ? decay.enter
              : null,
          invalid: config ? config.invalid === true : false,
        });
      }
    } catch (error) {
      // Fall through to the counting defaults below.
    }
    return fallback;
  }

  // Build the card context for one resolved single-task trigger, or null
  // when the card cannot render (mixed versions, unusable plan) so the
  // caller falls back to counting. Never throws.
  buildFreshnessDecayCardCtx(cm, cursor, content, filePath, resolved, queueBefore, options) {
    try {
      const api = getReviewFreshnessApi(this.app);
      if (!api || !freshnessSupportsDecayDecisions(api)) {
        return null;
      }
      const settings = options && typeof options === "object" ? options : {};
      const dateText = String(settings.dateText || "");
      const line = resolved && resolved.target ? resolved.target.line : NaN;
      const raw = resolved && resolved.target ? String(resolved.target.raw || "") : "";
      if (!Number.isInteger(line) || !raw || !/^\d{4}-\d{2}-\d{2}$/.test(dateText)) {
        return null;
      }
      const match = resolved.match;
      const entry = match && match.entry ? match.entry : null;
      const decay = this.readFreshnessDecayPolicy(api);
      const property = findFreshnessDecayPriorityProperty(this.config);
      const keeps = parseKeepsCount(raw);
      const intervalDays = resolveFreshnessDecayIntervalDays(api, entry, raw, content);
      const schedulesName =
        property && typeof property.schedules === "string" ? property.schedules : "";
      const scheduledField =
        schedulesName ? findBulletPropertyField(raw, schedulesName) : null;
      const currentScheduled = normalizeBulletPropertyValue(
        scheduledField ? scheduledField.value : "",
      );
      const priorityField =
        property && typeof property.name === "string"
          ? findBulletPropertyField(raw, property.name)
          : null;
      const currentValue = normalizeBulletPropertyValue(
        priorityField ? priorityField.value : "",
      );
      const plan = planFreshnessDecayCard({
        keeps,
        intervalDays,
        freshnessDecay: {
          enabled: decay.enabled,
          keeps: decay.keeps,
          enter: decay.enter,
          invalid: decay.invalid,
        },
        property,
        baseDate: new Date(),
        random: Math.random,
        currentScheduled,
        content: String(content || ""),
        taskLine: line,
      });
      if (!plan || plan.valid !== true) {
        return null;
      }
      const childBlock = snapshotFreshnessDecayChildBlock(
        String(content || ""),
        line,
      );
      const priorityConfig = serializeFreshnessDecayPriorityProperty(property);
      const taskText = cleanTaskDisplayText(raw);
      const noteBase = String(filePath || "").split("/").pop() || String(filePath || "");
      const createdField = findBulletPropertyField(raw, "created");
      const age = formatFreshnessDecayCapturedAge(
        createdField ? createdField.value : "",
        dateText,
      );
      const subtitle = age
        ? `${taskText} · ${noteBase} · ${age}`
        : `${taskText} · ${noteBase}`;
      return Object.freeze({
        cm,
        filePath: String(filePath || ""),
        line,
        rawLine: raw,
        invokeCh: cursor && Number.isInteger(cursor.ch) ? cursor.ch : 0,
        dateText,
        advance: settings.advance === true,
        queueBefore: Array.isArray(queueBefore) ? queueBefore : [],
        entry,
        keeps,
        limit: decay.keeps,
        intervalDays,
        currentScheduled,
        currentValue,
        childBlock,
        priorityConfig,
        decay,
        plan,
        rows: buildFreshnessDecayCardRows(plan),
        subtitle,
      });
    } catch (error) {
      return null;
    }
  }

  // Open the card for one trigger. True when the gesture is consumed
  // (card open, or a notice explains why nothing was written); false
  // when the caller should fall back to counting.
  async maybeOpenFreshnessDecayCard(cm, cursor, content, filePath, resolved, queueBefore, options) {
    try {
      if (this.activeFreshnessDecayCard) {
        new Notice("A decision card is already open");
        return true;
      }
      const cardCtx = this.buildFreshnessDecayCardCtx(
        cm,
        cursor,
        content,
        filePath,
        resolved,
        queueBefore,
        options,
      );
      if (!cardCtx) {
        return false;
      }
      return this.openFreshnessDecayCard(cardCtx);
    } catch (error) {
      return false;
    }
  }

  openFreshnessDecayCard(cardCtx) {
    try {
      if (!cardCtx || this.activeFreshnessDecayCard) {
        return false;
      }
      const modal = new FreshnessDecayCardModal(this.app, {
        title: cardCtx.plan.title || `Kept ${cardCtx.keeps} reviews in a row`,
        subtitle: cardCtx.subtitle,
        rows: cardCtx.rows,
        onChoose: (action) => {
          this.activeFreshnessDecayCard = null;
          void this.applyFreshnessDecayCardChoice(cardCtx, action);
        },
        onDismiss: () => {
          // Esc changes nothing: no writes, no log entries, no
          // accounting, no walk advance; the anchor is retained.
          this.activeFreshnessDecayCard = null;
        },
      });
      this.activeFreshnessDecayCard = modal;
      modal.open();
      return true;
    } catch (error) {
      this.activeFreshnessDecayCard = null;
      return false;
    }
  }

  // Revalidate the previewed plan against live state immediately before
  // commit: the task line, the local day, the decay config, the trigger
  // eligibility, the plan inputs (keeps, interval, scheduled and priority
  // values), the task's child block (Schedule Log preimages), and the
  // priority ladder config. Child-log insertion positions are still
  // recomputed at commit; any child-log content change is stale and
  // rebuilds for a fresh choice. Returns `{ ok, live }`.
  revalidateFreshnessDecayCard(cardCtx) {
    const stale = (reason) => ({ ok: false, reason, live: null });
    try {
      if (!cardCtx || !cardCtx.cm || typeof cardCtx.cm.getValue !== "function") {
        return stale("no-editor");
      }
      const cm = cardCtx.cm;
      const liveContent = String(cm.getValue() || "");
      const liveLine = getEditorLine(cm, cardCtx.line);
      if (liveLine === null || liveLine !== cardCtx.rawLine) {
        return stale("task-line");
      }
      if (this.getFreshnessDateText() !== cardCtx.dateText) {
        return stale("local-day");
      }
      const api = getReviewFreshnessApi(this.app);
      if (!api || !freshnessSupportsDecayDecisions(api)) {
        return stale("freshness-api");
      }
      const decay = this.readFreshnessDecayPolicy(api);
      if (
        decay.enabled !== cardCtx.decay.enabled ||
        decay.keeps !== cardCtx.decay.keeps ||
        decay.enter !== cardCtx.decay.enter ||
        decay.invalid !== cardCtx.decay.invalid
      ) {
        return stale("config");
      }
      const queue = this.readFreshnessQueue(api);
      const match = matchFreshStampExactEntry(queue, {
        path: cardCtx.filePath,
        line: cardCtx.line,
        raw: liveLine,
      });
      if (match.ok !== true || !isFreshnessDecayDecisionEntry(match.entry)) {
        return stale("eligibility");
      }
      if (parseKeepsCount(liveLine) !== cardCtx.keeps) {
        return stale("keeps");
      }
      if (
        resolveFreshnessDecayIntervalDays(api, match.entry, liveLine, liveContent) !==
        cardCtx.intervalDays
      ) {
        return stale("interval");
      }
      const property = findFreshnessDecayPriorityProperty(this.config);
      const schedulesName =
        property && typeof property.schedules === "string" ? property.schedules : "";
      const scheduledField =
        schedulesName ? findBulletPropertyField(liveLine, schedulesName) : null;
      if (
        normalizeBulletPropertyValue(scheduledField ? scheduledField.value : "") !==
        cardCtx.currentScheduled
      ) {
        return stale("scheduled");
      }
      const priorityField =
        property && typeof property.name === "string"
          ? findBulletPropertyField(liveLine, property.name)
          : null;
      if (
        normalizeBulletPropertyValue(priorityField ? priorityField.value : "") !==
        cardCtx.currentValue
      ) {
        return stale("priority");
      }
      if (
        serializeFreshnessDecayPriorityProperty(property) !==
        cardCtx.priorityConfig
      ) {
        return stale("priority-config");
      }
      if (
        snapshotFreshnessDecayChildBlock(liveContent, cardCtx.line) !==
        cardCtx.childBlock
      ) {
        return stale("child-log");
      }
      return {
        ok: true,
        reason: null,
        live: Object.freeze({ content: liveContent, lineText: liveLine, queue }),
      };
    } catch (error) {
      return stale("unexpected");
    }
  }

  // Rebuild for a fresh choice after a stale commit: new preview, new
  // card. False when the task no longer decides — the next press stamps.
  async reopenFreshnessDecayCard(cardCtx) {
    try {
      const cm = cardCtx ? cardCtx.cm : null;
      if (!cm || typeof cm.getValue !== "function") {
        return false;
      }
      const content = String(cm.getValue() || "");
      const liveLine = getEditorLine(cm, cardCtx.line);
      if (liveLine === null) {
        return false;
      }
      const api = getReviewFreshnessApi(this.app);
      const queue = this.readFreshnessQueue(api);
      const match = matchFreshStampExactEntry(queue, {
        path: cardCtx.filePath,
        line: cardCtx.line,
        raw: liveLine,
      });
      if (match.ok !== true || !isFreshnessDecayDecisionEntry(match.entry)) {
        return false;
      }
      const cursor = getEditorCursor(cm) || { line: cardCtx.line, ch: 0 };
      const next = this.buildFreshnessDecayCardCtx(
        cm,
        cursor,
        content,
        cardCtx.filePath,
        {
          target: Object.freeze({
            line: cardCtx.line,
            path: cardCtx.filePath,
            raw: liveLine,
            counted: true,
          }),
          match,
        },
        queue,
        { dateText: cardCtx.dateText, advance: cardCtx.advance },
      );
      if (!next) {
        return false;
      }
      return this.openFreshnessDecayCard(next);
    } catch (error) {
      return false;
    }
  }

  async applyFreshnessDecayCardChoice(cardCtx, action) {
    this.activeFreshnessDecayCard = null;
    try {
      const check = this.revalidateFreshnessDecayCard(cardCtx);
      if (!check.ok) {
        // Write nothing; rebuild for a fresh choice rather than applying
        // unseen dates or overwriting another edit.
        new Notice(REVIEW_QUEUE_CHANGED_NOTICE);
        await this.reopenFreshnessDecayCard(cardCtx);
        return false;
      }
      const key = String(action || "");
      if (key === "notNow") {
        return await this.applyFreshnessDecayCardDeferral(
          cardCtx,
          check.live,
          cardCtx.plan.notNow,
        );
      }
      if (key.startsWith("level:")) {
        const index = Number(key.slice("level:".length));
        const pick =
          cardCtx.plan.levels && Number.isInteger(index)
            ? cardCtx.plan.levels[index]
            : null;
        return await this.applyFreshnessDecayCardDeferral(cardCtx, check.live, pick);
      }
      if (key === "lessOften") {
        return await this.applyFreshnessDecayCardLessOften(cardCtx, check.live);
      }
      if (key === "reword") {
        return await this.applyFreshnessDecayCardReword(cardCtx, check.live);
      }
      if (key === "drop") {
        return await this.applyFreshnessDecayCardDrop(cardCtx, check.live);
      }
      if (key === "keep") {
        return await this.applyFreshnessDecayCardKeep(cardCtx, check.live);
      }
      return false;
    } catch (error) {
      new Notice("Could not update task; no tasks were updated");
      return false;
    }
  }

  // Walk bookkeeping shared by applied decisions: the handled entry keys
  // the walk anchor (the Tasks cache lags, so the jump reads the queue
  // fresh but continues from the surviving successor or predecessor).
  rememberFreshnessDecayCardAnchor(cardCtx) {
    try {
      const matched = matchFreshStampRefs(cardCtx.queueBefore, [
        { path: cardCtx.filePath, line: cardCtx.line, raw: cardCtx.rawLine },
      ]);
      this.reviewAnchor =
        matched.count > 0
          ? buildReviewAnchor(
              cardCtx.queueBefore,
              matched.keys,
              matched.rank,
              cardCtx.dateText,
            )
          : null;
    } catch (error) {
      this.reviewAnchor = null;
    }
  }

  // Successful Ctrl+Alt+F outcomes advance exactly once after commit —
  // except Reword, which leaves focus for editing, and failed or
  // dismissed secondary pickers, which stay due. The decay notice stays
  // its own toast; the tail lands with anchor-only planning, the lock,
  // and jump recording, and no preamble of its own.
  async maybeAdvanceFreshnessDecayWalk(cardCtx, action) {
    try {
      if (cardCtx && cardCtx.advance === true && action !== "reword") {
        return await this.jumpToDueTask(1, {
          fromStamp: this.reviewAnchor,
          fromAdvance: true,
        });
      }
    } catch (error) {
      return false;
    }
    return true;
  }

  // Resolve a previewed deferral pick to its configured level. Unknown
  // labels (or a missing ladder) refuse rather than inventing a level.
  resolveFreshnessDecayCardLevel(pick) {
    try {
      const property = findFreshnessDecayPriorityProperty(this.config);
      if (!property || !Array.isArray(property.levels)) {
        return null;
      }
      const label = normalizeBulletPropertyValue(pick ? pick.levelLabel : "");
      if (!label) {
        return null;
      }
      return (
        property.levels.find(
          (level) =>
            level && normalizeBulletPropertyValue(level.label) === label,
        ) || null
      );
    } catch (error) {
      return null;
    }
  }

  // Not now (Enter) and explicit 1–4 picks: preview and apply a deferral
  // through the existing priority writer. The previewed date persists
  // (what you see is what you get); Enter never cancels, including past
  // the last ladder level, where the planner already substituted a
  // same-level roll for this card only. Stamps and clears keeps through
  // the writer's own freshness step. One undo step.
  async applyFreshnessDecayCardDeferral(cardCtx, live, pick) {
    try {
      if (!pick || pick.available !== true) {
        new Notice("That choice is unavailable; nothing was written");
        return false;
      }
      const property = findFreshnessDecayPriorityProperty(this.config);
      if (!property) {
        new Notice("No priority ladder is configured; nothing was written");
        return false;
      }
      const level = this.resolveFreshnessDecayCardLevel(pick);
      if (!level) {
        new Notice(REVIEW_QUEUE_CHANGED_NOTICE);
        return false;
      }
      const ok = await this.setBulletPriorityValue(
        cardCtx.cm,
        { line: cardCtx.line, ch: 0 },
        cardCtx.filePath,
        cardCtx.rawLine,
        property,
        level,
        {
          baseDate: getLocalDateStart(new Date()),
          precomputedRoll: { date: pick.date, offset: pick.offset },
          scheduleReasonOverride: pick.reason,
        },
      );
      if (!ok) {
        return false;
      }
      this.rememberFreshnessDecayCardAnchor(cardCtx);
      await this.maybeAdvanceFreshnessDecayWalk(cardCtx, "deferral");
      return true;
    } catch (error) {
      new Notice("Could not update task; no tasks were updated");
      return false;
    }
  }

  // Less often (L): the next refresh preset strictly above the current
  // interval, stamped and cleared, with a dated review-reason Schedule
  // Log entry. At 90+ the existing custom refresh picker takes over,
  // constrained to a longer value ≤365; at 365 the row is unavailable.
  // One source-note decision is one undo step.
  async applyFreshnessDecayCardLessOften(cardCtx, live) {
    try {
      const lessOften = cardCtx.plan.lessOften;
      if (!lessOften || lessOften.available !== true) {
        new Notice("That choice is unavailable; nothing was written");
        return false;
      }
      if (lessOften.mode === "picker") {
        this.openFreshnessDecayLessOftenPicker(cardCtx);
        return true;
      }
      if (lessOften.mode !== "refresh" || !Number.isInteger(lessOften.afterDays)) {
        new Notice("That choice is unavailable; nothing was written");
        return false;
      }
      return await this.applyFreshnessDecayLessOftenDays(
        cardCtx,
        live,
        lessOften.beforeDays,
        lessOften.afterDays,
      );
    } catch (error) {
      new Notice("Could not update task; no tasks were updated");
      return false;
    }
  }

  // Commit a Less often interval: refresh-set (which stamps and clears)
  // plus the dated review-reason entry in one editor transaction.
  async applyFreshnessDecayLessOftenDays(cardCtx, live, beforeDays, days) {
    try {
      if (
        !Number.isInteger(days) ||
        days <= beforeDays ||
        days < 1 ||
        days > 365
      ) {
        new Notice("That choice is unavailable; nothing was written");
        return false;
      }
      const refresher = this.getFreshnessRefreshLine();
      if (typeof refresher !== "function") {
        new Notice(REVIEW_FRESHNESS_API_REQUIRED_NOTICE);
        return false;
      }
      const reason = formatFreshnessDecisionLessOftenReason({
        beforeDays,
        afterDays: days,
        keeps: cardCtx.keeps,
      });
      if (!reason) {
        new Notice("Could not update task; no tasks were updated");
        return false;
      }
      const nextLine = applyFreshRefreshLine(
        live.lineText,
        refresher,
        days,
        cardCtx.dateText,
      );
      if (nextLine === live.lineText) {
        new Notice("Refresh unchanged; nothing was written");
        return false;
      }
      const logPlan = planScheduleLogEntry(live.content, cardCtx.line, {
        from: cardCtx.currentScheduled,
        to: cardCtx.currentScheduled,
        reason,
      });
      const split = splitMarkdownContent(live.content);
      const lines = split.lines.slice();
      lines[cardCtx.line] = nextLine;
      applyScheduleLogEntryToLines(lines, logPlan);
      const applied = applyEditorContentTransaction(
        cardCtx.cm,
        live.content,
        lines.join(split.lineEnding),
        {
          line: cardCtx.line,
          ch: Math.min(cardCtx.invokeCh, nextLine.length),
        },
      );
      if (!applied) {
        new Notice("Could not update task; no tasks were updated");
        return false;
      }
      this.rememberFreshnessDecayCardAnchor(cardCtx);
      new Notice(`Less often · every ${beforeDays} → ${days} days · kept ${cardCtx.keeps}×`);
      await this.maybeAdvanceFreshnessDecayWalk(cardCtx, "lessOften");
      return true;
    } catch (error) {
      new Notice("Could not update task; no tasks were updated");
      return false;
    }
  }
}
// ---- src/535-plugin-review-checklist-walk.js ----
function reviewChecklistGroupScan(queue, entry, handledKeys) {
  const list = Array.isArray(queue) ? queue : [];
  const key = reviewQueueEntryKey(entry);
  const index = list.findIndex((candidate) => reviewQueueEntryKey(candidate) === key);
  if (index < 0) {
    return Object.freeze({ after: Object.freeze([]), before: Object.freeze([]) });
  }
  const tier = reviewEntryMachineTier(entry);
  const handled =
    handledKeys instanceof Set
      ? handledKeys
      : new Set(Array.isArray(handledKeys) ? handledKeys : []);
  const inGroup = (candidate) =>
    reviewEntryMachineTier(candidate) === tier &&
    !handled.has(reviewQueueEntryKey(candidate));
  return Object.freeze({
    after: Object.freeze(list.slice(index + 1).filter(inGroup)),
    before: Object.freeze(list.slice(0, index).filter(inGroup)),
  });
}

function formatReviewCtrlEnterDoneLine(taskText, tier) {
  const text = String(taskText || "").trim() || "task";
  const label = String(tier || "").toUpperCase();
  return `✓ Done · ${text} · Ctrl+Enter → next ${label}`;
}

function formatReviewChecklistGroupEndNotice(options = {}) {
  const taskText = String(options.taskText || "").trim() || "task";
  const label = String(options.tier || "").toUpperCase();
  const skipped = Number.isInteger(options.skipped)
    ? Math.max(0, options.skipped)
    : 0;
  const ending = skipped > 0 ? `end of ${label} · ${skipped} skipped` : `${label} done`;
  const lines = [`✓ Done · ${taskText} · ${ending}`];
  const nextLabel = String(options.nextLabel || "").trim();
  if (nextLabel) {
    lines.push(
      formatReviewAdvanceStopLine({
        nextLabel,
        commitments: options.commitments,
      }),
    );
  }
  return lines.join("\n");
}

function formatReviewClosedNotice(options = {}) {
  const commitments = Number.isInteger(options.commitments)
    ? Math.max(0, options.commitments)
    : 0;
  const postSkipped = Number.isInteger(options.postSkipped)
    ? Math.max(0, options.postSkipped)
    : 0;
  const rotten = Number.isInteger(options.rotten)
    ? Math.max(0, options.rotten)
    : 0;
  const prefix =
    (postSkipped > 0 ? `${postSkipped} POST still due · ` : "") +
    (commitments > 0 ? `${commitments} commitments still due · ` : "");
  return `${prefix}Review closed — ${rotten} ROTTEN left for later`;
}

class BobNavigationHotkeysChecklistWalkMixin {
  claimReviewWalkCtrlEnter(editor) {
    try {
      // While an answer is in flight or settling, the claim is swallowed
      // silently: the cycler treats the settled Promise as consumed.
      if (this.reviewWalkBusy()) {
        return Promise.resolve({ ok: false, reason: "busy" });
      }
      const landing = this.reviewLanding;
      if (!landing) {
        return null;
      }
      const todayText = this.laneReleaseDateText({});
      if (landing.day !== todayText) {
        return null;
      }
      const view = this.getActiveMarkdownView();
      if (
        !view ||
        !view.file ||
        !view.editor ||
        view.editor !== editor ||
        view.file.path !== landing.path
      ) {
        return null;
      }
      const cursor = getEditorCursor(editor);
      const text = cursor ? getEditorLine(editor, cursor.line) : null;
      if (text === null || String(text) !== landing.text) {
        return null;
      }
      const api = getReviewFreshnessApi(this.app);
      if (!reviewFreshnessSupportsChecklistTiers(api)) {
        return null;
      }
      if (!getReviewCyclerApi(this.app)) {
        return null;
      }
      const queue = this.readFreshnessQueue(api);
      const entry = matchReviewChecklistCursor(queue, {
        path: landing.path,
        line: cursor.line + 1,
        text: String(text),
      });
      const tier = reviewEntryMachineTier(entry);
      if (
        !entry ||
        (tier !== "pre" && tier !== "post") ||
        entry.path !== landing.path ||
        entry.originalMarkdown !== landing.text ||
        landing.tier !== tier
      ) {
        return null;
      }
      // The completion holds the gesture lock, settling afterwards.
      this.takeReviewWalkLock(REVIEW_GESTURE_LOCK_MS);
      return Promise.resolve(
        this.completeReviewChecklistRow(editor, {
          api,
          queueBefore: queue,
          entry,
          filePath: landing.path,
          dateText: todayText,
          advance: true,
          withinGroup: true,
        }),
      )
        .then((ok) => {
          this.settleReviewWalkLock(ok === true);
          return ok === true
            ? { ok: true }
            : { ok: false, reason: "not-completed" };
        })
        .catch(() => {
          this.settleReviewWalkLock(false);
          return { ok: false, reason: "not-completed" };
        });
    } catch (error) {
      return null;
    }
  }

  async filterLiveReviewEntries(entries, editor, activePath) {
    const contentByPath = new Map();
    const live = [];
    for (const entry of Array.isArray(entries) ? entries : []) {
      const path = entry && typeof entry.path === "string" ? entry.path : "";
      if (!path) {
        continue;
      }
      if (!contentByPath.has(path)) {
        if (
          path === activePath &&
          editor &&
          typeof editor.getValue === "function"
        ) {
          contentByPath.set(path, String(editor.getValue() || ""));
        } else {
          const vault = this.app && this.app.vault;
          const file =
            vault && typeof vault.getAbstractFileByPath === "function"
              ? vault.getAbstractFileByPath(path)
              : null;
          contentByPath.set(
            path,
            file ? this.readLinkPickerNoteContent(path, file) : null,
          );
        }
      }
      const content = await contentByPath.get(path);
      if (content !== null && resolveReviewQueueLine(content, entry).ok) {
        live.push(entry);
      }
    }
    return live;
  }

  async completeReviewChecklistRow(cm, options = {}) {
    const api = options.api;
    const entry = options.entry;
    const queueBefore = Array.isArray(options.queueBefore) ? options.queueBefore : [];
    const filePath = options.filePath;
    const advance = options.advance === true;
    const withinGroup = options.withinGroup === true;
    const todayText =
      typeof options.dateText === "string" && options.dateText
        ? options.dateText
        : this.laneReleaseDateText({});
    const tier = reviewEntryMachineTier(entry);
    if (!reviewFreshnessSupportsChecklistTiers(api)) {
      new Notice(REVIEW_CHECKLIST_UPDATE_LEDGER_NOTICE);
      return false;
    }
    const cycler = getReviewCyclerApi(this.app);
    if (!cycler) {
      new Notice(REVIEW_CHECKLIST_UPDATE_CYCLER_NOTICE);
      return false;
    }
    const prior =
      this.reviewAnchor &&
      reviewAnchorIsCurrentDay(this.reviewAnchor, todayText) &&
      Array.isArray(this.reviewAnchor.keys)
        ? this.reviewAnchor.keys
        : [];
    const handled = new Set(prior);
    handled.add(reviewQueueEntryKey(entry));
    let nextPlan = null;
    if (advance && tier !== "post" && !withinGroup) {
      nextPlan = planReviewJump(queueBefore, {
        direction: 1,
        cursor: { path: filePath, line: entry.line, text: entry.originalMarkdown },
        anchor: buildReviewAnchor(queueBefore, Array.from(handled), entry.rank, todayText),
        todayText,
      });
    }
    let result;
    try {
      result = await cycler.completeTaskAtCursor(cm);
    } catch (error) {
      new Notice("Not completed — not-closed");
      return false;
    }
    if (!result || result.ok !== true) {
      new Notice(`Not completed — ${result && result.reason ? result.reason : "not-closed"}`);
      return false;
    }

    this.reviewLanding = null;
    this.addReviewAnsweredKeys([reviewQueueEntryKey(entry)], todayText);
    // The pre-landing cursor for the `<C-o>` jump record: the completed row.
    const jumpOrigin = {
      path: filePath,
      line: Number.isInteger(entry.line) ? entry.line - 1 : 0,
      ch: 0,
    };
    const taskText =
      entry && typeof entry.text === "string" && entry.text.trim()
        ? entry.text.trim()
        : "task";
    const groupWalk = withinGroup && tier === "pre" || tier === "post";
    let liveGroup = { after: [], before: [] };
    if (groupWalk) {
      const scan = reviewChecklistGroupScan(queueBefore, entry, handled);
      const liveEntries = await this.filterLiveReviewEntries(
        scan.after.concat(scan.before),
        cm,
        filePath,
      );
      const liveKeys = new Set(liveEntries.map((row) => reviewQueueEntryKey(row)));
      liveGroup = {
        after: scan.after.filter((row) => liveKeys.has(reviewQueueEntryKey(row))),
        before: scan.before.filter((row) => liveKeys.has(reviewQueueEntryKey(row))),
      };
    }
    if (groupWalk) {
      const liveGroupKeys = new Set(
        liveGroup.after.concat(liveGroup.before).map((row) => reviewQueueEntryKey(row)),
      );
      const scanned = reviewChecklistGroupScan(queueBefore, entry, handled);
      for (const row of scanned.after.concat(scanned.before)) {
        if (!liveGroupKeys.has(reviewQueueEntryKey(row))) {
          handled.add(reviewQueueEntryKey(row));
        }
      }
    }
    this.reviewAnchor = buildReviewAnchor(
      queueBefore,
      Array.from(handled),
      entry.rank,
      todayText,
    );
    const remaining = reviewWalkRemaining(queueBefore, handled);

    if (groupWalk && advance) {
      for (const successor of liveGroup.after) {
        let landed;
        try {
          landed = await this.landOnReviewQueueEntry(successor, {
            jumpOrigin,
          });
        } catch (error) {
          landed = { ok: false, stale: true };
        }
        if (landed && landed.ok) {
          this.reviewAnchor = buildReviewAnchor(
            queueBefore,
            [reviewQueueEntryKey(successor)],
            successor.rank,
            todayText,
          );
          const postLanding = tier === "post";
          const successorIndex = queueBefore.findIndex(
            (candidate) => reviewQueueEntryKey(candidate) === reviewQueueEntryKey(successor),
          );
          let landingNotice = buildReviewJumpNotice(
            successor,
            successorIndex >= 0 ? successorIndex + 1 : successor.rank,
            queueBefore.length,
            {
              todayText,
              trackers: reviewFreshnessSupportsTrackers(api),
              omitActionHint: withinGroup || postLanding,
              reviewEntryView:
                api && typeof api.reviewEntryView === "function"
                  ? (noticeEntry, noticeOptions) =>
                      api.reviewEntryView(noticeEntry, noticeOptions)
                  : null,
            },
          );
          if (postLanding) {
            landingNotice = appendReviewPostLandingTail(landingNotice, remaining);
          }
          const doneLine = withinGroup
            ? formatReviewCtrlEnterDoneLine(taskText, tier)
            : `✓ Done · ${taskText}`;
          new Notice([doneLine, landingNotice].filter(Boolean).join("\n"));
          return true;
        }
        if (landed && landed.stale !== true) {
          new Notice(`✓ Done · ${taskText}\nCould not jump to task`);
          return true;
        }
      }
    }

    if (withinGroup && tier === "pre") {
      const anchor = buildReviewAnchor(
        queueBefore,
        Array.from(handled),
        entry.rank,
        todayText,
      );
      const next = planReviewJump(queueBefore, {
        direction: 1,
        anchor,
        todayText,
      });
      const nextLabel =
        next && next.kind === "jump" ? reviewEntryTierLabel(next.entry) : "";
      new Notice(
        formatReviewChecklistGroupEndNotice({
          taskText,
          tier,
          skipped: liveGroup.before.length,
          nextLabel,
          commitments: remaining.commitments,
        }),
      );
      return true;
    }

    if (tier === "post") {
      if (!advance && liveGroup.after.length + liveGroup.before.length > 0) {
        const postLeft = liveGroup.after.length + liveGroup.before.length;
        new Notice(`✓ Done · ${postLeft} POST left`);
      } else {
        new Notice(
          formatReviewClosedNotice({
            commitments: remaining.commitments,
            postSkipped: liveGroup.before.length,
            rotten: remaining.rotten,
          }),
        );
      }
      return true;
    }

    if (!advance) {
      new Notice(`✓ Done · ${remaining.pre} PRE left`);
      return true;
    }
    const doneLine = `✓ Done · ${taskText}`;
    if (!nextPlan || nextPlan.kind !== "jump") {
      new Notice(doneLine);
      return true;
    }
    const landed = await this.landOnReviewQueueEntry(nextPlan.entry, {
      jumpOrigin,
    });
    if (!landed.ok) {
      new Notice(doneLine);
      return true;
    }
    this.reviewAnchor = buildReviewAnchor(
      queueBefore, [reviewQueueEntryKey(nextPlan.entry)], nextPlan.rank, todayText,
    );
    let landingNotice = buildReviewJumpNotice(
      nextPlan.entry, nextPlan.rank, nextPlan.total, {
        wrapped: nextPlan.wrapped,
        todayText,
        trackers: reviewFreshnessSupportsTrackers(api),
        reviewEntryView:
          api && typeof api.reviewEntryView === "function"
            ? (noticeEntry, noticeOptions) => api.reviewEntryView(noticeEntry, noticeOptions)
            : null,
      },
    );
    const destTier = reviewEntryMachineTier(nextPlan.entry);
    const boundary = buildReviewBoundaryNotice({
      originTier: tier, destTier,
      commitmentsLeft: remaining.commitments,
      rottenLeft: remaining.rotten, postLeft: remaining.post,
    });
    if (destTier === "post") {
      landingNotice = appendReviewPostLandingTail(landingNotice, remaining);
    }
    new Notice([doneLine, boundary, landingNotice].filter(Boolean).join("\n"));
    return true;
  }
}
// ---- src/536-plugin-review-advance.js ----
// Review-walk auto-advance core: the landing-scoped capture/continue
// helper, the gesture lock, and the shared advance tail
// (`docs/freshness.md` §6).
//
// The rule: a gesture that started on the row `]s` just landed on, and that
// committed a write taking that row out of today's walk, advances the walk
// exactly once to the next remaining review item. Capture runs synchronously
// when the gesture starts (taking the gesture lock); continue runs after the
// write, plans anchor-only from the pre-write queue, records a Vim jump,
// and composes one toast. Nothing here throws: capture returns null off a
// landing (behave normally) or REVIEW_WALK_BUSY while locked (swallow the
// key, write nothing), and continue resolves `{ ok, advanced, stopped }`.

const REVIEW_GESTURE_LOCK_MS = 3000;
const REVIEW_ADVANCE_SETTLE_MS = 350;
const REVIEW_WALK_BUSY = Object.freeze({ busy: true });

function reviewAdvanceLineTaskStatus(line) {
  try {
    const status = getObsidianTaskCheckboxStatus(line);
    return typeof status === "string" ? status.toLowerCase() : null;
  } catch (error) {
    return null;
  }
}

function reviewAdvanceLineIsClosed(line) {
  const status = reviewAdvanceLineTaskStatus(line);
  return status === "x" || status === "-";
}

// First `YYYY-MM-DD` value of one inline `[field:: date]` / `(field:: date)`
// on the line, or null. Compared as strings: both sides are validated
// `YYYY-MM-DD`, so lexicographic order is calendar order.
function reviewAdvanceLineInlineDate(line, field) {
  try {
    const pattern = new RegExp(
      `[\\[(]\\s*${field}\\s*::\\s*(\\d{4}-\\d{2}-\\d{2})`,
      "i",
    );
    const match = pattern.exec(String(line || ""));
    return match ? match[1] : null;
  } catch (error) {
    return null;
  }
}

function reviewAdvanceLineDependsOnIds(line) {
  const ids = new Set();
  try {
    const pattern = /[\[(]\s*dependsOn\s*::([^\]\)\n]*)[\]\)]/gi;
    let match = pattern.exec(String(line || ""));
    while (match) {
      for (const segment of String(match[1] || "").split(",")) {
        for (const part of String(segment || "").split(/\s+/)) {
          const id = part.trim();
          if (id) {
            ids.add(id);
          }
        }
      }
      match = pattern.exec(String(line || ""));
    }
  } catch (error) {
    // An unparseable line simply carries no ids below.
  }
  return ids;
}

// Pure outcome predicate: did this gesture's committed write take its row
// out of today's walk? `tier` is the landing's machine tier, `outcome` one
// of the `{ kind }` shapes below, and `todayText` is `YYYY-MM-DD`. When in
// doubt this returns false: a missed advance costs one `]s`, while a wrong
// advance loses context.
function reviewOutcomeResolves(tier, outcome, todayText) {
  try {
    if (!outcome || typeof outcome !== "object") {
      return false;
    }
    const kind = String(outcome.kind || "");
    const checklist = tier === "pre" || tier === "post";
    if (kind === "complete") {
      return true;
    }
    if (kind === "lane" || kind === "link-today" || kind === "move") {
      return !checklist;
    }
    if (kind !== "card") {
      return false;
    }
    const before = String(outcome.beforeLine ?? "");
    const after = String(outcome.afterLine ?? "");
    if (!after || after === before) {
      return false;
    }
    if (reviewAdvanceLineIsClosed(after)) {
      return true;
    }
    const day =
      typeof todayText === "string" && /^\d{4}-\d{2}-\d{2}$/.test(todayText.trim())
        ? todayText.trim()
        : "";
    const scheduled = reviewAdvanceLineInlineDate(after, "scheduled");
    if (scheduled && day && scheduled > day) {
      return true;
    }
    if (checklist) {
      const beforeIds = reviewAdvanceLineDependsOnIds(before);
      for (const id of reviewAdvanceLineDependsOnIds(after)) {
        if (!beforeIds.has(id)) {
          return true;
        }
      }
      return false;
    }
    const fresh = reviewAdvanceLineInlineDate(after, "fresh");
    return Boolean(fresh && day && fresh === day);
  } catch (error) {
    return false;
  }
}

// Second line of a stopped advance: `]s → {LABEL}[ · {c} commitments due]`.
// Shared with the PRE group-end notice so both read the same.
function formatReviewAdvanceStopLine(options = {}) {
  const nextLabel = String(options.nextLabel || "").trim();
  const commitments = Number.isInteger(options.commitments)
    ? Math.max(0, options.commitments)
    : 0;
  return `]s → ${nextLabel}${commitments > 0 ? ` · ${commitments} commitments due` : ""}`;
}

// nav api v3 `reviewWalk` (`docs/task-dependencies.md` §9). Synchronous
// `capture` never throws (null off a landing, REVIEW_WALK_BUSY while
// locked, otherwise a frozen origin that took the gesture lock); async
// `continue` never throws and resolves `{ ok, advanced, stopped }`. With a
// null plugin (after unload) capture returns null and continue shows
// `outcome.notice`, if any, resolving `{ ok: false, advanced: false }`.
function createReviewWalkApi(plugin) {
  const showAlone = (outcome) => {
    try {
      const notice =
        outcome && typeof outcome === "object" && typeof outcome.notice === "string"
          ? outcome.notice
          : "";
      if (notice) {
        new Notice(notice);
      }
    } catch (error) {
      // Best effort: Obsidian is tearing down.
    }
  };
  return Object.freeze({
    version: 1,
    capture(editor) {
      try {
        if (!plugin || typeof plugin.captureReviewGesture !== "function") {
          return null;
        }
        return plugin.captureReviewGesture(editor);
      } catch (error) {
        return null;
      }
    },
    continue(origin, outcome) {
      try {
        if (!plugin || typeof plugin.continueReviewWalkAfter !== "function") {
          showAlone(outcome);
          return Promise.resolve(
            Object.freeze({ ok: false, advanced: false, stopped: false }),
          );
        }
        return Promise.resolve(
          plugin.continueReviewWalkAfter(origin, outcome),
        ).then(
          (result) =>
            result && typeof result === "object"
              ? result
              : Object.freeze({ ok: false, advanced: false, stopped: false }),
          () => Object.freeze({ ok: false, advanced: false, stopped: false }),
        );
      } catch (error) {
        showAlone(outcome);
        return Promise.resolve(
          Object.freeze({ ok: false, advanced: false, stopped: false }),
        );
      }
    },
  });
}

class BobNavigationHotkeysReviewAdvanceMixin {
  // Overridable clock so tests can expire the gesture lock and settle
  // window without sleeping.
  reviewAdvanceNow() {
    return Date.now();
  }

  // True while an answer is in flight or settling. An expired lock reads
  // free. The lock only exists during a review answer, so daytime use
  // never sees it.
  reviewWalkBusy() {
    try {
      const until = this.reviewWalkLock;
      if (until === null || until === undefined) {
        return false;
      }
      if (this.reviewAdvanceNow() >= until) {
        this.reviewWalkLock = null;
        return false;
      }
      return true;
    } catch (error) {
      return false;
    }
  }

  takeReviewWalkLock(ms) {
    try {
      const duration = Math.max(
        0,
        Math.floor(numericOrDefault(ms, REVIEW_GESTURE_LOCK_MS)),
      );
      this.reviewWalkLock = this.reviewAdvanceNow() + duration;
    } catch (error) {
      this.reviewWalkLock = null;
    }
  }

  // End the gesture lock: start the settle window when the gesture wrote,
  // otherwise free the lock immediately.
  settleReviewWalkLock(wrote) {
    try {
      if (wrote === true) {
        this.takeReviewWalkLock(REVIEW_ADVANCE_SETTLE_MS);
      } else {
        this.reviewWalkLock = null;
      }
    } catch (error) {
      this.reviewWalkLock = null;
    }
  }

  // One landing setter: every walk landing replaces the landing and bumps
  // the epoch, so a stale `continue` can never move the cursor.
  setReviewLanding(entry, path) {
    try {
      this.reviewLandingEpoch =
        Math.floor(numericOrDefault(this.reviewLandingEpoch, 0)) + 1;
    } catch (error) {
      this.reviewLandingEpoch = 1;
    }
    this.reviewLanding = Object.freeze({
      path,
      text: entry.originalMarkdown,
      key: reviewQueueEntryKey(entry),
      tier: reviewEntryMachineTier(entry) || null,
      day: this.laneReleaseDateText({}),
    });
  }

  // Accumulate today's answered keys (the accumulator resets on day
  // change). Never throws.
  addReviewAnsweredKeys(keys, dayText) {
    try {
      const day = String(dayText || "");
      if (
        !this.reviewAnsweredKeys ||
        typeof this.reviewAnsweredKeys !== "object" ||
        this.reviewAnsweredKeys.day !== day
      ) {
        this.reviewAnsweredKeys = { day, keys: new Set() };
      }
      const set =
        this.reviewAnsweredKeys.keys instanceof Set
          ? this.reviewAnsweredKeys.keys
          : new Set();
      this.reviewAnsweredKeys.keys = set;
      for (const key of Array.isArray(keys) ? keys : []) {
        if (typeof key === "string" && key) {
          set.add(key);
        }
      }
    } catch (error) {
      // Best effort: answering never depends on the accumulator.
    }
  }

  // Pre-landing cursor for the `<C-o>` jump record, or null. Read before
  // the landing moves the cursor.
  getReviewWalkOriginCursor() {
    try {
      const view = this.getActiveMarkdownView();
      if (
        !view ||
        !view.file ||
        typeof view.file.path !== "string" ||
        !view.editor ||
        typeof view.editor.getCursor !== "function"
      ) {
        return null;
      }
      const cursor = normalizePosition(view.editor.getCursor());
      if (!cursor) {
        return null;
      }
      return { path: view.file.path, line: cursor.line, ch: cursor.ch };
    } catch (error) {
      return null;
    }
  }

  // Synchronous landing check when a gesture starts. Null means "not on a
  // landing, behave normally"; REVIEW_WALK_BUSY means "swallow the key,
  // write nothing"; otherwise the frozen origin, which took the gesture
  // lock and must be settled exactly once via continueReviewWalkAfter.
  captureReviewGesture(editor) {
    try {
      if (this.reviewWalkBusy()) {
        return REVIEW_WALK_BUSY;
      }
      const landing = this.reviewLanding;
      if (!landing) {
        return null;
      }
      const todayText = this.laneReleaseDateText({});
      if (landing.day !== todayText) {
        return null;
      }
      const view = this.getActiveMarkdownView();
      if (
        !view ||
        !view.file ||
        !view.editor ||
        view.editor !== editor ||
        view.file.path !== landing.path
      ) {
        return null;
      }
      const cursor = getEditorCursor(editor);
      const text = cursor ? getEditorLine(editor, cursor.line) : null;
      if (text === null || String(text) !== landing.text) {
        return null;
      }
      const queueBefore = this.readFreshnessQueue(
        getReviewFreshnessApi(this.app),
      );
      const found = queueBefore.find(
        (candidate) => reviewQueueEntryKey(candidate) === landing.key,
      );
      if (!found) {
        return null;
      }
      this.reviewGestureSeq =
        Math.floor(numericOrDefault(this.reviewGestureSeq, 0)) + 1;
      this.takeReviewWalkLock(REVIEW_GESTURE_LOCK_MS);
      const anchor = this.reviewAnchor;
      const priorKeys =
        anchor &&
        reviewAnchorIsCurrentDay(anchor, todayText) &&
        Array.isArray(anchor.keys)
          ? anchor.keys.slice()
          : [];
      const taskText =
        found && typeof found.text === "string" && found.text.trim()
          ? found.text.trim()
          : "task";
      return Object.freeze({
        seq: this.reviewGestureSeq,
        epoch: Math.floor(numericOrDefault(this.reviewLandingEpoch, 0)),
        day: todayText,
        path: landing.path,
        line: cursor.line,
        text: landing.text,
        key: landing.key,
        tier: landing.tier || null,
        taskText,
        rank: Number.isInteger(found.rank) ? found.rank : null,
        queueBefore: Object.freeze(
          queueBefore.map((row) => Object.freeze({ ...(row || {}) })),
        ),
        priorKeys: Object.freeze(priorKeys),
      });
    } catch (error) {
      return null;
    }
  }

  // After the gesture's write: refuse stale origins, stay on
  // non-resolving outcomes, and otherwise consume the landing and advance
  // exactly once through the shared tail. Never throws. `outcome.notice`
  // is shown exactly once: composed into the landing toast, or on its own.
  async continueReviewWalkAfter(origin, outcome) {
    let notice = "";
    let shown = false;
    const showNotice = (text) => {
      if (shown) {
        return;
      }
      const message = String(text || "");
      if (!message) {
        return;
      }
      shown = true;
      try {
        new Notice(message);
      } catch (error) {
        // Best effort: Obsidian is tearing down.
      }
    };
    try {
      // Yield one macrotask before doing anything, so a modal submit has
      // closed and focus has returned before the state is read.
      await new Promise((resolve) => setTimeout(resolve, 0));
      const input = outcome && typeof outcome === "object" ? outcome : null;
      if (input && typeof input.notice === "string" && input.notice) {
        notice = input.notice;
      }
      const seq = Math.floor(numericOrDefault(this.reviewGestureSeq, 0));
      const epoch = Math.floor(numericOrDefault(this.reviewLandingEpoch, 0));
      const todayText = this.laneReleaseDateText({});
      const stale =
        !origin ||
        typeof origin !== "object" ||
        origin.seq !== seq ||
        origin.epoch !== epoch ||
        !this.reviewLanding ||
        this.reviewLanding.key !== origin.key ||
        todayText !== origin.day;
      if (stale) {
        showNotice(notice);
        // Settle only our own lock: a stale origin means a newer gesture
        // or landing owns it now.
        if (origin && typeof origin === "object" && origin.seq === seq) {
          this.settleReviewWalkLock(false);
        }
        return Object.freeze({ ok: true, advanced: false, stopped: false });
      }
      const kind = input ? String(input.kind || "") : "";
      const tier = typeof origin.tier === "string" ? origin.tier : "";
      // A checklist completion that reaches continue (the claim declined
      // on mixed versions) stays: the claim owns checklist rows.
      const resolves =
        kind === "complete" && (tier === "pre" || tier === "post")
          ? false
          : reviewOutcomeResolves(tier, input, todayText);
      if (!resolves) {
        showNotice(notice);
        this.settleReviewWalkLock(false);
        return Object.freeze({ ok: true, advanced: false, stopped: false });
      }
      // Consume synchronously: the landing is gone and the walk anchor
      // covers the answered row before any await can interleave.
      this.reviewLanding = null;
      const handledRefs =
        input && Array.isArray(input.handledRefs) ? input.handledRefs : [];
      let matchedKeys = [];
      try {
        const matched = matchFreshStampRefs(origin.queueBefore, handledRefs);
        matchedKeys = Array.isArray(matched.keys) ? matched.keys : [];
      } catch (error) {
        matchedKeys = [];
      }
      const handled = new Set(
        [origin.key]
          .concat(Array.isArray(origin.priorKeys) ? origin.priorKeys : [])
          .concat(matchedKeys),
      );
      try {
        const stored = this.reviewAnsweredKeys;
        if (
          stored &&
          typeof stored === "object" &&
          stored.day === todayText &&
          stored.keys instanceof Set
        ) {
          for (const key of stored.keys) {
            handled.add(key);
          }
        }
      } catch (error) {
        // The accumulator is advisory; the handled set above still walks.
      }
      this.addReviewAnsweredKeys(Array.from(handled), todayText);
      const before = Array.isArray(origin.queueBefore) ? origin.queueBefore : [];
      const landedEntry = before.find(
        (row) => reviewQueueEntryKey(row) === origin.key,
      );
      const entryRank = Number.isInteger(origin.rank)
        ? origin.rank
        : Number.isInteger(landedEntry && landedEntry.rank)
          ? landedEntry.rank
          : 1;
      const anchor = buildReviewAnchor(
        before,
        Array.from(handled),
        entryRank,
        todayText,
      );
      this.reviewAnchor = anchor;
      const remaining = reviewWalkRemaining(before, handled);
      const preamble =
        notice || (kind === "complete" ? `✓ Done · ${origin.taskText || "task"}` : "");
      const tailed = await this.advanceReviewWalkAfterAnswer({
        anchor,
        preamble,
        originTier: tier || null,
        stopBeforeChecklist: kind === "complete",
        closeOnPostWrap: tier === "post",
        remaining,
      });
      return Object.freeze({
        ok: true,
        advanced: tailed.advanced === true,
        stopped: tailed.stopped === true,
      });
    } catch (error) {
      showNotice(notice);
      return Object.freeze({ ok: false, advanced: false, stopped: false });
    }
  }

  // One composed toast from the preamble and the tail lines.
  composeReviewAdvanceNotice(preamble, ...parts) {
    return [preamble].concat(parts).filter(Boolean).join("\n");
  }

  // The advance gates for one plan: the Ctrl+Enter checklist-boundary stop
  // and the POST no-wrap close. Returns the stop notice, or null to land.
  checkReviewAdvanceStop(plan, settings, remaining) {
    const entry = plan && plan.entry ? plan.entry : null;
    if (
      settings.stopBeforeChecklist === true &&
      reviewIsChecklistTier(reviewEntryMachineTier(entry))
    ) {
      return formatReviewAdvanceStopLine({
        nextLabel: reviewEntryTierLabel(entry),
        commitments: remaining.commitments,
      });
    }
    if (settings.closeOnPostWrap === true && plan.wrapped === true) {
      return formatReviewClosedNotice({
        commitments: remaining.commitments,
        postSkipped: remaining.post,
        rotten: remaining.rotten,
      });
    }
    return null;
  }

  // Shared advance tail. Plans anchor-only from the pre-write queue (never
  // from the post-write cursor, which can sit on a different due row after
  // a move or a line-shifting write), holds the in-flight lock, records
  // the Vim jump at landing, and shows one composed toast. Resolves
  // `{ advanced, stopped }`; `jumpToDueTask` narrows that to a boolean.
  async advanceReviewWalkAfterAnswer(options = {}) {
    const settings = options && typeof options === "object" ? options : {};
    this.takeReviewWalkLock(REVIEW_GESTURE_LOCK_MS);
    try {
      const preamble =
        typeof settings.preamble === "string" && settings.preamble
          ? settings.preamble
          : "";
      const api = getReviewFreshnessApi(this.app);
      if (!api) {
        new Notice(preamble || REVIEW_FRESHNESS_API_REQUIRED_NOTICE);
        return { advanced: false, stopped: false };
      }
      const todayText = this.laneReleaseDateText({});
      const anchor =
        settings.anchor && typeof settings.anchor === "object"
          ? settings.anchor
          : settings.fromStamp && typeof settings.fromStamp === "object"
            ? settings.fromStamp
            : null;
      let queue = this.readFreshnessQueue(api);
      const counts = this.readFreshnessCounts(api);
      if (queue.length === 0) {
        this.reviewLanding = null;
        new Notice(
          this.composeReviewAdvanceNotice(preamble, buildReviewEmptyNotice(counts)),
        );
        return { advanced: false, stopped: false };
      }
      const planOnce = (walkQueue) =>
        planReviewJump(walkQueue, {
          direction: 1,
          cursor: null,
          anchor,
          todayText,
        });
      let plan = planOnce(queue);
      if (plan.kind === "empty") {
        this.reviewLanding = null;
        new Notice(
          this.composeReviewAdvanceNotice(preamble, buildReviewEmptyNotice(counts)),
        );
        return { advanced: false, stopped: false };
      }
      const remaining =
        settings.remaining && typeof settings.remaining === "object"
          ? settings.remaining
          : reviewWalkRemaining(
              queue,
              anchor && Array.isArray(anchor.keys) ? anchor.keys : [],
            );
      const stopped = this.checkReviewAdvanceStop(plan, settings, remaining);
      if (stopped !== null) {
        new Notice(this.composeReviewAdvanceNotice(preamble, stopped));
        return { advanced: false, stopped: true };
      }
      let landed = await this.landOnReviewQueueEntry(plan.entry, {
        jumpOrigin: this.getReviewWalkOriginCursor(),
      });
      if (!landed.ok && landed.stale) {
        queue = this.readFreshnessQueue(api);
        plan = planOnce(queue);
        if (plan.kind === "empty") {
          this.reviewLanding = null;
          const emptyNotice = buildReviewEmptyNotice(counts);
          new Notice(this.composeReviewAdvanceNotice(preamble, emptyNotice));
          return { advanced: false, stopped: false };
        }
        const restopped = this.checkReviewAdvanceStop(plan, settings, remaining);
        if (restopped !== null) {
          new Notice(this.composeReviewAdvanceNotice(preamble, restopped));
          return { advanced: false, stopped: true };
        }
        landed = await this.landOnReviewQueueEntry(plan.entry, {
          jumpOrigin: this.getReviewWalkOriginCursor(),
        });
      }
      if (!landed.ok) {
        new Notice(
          this.composeReviewAdvanceNotice(
            preamble,
            landed.stale
              ? REVIEW_QUEUE_CHANGED_NOTICE
              : "Could not jump to task",
          ),
        );
        return { advanced: false, stopped: false };
      }
      // The walk anchor follows every successful landing, so a later
      // gesture continues from here.
      this.reviewAnchor = buildReviewAnchor(
        queue,
        [reviewQueueEntryKey(plan.entry)],
        plan.rank,
        todayText,
      );
      let landingNotice = buildReviewJumpNotice(
        plan.entry,
        plan.rank,
        plan.total,
        {
          wrapped: plan.wrapped,
          todayText,
          trackers: reviewFreshnessSupportsTrackers(api),
          reviewEntryView:
            api && typeof api.reviewEntryView === "function"
              ? (noticeEntry, noticeOptions) =>
                  api.reviewEntryView(noticeEntry, noticeOptions)
              : null,
        },
      );
      const destTier = reviewEntryMachineTier(plan.entry);
      const originTier =
        typeof settings.originTier === "string" && settings.originTier
          ? settings.originTier
          : plan && typeof plan.originTier === "string"
            ? plan.originTier
            : null;
      const boundary = buildReviewBoundaryNotice({
        originTier,
        destTier,
        commitmentsLeft: remaining.commitments,
        rottenLeft: remaining.rotten,
        postLeft: remaining.post,
      });
      if (destTier === "post") {
        landingNotice = appendReviewPostLandingTail(landingNotice, remaining);
      }
      new Notice(
        this.composeReviewAdvanceNotice(preamble, boundary, landingNotice),
      );
      return { advanced: true, stopped: false };
    } finally {
      this.settleReviewWalkLock(true);
    }
  }

  // Land on one queue entry without writing: resolve its line in the target
  // note, then put the cursor there and center it. Same-note landings write
  // the cursor directly; cross-note landings reuse the leaf-reuse open plus
  // the shared jump-or-defer retry so the cursor lands after the new leaf
  // renders. Returns `{ ok, stale }`; `stale` means the queue moved and the
  // caller should rebuild once and try again. `options.jumpOrigin` is the
  // pre-landing cursor: every walk landing records a Vim jump from it to
  // the landed row, so `<C-o>` returns to the answered row. Recording never
  // blocks the landing.
  async landOnReviewQueueEntry(entry, options = {}) {
    const jumpOrigin =
      options && typeof options === "object" ? options.jumpOrigin : null;
    const path = entry && typeof entry.path === "string" ? entry.path : "";
    if (!path) {
      return { ok: false, stale: true };
    }
    const activeView = this.getActiveMarkdownView();
    const activeEditor = activeView && activeView.editor;
    const sameNote = Boolean(
      activeView &&
        activeView.file &&
        activeView.file.path === path &&
        activeEditor &&
        typeof activeEditor.getValue === "function",
    );
    let content = null;
    let file =
      activeView && activeView.file && activeView.file.path === path
        ? activeView.file
        : null;
    if (sameNote) {
      content = String(activeEditor.getValue() || "");
    } else {
      const vault = this.app && this.app.vault;
      file =
        file ||
        (vault && typeof vault.getAbstractFileByPath === "function"
          ? vault.getAbstractFileByPath(path)
          : null);
      if (!file) {
        return { ok: false, stale: true };
      }
      content = await this.readLinkPickerNoteContent(path, file);
      if (content === null) {
        return { ok: false, stale: true };
      }
    }
    const resolved = resolveReviewQueueLine(content, entry);
    if (!resolved.ok) {
      return { ok: false, stale: true };
    }
    if (sameNote) {
      if (!setEditorCursor(activeEditor, { line: resolved.line, ch: 0 })) {
        return { ok: false, stale: false };
      }
      scheduleOpenTaskJumpCenter(this, activeEditor, resolved.line, 0);
      if (jumpOrigin) {
        try {
          const jumpContext =
            this.createVimJumpContextWithOrigin(jumpOrigin);
          if (jumpContext) {
            const settled = this.enqueueVimJumpContextTransition(
              jumpContext,
              { path, line: resolved.line, ch: 0 },
              { expectedPath: path },
            );
            if (settled && typeof settled.catch === "function") {
              settled.catch(() => false);
            }
          }
        } catch (error) {
          // Jump history is best-effort after a successful landing.
        }
      }
      this.setReviewLanding(entry, path);
      return { ok: true, stale: false };
    }
    const opened = await openMarkdownFileWithLeafReuse(
      this,
      file,
      `Review jump, but could not open ${path}`,
    );
    if (!opened) {
      return { ok: false, stale: false };
    }
    if (jumpOrigin) {
      let jumpContext = null;
      try {
        jumpContext = this.createVimJumpContextWithOrigin(jumpOrigin);
      } catch (error) {
        jumpContext = null;
      }
      if (jumpContext) {
        const completion = {
          token: jumpContext.token,
          resolve: (result) => {
            try {
              if (result && result.ok && result.destination) {
                const settled = this.enqueueVimJumpContextTransition(
                  jumpContext,
                  result.destination,
                  { expectedPath: path },
                );
                if (settled && typeof settled.catch === "function") {
                  settled.catch(() => false);
                }
              }
            } catch (error) {
              // Jump history is best-effort after a successful landing.
            }
          },
        };
        this.jumpOrDeferTaskMoveDestination(
          path,
          { line: resolved.line, text: entry.originalMarkdown },
          TASK_MOVE_DESTINATION_JUMP_RETRIES,
          completion,
        );
      } else {
        this.jumpOrDeferTaskMoveDestination(path, {
          line: resolved.line,
          text: entry.originalMarkdown,
        });
      }
    } else {
      this.jumpOrDeferTaskMoveDestination(path, {
        line: resolved.line,
        text: entry.originalMarkdown,
      });
    }
    this.setReviewLanding(entry, path);
    return { ok: true, stale: false };
  }

  // Capture a Vim count for `]s` / `[s` before any await. An explicit
  // `options.repeat` is the whole count and skips Vim. Endpoint jumps
  // ignore a pending prefix. Otherwise a Vim-normal editor with an
  // explicit prefix is N queue steps; reset that state immediately so
  // CodeMirror cannot drop it across the landing await.
  consumePendingReviewJumpRepeat(options, endpoint) {
    if (options && options.repeat !== undefined && options.repeat !== null) {
      return normalizeVimRepeat(options.repeat);
    }
    if (endpoint) {
      return 1;
    }
    try {
      const view = this.getActiveMarkdownView();
      const editor = view && view.editor;
      if (!editor || !this.isVimNormalModeEditor(editor, view)) {
        return 1;
      }
      const cm = this.resolveVimCodeMirror(editor, view);
      const pending = getPendingVimRepeat(cm);
      if (!pending.explicit) {
        return 1;
      }
      resetPendingVimInputState(cm, "counted-review-jump");
      return normalizeVimRepeat(pending.repeat);
    } catch {
      return 1;
    }
  }

  // Vault-wide jump to the next (direction +1) or previous (direction -1)
  // task due for freshness review. From a queued task go to the following
  // (or preceding) entry; from a just-stamped task go to the entry after
  // its remembered rank tuple; otherwise go to the first (or last) entry.
  // Wraps with a Notice; an empty queue shows the refreshed-today count.
  // With `options.endpoint` ("first"/"last") jump to that queue endpoint
  // instead, ignoring cursor, anchor, and a typed count, without a
  // boundary preamble. A Vim count on a relative jump is N queue steps
  // in one landing.
  async jumpToDueTask(direction, options = {}) {
    // While an answer is in flight or settling, every external walk key
    // (`]s` `[s` `]S` `[S` Ctrl+Alt+J/K) is swallowed silently with no
    // write. The shared advance tail sets `fromAdvance` to bypass this.
    const fromAdvance = options && options.fromAdvance === true;
    if (!fromAdvance && this.reviewWalkBusy()) {
      return false;
    }
    // The shared advance tail: anchor-only planning, the in-flight lock,
    // jump recording, and one composed toast. Ctrl+Alt+F and the decay
    // card advance through here with their preamble.
    if (fromAdvance) {
      const tailed = await this.advanceReviewWalkAfterAnswer(options);
      return tailed.advanced === true;
    }
    const api = this.requireFreshnessApi();
    if (!api) {
      return false;
    }
    const step = direction < 0 ? -1 : 1;
    const endpointRaw =
      options && typeof options.endpoint === "string"
        ? options.endpoint.trim().toLowerCase()
        : "";
    const endpoint =
      endpointRaw === "first" || endpointRaw === "last" ? endpointRaw : null;
    const repeat = this.consumePendingReviewJumpRepeat(options, endpoint);
    const jumpOrigin = this.getReviewWalkOriginCursor();
    let queue = this.readFreshnessQueue(api);
    if (queue.length === 0) {
      this.reviewLanding = null;
      new Notice(buildReviewEmptyNotice(this.readFreshnessCounts(api)));
      return false;
    }
    const cursor = this.getReviewJumpCursor();
    const todayText = this.laneReleaseDateText({});
    let anchor =
      options.fromStamp !== undefined
        ? options.fromStamp
        : this.reviewAnchor || null;
    if (anchor && !reviewAnchorIsCurrentDay(anchor, todayText)) {
      anchor = null;
    }
    let plan = planReviewJump(queue, {
      direction: step,
      cursor,
      stamped: anchor,
      anchor,
      todayText,
      endpoint,
      repeat,
    });
    if (plan.kind === "empty") {
      this.reviewLanding = null;
      new Notice(buildReviewEmptyNotice(this.readFreshnessCounts(api)));
      return false;
    }
    let landed = await this.landOnReviewQueueEntry(plan.entry, { jumpOrigin });
    if (!landed.ok && landed.stale) {
      queue = this.readFreshnessQueue(api);
      plan = planReviewJump(queue, {
        direction: step,
        cursor,
        stamped: anchor,
        anchor,
        todayText,
        endpoint,
        repeat,
      });
      if (plan.kind === "empty") {
        this.reviewLanding = null;
        new Notice(buildReviewEmptyNotice(this.readFreshnessCounts(api)));
        return false;
      }
      landed = await this.landOnReviewQueueEntry(plan.entry, { jumpOrigin });
    }
    if (!landed.ok) {
      new Notice(
        landed.stale ? REVIEW_QUEUE_CHANGED_NOTICE : "Could not jump to task",
      );
      return false;
    }
    // The walk anchor follows every successful landing, so a later
    // release, roll, or stamp continues from here.
    this.reviewAnchor = buildReviewAnchor(
      queue,
      [reviewQueueEntryKey(plan.entry)],
      plan.rank,
      todayText,
    );
    let notice = buildReviewJumpNotice(plan.entry, plan.rank, plan.total, {
      wrapped: plan.wrapped,
      todayText,
      trackers: reviewFreshnessSupportsTrackers(api),
      reviewEntryView:
        api && typeof api.reviewEntryView === "function"
          ? (noticeEntry, noticeOptions) =>
              api.reviewEntryView(noticeEntry, noticeOptions)
          : null,
    });
    const destTier = reviewEntryMachineTier(plan.entry);
    const handled = new Set(
      anchor && Array.isArray(anchor.keys) ? anchor.keys : [],
    );
    const remaining = reviewWalkRemaining(queue, handled);
    // A forward step out of the commitments into ROTTEN or POST names
    // the boundary (v4 tier entries only; v3 keeps the plain jump
    // notice). Endpoint jumps never carry the relative-walk boundary
    // preamble. Landing on POST always appends remaining counts.
    if (!endpoint && step > 0 && reviewFreshnessSupportsTiers(api)) {
      const boundary = buildReviewBoundaryNotice({
        originTier:
          plan && typeof plan.originTier === "string" ? plan.originTier : null,
        destTier,
        commitmentsLeft: remaining.commitments,
        rottenLeft: remaining.rotten,
        postLeft: remaining.post,
      });
      if (boundary) {
        notice = `${boundary}\n${notice}`;
      }
    }
    if (destTier === "post") {
      notice = appendReviewPostLandingTail(notice, remaining);
    }
    new Notice(notice);
    return true;
  }
}
// ---- src/540-plugin-decay-picker-and-cancel.js ----
class BobNavigationHotkeysDecayCancelMixin {

  // Less often at 90+: the existing custom refresh picker, constrained to
  // a longer value ≤365. The picker only selects; the commit revalidates
  // and writes through the same single-transaction path as presets. A
  // dismissed picker stays due and never advances.
  openFreshnessDecayLessOftenPicker(cardCtx) {
    try {
      const lessOften = cardCtx.plan.lessOften;
      if (!lessOften || lessOften.mode !== "picker") {
        return false;
      }
      const liveLine = getEditorLine(cardCtx.cm, cardCtx.line);
      if (liveLine === null || liveLine !== cardCtx.rawLine) {
        new Notice(REVIEW_QUEUE_CHANGED_NOTICE);
        return false;
      }
      const picker = new BulletPropertyPickerModal(
        this.app,
        this,
        cardCtx.cm,
        { line: cardCtx.line, ch: 0 },
        liveLine,
        this.config,
        {
          filePath: cardCtx.filePath,
          baseDate: getLocalDateStart(new Date()),
          directStage: true,
        },
      );
      picker.showRefreshValueStage({
        days: lessOften.beforeDays,
        mixed: false,
        property: { values: "number" },
      });
      const constrained = createRefreshValueItems(lessOften.beforeDays).filter(
        (item) =>
          Number.isInteger(item.refreshDays) &&
          item.refreshDays >= lessOften.minDays &&
          item.refreshDays <= lessOften.maxDays,
      );
      picker.applyOptions({
        items: constrained,
        title: `Refresh every · longer than ${lessOften.beforeDays} d`,
        emptyText: `No longer preset · type ${lessOften.minDays}–${lessOften.maxDays}`,
        getSubtitle: () =>
          `Choose days · current: every ${lessOften.beforeDays} d · longer only`,
        openItem: (item) => picker.applySelectedValue(item),
      });
      const plugin = this;
      picker.applySelectedValue = async (item) => {
        try {
          const days =
            item && Number.isInteger(item.refreshDays)
              ? item.refreshDays
              : item && Number.isInteger(item.value)
                ? item.value
                : null;
          if (
            !Number.isInteger(days) ||
            days < lessOften.minDays ||
            days > lessOften.maxDays
          ) {
            new Notice(
              `Choose every ${lessOften.minDays}–${lessOften.maxDays} days`,
            );
            return false;
          }
          picker.close();
          const check = plugin.revalidateFreshnessDecayCard(cardCtx);
          if (!check.ok) {
            new Notice(REVIEW_QUEUE_CHANGED_NOTICE);
            await plugin.reopenFreshnessDecayCard(cardCtx);
            return false;
          }
          return await plugin.applyFreshnessDecayLessOftenDays(
            cardCtx,
            check.live,
            lessOften.beforeDays,
            days,
          );
        } catch (error) {
          new Notice("Could not update task; no tasks were updated");
          return false;
        }
      };
      picker.applyRefreshCustomFromQuery = (query) => {
        try {
          const custom = parseRefreshCustomValue(query);
          if (custom === null) {
            return false;
          }
          void picker.applySelectedValue({
            refreshDays: custom,
            value: custom,
          });
          return true;
        } catch (error) {
          return false;
        }
      };
      picker.open();
      return true;
    } catch (error) {
      new Notice("Could not update task; no tasks were updated");
      return false;
    }
  }

  // Reword (E): stamp and clear, then put the cursor at the end of the
  // task body before metadata for editing. Stays on this task even for
  // Ctrl+Alt+F — no walk advance.
  async applyFreshnessDecayCardReword(cardCtx, live) {
    try {
      const stamper = this.getFreshnessStampLine();
      if (typeof stamper !== "function") {
        new Notice(REVIEW_FRESHNESS_API_REQUIRED_NOTICE);
        return false;
      }
      const nextLine = applyFreshStampLine(
        live.lineText,
        stamper,
        cardCtx.dateText,
      );
      const reason = formatFreshnessDecisionRewordReason({
        keeps: cardCtx.keeps,
      });
      if (reason !== cardCtx.plan.reword.reason) {
        new Notice(REVIEW_QUEUE_CHANGED_NOTICE);
        return false;
      }
      const logPlan = planScheduleLogEntry(live.content, cardCtx.line, {
        from: cardCtx.currentScheduled,
        to: cardCtx.currentScheduled,
        reason,
      });
      const split = splitMarkdownContent(live.content);
      const lines = split.lines.slice();
      lines[cardCtx.line] = nextLine;
      applyScheduleLogEntryToLines(lines, logPlan);
      const applied = applyEditorContentTransaction(
        cardCtx.cm,
        live.content,
        lines.join(split.lineEnding),
        {
          line: cardCtx.line,
          ch: freshnessDecayRewordCursorCh(nextLine),
        },
      );
      if (!applied) {
        new Notice("Could not update task; no tasks were updated");
        return false;
      }
      try {
        if (cardCtx.cm && typeof cardCtx.cm.focus === "function") {
          cardCtx.cm.focus();
        }
      } catch (error) {
        // Best effort: the cursor is already placed for editing.
      }
      this.rememberFreshnessDecayCardAnchor(cardCtx);
      new Notice("Reword · count restarted — edit the task");
      return true;
    } catch (error) {
      new Notice("Could not update task; no tasks were updated");
      return false;
    }
  }

  // Drop (D): the existing guarded cancel writer and side effects, with
  // the dated `dropped after N keeps` Cancel Log reason. History stays
  // on the closed line; no stamp runs on a cancel row.
  async applyFreshnessDecayCardDrop(cardCtx, live) {
    try {
      const reason = cardCtx.plan.drop ? cardCtx.plan.drop.reason : "";
      if (!reason) {
        new Notice("Could not update task; no tasks were updated");
        return false;
      }
      const ok = await this.applyTaskCancelFromPicker(
        {
          editor: cardCtx.cm,
          cursor: { line: cardCtx.line, ch: 0 },
          filePath: cardCtx.filePath,
          lineText: cardCtx.rawLine,
          valueBaseDate: getLocalDateStart(new Date()),
        },
        { reason },
      );
      if (!ok) {
        return false;
      }
      this.rememberFreshnessDecayCardAnchor(cardCtx);
      await this.maybeAdvanceFreshnessDecayWalk(cardCtx, "drop");
      return true;
    } catch (error) {
      new Notice("Could not update task; no tasks were updated");
      return false;
    }
  }

  // Keep (Alt+F): a counted keep with saturation — stamp, do not reset.
  // The next due review asks again.
  async applyFreshnessDecayCardKeep(cardCtx, live) {
    try {
      const api = getReviewFreshnessApi(this.app);
      if (!freshnessSupportsKeeps(api)) {
        new Notice(REVIEW_FRESHNESS_KEEP_REQUIRED_NOTICE);
        return false;
      }
      if (getEditorLine(cardCtx.cm, cardCtx.line) !== live.lineText) {
        new Notice(REVIEW_QUEUE_CHANGED_NOTICE);
        return false;
      }
      let nextLine = null;
      try {
        nextLine = String(
          api.keepLine(live.lineText, cardCtx.dateText, { counted: true }) ??
            live.lineText,
        );
      } catch (error) {
        new Notice("Could not update task; no tasks were updated");
        return false;
      }
      if (!replaceEditorLine(cardCtx.cm, cardCtx.line, live.lineText, nextLine)) {
        new Notice("Could not update task; no tasks were updated");
        return false;
      }
      this.rememberFreshnessDecayCardAnchor(cardCtx);
      const nextKeeps = Math.min(999, cardCtx.keeps + 1);
      new Notice(`Kept ${nextKeeps}× · next review asks`);
      await this.maybeAdvanceFreshnessDecayWalk(cardCtx, "keep");
      return true;
    } catch (error) {
      new Notice("Could not update task; no tasks were updated");
      return false;
    }
  }

  // Capture-phase fallback so Alt+F / Ctrl+Alt+F reach the counted refresh
  // route while Vim normal mode is active. CodeMirror Vim swallows Alt
  // chords before Obsidian's hotkey dispatcher runs, so the hotkeys below
  // only cover insert mode and non-Vim editing. A pending numeric Vim prefix
  // is "N additional tasks", mirroring the counted Alt+N route, and
  // Ctrl+Alt+F selects refresh-and-advance.
  registerReviewRefreshInputListeners() {
    this.handledReviewRefreshEvents = new WeakSet();
    const keydownHandler = (event) =>
      this.handleReviewRefreshPhysicalKeydown(event);
    const targets = [];
    if (typeof window !== "undefined") {
      targets.push(window);
    }
    if (typeof document !== "undefined" && document !== window) {
      targets.push(document);
    }
    for (const target of targets) {
      if (!target || typeof target.addEventListener !== "function") {
        continue;
      }
      target.addEventListener("keydown", keydownHandler, true);
      this.register(() => {
        target.removeEventListener("keydown", keydownHandler, true);
      });
    }
  }

  handleReviewRefreshPhysicalKeydown(event) {
    if (event && event.repeat) {
      return false;
    }
    if (
      !isReviewRefreshKeydown(event, false) &&
      !isReviewRefreshKeydown(event, true)
    ) {
      return false;
    }
    if (
      this.handledReviewRefreshEvents &&
      this.handledReviewRefreshEvents.has(event)
    ) {
      return false;
    }
    const view = this.getFocusedMarkdownEditorView(event);
    if (!view || !this.isVimNormalModeEditor(view.editor, view)) {
      return false;
    }
    const cm = this.resolveVimCodeMirror(view.editor, view);
    const pendingRepeat = getPendingVimRepeat(cm);
    if (this.handledReviewRefreshEvents) {
      this.handledReviewRefreshEvents.add(event);
    }
    event.preventDefault();
    event.stopPropagation();
    if (typeof event.stopImmediatePropagation === "function") {
      event.stopImmediatePropagation();
    }
    resetPendingVimInputState(cm, "review-freshness-refresh");
    void this.refreshTaskFreshness(view.editor, {
      advance: isReviewRefreshKeydown(event, true),
      countExplicit: pendingRepeat.explicit,
      additionalTaskCount: pendingRepeat.explicit ? pendingRepeat.repeat : 0,
    }).catch(() => false);
    return true;
  }

  async applyLaneToggleFromPicker(picker, options = {}) {
    if (!picker) {
      new Notice("Could not update task; no tasks were updated");
      return false;
    }
    const summary =
      typeof options.summary === "string" ? options.summary : "";
    const dateText =
      typeof options.dateText === "string" && options.dateText
        ? String(options.dateText)
        : formatBulletPropertyDate(getLocalDateStart(new Date()));
    if (picker.linkSession) {
      const resolved = Array.isArray(picker.linkSession.resolved)
        ? picker.linkSession.resolved
        : [];
      if (resolved.length === 0) {
        new Notice("Could not update task; no tasks were updated");
        return false;
      }
      const laneBudgets = readLaneBudgets(this.app);
      const groups = groupLinkPickerTargetsByNote(resolved);
      const planned = [];
      for (const group of groups) {
        const plan = planTaskLaneBatch(group.content, group.session, {
          summary,
          dateText,
          stampLine: this.getFreshnessStampLine(),
          freshDateText: this.getFreshnessDateText(),
        });
        if (!plan.valid) {
          new Notice("A linked note changed; no tasks were updated");
          return false;
        }
        planned.push({ group, plan });
      }
      const pruneTargets = [];
      for (const { group, plan } of planned) {
        if (plan.mode !== "release") {
          continue;
        }
        for (const entry of plan.released) {
          if (entry.blockId) {
            pruneTargets.push(
              Object.freeze({ path: group.path, blockId: entry.blockId }),
            );
          }
        }
      }
      let pomodoroSnapshot = null;
      let dailyCleanupPlan = null;
      let foldedDailyPath = null;
      if (pruneTargets.length > 0) {
        const sourcePaths = planned.map(({ group }) => group.path);
        pomodoroSnapshot = await this.readDeferredPomodoroSnapshot(this.app, {
          sourcePath: sourcePaths.length === 1 ? sourcePaths[0] : "",
          sourceContent: planned.length === 1 ? planned[0].plan.content : "",
          today: new Date(),
        });
        if (pomodoroSnapshot) {
          const folded = planned.find(
            ({ group }) => group.path === pomodoroSnapshot.dailyPath,
          );
          const dailyBase = folded
            ? folded.plan.content
            : pomodoroSnapshot.content;
          if (dailyBase !== null) {
            dailyCleanupPlan = planDeferredPomodoroLinkCleanup(
              dailyBase,
              pruneTargets,
              {
                dailyPath: pomodoroSnapshot.dailyPath,
                noteIndex: pomodoroSnapshot.noteIndex,
              },
            );
            if (folded && dailyCleanupPlan.changed) {
              foldedDailyPath = folded.group.path;
            }
          }
        }
      }
      const commit = await this.commitLinkPickerNoteWrites(planned, {
        pomodoroSnapshot,
        dailyCleanupPlan,
        foldedDailyPath,
      });
      if (!commit.ok) {
        new Notice("A linked note changed; no tasks were updated");
        return false;
      }
      let changedTaskCount = 0;
      let blockedSkipped = 0;
      let releasedNextCount = 0;
      let releasedPendingCount = 0;
      let mode = "commit";
      for (const { plan } of planned) {
        changedTaskCount += plan.changedTaskCount;
        blockedSkipped += plan.blockedSkipped;
        if (plan.mode === "release") {
          mode = "release";
        }
        for (const entry of plan.released || []) {
          if (entry.fromStatus === "*") {
            releasedNextCount += 1;
          } else if (entry.fromStatus === "/") {
            releasedPendingCount += 1;
          }
        }
      }
      const removedPomodoroLinkCount =
        dailyCleanupPlan &&
        dailyCleanupPlan.changed &&
        !commit.pomodoroPruneFailed
          ? dailyCleanupPlan.removedLinkCount
          : 0;
      new Notice(
        buildLaneToggleNotice({
          mode,
          changedTaskCount,
          blockedSkipped,
          unlinkedFromToday: removedPomodoroLinkCount,
          releasedNextCount,
          releasedPendingCount,
          laneBudgets,
        }),
      );
      return true;
    }
    const editor = picker.editor;
    const cursor = picker.cursor;
    const filePath = picker.filePath;
    if (!editor || typeof editor.getValue !== "function" || !cursor) {
      new Notice("Could not update task; no tasks were updated");
      return false;
    }
    let session = null;
    if (
      picker.taskSession &&
      picker.taskSession.explicit &&
      Array.isArray(picker.taskSession.targets) &&
      picker.taskSession.targets.length > 0
    ) {
      session = picker.taskSession;
    } else {
      const content = String(editor.getValue() || "");
      if (!isObsidianTaskAtLine(content, cursor.line)) {
        new Notice("Cursor is not on a task or Task Link");
        return false;
      }
      const line = getEditorLine(editor, cursor.line);
      session = Object.freeze({
        valid: true,
        error: null,
        explicit: false,
        startLine: cursor.line,
        requestedAdditionalCount: 0,
        requestedCount: 1,
        actualCount: 1,
        clamped: false,
        targets: Object.freeze([{ line: cursor.line, rawLine: line }]),
      });
    }
    const writeContext = this.getCountedTaskWriteContext(
      editor,
      filePath,
      session.explicit ? session : session,
    );
    if (!writeContext.valid) {
      new Notice(writeContext.error);
      return false;
    }
    const laneBudgets = readLaneBudgets(this.app);
    const plan = planTaskLaneBatch(writeContext.content, session, {
      summary,
      dateText,
      stampLine: this.getFreshnessStampLine(),
      freshDateText: this.getFreshnessDateText(),
    });
    if (!plan.valid) {
      new Notice(
        plan.stale ? `${plan.error}; no tasks were updated` : plan.error,
      );
      return false;
    }
    let finalContent = plan.content;
    let finalCursorLine = cursor.line;
    let pomodoroSnapshot = null;
    let dailyCleanupPlan = null;
    if (plan.mode === "release") {
      const pruneTargets = plan.released
        .filter((entry) => entry.blockId)
        .map((entry) =>
          Object.freeze({ path: filePath, blockId: entry.blockId }),
        )
        .filter((entry) => entry.path);
      if (pruneTargets.length > 0) {
        pomodoroSnapshot = await this.readDeferredPomodoroSnapshot(this.app, {
          sourcePath: filePath,
          sourceContent: writeContext.content,
          today: new Date(),
        });
        const guarded = this.getCountedTaskWriteContext(editor, filePath, session);
        if (!guarded.valid || guarded.content !== writeContext.content) {
          new Notice(
            guarded.valid
              ? "Active note changed; no tasks were updated"
              : guarded.error,
          );
          return false;
        }
        if (pomodoroSnapshot) {
          if (pomodoroSnapshot.sameFile) {
            dailyCleanupPlan = planDeferredPomodoroLinkCleanup(
              finalContent,
              pruneTargets,
              {
                dailyPath: pomodoroSnapshot.dailyPath,
                noteIndex: pomodoroSnapshot.noteIndex,
              },
            );
            if (dailyCleanupPlan.changed) {
              const removedBefore = dailyCleanupPlan.removedLineRanges.reduce(
                (total, range) =>
                  range.endLineExclusive <= finalCursorLine
                    ? total + (range.endLineExclusive - range.startLine)
                    : total,
                0,
              );
              finalContent = dailyCleanupPlan.content;
              finalCursorLine = finalCursorLine - removedBefore;
            }
          } else {
            dailyCleanupPlan = planDeferredPomodoroLinkCleanup(
              pomodoroSnapshot.content,
              pruneTargets,
              {
                dailyPath: pomodoroSnapshot.dailyPath,
                noteIndex: pomodoroSnapshot.noteIndex,
              },
            );
          }
        }
      }
    }
    const lines = splitMarkdownContent(finalContent).lines;
    const finalLine = String(lines[finalCursorLine] || "");
    const applied = applyEditorContentTransaction(
      editor,
      writeContext.content,
      finalContent,
      {
        line: finalCursorLine,
        ch: Math.min(Math.max(cursor.ch, 0), finalLine.length),
      },
    );
    if (!applied) {
      new Notice("Could not update task; no tasks were updated");
      return false;
    }
    let removedPomodoroLinkCount = 0;
    if (dailyCleanupPlan && dailyCleanupPlan.changed && pomodoroSnapshot) {
      if (pomodoroSnapshot.sameFile) {
        removedPomodoroLinkCount = dailyCleanupPlan.removedLinkCount;
      } else {
        const written = await this.writeDeferredPomodoroCleanup(
          pomodoroSnapshot,
          dailyCleanupPlan,
        );
        removedPomodoroLinkCount = written
          ? dailyCleanupPlan.removedLinkCount
          : 0;
      }
    }
    const releasedNextCount = plan.released.filter(
      (entry) => entry.fromStatus === "*",
    ).length;
    const releasedPendingCount = plan.released.filter(
      (entry) => entry.fromStatus === "/",
    ).length;
    new Notice(
      buildLaneToggleNotice({
        mode: plan.mode,
        changedTaskCount: plan.changedTaskCount,
        blockedSkipped: plan.blockedSkipped,
        unlinkedFromToday: removedPomodoroLinkCount,
        releasedNextCount,
        releasedPendingCount,
        laneBudgets,
      }),
    );
    return true;
  }

  // Apply the picker's pinned Cancel row: write `[-]`, upsert
  // `[cancelled:: date]`, and record the reason in a first-child
  // `❌ **CANCEL LOG**`, then prune the cancelled tasks' links from today's
  // open Pomodoros, recover Blocked dependents through Task Status Cycler's
  // versioned API, and show one Cancelled notice card. Nothing is written
  // until this runs; every refusal ends with `…; no tasks were updated`.
  async applyTaskCancelFromPicker(picker, options = {}) {
    if (!picker) {
      new Notice("Could not update task; no tasks were updated");
      return false;
    }
    const reason = String(options.reason || "");
    const fallbackReason = String(options.fallbackReason || "");
    const baseDate =
      picker.valueBaseDate instanceof Date
        ? picker.valueBaseDate
        : getLocalDateStart(new Date());
    const dateText = formatBulletPropertyDate(baseDate);
    const cancel = { reason, fallbackReason, baseDate, dateText };
    if (
      picker.linkSession &&
      picker.linkSession.kind === "task-link" &&
      Array.isArray(picker.linkSession.targets) &&
      picker.linkSession.targets.length > 0
    ) {
      return await this.applyTaskCancelFromLinkPicker(picker, cancel);
    }
    return await this.applyTaskCancelFromEditor(picker, cancel);
  }

  // Single and counted cancel sessions write through the open editor in one
  // `applyEditorContentTransaction` (one undo step, cursor clamped onto the
  // post-image line). When today's daily note is the active note the prune
  // folds into the same transaction; otherwise the daily note is pruned
  // afterwards through the deferred snapshot, and a failed prune is reported
  // but never rolled back.
  async applyTaskCancelFromEditor(picker, cancel) {
    const editor = picker.editor;
    const cursor = picker.cursor;
    const filePath = picker.filePath;
    if (!editor || typeof editor.getValue !== "function" || !cursor) {
      new Notice("Could not update task; no tasks were updated");
      return false;
    }
    let session = null;
    if (
      picker.taskSession &&
      picker.taskSession.explicit &&
      Array.isArray(picker.taskSession.targets) &&
      picker.taskSession.targets.length > 0
    ) {
      session = picker.taskSession;
    } else {
      const content = String(editor.getValue() || "");
      const liveLine = getEditorLine(editor, cursor.line);
      if (liveLine === null || liveLine !== picker.lineText) {
        new Notice("Current task changed while the picker was open; no tasks were updated");
        return false;
      }
      if (!isObsidianTaskAtLine(content, cursor.line)) {
        new Notice("Task is no longer open; no tasks were updated");
        return false;
      }
      const status = getObsidianTaskCheckboxStatus(liveLine);
      if (!OPEN_OBSIDIAN_TASK_STATUSES.has(status)) {
        new Notice("Task is no longer open; no tasks were updated");
        return false;
      }
      if (isRecurringTaskLine(liveLine)) {
        new Notice(
          "Recurring tasks are cancelled with Obsidian Tasks so the next occurrence is handled; no tasks were updated",
        );
        return false;
      }
      session = Object.freeze({
        valid: true,
        error: null,
        explicit: false,
        startLine: cursor.line,
        requestedAdditionalCount: 0,
        requestedCount: 1,
        actualCount: 1,
        clamped: false,
        targets: Object.freeze([{ line: cursor.line, rawLine: liveLine }]),
      });
    }
    const writeContext = this.getCountedTaskWriteContext(
      editor,
      filePath,
      session,
    );
    if (!writeContext.valid) {
      new Notice(writeContext.error);
      return false;
    }
    const plan = planTaskCancelBatch(writeContext.content, session, {
      date: cancel.dateText,
      reason: cancel.reason,
      fallbackReason: cancel.fallbackReason,
    });
    if (!plan.valid) {
      new Notice(
        plan.stale ? `${plan.error}; no tasks were updated` : plan.error,
      );
      return false;
    }

    let finalContent = plan.content;
    let finalCursorLine = plan.cursorLineShift(cursor.line);
    let pomodoroSnapshot = null;
    let dailyCleanupPlan = null;
    const pruneTargets = [];
    for (const entry of plan.cancelled) {
      if (entry.blockId) {
        pruneTargets.push(
          Object.freeze({ path: filePath, blockId: entry.blockId }),
        );
      }
    }
    if (pruneTargets.length > 0) {
      pomodoroSnapshot = await this.readDeferredPomodoroSnapshot(this.app, {
        sourcePath: filePath,
        sourceContent: writeContext.content,
        today: cancel.baseDate,
      });
      const guarded = this.getCountedTaskWriteContext(editor, filePath, session);
      if (!guarded.valid || guarded.content !== writeContext.content) {
        new Notice(
          guarded.valid
            ? "Active note changed; no tasks were updated"
            : guarded.error,
        );
        return false;
      }
      if (pomodoroSnapshot) {
        if (pomodoroSnapshot.sameFile) {
          dailyCleanupPlan = planDeferredPomodoroLinkCleanup(
            finalContent,
            pruneTargets,
            {
              dailyPath: pomodoroSnapshot.dailyPath,
              noteIndex: pomodoroSnapshot.noteIndex,
            },
          );
          if (dailyCleanupPlan.changed) {
            const linesRemovedBeforeCursor =
              dailyCleanupPlan.removedLineRanges.reduce(
                (total, range) =>
                  range.endLineExclusive <= finalCursorLine
                    ? total + (range.endLineExclusive - range.startLine)
                    : total,
                0,
              );
            finalContent = dailyCleanupPlan.content;
            finalCursorLine = finalCursorLine - linesRemovedBeforeCursor;
          }
        } else {
          dailyCleanupPlan = planDeferredPomodoroLinkCleanup(
            pomodoroSnapshot.content,
            pruneTargets,
            {
              dailyPath: pomodoroSnapshot.dailyPath,
              noteIndex: pomodoroSnapshot.noteIndex,
            },
          );
        }
      }
    }

    const finalLine =
      splitMarkdownContent(finalContent).lines[finalCursorLine] || "";
    try {
      if (
        finalContent !== writeContext.content &&
        !applyEditorContentTransaction(editor, writeContext.content, finalContent, {
          line: finalCursorLine,
          ch: Math.min(Math.max(cursor.ch, 0), finalLine.length),
        })
      ) {
        throw new Error("Editor cannot apply a cancel transaction");
      }
    } catch (error) {
      new Notice("Could not update task; no tasks were updated");
      return false;
    }

    let removedPomodoroLinkCount = 0;
    let pomodoroPruneFailed = false;
    if (dailyCleanupPlan && dailyCleanupPlan.changed && pomodoroSnapshot) {
      if (pomodoroSnapshot.sameFile) {
        removedPomodoroLinkCount = dailyCleanupPlan.removedLinkCount;
      } else {
        const written = await this.writeDeferredPomodoroCleanup(
          pomodoroSnapshot,
          dailyCleanupPlan,
        );
        if (written) {
          removedPomodoroLinkCount = dailyCleanupPlan.removedLinkCount;
        } else {
          pomodoroPruneFailed = true;
        }
      }
    }

    const identities = plan.cancelled.map((entry) =>
      Object.freeze({
        path: filePath,
        blockId: entry.blockId,
        taskId: entry.taskId,
      }),
    );
    const postPruneDailyContent =
      dailyCleanupPlan && dailyCleanupPlan.changed
        ? dailyCleanupPlan.content
        : null;
    return await this.finishTaskCancelNotice(picker, {
      identities,
      activePath: filePath,
      editor,
      count: Math.max(1, plan.cancelledCount),
      viaLinks: false,
      dateText: cancel.dateText,
      reason: cancel.reason,
      fallbackUsed: plan.fallbackLoggedCount > 0,
      skippedClosedCount: plan.skippedClosedCount,
      removedPomodoroLinkCount,
      pomodoroPruneFailed,
      postPruneDailyContent,
    });
  }
}
// ---- src/550-plugin-cancel-and-counted-property.js ----
class BobNavigationHotkeysCancelPropertyMixin {

  // Link-session cancels plan every target note with the pure planner and
  // commit through the shared `commitLinkPickerNoteWrites` core: every
  // preimage is re-verified before the first write, targets write first, the
  // daily-note prune folds into the daily note's own write when it is a
  // target note, target writes roll back when one fails, and a failed prune
  // is reported but never rolled back.
  async applyTaskCancelFromLinkPicker(picker, cancel) {
    const linkSession = picker.linkSession;
    const resolved = Array.isArray(linkSession.resolved)
      ? linkSession.resolved
      : [];
    if (resolved.length === 0) {
      new Notice("Could not update task; no tasks were updated");
      return false;
    }
    const groups = groupLinkPickerTargetsByNote(resolved);
    if (groups.length === 0) {
      new Notice("Could not update task; no tasks were updated");
      return false;
    }
    const planned = [];
    for (const group of groups) {
      const plan = planTaskCancelBatch(group.content, group.session, {
        date: cancel.dateText,
        reason: cancel.reason,
        fallbackReason: cancel.fallbackReason,
      });
      if (!plan.valid) {
        new Notice(
          plan.stale ? `${plan.error}; no tasks were updated` : plan.error,
        );
        return false;
      }
      planned.push({ group, plan });
    }

    const pruneTargets = [];
    for (const { group, plan } of planned) {
      for (const entry of plan.cancelled) {
        if (entry.blockId) {
          pruneTargets.push(
            Object.freeze({ path: group.path, blockId: entry.blockId }),
          );
        }
      }
    }
    let pomodoroSnapshot = null;
    let dailyCleanupPlan = null;
    let foldedDailyPath = null;
    if (pruneTargets.length > 0) {
      const sourcePaths = planned.map(({ group }) => group.path);
      pomodoroSnapshot = await this.readDeferredPomodoroSnapshot(this.app, {
        sourcePath: sourcePaths.length === 1 ? sourcePaths[0] : "",
        sourceContent: planned.length === 1 ? planned[0].plan.content : "",
        today: cancel.baseDate,
      });
      if (pomodoroSnapshot) {
        // When the daily note is one of the edited target notes, the prune
        // folds into that note's own write instead of racing it.
        const folded = planned.find(
          ({ group }) => group.path === pomodoroSnapshot.dailyPath,
        );
        const dailyBase = folded
          ? folded.plan.content
          : pomodoroSnapshot.content;
        if (dailyBase !== null) {
          dailyCleanupPlan = planDeferredPomodoroLinkCleanup(
            dailyBase,
            pruneTargets,
            {
              dailyPath: pomodoroSnapshot.dailyPath,
              noteIndex: pomodoroSnapshot.noteIndex,
            },
          );
          if (folded && dailyCleanupPlan.changed) {
            foldedDailyPath = folded.group.path;
          }
        }
      }
    }

    const commit = await this.commitLinkPickerNoteWrites(planned, {
      pomodoroSnapshot,
      dailyCleanupPlan,
      foldedDailyPath,
    });
    if (!commit.ok) {
      new Notice("A linked note changed; no tasks were updated");
      return false;
    }

    const removedPomodoroLinkCount =
      dailyCleanupPlan && dailyCleanupPlan.changed && !commit.pomodoroPruneFailed
        ? dailyCleanupPlan.removedLinkCount
        : 0;
    const identities = [];
    let cancelledCount = 0;
    let skippedClosedCount = 0;
    let fallbackLoggedCount = 0;
    for (const { group, plan } of planned) {
      cancelledCount += plan.cancelledCount;
      skippedClosedCount += plan.skippedClosedCount;
      fallbackLoggedCount += plan.fallbackLoggedCount;
      for (const entry of plan.cancelled) {
        identities.push(
          Object.freeze({
            path: group.path,
            blockId: entry.blockId,
            taskId: entry.taskId,
          }),
        );
      }
    }
    const postPruneDailyContent =
      dailyCleanupPlan && dailyCleanupPlan.changed
        ? dailyCleanupPlan.content
        : null;
    return await this.finishTaskCancelNotice(picker, {
      identities,
      activePath: picker.filePath,
      editor: picker.editor,
      count: Math.max(1, cancelledCount),
      viaLinks: true,
      dateText: cancel.dateText,
      reason: cancel.reason,
      fallbackUsed: fallbackLoggedCount > 0,
      skippedClosedCount,
      removedPomodoroLinkCount,
      pomodoroPruneFailed: commit.pomodoroPruneFailed,
      postPruneDailyContent,
    });
  }

  // Shared cancel completion: close the modal as soon as the writes land,
  // recover Blocked dependents through Task Status Cycler's versioned API
  // (skipped silently when missing, throwing, or rejecting — the hooks
  // recover them later), then show exactly one Cancelled notice card after
  // recovery settles.
  async finishTaskCancelNotice(picker, details = {}) {
    if (picker && typeof picker.close === "function") {
      try {
        picker.close();
      } catch (error) {
        // The outer openItemAtIndex closes the modal anyway.
      }
    }
    const identities = Array.isArray(details.identities)
      ? details.identities
      : [];
    let reopened = 0;
    let recoveryRan = false;
    if (identities.length > 0) {
      try {
        const plugins = this.app && this.app.plugins && this.app.plugins.plugins;
        const holder = plugins && plugins["task-status-cycler"];
        const api = holder && holder.api;
        if (
          api &&
          typeof api.recoverBlockedDependents === "function" &&
          Number(api.version) >= 1
        ) {
          recoveryRan = true;
          const result = await api.recoverBlockedDependents(identities, {
            activePath: details.activePath,
            editor: details.editor,
          });
          reopened = Math.max(
            0,
            Math.floor(numericOrDefault(result && result.reopened, 0)),
          );
        }
      } catch (error) {
        recoveryRan = false;
        reopened = 0;
      }
    }
    // The plan chip covers the prune only: it needs the post-prune daily
    // note text, and is omitted when nothing was pruned or the API is
    // unavailable.
    const planChip =
      details.postPruneDailyContent !== null &&
      details.postPruneDailyContent !== undefined
        ? getCancelPlanBudgetChip(this.app, details.postPruneDailyContent)
        : "";
    showCancelNotice(
      buildCancelNoticeModel({
        count: details.count,
        viaLinks: details.viaLinks,
        date: details.dateText,
        reason: details.reason,
        fallbackUsed: details.fallbackUsed,
        removedPomodoroLinkCount: details.removedPomodoroLinkCount,
        reopenedDependents: reopened,
        recoveryRan,
        planChip,
        skippedClosedCount: details.skippedClosedCount,
        pomodoroPruneFailed: details.pomodoroPruneFailed,
      }),
    );
    return true;
  }

  openBulletPropertyPicker(cm, options = {}) {
    const activePicker = this.activeBulletPropertyPicker;
    if (activePicker) {
      const incomingCountExplicit = Boolean(
        options.countExplicit === true ||
          (options.taskSession && options.taskSession.explicit),
      );
      const activeCountExplicit = Boolean(
        activePicker.taskSession && activePicker.taskSession.explicit,
      );
      if (!incomingCountExplicit || activeCountExplicit) {
        return true;
      }
      activePicker.close();
    }

    const cursor = getEditorCursor(cm);
    if (!cursor) {
      new Notice("No active markdown editor");
      return false;
    }

    const lineText = getEditorLine(cm, cursor.line);
    if (lineText === null) {
      new Notice("No active markdown editor");
      return false;
    }

    const content =
      cm && typeof cm.getValue === "function"
        ? String(cm.getValue() || "")
        : "";
    // Anywhere on a Depends-On line opens the owning task's Depends on
    // stage, skipping the property step — never the link under the cursor
    // (`docs/task-dependencies.md` §6.1).
    if (!options.taskSession && !options.initialProperty) {
      const entry = resolveDependencyStageEntry(content, cursor.line);
      if (entry.ok && entry.skipPropertyStep) {
        setEditorCursorSafely(cm, entry.parentLine, 0);
        return this.openBulletPropertyPicker(cm, {
          ...options,
          initialProperty: "dependsOn",
        });
      }
    }
    if (!options.taskSession && editorSelectionSpansTasks(cm, content)) {
      new Notice("Selection spans several tasks; put the cursor on one task");
      return false;
    }
    // On a dedicated Task Link bullet, the picker targets the linked task in
    // its own note. On a #task line the existing behavior is unchanged.
    if (
      !options.taskSession &&
      !isObsidianTaskAtLine(content, cursor.line) &&
      parseLinkPickerTaskLink(lineText)
    ) {
      void this.openLinkPicker(cm, options).catch(() => false);
      return true;
    }
    let taskSession = options.taskSession || null;
    if (options.countExplicit && !taskSession) {
      taskSession = discoverCountedObsidianTaskTargets(
        content,
        cursor.line,
        options.additionalTaskCount,
      );
    }
    if (taskSession && taskSession.explicit) {
      if (!taskSession.valid) {
        new Notice(taskSession.error);
        return false;
      }
    } else if (!isBulletLine(lineText)) {
      // Prose with several links is refused with a short reason; a single
      // dedicated Task Link routed to the link picker above.
      if ((lineText.match(/\[\[/g) || []).length >= 2) {
        new Notice("Several links here — put the cursor on one Task Link");
        return false;
      }
      new Notice("Cursor is not on a bullet");
      return false;
    }

    const config = options.config || loadBulletPropertyConfig();
    if (!config) {
      return false;
    }
    if (taskSession && taskSession.explicit) {
      const aggregate = createCountedBulletPropertyItems(
        config,
        content,
        taskSession,
      );
      if (!aggregate.valid) {
        new Notice(aggregate.error);
        return false;
      }
    }

    const basePropertyContext = getProjectNotePropertyContext(
      content,
      cursor.line,
    );
    if (!basePropertyContext.valid) {
      new Notice(basePropertyContext.error);
      return false;
    }
    const propertyContext = {
      ...basePropertyContext,
      isObsidianTask: isObsidianTaskAtLine(content, cursor.line),
    };

    const activeView = this.getActiveMarkdownView();
    if (!activeView || activeView.editor !== cm || !activeView.file) {
      new Notice("No active markdown note");
      return false;
    }
    const filePath = activeView.file.path;

    const picker = new BulletPropertyPickerModal(
      this.app,
      this,
      cm,
      cursor,
      lineText,
      config,
      {
        filePath,
        propertyContext,
        taskSession,
        initialProperty: options.initialProperty || null,
        random: options.random,
        baseDate: options.baseDate,
      },
    );
    this.activeBulletPropertyPicker = picker;
    try {
      picker.open();
    } catch (error) {
      if (this.activeBulletPropertyPicker === picker) {
        this.activeBulletPropertyPicker = null;
      }
      throw error;
    }
    // `initialProperty: "dependsOn"` skips the property step: the Depends
    // on value stage opens straight away (`docs/task-dependencies.md` §6.1).
    if (options.initialProperty) {
      const wanted = (picker.propertyItems || []).find(
        (item) =>
          item &&
          item.kind === "property" &&
          item.property &&
          item.property.name === options.initialProperty,
      );
      if (!wanted) {
        // A direct stage has no card or list to fall back on.
        picker.close();
        new Notice(`${options.initialProperty} is not configured`);
        return false;
      }
      picker.showValueStage(wanted);
    }
    return true;
  }

  getCountedTaskWriteContext(cm, filePath, session) {
    const activeView = this.getActiveMarkdownView();
    if (
      !activeView ||
      activeView.editor !== cm ||
      !activeView.file ||
      activeView.file.path !== filePath
    ) {
      return Object.freeze({
        valid: false,
        error: "Active note changed; no tasks were updated",
      });
    }
    if (!cm || typeof cm.getValue !== "function") {
      return Object.freeze({
        valid: false,
        error: "No active markdown editor",
      });
    }
    const content = String(cm.getValue() || "");
    const validation = validateCountedTaskSession(content, session);
    if (!validation.valid) {
      return Object.freeze({
        valid: false,
        error: `${validation.error}; no tasks were updated`,
      });
    }
    return Object.freeze({ valid: true, error: null, content });
  }

  getInlinePropertyWriteContext(cm, cursor, options = {}) {
    if (
      !cm ||
      typeof cm.getValue !== "function" ||
      !cursor ||
      !Number.isInteger(cursor.line)
    ) {
      return Object.freeze({
        valid: false,
        error: "No active markdown editor",
      });
    }
    const filePath = normalizeVaultRelativePath(options.filePath);
    if (filePath) {
      const activeView = this.getActiveMarkdownView();
      if (
        !activeView ||
        activeView.editor !== cm ||
        !activeView.file ||
        normalizeVaultRelativePath(activeView.file.path) !== filePath
      ) {
        return Object.freeze({
          valid: false,
          error: "Active note changed; bullet property was not updated",
        });
      }
    }
    const content = String(cm.getValue() || "");
    const line = getEditorLine(cm, cursor.line);
    if (line === null) {
      return Object.freeze({
        valid: false,
        error: "No active markdown editor",
      });
    }
    if (
      options.expectedLine !== undefined &&
      options.expectedLine !== null &&
      line !== options.expectedLine
    ) {
      return Object.freeze({
        valid: false,
        error: "Current task changed; bullet property was not updated",
      });
    }
    return Object.freeze({
      valid: true,
      error: null,
      filePath,
      content,
      line,
    });
  }

  getCountedTaskNoticeSuffix(session, unchangedTaskCount = 0) {
    return getCountedTaskNoticeSuffix(session, unchangedTaskCount);
  }

  async setCountedBulletPropertyValue(
    cm,
    cursor,
    filePath,
    session,
    name,
    value,
    options = {},
  ) {
    const writeContext = this.getCountedTaskWriteContext(
      cm,
      filePath,
      session,
    );
    if (!writeContext.valid) {
      new Notice(writeContext.error);
      return false;
    }
    const today = new Date();
    let recoveryByLine = null;
    if (
      normalizeBulletPropertyName(name) === "scheduled" &&
      isDueInlineScheduledValue(value, today)
    ) {
      const includesProjectSchedule = session.targets.some((target) =>
        isProjectLifecycleTaskAtLine(writeContext.content, target.line),
      );
      const recoveryLines = includesProjectSchedule
        ? getProjectScheduleRecoveryTargetLines(writeContext.content)
        : session.targets.map((target) => target.line);
      recoveryByLine = await buildTargetScheduledRecoveryByLine(
        this.app,
        filePath,
        writeContext.content,
        recoveryLines,
        today,
      );
      const guarded = this.getCountedTaskWriteContext(
        cm,
        filePath,
        session,
      );
      if (!guarded.valid || guarded.content !== writeContext.content) {
        new Notice(
          guarded.valid
            ? "Active note changed; no tasks were updated"
            : guarded.error,
        );
        return false;
      }
    }
    const plan = planCountedBulletPropertyBatch(
      writeContext.content,
      session,
      name,
      value,
      {
        operation: "set",
        today,
        recoveryByLine,
        scheduleLog: options.scheduleLog,
        schedulingWorkLog: options.schedulingWorkLog || options.workLog,
        stampLine: this.getFreshnessStampLine(),
        freshDateText: this.getFreshnessDateText(),
      },
    );
    if (!plan.valid) {
      new Notice(
        plan.stale ? `${plan.error}; no tasks were updated` : plan.error,
      );
      return false;
    }

    let finalContent = plan.content;
    let finalCursorLine = plan.cursorLine;
    let pomodoroSnapshot = null;
    let dailyCleanupPlan = null;
    if (plan.futureScheduledTaskLines.length > 0) {
      pomodoroSnapshot = await this.readDeferredPomodoroSnapshot(this.app, {
        sourcePath: filePath,
        sourceContent: writeContext.content,
        today,
      });
      const guarded = this.getCountedTaskWriteContext(cm, filePath, session);
      if (!guarded.valid || guarded.content !== writeContext.content) {
        new Notice(
          guarded.valid
            ? "Active note changed; no tasks were updated"
            : guarded.error,
        );
        return false;
      }
      if (pomodoroSnapshot) {
        const targets = deferredPomodoroTargetsFromLines(
          filePath,
          splitMarkdownContent(writeContext.content).lines,
          plan.futureScheduledTaskLines,
        );
        if (targets.length > 0) {
          if (pomodoroSnapshot.sameFile) {
            dailyCleanupPlan = planDeferredPomodoroLinkCleanup(
              finalContent,
              targets,
              {
                dailyPath: pomodoroSnapshot.dailyPath,
                noteIndex: pomodoroSnapshot.noteIndex,
              },
            );
            if (dailyCleanupPlan.changed) {
              const linesRemovedBeforeCursor =
                dailyCleanupPlan.removedLineRanges.reduce(
                  (total, range) =>
                    range.endLineExclusive <= plan.cursorLine
                      ? total + (range.endLineExclusive - range.startLine)
                      : total,
                  0,
                );
              finalContent = dailyCleanupPlan.content;
              finalCursorLine = plan.cursorLine - linesRemovedBeforeCursor;
            }
          } else {
            dailyCleanupPlan = planDeferredPomodoroLinkCleanup(
              pomodoroSnapshot.content,
              targets,
              {
                dailyPath: pomodoroSnapshot.dailyPath,
                noteIndex: pomodoroSnapshot.noteIndex,
              },
            );
          }
        }
      }
    }

    const finalLine = splitMarkdownContent(finalContent).lines[finalCursorLine] || "";
    try {
      if (
        finalContent !== writeContext.content &&
        !applyEditorContentTransaction(
          cm,
          writeContext.content,
          finalContent,
          {
            line: finalCursorLine,
            ch: Math.min(Math.max(cursor.ch, 0), finalLine.length),
          },
        )
      ) {
        throw new Error("Editor cannot apply a counted property transaction");
      }
    } catch (error) {
      new Notice("Could not update counted task properties; no tasks were updated");
      return false;
    }

    let removedPomodoroLinkCount = 0;
    let pomodoroPruneFailed = false;
    if (dailyCleanupPlan && dailyCleanupPlan.changed && pomodoroSnapshot) {
      if (pomodoroSnapshot.sameFile) {
        removedPomodoroLinkCount = dailyCleanupPlan.removedLinkCount;
      } else {
        const written = await this.writeDeferredPomodoroCleanup(
          pomodoroSnapshot,
          dailyCleanupPlan,
        );
        if (written) {
          removedPomodoroLinkCount = dailyCleanupPlan.removedLinkCount;
        } else {
          pomodoroPruneFailed = true;
        }
      }
    }

    const propagationSuffix =
      plan.propagatedScheduleTaskCount > 0
        ? `; scheduled ${formatCountLabel(
            plan.propagatedScheduleTaskCount,
            "task",
          )}`
        : "";
    const hideSuffix =
      plan.removedHideTaskCount > 0
        ? `; removed #hide from ${formatCountLabel(
            plan.removedHideTaskCount,
            "task",
          )}`
        : "";
    const ambiguitySuffix =
      plan.ambiguousProjectTaskCount > 0
        ? `; ${formatCountLabel(
            plan.ambiguousProjectTaskCount,
            "task",
          )} with multiple scheduled fields unchanged`
        : "";
    const blockedSuffix =
      plan.blockedTaskCount > 0
        ? `; marked ${formatCountLabel(
            plan.blockedTaskCount,
            "task",
          )} Blocked`
        : "";
    const recoverySuffix = scheduledRecoveryNoticeSuffix({
      ready: plan.recoveredReadyTaskCount,
      next: plan.recoveredNextTaskCount,
      inProgress: plan.recoveredInProgressTaskCount,
      stillBlocked: plan.stillBlockedTaskCount,
      deferred: plan.deferredRecoveryTaskCount,
    });
    const scheduleLogSuffix =
      plan.scheduleLoggedTaskCount > 0
        ? `; ${
            plan.scheduleLogFallbackTaskCount === plan.scheduleLoggedTaskCount
              ? "logged without a reason on"
              : "logged reason on"
          } ${formatCountLabel(plan.scheduleLoggedTaskCount, "task")}`
        : "";
    const workLogSuffix =
      plan.schedulingWorkLogWrittenCount > 0
        ? `; ${formatCountLabel(plan.schedulingWorkLogWrittenCount, "Work Log")}`
        : "";
    const pomodoroPruneSuffix =
      removedPomodoroLinkCount > 0
        ? `; removed ${formatCountLabel(removedPomodoroLinkCount, "Pomodoro link")}`
        : pomodoroPruneFailed
          ? "; Pomodoro links not removed"
          : "";
    new Notice(
      `${name} → ${normalizeBulletPropertyValue(value)} on ${formatCountLabel(
        plan.changedTaskCount,
        "task",
      )}${this.getCountedTaskNoticeSuffix(
        session,
        plan.unchangedTaskCount,
      )}${propagationSuffix}${hideSuffix}${blockedSuffix}${ambiguitySuffix}${recoverySuffix}${scheduleLogSuffix}${workLogSuffix}${pomodoroPruneSuffix}`,
    );
    return true;
  }
}
